# ---------------------------------------------------------------- victory points of joined players (0.2.6)

VP_BATTLE_RE = r'victory points: nation (\d+) \+(\d+) in its battle against the host -> (-?\d+)'
VP_SHARE_RE = r"victory points: nation (\d+) \+(\d+) of the host's enemies' (\d+) this month -> (-?\d+)"
VP_PEACE_RE = r'victory points: nation (\d+) is at peace; (-?\d+) -> 0'
VP_AIPEACE_RE = r'AI peace: VP of player nation (\d+) kept at (-?\d+) \(the game set (-?\d+)\)'
VP_SHOWN_RE = r'victory points shown: own (-?\d+), enemy (-?\d+)'
# B4 (0.5.0): nation 1's own peace with the computer's nations in its relation turn (the game's DoPeace in its view)
PLAYER_PEACE_RE = r"relations v2: peace: DoPeace \(nation 1's wars with the computer's nations end\)"
WAR_SCORE_RE = r'war score (\d+)-(\d+): \+(\d+)/\+(\d+) -> (\d+):(\d+)'


def war_score_steps(txt, a, b):
    """The host's steps of the war score a-b (a < b) in log order: its battle hooks' "war score a-b: +x/+y -> A:B" lines
    and (0.6.0) its CreditWarVP lines "victory points: nation G +v (<why>, in its war with nation L) -> t, war score a-b
    A:B" (e.g. B5's blockade points) -> [(+x, +y, A, B, 'battle' | <why>)]."""
    out = []
    for ln in txt.splitlines():
        m = re.search(WAR_SCORE_RE, ln)
        if m and (int(m[1]), int(m[2])) == (a, b):
            out.append((int(m[3]), int(m[4]), int(m[5]), int(m[6]), 'battle'))
            continue
        m = re.search(WAR_VP_CREDIT_RE, ln)
        if m and (int(m[5]), int(m[6])) == (a, b) and sorted((int(m[1]), int(m[4]))) == [a, b]:
            v = int(m[2])
            out.append((v, 0) + (int(m[7]), int(m[8]), m[3]) if int(m[1]) == a else (0, v, int(m[7]), int(m[8]), m[3]))
    return out
VP_PLAYERS = (1, STANDIN)  # the human nations the host credits (the client's and the stand-in's); 3..8 are AI
VP_AI = tuple(range(3, 9))


def vp_shown_ok(clog, cv):
    """victory_points a): (ok, peace): the client's latest "victory points shown: own V, enemy E" (each month's load)
    equals its vpinfo (nation 1's VP, the shown Enemy VP), or nation 1's own peace after that line (the month's relation
    turn after the load: PLAYER_PEACE_RE, the game's DoPeace in its view; a --stress run of 2026-10-23 after 12 months of
    `battles`' war with Spain) zeroed both."""
    m = list(re.finditer(VP_SHOWN_RE, clog))
    if not m or cv is None:
        return False, False
    want = (str(cv['vp'].get(1)), str(cv['enemy']))
    peace = bool(re.search(PLAYER_PEACE_RE, clog[m[-1].end():]))
    return m[-1].groups() == want or (peace and want == ('0', '0')), peace


def vpinfo(port):
    """`vpinfo` -> dict(enemy=EnemyVP (on a client: its "Enemy VP" as shown), seen=the part of EnemyVP the host
    already gave out (-1 = not known yet), vp={nation: VP}, raw), or None."""
    m = re.match(r'^ok enemy=(-?\d+) seen=(-?\d+) vp=(\S*)$', cmd(port, 'vpinfo'))
    if not m:
        return None
    vp = {int(a): int(b) for a, b in (e.split(':') for e in m[3].split(',') if ':' in e)}
    return dict(enemy=int(m[1]), seen=int(m[2]), vp=vp, raw=m.group(0)[3:])


def saved_vp(slot):
    """{nation: [NationN] VP} of a slot's saved .bcs (nations 0-8; None where it can't be read)."""
    d = read_save(save_path(slot)) or {}
    out = {}
    for n in range(9):
        try:
            out[n] = int((d.get(f'Nation{n}') or {}).get('VP'))
        except (TypeError, ValueError):
            out[n] = None
    return out


def file_time(path):
    """A file's last write time (HH:MM:SS.mmm), or '-'."""
    try:
        t = os.path.getmtime(path)
    except OSError:
        return '-'
    return time.strftime('%H:%M:%S', time.localtime(t)) + f'.{int((t % 1) * 1000):03d}'


def save_repeats(path, keys=('VP', 'EnemyVP')):
    """Sections that occur more than once in a save, and `keys` that occur more than once in one section (the game's
    reader and read_save could take different ones): [(section, key or '[section]', values)]."""
    try:
        with open(path, 'rb') as f:
            t = f.read().decode('utf-8-sig', errors='replace')
    except OSError:
        return ['not read']
    seen, cur, out = {}, '', []
    secs = {}
    for ln in t.splitlines():
        if ln.startswith('[') and ln.endswith(']'):
            cur = ln[1:-1]
            secs[cur] = secs.get(cur, 0) + 1
        elif '=' in ln:
            k, v = ln.split('=', 1)
            if k in keys:
                seen.setdefault((cur, k), []).append(v)
    out += [(s, f'[{s}]', n) for s, n in secs.items() if n > 1][:10]
    out += [(s, k, v) for (s, k), v in seen.items() if len(v) > 1][:10]
    return out


def save_diff(a, b, limit=30):
    """Keys that differ between two parsed saves -> ([(section, key, a, b)] (the first `limit`), count)."""
    out, n = [], 0
    for sec in sorted(set(a or {}) | set(b or {})):
        sa, sb = (a or {}).get(sec) or {}, (b or {}).get(sec) or {}
        for k in sorted(set(sa) | set(sb)):
            if sa.get(k) != sb.get(k):
                n += 1
                if len(out) < limit:
                    out.append((sec, k, (sa.get(k) or '')[:40], (sb.get(k) or '')[:40]))
    return out, n


def vp_mismatch_probe(ctx, tag, nation=1):
    """Diagnosis of a VP mismatch after a month (0.3.2 f): the host's saved slot vs the client's package file (repeated
    VP keys or sections, the keys that differ), then each copy loads its own slot again (`load`, as after a merge) and
    the VP are read again: the same extra points on both -> the game's load adds them (the host's memory before its
    reload lags); only on the client -> something of the client's own state before the load."""
    hp_, cp_ = save_path(HOST_SLOT), save_path(CLIENT_SLOT)
    hs, cs = read_save(hp_) or {}, read_save(cp_) or {}
    diff, n = save_diff(hs, cs)
    rep = dict(host=save_repeats(hp_), client=save_repeats(cp_))
    gen = {k: ((hs.get('General') or {}).get(k), (cs.get('General') or {}).get(k))
           for k in ('Year', 'Month', 'Day', 'EnemyVP', 'War', 'HasBeenBattle', 'ScenarioInProgress', 'DeclineCount',
                     'EnemyDeclineCount', 'BattleIsSurpriseAttack')}

    def load(port, line, proc, who):
        return load_answering(port, line, proc, who)

    c0 = vpinfo(C)
    rc = load(C, f'load {CLIENT_SLOT} {nation}', ctx.cp, 'client')
    c1 = vpinfo(C)
    h0 = vpinfo(H)
    rh = load(H, f'load {HOST_SLOT} 0', ctx.hp, 'host')
    h1 = vpinfo(H)
    log(f'  {tag}: VP probe: [General] host/client {gen}; repeated keys {rep}; {n} keys differ between the host\'s slot '
        f'{HOST_SLOT} and the client\'s slot {CLIENT_SLOT}: {diff}')
    log(f'  {tag}: VP probe: client before/after `load {CLIENT_SLOT} {nation}` ({rc}): {c0 and c0["vp"]} -> '
        f'{c1 and c1["vp"]}; host before/after `load {HOST_SLOT} 0` ({rh}): {h0 and h0["vp"]} -> {h1 and h1["vp"]}')
    return dict(diff=diff, n=n, rep=rep, gen=gen, c=(c0, c1), h=(h0, h1))


def load_answering(port, line, proc, who, timeout=60):
    """A bridge `load` (it runs on the game's main thread) while the copy's dialogs are answered -> the reply."""
    out = {}

    def run():
        try:
            out['r'] = ctl.cmd(port, line, timeout)
        except OSError as e:
            out['r'] = f'error {e!r}'

    th = threading.Thread(target=run, daemon=True)
    th.start()
    while th.is_alive():
        answer_dialogs(proc, who)
        th.join(0.3)
    return out.get('r', '')


LOAD_VP_RE = (r"load: the game's blockade check gave victory points the save doesn't have; put back: (.*) "
              r"\(blockaded:((?: \d+)+| none)\)")
BLOCKADE_LEVER = 1000  # nation 0's BlockadeModifier during vp_reload_check: its enemies are blockaded at every load


def vp_reload_check(ctx, tag, loads=2):
    """lockstep_month (0.4.0): every load of a saved campaign gives exactly the saved victory points, on both copies.
    The game's load (LoadBuildCampaign -> CheckBlockadeStatus) credits every blockade between nation 0 and a nation at
    war with it, as the month does: nation 0's VP when it blockades, EnemyVP when it is blockaded. The mod puts the
    load's credit back and logs it ("load: the game's blockade check gave victory points the save doesn't have; put
    back: ..."). A blockade is made for the check: nation 0's BlockadeModifier is raised and saved on both copies (the
    host's slot 1, the client's slot 77), so while the war 0-1 goes on nation 1 is blockaded at every load. Each copy
    then loads its own slot `loads` times: after each load every nation's VP and EnemyVP equal the file's, and the load
    logged one "put back" line naming nation 1. The modifier is put back and saved afterwards."""
    sides = ((H, HOST_SLOT, 0, ctx.hp, 'host'), (C, CLIENT_SLOT, 1, ctx.cp, 'client'))
    war = rel(0, 1).get('war') == '1'
    orig = {port: nint(port, 0, 'BlockadeModifier') for port, *_ in sides}
    rows, good = [], all(v is not None for v in orig.values())
    try:
        for port, slot, nation, pid, who in sides:
            if orig.get(port) is None:
                break
            r1, r2 = cmd(port, f'nfield 0 BlockadeModifier {BLOCKADE_LEVER}'), cmd(port, 'save')
            f = read_save(save_path(slot)) or {}
            fv, fe = saved_vp(slot), (f.get('General') or {}).get('EnemyVP')
            if not (r1.startswith('ok') and r2 == 'ok' and (f.get('Nation0') or {}).get('BlockadeModifier')
                    == str(BLOCKADE_LEVER)):
                rows.append((who, 'lever', r1, r2))
                good = False
                break
            for i in range(1, loads + 1):
                mark = log_mark(port)
                r = load_answering(port, f'load {slot} {nation}', pid, who)
                v = vpinfo(port)
                lines = log_lines(log_since(port, mark), LOAD_VP_RE)
                m = [re.search(LOAD_VP_RE, x) for x in lines]
                same = r == 'ok' and v is not None and all(v['vp'].get(n) == fv.get(n) for n in range(9)) \
                    and str(v['enemy']) == fe
                logged = len(m) == 1 and '1' in m[0][2].split() if war else len(m) <= 1
                rows.append((who, i, r, {n: v['vp'].get(n) for n in range(9) if v['vp'].get(n)} if v else None,
                             v and v['enemy'], {n: x for n, x in fv.items() if x}, fe, [x[1] for x in m],
                             [x[2].strip() for x in m]))
                good = good and same and logged
    finally:
        for port, slot, nation, pid, who in sides:
            if orig.get(port) is not None:
                cmd(port, f'nfield 0 BlockadeModifier {orig[port]}')
                cmd(port, 'save')
    check(f'{tag}: every load keeps the saved victory points (0.4.0): with a blockade of nation 1 made for the check '
          f'(nation 0\'s BlockadeModifier {BLOCKADE_LEVER}, saved), the host loads slot {HOST_SLOT} and the client slot '
          f'{CLIENT_SLOT} {loads} times each: after each load every nation\'s VP and EnemyVP equal the file\'s, and the '
          f'load put back the game\'s blockade credit ("load: the game\'s blockade check gave victory points the save '
          f'doesn\'t have; put back: ...", nation 1 blockaded)' + ('' if war else ' (not at war: no credit to put back)'),
          good, f'at war {war}; BlockadeModifier before {orig}; loads (copy, n, reply, VP, EnemyVP, file VP, file '
                f'EnemyVP, put back, blockaded): {rows}')
    return good


def battlevp(ctx, opp, vp_host, vp_opp, level='Minor'):
    """Host `battlevp`: the game's own HandleBattleAftermath against `opp` through the mod's hook, as after a tactical
    battle -> dict(ok, host=(a, b), enemy=(c, d), opp=(e, f), raw). The bridge runs it synchronously on the game's main
    thread, so the host's dialogs are answered meanwhile."""
    out = {}

    def run():
        try:
            out['r'] = ctl.cmd(H, f'battlevp {opp} {vp_host} {vp_opp} {level}', 130)
        except OSError as e:
            out['r'] = f'error {e!r}'

    th = threading.Thread(target=run, daemon=True)
    th.start()
    while th.is_alive():
        answer_dialogs(ctx.hp, 'host')
        th.join(0.3)
    r = out.get('r', '')
    m = re.match(r'^ok host=(-?\d+)->(-?\d+) enemy=(-?\d+)->(-?\d+) opp=(-?\d+)->(-?\d+)$', r)
    if not m:
        log('  !! battlevp ->', r)
        return dict(ok=False, host=(0, 0), enemy=(0, 0), opp=(0, 0), raw=r)
    v = [int(x) for x in m.groups()]
    return dict(ok=True, host=(v[0], v[1]), enemy=(v[2], v[3]), opp=(v[4], v[5]), raw=r[3:])


def wars_of(n):
    """The nations (0..8) at war with nation n on the host."""
    return [j for j in range(9) if j != n and rel(n, j).get('war') == '1']


def vp_shares(rest, enemies):
    """ShareEnemyVP's split: `rest` evenly among the host's enemies in index order, the remainder +1 to the first."""
    share, extra = divmod(rest, len(enemies)) if enemies else (0, 0)
    return {j: share + (1 if i < extra else 0) for i, j in enumerate(enemies)}


def vp_diff(a, b, nations):
    """{nation: (before, after)} for the nations whose VP differ between two vpinfo results."""
    return {n: (a['vp'].get(n), b['vp'].get(n)) for n in nations if a['vp'].get(n) != b['vp'].get(n)}


def apply_vp(ctx, want_seen, timeout=15):
    """applydiplo when the month-end step must share EnemyVP: done once `seen` (set first thing) reached want_seen."""
    return apply_diplo(ctx, lambda: (vpinfo(H) or {}).get('seen') == want_seen, timeout)


def client_accept_peace(ctx, nation):
    """The client accepts the peace `nation` offered with its Diplomacy button: the nation's row selected in the list
    (LVM_SETITEMSTATE), button 1084 reading "Accept peace", a posted BM_CLICK. Returns (button text, the host's
    `diplomacy request 1 peace <nation> accepted` lines)."""
    cp = ctx.cp
    cmd(C, 'mpwindow')
    time.sleep(0.5)
    lvh, btn = mp_ctl(cp, 'list'), mp_ctl(cp, 'peace')
    rows = lv_rows(cp, lvh)
    idx = next((i for i, (prm, _, _) in enumerate(rows) if prm == nation), None)
    if idx is not None:
        lv_select(cp, lvh, idx)
    bt = wait_until(lambda: text(btn), lambda s: s == 'Accept peace', 8)
    mark = log_mark(H)
    if bt == 'Accept peace':
        u.PostMessageW(btn, 0x00F5, 0, 0)  # BM_CLICK
    return bt, wait_log(H, mark, rf'diplomacy request 1 peace {nation} accepted', 8)


def scenario_victory_points(ctx):
    """0.2.6: victory points of joined players. The game credits whatever the host's enemies achieve in the host's
    wars to EnemyVP only (a joined nation's own VP never moved). The host now gives a human enemy the points of its
    battles at once (OnBattleVP), shares the rest of the month's EnemyVP among its enemies at month end
    (ShareEnemyVP; `seen` = the part already given out), resets a human nation at peace to VP 0, keeps the VP of
    human nations still at war through HandleAIPeace and keeps its own VP in the merge; the client shows the VP of
    its own enemies as "Enemy VP". Driven with `battlevp` (the game's HandleBattleAftermath), `enemyvpadd` (EnemyVP
    outside a battle, like a blockade) and `applydiplo`, so no month is processed while the host is at war; one month
    is processed with only the war 1-2 (merge and the client's view)."""
    hp = ctx.hp
    ALL = range(9)

    # a) startup
    avail = {}
    for port, who in ((H, 'host'), (C, 'client')):
        ln = log_lines(log_since(port), r'Peace treaties: ')
        avail[who] = bool(ln) and bool(re.search(r'Peace treaties: ok \(.*battleHooks=1/1/1\)', ln[0]))
        check(f'a) {who} log at startup: "Peace treaties: ok (... battleHooks=1/1/1)" (the VP hooks)', avail[who],
              [x.split('] ', 1)[-1] for x in ln[:1]] or 'no line')
    if not all(avail.values()):  # every further step needs the hooks: don't keep the game open for nothing
        check('victory points: the VP hooks are available on host and client (needed by every further check)', False,
              f'{avail}: the remaining checks were not run')
        return
    cv = vpinfo(C)
    clog = log_since(C)
    shown = re.findall(VP_SHOWN_RE, clog)
    vp_ok, vp_peace = vp_shown_ok(clog, cv)
    if vp_peace:
        log(f'  NOTE a) nation 1 made its own peace with the computer\'s nations after the last month\'s load (the game\'s '
            f'DoPeace in its relation turn): its VP and the shown Enemy VP are 0 since then ({cv and cv["raw"]})')
    check('a) client log "victory points shown: own V, enemy E" for every loaded month; the latest = the client\'s '
          'vpinfo (nation 1\'s VP, the shown Enemy VP; 0 and 0 after nation 1\'s own peace in the month\'s relation turn)',
          vp_ok, f'{shown[-3:]} | {cv and cv["raw"]}')
    r01, r12 = rel(0, 1), rel(1, 2)
    v0 = vpinfo(H)
    log(f'  start: host vpinfo {v0 and v0["raw"]} | client vpinfo {cv and cv["raw"]} | wars of 1: {wars_of(1)}, '
        f'of 2: {wars_of(2)}')
    check('start: the host at war with nobody, nations 1 and 2 at peace with each other',
          r01['hostWars'] == '0' and r12['war'] == '0', f'0-1 {r01} | 1-2 {r12}')

    # b) the host at war with nation 1; the game's end-of-battle routine of a host battle against it
    mark = log_mark(H)
    rh = cmd(H, 'diplo war 1')
    acc = wait_log(H, mark, r'diplomacy request 0 war 1 accepted', 8)
    apply_diplo(ctx, lambda: rel(0, 1).get('war') == '1')
    r01, v1 = rel(0, 1), vpinfo(H)
    check('b) host `diplo war 1` (accepted) + applydiplo: at war with 1 (rel 0 1 war=1, hostWars=1)',
          rh == 'ok' and acc and r01['war'] == '1' and r01['hostWars'] == '1', f'{rh} {acc} {r01}')
    log(f'  b) at war: host vpinfo {v1["raw"]}')
    mark = log_mark(H)
    bv = battlevp(ctx, 1, 1000, 3000, 'Minor')
    v2, hl = vpinfo(H), log_since(H, mark)
    gain = bv['enemy'][1] - bv['enemy'][0]
    log(f'  b) battlevp 1 1000 3000 Minor -> {bv["raw"]} | host vpinfo {v2["raw"]}')
    check('b) the host\'s side as before: its VP and EnemyVP rise (battlevp host a->b, enemy c->d; vpinfo agrees)',
          bv['ok'] and bv['host'][1] > bv['host'][0] == v1['vp'][0] and gain > 0 and bv['enemy'][0] == v1['enemy']
          and v2['vp'][0] == bv['host'][1] and v2['enemy'] == bv['enemy'][1], bv['raw'])
    check(f'b) nation 1 (the joined enemy) VP +{gain} = the EnemyVP gain of the battle (0.2.5: unchanged)',
          bv['ok'] and bv['opp'] == (v1['vp'][1], v1['vp'][1] + gain) and v2['vp'][1] == v1['vp'][1] + gain,
          f'opp {bv["opp"]}, vpinfo nation 1 {v1["vp"][1]} -> {v2["vp"][1]}')
    got = re.findall(VP_BATTLE_RE, hl)
    check(f'b) host log "victory points: nation 1 +{gain} in its battle against the host -> {v2["vp"][1]}"',
          got == [('1', str(gain), str(v2['vp'][1]))], got)
    check('b) vpinfo seen == enemy (the battle\'s points count as given out)', v2['seen'] == v2['enemy'], v2['raw'])
    check('b) nation 2 and the AI nations 3-8 keep their VP', not vp_diff(v1, v2, (2,) + VP_AI),
          vp_diff(v1, v2, (2,) + VP_AI))

    # c) EnemyVP outside a battle (like a blockade) is shared at month end: nation 1 is the host's only enemy
    ra = cmd(H, 'enemyvpadd 101')
    va, enemies = vpinfo(H), wars_of(0)
    hl = apply_vp(ctx, va['enemy'])
    vc = vpinfo(H)
    rest = va['enemy'] - va['seen']
    got = re.findall(VP_SHARE_RE, hl)
    log(f'  c) enemyvpadd 101 -> {ra[3:]} | host enemies {enemies} | after applydiplo {vc["raw"]} | {got}')
    check('c) enemyvpadd 101: EnemyVP +101, seen unchanged (the reply is vpinfo)',
          ra.startswith('ok enemy=') and va['enemy'] == v2['enemy'] + 101 and va['seen'] == v2['seen'], ra)
    check('c) applydiplo shares the month\'s rest 101 with the host\'s only enemy: nation 1 +101',
          enemies == [1] and rest == 101 and vc['vp'][1] == va['vp'][1] + 101,
          f'enemies {enemies}, rest {rest}, nation 1 {va["vp"][1]} -> {vc["vp"][1]}')
    check(f'c) host log "victory points: nation 1 +101 of the host\'s enemies\' 101 this month -> {vc["vp"][1]}"',
          got == [('1', '101', '101', str(vc['vp'][1]))], got)
    check('c) seen == enemy; the share changes neither the host\'s VP nor its EnemyVP (the host\'s screen) nor '
          'nations 2-8', vc['seen'] == vc['enemy'] == va['enemy'] and vc['vp'][0] == va['vp'][0] and
          not vp_diff(va, vc, (2,) + VP_AI), f'{va["raw"]} -> {vc["raw"]}')
    sf = session_file()
    check(f'c) {SESSION_FILE} keeps enemyVPSeen={vc["seen"]}, stamped with diplomacyDate',
          sf.get('enemyVPSeen') == str(vc['seen']) and bool(sf.get('diplomacyDate')),
          {k: sf.get(k) for k in ('enemyVPSeen', 'diplomacyDate')})

    # d) a second enemy: the host at war with 1 and 2, the month's rest split evenly in index order
    mark = log_mark(H)
    rh = cmd(H, 'diplo war 2')
    acc = wait_log(H, mark, r'diplomacy request 0 war 2 accepted', 8)
    apply_diplo(ctx, lambda: rel(0, 2).get('war') == '1')
    r02, vd0 = rel(0, 2), vpinfo(H)
    check('d) host `diplo war 2` + applydiplo: at war with 1 and 2 (hostWars=2); a second war resets nothing (VP, '
          'EnemyVP, seen unchanged)', rh == 'ok' and acc and r02['war'] == '1' and r02['hostWars'] == '2' and
          vd0['enemy'] == vc['enemy'] and vd0['seen'] == vc['seen'] and not vp_diff(vc, vd0, ALL),
          f'{rh} {acc} {r02} | {vc["raw"]} -> {vd0["raw"]}')
    ra = cmd(H, 'enemyvpadd 101')
    va, enemies = vpinfo(H), wars_of(0)
    hl = apply_vp(ctx, va['enemy'])
    vd = vpinfo(H)
    rest = va['enemy'] - va['seen']
    want = vp_shares(rest, enemies)
    got = re.findall(VP_SHARE_RE, hl)
    want_lines = sorted((str(j), str(want[j]), str(rest), str(vd['vp'][j])) for j in enemies
                        if j in VP_PLAYERS and want[j] > 0)
    log(f'  d) enemyvpadd 101 -> {ra[3:]} | host enemies {enemies} | after applydiplo {vd["raw"]} | {got}')
    check('d) enemyvpadd 101 + applydiplo: shared evenly among the host\'s enemies [1, 2] in index order: nation 1 '
          '+51, nation 2 +50', enemies == [1, 2] and rest == 101 and vd['vp'][1] == va['vp'][1] + 51 and
          vd['vp'][2] == va['vp'][2] + 50, f'enemies {enemies}, rest {rest}, {va["raw"]} -> {vd["raw"]}')
    check(f'd) host log "victory points: nation K +x of the host\'s enemies\' {rest} this month -> V" for 1 and 2',
          sorted(got) == want_lines and len(got) == 2, f'{got} (want {want_lines})')
    check('d) seen == enemy; the host\'s VP, its EnemyVP and the AI nations unchanged by the share',
          vd['seen'] == vd['enemy'] == va['enemy'] and vd['vp'][0] == va['vp'][0] and not vp_diff(va, vd, VP_AI),
          f'{va["raw"]} -> {vd["raw"]}')

    # e) a drop: the game reset EnemyVP (DoPeace / WarStartsWithNation set it to 0) and it is below `seen` at month end
    E = vd['enemy']
    r1, r2 = cmd(H, f'enemyvpadd {-E}'), cmd(H, 'enemyvpadd 101')
    ve0 = vpinfo(H)
    hl = apply_vp(ctx, ve0['enemy'])
    ve = vpinfo(H)
    got = re.findall(VP_SHARE_RE, hl)
    check(f'e) a drop: EnemyVP {E} -> 0 (as the game resets it) -> 101, below seen {vd["seen"]}: applydiplo shares '
          f'nothing (no share line, every VP unchanged) and seen = enemy = 101',
          E > 101 and r1.startswith('ok') and r2.startswith('ok') and ve0['enemy'] == 101 and
          ve0['seen'] == vd['seen'] and not got and not vp_diff(ve0, ve, ALL) and ve['seen'] == ve['enemy'] == 101,
          f'{ve0["raw"]} -> {ve["raw"]}; {got}')

    # f) peace with 1 (the host stays at war with 2), the client accepts with its button; equal war score: compromise
    warvp(0, 1, 300, 300)
    rh = cmd(H, 'diplo peace 1')
    bt, acc = client_accept_peace(ctx, 0)
    r = wait_until(lambda: row(H, 1), lambda r: r and 'peace agreed' in r['pending'], 5)
    check('f) host offers peace to 1; the client accepts with its "Accept peace" button (1084): host row 1 "peace '
          'agreed"', rh == 'ok' and bt == 'Accept peace' and bool(acc) and r and 'peace agreed' in r['pending'],
          f'{rh}; button "{bt}"; {acc}; {r}')
    vf0 = vpinfo(H)
    hl = apply_diplo(ctx, lambda: rel(0, 1).get('war') == '0')
    vf, r01, w1 = vpinfo(H), rel(0, 1), wars_of(1)
    got = re.findall(VP_PEACE_RE, hl)
    log(f'  f) peace 0-1: {vf0["raw"]} -> {vf["raw"]} | {got}')
    check('f) applydiplo: peace 0-1, the host still at war with 2 (hostWars=1): no DoPeace, the host\'s VP and '
          'EnemyVP unchanged', r01['war'] == '0' and r01['hostWars'] == '1' and vf['vp'][0] == vf0['vp'][0] and
          vf['enemy'] == vf0['enemy'], f'{r01} | {vf0["raw"]} -> {vf["raw"]}')
    check(f'f) nation 1 at war with nobody: host log "victory points: nation 1 is at peace; {vf0["vp"][1]} -> 0", VP '
          f'0; nation 2 (still at war) keeps {vf0["vp"][2]}',
          not w1 and vf0['vp'][1] != 0 and got == [('1', str(vf0['vp'][1]))] and vf['vp'][1] == 0 and
          vf['vp'][2] == vf0['vp'][2], f'wars of 1 {w1}; {got}; {vf0["raw"]} -> {vf["raw"]}')

    # peace with 2 ends the host's last war (DoPeace); in the same month-end step the host declares war on 1 again
    warvp(0, 2, 300, 300)
    rh, ra, rw = cmd(H, 'diplo peace 2'), cmd(H, 'diploas 2 peace 0'), cmd(H, 'diplo war 1')
    vg0 = vpinfo(H)
    hl = apply_diplo(ctx, lambda: rel(0, 2).get('war') == '0' and rel(0, 1).get('war') == '1', 25)
    vg, r02, r01, w2 = vpinfo(H), rel(0, 2), rel(0, 1), wars_of(2)
    got = re.findall(VP_PEACE_RE, hl)
    log(f'  f) peace 0-2 + war 0-1 in one step: {vg0["raw"]} -> {vg["raw"]} | {got}')
    check('f) host offers peace to 2, the stand-in accepts (diploas 2 peace 0) + applydiplo: the host\'s last war '
          'ends, DoPeace resets the host\'s VP and EnemyVP to 0',
          rh == ra == 'ok' and r02['war'] == '0' and vg0['vp'][0] != 0 and vg['vp'][0] == 0 and vg['enemy'] == 0,
          f'{rh} {ra} {r02} | {vg0["raw"]} -> {vg["raw"]}')
    check(f'f) nation 2 at war with nobody: host log "victory points: nation 2 is at peace; {vg0["vp"][2]} -> 0", VP 0',
          not w2 and vg0['vp'][2] != 0 and got == [('2', str(vg0['vp'][2]))] and vg['vp'][2] == 0,
          f'wars of 2 {w2}; {got}; {vg["raw"]}')
    check('f) the host\'s new war on 1 started in the same step (rel 0 1 war=1, hostWars=1)',
          rw == 'ok' and r01['war'] == '1' and r01['hostWars'] == '1', f'{rw} {r01}')
    # The step reset EnemyVP after its own ShareEnemyVP (DoPeace; the new war): `seen` is re-synced by the DoPeace hook
    # and at the end of the step, so the new war's points are shared from 0 (0.2.6 first build: seen stayed at the old
    # score and the new war's first month shared nothing).
    shared = re.findall(VP_SHARE_RE, hl)
    check(f'f) re-sync: after that step seen == enemy == 0 (was seen {vg0["seen"]}), and no share line in it (the DoPeace '
          f'hook\'s ShareEnemyVP credits nothing twice)', vg['seen'] == vg['enemy'] == 0 and not shared,
          f'{vg0["raw"]} -> {vg["raw"]}; {shared}')
    ra = cmd(H, 'enemyvpadd 101')
    vh0 = vpinfo(H)
    hl = apply_vp(ctx, vh0['enemy'])
    vh = vpinfo(H)
    got = re.findall(VP_SHARE_RE, hl)
    log(f'  f) re-sync: enemyvpadd 101 -> {ra[3:]} | after applydiplo {vh["raw"]} | {got}')
    check(f'f) re-sync: enemyvpadd 101 + applydiplo in the new war: nation 1 (the host\'s only enemy) {vh0["vp"][1]} -> '
          f'{vh0["vp"][1] + 101}, "victory points: nation 1 +101 of the host\'s enemies\' 101 this month -> '
          f'{vh0["vp"][1] + 101}", seen == enemy == 101',
          ra.startswith('ok') and wars_of(0) == [1] and vh['vp'][1] == vh0['vp'][1] + 101 and
          got == [('1', '101', '101', str(vh['vp'][1]))] and vh['seen'] == vh['enemy'] == 101,
          f'{vh0["raw"]} -> {vh["raw"]}; {got}')

    # g) the players' war 1-2, and the host at war with both: the host's battles against 1 and 2 credit them; then the
    # host makes peace with both (the game's DoPeace) while 1 and 2 stay at war with each other, and one month is
    # processed (merge, the client's view). Battles only inside a host war that DoPeace ends: a battlevp at peace
    # leaves the host's VP and EnemyVP non-zero, and the game's DoPeace of a later war then skips its "war ending
    # without any major battle" prestige dent (treaty i failed with host Prestige +2 instead of +1).
    rc = client_request('diplo war 2', 'war', 2)
    mark = log_mark(H)
    rh = cmd(H, 'diplo war 2')
    acc = wait_log(H, mark, r'diplomacy request 0 war 2 accepted', 8)
    apply_diplo(ctx, lambda: rel(1, 2).get('war') == '1' and rel(0, 2).get('war') == '1')
    r12, r02, vj = rel(1, 2), rel(0, 2), vpinfo(H)
    check('g) client `diplo war 2` + host `diplo war 2` + applydiplo: 1-2 at war, the host at war with 1 and 2 '
          '(hostWars=2)', rc == 'ok' and rh == 'ok' and bool(acc) and r12['war'] == '1' and r02['war'] == '1' and
          r02['hostWars'] == '2', f'{rc} {rh} {acc}; 1-2 {r12}; 0-2 {r02}')
    for opp, a, b in ((1, 500, 2000), (2, 300, 1000)):
        mark = log_mark(H)
        bv = battlevp(ctx, opp, a, b, 'Minor')
        vn, hl = vpinfo(H), log_since(H, mark)
        gain, other = bv['enemy'][1] - bv['enemy'][0], 3 - opp
        got = re.findall(VP_BATTLE_RE, hl)
        log(f'  g) battlevp {opp} {a} {b} Minor -> {bv["raw"]} | host vpinfo {vn["raw"]}')
        check(f'g) battlevp {opp} {a} {b} Minor: nation {opp} +{gain} = the EnemyVP gain (log line), nation {other} '
              f'unchanged, seen == enemy', bv['ok'] and gain > 0 and vn['vp'][opp] == vj['vp'][opp] + gain and
              vn['vp'][other] == vj['vp'][other] and got == [(str(opp), str(gain), str(vn['vp'][opp]))] and
              vn['seen'] == vn['enemy'], f'{bv["raw"]} | {got} | {vj["raw"]} -> {vn["raw"]}')
        vj = vn
    warvp(0, 1, 300, 300)
    warvp(0, 2, 300, 300)
    rh = cmd(H, 'diplo peace 1')
    bt, acc = client_accept_peace(ctx, 0)
    wait_until(lambda: row(H, 1), lambda r: r and 'peace agreed' in r['pending'], 5)
    rh2, ra2 = cmd(H, 'diplo peace 2'), cmd(H, 'diploas 2 peace 0')
    hl = apply_diplo(ctx, lambda: rel(0, 1).get('war') == '0' and rel(0, 2).get('war') == '0', 25)
    vi, r01, r12 = vpinfo(H), rel(0, 1), rel(1, 2)
    got = re.findall(VP_PEACE_RE, hl)
    log(f'  g) peace 0-1 and 0-2: {vj["raw"]} -> {vi["raw"]} | {got}')
    check('g) host peace with 1 (the client\'s "Accept peace" button) and with 2 + applydiplo: the host\'s last war '
          'ends (hostWars=0), DoPeace resets the host\'s VP and EnemyVP to 0',
          rh == rh2 == ra2 == 'ok' and bt == 'Accept peace' and bool(acc) and r01['war'] == '0' and
          r01['hostWars'] == '0' and vj['vp'][0] != 0 and vi['vp'][0] == 0 and vi['enemy'] == 0,
          f'{rh} {rh2} {ra2}; button "{bt}"; {acc}; {r01}; {vj["raw"]} -> {vi["raw"]}')
    check(f'g) nations 1 and 2, still at war with each other, keep their VP {vj["vp"][1]}/{vj["vp"][2]} through the '
          f'host\'s DoPeace (no "is at peace" line)', r12['war'] == '1' and vi['vp'][1] == vj['vp'][1] and
          vi['vp'][2] == vj['vp'][2] and not got, f'1-2 {r12}; {got}; {vj["raw"]} -> {vi["raw"]}')
    shared = re.findall(VP_SHARE_RE, hl)
    check(f'g) re-sync after the host\'s DoPeace: seen == enemy == 0 (was {vj["seen"]}), no share line (nothing new to '
          f'share before DoPeace, nothing credited twice)', vi['seen'] == vi['enemy'] == 0 and not shared,
          f'{vj["raw"]} -> {vi["raw"]}; {shared}')
    if r01['war'] != '0' or r01['hostWars'] != '0':
        check('g) the month can be processed (the host at war with nobody)', False, r01)
        return
    cmd(H, 'enemyvpadd 77')  # a marker: the host's own "Enemy VP", unlike what the client shows (reset at the end)
    vj = vpinfo(H)
    credited, cpre = vj['vp'][1], vpinfo(C)
    hm, cm = log_mark(H), log_mark(C)
    run_month(ctx, 'victory_points')
    hl, cl = log_since(H, hm), log_since(C, cm)
    vk, w1 = vpinfo(H), wars_of(1)
    ws = [m for m in re.findall(WAR_SCORE_RE, hl) if {m[0], m[1]} == {'1', '2'}]
    g1 = sum(int(m[2]) if m[0] == '1' else int(m[3]) for m in ws)
    g2 = sum(int(m[3]) if m[0] == '1' else int(m[2]) for m in ws)
    # 0.6.0 (B5): a blockade in the war 1-2 gives its points as the player's (warfx: nation 1 under the player's rules)
    bc = blockade_credits(hl)
    b1 = sum(v for g, v, lo in bc if g == 1 and lo == 2)
    b2 = sum(v for g, v, lo in bc if g == 2 and lo == 1)
    log(f'  g) month: host {vj["raw"]} -> {vk["raw"]} | client before {cpre and cpre["raw"]} | wars of 1 {w1} | war '
        f'score 1-2 lines {ws} | blockade credits {bc} | AI peace lines {re.findall(VP_AIPEACE_RE, hl)} | share/peace '
        f'lines {re.findall(VP_SHARE_RE, hl)} {re.findall(VP_PEACE_RE, hl)} | merge {log_lines(hl, r"merge nation 1")[:1]}')
    check(f'g) host after the month: nation 1 VP = the credited {credited} + its 1-2 battle points {g1} + its blockade '
          f'points {b1} (0.6.0; the merge kept the host\'s VP; the player\'s copy had {cpre and cpre["vp"].get(1)}); nation '
          f'2 = {vj["vp"][2]} + {g2} + {b2}',
          w1 == [2] and vk['vp'][1] == credited + g1 + b1 and vk['vp'][2] == vj['vp'][2] + g2 + b2 and
          bool(log_lines(hl, r'merge nation 1')), f'wars of 1 {w1}; {vj["raw"]} -> {vk["raw"]}; war score {ws}; {bc}')
    cv = vpinfo(C)
    want_e = sum(max(0, vk['vp'][j]) for j in w1)
    shown = re.findall(VP_SHOWN_RE, cl)
    check(f'g) client vpinfo after the month: every nation\'s VP as on the host (nation 1: {vk["vp"][1]}), "Enemy VP" '
          f'= the VP of the nations at war with 1 {w1} = {want_e} (not the host\'s EnemyVP {vk["enemy"]})',
          cv is not None and cv['vp'] == vk['vp'] and cv['enemy'] == want_e and want_e > 0 and
          want_e != vk['enemy'], f'client {cv and cv["raw"]} | host {vk["raw"]}')
    check(f'g) client log "victory points shown: own {vk["vp"][1]}, enemy {want_e}" once for the new month',
          shown == [(str(vk['vp'][1]), str(want_e))], shown)
    check(f'i) the host\'s EnemyVP is its own: unchanged by the month and the merge ({vj["enemy"]}; the client showed '
          f'{cpre and cpre["enemy"]} and never sends [General])', vk['enemy'] == vj['enemy'],
          f'{vj["enemy"]} -> {vk["enemy"]}')

    # h) a real AI peace (HandleAIPeace sets VP 0 for nations 1-8) while the players' nations are at war with VP
    vh0 = vpinfo(H)
    keep = {n: vh0['vp'][n] for n in VP_PLAYERS if vh0['vp'][n] != 0 and wars_of(n)}
    cmd(H, 'settension 2 3 50')  # nation 2 also fights the AI nation 3
    r23 = rel(2, 3)
    hm = log_mark(H)
    cmd(H, 'aipeace 2 0')
    drain(hp, 6)
    r23b, r12, vh1 = rel(2, 3), rel(1, 2), vpinfo(H)
    got = re.findall(VP_AIPEACE_RE, log_since(H, hm))
    log(f'  h) aipeace 2 0: 2-3 {r23} -> {r23b}, 1-2 {r12} | {vh0["raw"]} -> {vh1["raw"]} | {got}')
    if r23['war'] == '1' and r23b['war'] == '0' and keep:
        want = sorted((str(n), str(p), '0') for n, p in keep.items())
        check(f'h) a real AI peace (aipeace 2 0 ends the AI war 2-3; the players\' war 1-2 goes on): host log "AI '
              f'peace: VP of player nation K kept at P (the game set 0)" for {sorted(keep)}',
              r12['war'] == '1' and sorted(got) == want, f'{got} (want {want}); 1-2 {r12}')
        check(f'h) the players\' nations at war keep their VP {keep}; the AI nations get the game\'s 0',
              all(vh1['vp'][n] == p for n, p in keep.items()) and all(vh1['vp'][n] == 0 for n in VP_AI),
              f'{vh0["raw"]} -> {vh1["raw"]}')
    else:
        log(f'  SKIP h) no AI peace with a player nation at war with VP != 0 (2-3 {r23} -> {r23b}, keep {keep})')

    # end: peace 1-2 (compromise), so the next scenario starts from peace
    warvp(1, 2, 300, 300)
    rc = client_request('diplo peace 2', 'peace', 2)
    ra = cmd(H, 'diploas 2 peace 1')
    vz0 = vpinfo(H)
    hl = apply_diplo(ctx, lambda: rel(1, 2).get('war') == '0')
    vz, r01 = vpinfo(H), rel(0, 1)
    got = sorted(re.findall(VP_PEACE_RE, hl))
    at_peace = [n for n in VP_PLAYERS if not wars_of(n)]
    want = sorted((str(n), str(vz0['vp'][n])) for n in at_peace if vz0['vp'][n])
    log(f'  end: peace 1-2: {vz0["raw"]} -> {vz["raw"]} | {got}')
    check('end: peace 1-2 (client offers, nation 2 accepts, compromise) + applydiplo: 1 and 2 at war with nobody, VP 0, '
          'a "nation K is at peace; V -> 0" line for each that had VP; the host at war with nobody',
          rc == 'ok' and ra == 'ok' and at_peace == list(VP_PLAYERS) and all(vz['vp'][n] == 0 for n in VP_PLAYERS)
          and got == want and r01['hostWars'] == '0', f'{rc} {ra}; at peace {at_peace}; {got} (want {want}); {r01}')
    rz = cmd(H, f'enemyvpadd {-vz["enemy"]}') if vz['enemy'] else 'ok'
    vz = vpinfo(H)
    check('end: the host\'s VP and EnemyVP back at 0 (marker removed), as after the game\'s DoPeace, so later scenarios '
          'meet a host without battles', rz.startswith('ok') and vz['vp'][0] == 0 and vz['enemy'] == 0, vz['raw'])


# ---------------------------------------------------------------- a joined player's "Copy game" (0.2.7)

COPY_SLOTS = (78, 79, 80)  # player_copy's bridge copies: the run refuses to start if one exists; deleted after the run
BUTTON_SLOTS = range(9, 2, -1)  # the game's Copy game dialog takes slots 1-9 only (81 became 9): the highest free one
_button_slot = [None]  # the slot the real button copies to, chosen free before the run (deleted after it)
PLAYER_COPY_RE = (r'player copy in slot (\d+): (.+) is the player nation, (.+) is nation (\d+) \(AI\); (\d+) sections, '
                  r'(\d+) commanders, (\d+) map fields, divisions (\d+) kept / (\d+) dropped, (at war|at peace)')
REL_KEY = re.compile(r'Tension|Allied|TechSharing|AITension\d+|AIAlliance\d+')
NUM_KEY = re.compile(r'Ship\d+BuildingNationIdx|.*A[UT]\d+Nation')
BATTLE_FILES = ('Autosave.sac', 'Autosave.off', 'BattleInfo.bbi')  # the copy must not keep the host's battle
_u32t = ctypes.WinDLL('user32')  # WM_SETTEXT with a string argument (Windows marshals it across processes)
_u32t.SendMessageW.restype = ctypes.c_ssize_t
_u32t.SendMessageW.argtypes = [wt.HWND, wt.UINT, ctypes.c_size_t, wt.LPCWSTR]


def slot_dir(slot):
    return os.path.join(SAVE, f'Game{slot}')


def read_save(path):
    """A save file (.bcs, MapData .dat, .off) as {section: {key: value}} ('' = lines before the first section; the first
    of a repeated key wins), or None."""
    try:
        with open(path, 'rb') as f:
            return parse_save(f.read())
    except OSError:
        return None


def parse_save(raw):
    """read_save of a file's bytes (None stays None)."""
    if raw is None:
        return None
    t = raw.decode('utf-8-sig', errors='replace')
    out, cur = {'': {}}, ''
    for ln in t.splitlines():
        if ln.startswith('[') and ln.endswith(']'):
            cur = ln[1:-1]
            out.setdefault(cur, {})
        elif '=' in ln:
            k, v = ln.split('=', 1)
            out[cur].setdefault(k, v)
    return out


def save_files(slot):
    """{file name: sha256} of a save slot folder ({} if there is none)."""
    return tree_digest(slot_dir(slot)) if os.path.isdir(slot_dir(slot)) else {}


def save_date(slot):
    """(Year, Month) of a slot's .bcs, or None while it can't be read."""
    g = (read_save(save_path(slot)) or {}).get('General')
    return (g.get('Year'), g.get('Month')) if g else None


def gen_date(slot):
    """'<Year>/<Month>/<Day> sip=<ScenarioInProgress>' of a slot's .bcs ('-' if it can't be read): reported where a
    month mismatch between host and client could start (a joined player's turn is merged only when its save's
    [General] Year/Month equal the host's)."""
    g = (read_save(save_path(slot)) or {}).get('General')
    return f'{g.get("Year")}/{g.get("Month")}/{g.get("Day")} sip={g.get("ScenarioInProgress")}' if g else '-'


def ymd(gen):
    """The 'Y/M/D' part of a gen_date string."""
    return gen.split(' ')[0]


INVASION_KEYS = ('ArmyOffensive', 'InvasionTargetName', 'EnemyInvasionTargetName', 'RevolutionPending')


def poss_fields(slot):
    """The possessions of a slot's MapData ([MapAreas]): {'MapArea<i>Possession<j>': {Owner, Name, Value, Invaded,
    InvasionSupport, TakenFrom, ...}} ({} if it can't be read), plus '[General]': the save's invasion keys."""
    d = read_save(os.path.join(slot_dir(slot), f'MapData{slot}.dat')) or {}
    out = {}
    for k, v in (d.get('MapAreas') or {}).items():
        m = re.match(r'(MapArea\d+Possession\d+)([A-Za-z]+)$', k)
        if m:
            out.setdefault(m[1], {})[m[2]] = v
    g = (read_save(save_path(slot)) or {}).get('General') or {}
    out['[General]'] = {k: g.get(k) for k in INVASION_KEYS}
    return out


def poss_changes(a, b):
    """What changed hands between two poss_fields: ['<Name>: <owner> -> <owner> {other changed fields}'], and the
    [General] invasion keys that changed."""
    out = []
    for p, fb in b.items():
        fa = a.get(p, {})
        if p == '[General]':
            ch = {k: (fa.get(k), v) for k, v in fb.items() if fa.get(k) != v}
            if ch:
                out.append(f'[General] {ch}')
        elif fa.get('Owner') != fb.get('Owner'):
            other = {k: (fa.get(k), v) for k, v in fb.items() if k not in ('Owner', 'Name') and fa.get(k) != v}
            out.append(f'{fb.get("Name")} ({p}): {fa.get("Owner")} -> {fb.get("Owner")}' + (f' {other}' if other else ''))
    return out


def ymd_log(gen):
    """A gen_date's date as the mod logs it ('1900-08-01'), or None."""
    try:
        y, m, d = (int(x) for x in ymd(gen).split('/'))
    except ValueError:
        return None
    return f'{y}-{m:02}-{d:02}'


def next_month_ymd(gen):
    """The 'Y/M/D' a month after a gen_date's date, as the game's month advance (IncMonth: the day kept, clamped)."""
    try:
        y, m, d = (int(x) for x in ymd(gen).split('/'))
    except ValueError:
        return None
    y, m = (y + 1, 1) if m == 12 else (y, m + 1)
    return f'{y}/{m}/{min(d, calendar.monthrange(y, m)[1])}'


def slot_snapshot(slot, d=None):
    d = d or slot_dir(slot)
    return dict(slot=slot, files=tree_digest(d) if os.path.isdir(d) else {},
                bcs=read_save(os.path.join(d, f'RTWGame{slot}.bcs')), map=read_save(os.path.join(d, f'MapData{slot}.dat')),
                off=read_save(os.path.join(d, f'RTWGame{slot}.off')))


def ship_ids(sec):
    return [v for k, v in (sec or {}).items() if re.fullmatch(r'Ship\d+Id', k)]


def nation_sections(doc, n):
    """[Nation<n>], [Nation<n>Ships], [Nation<n>Losses], ... (not [Nation<n><digit>...])."""
    p = f'Nation{n}'
    return [s for s in doc if s.startswith(p) and not (len(s) > len(p) and s[len(p)].isdigit())]


def swap_idx(v, k):
    return k if v == 0 else 0 if v == k else v


def is_int(v):
    return bool(re.fullmatch(r'-?\d+', v or ''))


def expected_copy(src, K, eut=None, kwar=None):
    """What the .bcs of a joined player's copy must hold (0.2.7 specification), from the source save `src`: every
    [Nation0*] section trades contents with [NationK*]; relations from K's point of view (the others' Tension/Allied
    = their relation with K, their AITension<K>/AIAlliance<K> = their relation with the old host, TechSharing 0, the
    new nation 0 keeps the player slot's own values); nation numbers 0 <-> K; the host's old ships without commanders;
    [General] war state for K (0.5.0: War = K's own war counter `kwar` as the copying PC knows it when it agrees with K's
    wars, > 0 exactly while at war; else the host's as a guess); [EUT] = the player's cooldowns `eut` (None: unchanged).
    Returns (document, facts)."""
    def gi(doc, sec, key):
        v = doc.get(sec, {}).get(key, '0')
        return int(v) if is_int(v) else 0

    exp = {s: dict(kv) for s, kv in src.items()}
    pairs = 0
    for s in nation_sections(src, 0):
        o = f'Nation{K}' + s[7:]
        if o in src:
            exp[s], exp[o] = dict(src[o]), dict(src[s])
            pairs += 1

    def put(sec, key, val):
        if key in exp.get(sec, {}):
            exp[sec][key] = str(val)

    for key in list(exp['Nation0']):
        if REL_KEY.fullmatch(key) and key in src['Nation0']:
            exp['Nation0'][key] = src['Nation0'][key]
    for x in range(1, 9):
        sec = f'Nation{x}'
        if x == K:  # the old host, now AI nation K: its relations as the host had them
            put(sec, 'Tension', gi(src, sec, 'Tension'))
            put(sec, 'Allied', gi(src, sec, 'Allied'))
            for y in range(1, 9):
                put(sec, f'AITension{y}', 0 if y == K else gi(src, f'Nation{y}', 'Tension'))
                put(sec, f'AIAlliance{y}', 0 if y == K else gi(src, f'Nation{y}', 'Allied'))
        else:
            put(sec, 'Tension', gi(src, sec, f'AITension{K}'))
            put(sec, 'Allied', gi(src, sec, f'AIAlliance{K}'))
            put(sec, f'AITension{K}', gi(src, sec, 'Tension'))
            put(sec, f'AIAlliance{K}', gi(src, sec, 'Allied'))
            put(sec, f'AITension{x}', 0)
            put(sec, f'AIAlliance{x}', 0)
        put(sec, 'TechSharing', 0)
    swaps = commanders = 0
    hk = f'Nation{K}'
    for s, kv in exp.items():
        host_ships = s.startswith(hk) and len(s) > len(hk) and not s[len(hk)].isdigit()
        for k, v in kv.items():
            if not is_int(v):
                continue
            if NUM_KEY.fullmatch(k):
                kv[k] = str(swap_idx(int(v), K))
                swaps += kv[k] != v
            elif host_ships and re.fullmatch(r'Ship\d+CommanderId', k) and v != '-1':
                kv[k] = '-1'
                commanders += 1
    at_war = [x for x in range(1, 9) if gi(exp, f'Nation{x}', 'Tension') > 40]
    enemy_vp = sum(max(0, gi(exp, f'Nation{x}', 'VP')) for x in at_war)
    war = gi(src, 'General', 'War')
    known = kwar is not None and (kwar > 0) == bool(at_war)
    put('General', 'War', kwar if known else (war if war > 0 else 1) if at_war else (-12 if war > 0 else war))
    put('General', 'EnemyVP', enemy_vp)
    put('General', 'ScenarioInProgress', -1)
    for key in ('BattleAlliedNationIdx', 'BattleEnemyAlliedNationIdx'):
        v = src['General'].get(key, '')
        if is_int(v):
            put('General', key, swap_idx(int(v), K))
    for key, val in (('InvasionTargetName', 'XXX'), ('EnemyInvasionTargetName', 'XXX'), ('ArmyOffensive', 0),
                     ('RevolutionPending', 0), ('LastMissionIdx', 20)):
        put('General', key, val)
    if war > 0 and not at_war:  # only the host was at war: as the game's DoPeace leaves it
        for key, val in (('TotalWar', 0), ('TFW', 1), ('HasBeenBattle', 0), ('AutoBuildSubs', 0)):
            put('General', key, val)
    if eut:
        for j in range(100):
            put('EUT', f'EUT{j}', eut[j])
    return exp, dict(pairs=pairs, swaps=swaps, commanders=commanders, at_war=at_war, enemy_vp=enemy_vp,
                     war=(war, exp['General'].get('War')), player_ids=set(ship_ids(exp.get('Nation0Ships'))))


def expected_map(src, K):
    """MapData: MapArea<a>MineLevel<0|K> trade values, MapArea...TakenFrom 0 <-> K. Returns (document, changed lines)."""
    exp, n = {s: dict(kv) for s, kv in src.items()}, 0
    for s, kv in src.items():
        for k, v in kv.items():
            m = re.fullmatch(r'(MapArea\d+MineLevel)(\d+)', k)
            if m and int(m[2]) in (0, K):
                exp[s][f'{m[1]}{swap_idx(int(m[2]), K)}'] = v
                n += 1
            elif k.startswith('MapArea') and k.endswith('TakenFrom') and is_int(v) and int(v) in (0, K):
                exp[s][k] = str(swap_idx(int(v), K))
                n += 1
    return exp, n


def expected_off(src, player_ids):
    """.off: officers kept; [CampaignDivisions] keeps the divisions whose ships are all the new player's (renumbered).
    Returns (document, kept, dropped)."""
    exp = {s: dict(kv) for s, kv in src.items()}
    cd = src.get('CampaignDivisions')
    if cd is None:
        return exp, 0, 0
    divs, other = {}, {}
    for k, v in cd.items():
        m = re.fullmatch(r'CampDiv(\d+)(\D.*)', k)
        if m:
            divs.setdefault(int(m[1]), []).append((m[2], v))
        elif k != 'CampDivNo':
            other[k] = v
    new, kept, dropped = {}, 0, 0
    for n in sorted(divs):
        if all(v in player_ids for f, v in divs[n] if re.fullmatch(r'ShipId\d+', f)):
            new.update({f'CampDiv{kept}{f}': v for f, v in divs[n]})
            kept += 1
        else:
            dropped += 1
    if divs or other:
        exp['CampaignDivisions'] = dict(CampDivNo=str(kept), **new, **other)
    return exp, kept, dropped


def doc_diff(exp, act):
    """[(section, key, expected, actual)] where two documents differ (key None: a section missing on one side)."""
    out = []
    for s in list(exp) + [s for s in act if s not in exp]:
        e, a = exp.get(s), act.get(s)
        if e is None or a is None:
            out.append((s, None, e is not None, a is not None))
            continue
        out += [(s, k, e.get(k), a.get(k)) for k in list(e) + [k for k in a if k not in e] if e.get(k) != a.get(k)]
    return out


def diff_kind(d):
    s, k = d[0], d[1]
    if s == 'EUT':
        return 'eut'
    if k and (NUM_KEY.fullmatch(k) or re.fullmatch(r'Ship\d+CommanderId', k) or 'BattleAllied' in k
              or 'BattleEnemyAllied' in k):
        return 'numbers'
    if s == 'General':
        return 'general'
    if k and re.fullmatch(r'Nation\d+', s) and REL_KEY.fullmatch(k):
        return 'relations'
    if s.startswith('Nation'):
        return 'sections'
    return 'other'


def verify_copy(src, to, K, eut=None, d=None, kwar=None):
    """The copy in slot `to` against the specification applied to the source snapshot `src` (slot_snapshot); kwar: K's
    own war counter on the copying PC (`kwar` on the client while it is in the session; None: unknown, the host's guess).
    Returns dict(diffs={kind: [...]}, facts, files=[problems], act=snapshot of the copy)."""
    act = slot_snapshot(to, d)
    exp_bcs, facts = expected_copy(src['bcs'], K, eut, kwar)
    exp_map, facts['map_fields'] = expected_map(src['map'] or {}, K)
    exp_off, facts['div_kept'], facts['div_dropped'] = expected_off(src['off'] or {}, facts['player_ids'])
    diffs = {}
    for d in doc_diff(exp_bcs, act['bcs'] or {}):
        diffs.setdefault(diff_kind(d), []).append(d)
    diffs['map'] = doc_diff(exp_map, act['map'] or {})
    diffs['off'] = doc_diff(exp_off, act['off'] or {})
    s, sf, af = src['slot'], src['files'], act['files']
    probs = [f'missing {n}' for n in (f'RTWGame{to}.bcs', f'RTWGame{to}.sta', f'MapData{to}.dat') if n not in af]
    if f'RTWGame{s}.off' in sf and f'RTWGame{to}.off' not in af:
        probs.append(f'missing RTWGame{to}.off')
    probs += [f'{n} left in the copy' for n in BATTLE_FILES + ('DesignFiles_swap.tmp',) if n in af]
    if af.get(f'RTWGame{to}.sta') != sf.get(f'RTWGame{s}.sta'):
        probs.append('.sta differs from the source')
    for i in range(9):
        want = sf.get(f'DesignFiles{swap_idx(i, K)}.des')
        if af.get(f'DesignFiles{i}.des') != want:
            probs.append(f'DesignFiles{i}.des != source DesignFiles{swap_idx(i, K)}.des')
    facts['battle_files_in_source'] = [n for n in BATTLE_FILES if n in sf]
    facts['copy_files'] = sorted(af)
    return dict(diffs=diffs, facts=facts, files=probs, act=act)


def client_cooldowns():
    """The joined player's event cooldowns (the 100 'used' values of its events_<hash>.ini for nation 1) or None."""
    for f in event_files():
        try:
            with open(os.path.join(LOG_DIR, f), encoding='utf-8', errors='replace') as fh:
                kv = dict(ln.split('=', 1) for ln in fh.read().splitlines() if '=' in ln)
        except OSError:
            continue
        used = [int(x) for x in kv.get('used', '').split(',') if is_int(x.strip())]
        if kv.get('campaign', '').endswith('|nation1') and len(used) == 100:
            return used
    return None


def visible_boxes(pid):
    """Visible message boxes and game dialogs of a copy: TMessageForm, #32770 and Tdlg* windows."""
    return [h for h in top_windows(pid)
            if e2e_test.class_name(h) in ('TMessageForm', '#32770') or e2e_test.class_name(h).startswith('Tdlg')]


def box_info(h):
    """(dict(cls, title, text, buttons), [(button caption, hwnd)]); text only for Win32 boxes (#32770): a VCL
    TMessageForm shows its text in a TLabel, which has no window."""
    k = e2e_test.class_name(h)
    btns = [(caption(c), c) for c in children(h) if e2e_test.class_name(c) in ('TButton', 'TBitBtn', 'Button')
            and u.IsWindowVisible(c) and u.IsWindowEnabled(c)]
    txt = ' '.join(text(c) for c in children(h) if e2e_test.class_name(c) == 'Static' and text(c)) if k == '#32770' else ''
    return dict(cls=k, title=e2e_test.window_text(h), text=txt.replace('\r', ' ').replace('\n', ' '),
                buttons=[b for b, _ in btns]), btns


def copy_dialogs(pid, confirm, done, who='client', timeout=30, quiet=2.5):
    """Answer the dialogs of a "Copy game" and record them until done(seen) holds and no dialog was open for `quiet` s:
    the game's overwrite confirmation (a box with Yes/OK and No/Cancel: Yes/OK if `confirm`, else No/Cancel), its
    "Saved game copied to slot N" (OK) and the mod's "Multiplayer" box (OK). Other Tdlg* dialogs are recorded and left
    alone (dismiss_dialogs is never used here: on an overwrite prompt it would press OK). Returns [dict(cls, title,
    text, buttons, confirm, pressed)]."""
    seen, pressed, end, last = [], {}, time.time() + timeout, time.time()
    while time.time() < end:
        assert_alive()
        boxes = visible_boxes(pid)
        for h in boxes:
            if time.time() - pressed.get(h, 0) < 1.5:
                continue
            info, btns = box_info(h)
            pos = next((b for b in btns if b[0].lower() in ('yes', 'ok')), None)
            neg = next((b for b in btns if b[0].lower() in ('no', 'cancel')), None)
            info['confirm'] = bool(pos and neg)
            b = None if info['cls'].startswith('Tdlg') else (pos if confirm else neg) if info['confirm'] else \
                pos or (btns[0] if len(btns) == 1 else None)
            info['pressed'] = b[0] if b else None
            if b:
                u.PostMessageW(b[1], 0x00F5, 0, 0)  # BM_CLICK
            pressed[h] = time.time() + (3600 if not b else 0)  # an unexpected dialog is recorded once
            seen.append(info)
            log(f'  {who} copy dialog: {info["cls"]}:"{info["title"]}" {info["buttons"]}'
                + (f' "{info["text"]}"' if info['text'] else '') + f' -> {info["pressed"]}')
        if boxes:
            last = time.time()
        if done(seen) and time.time() - last >= quiet:
            break
        time.sleep(0.3)
    return seen


def copy_lines(port, mark, to):
    return [x.split('] ', 1)[-1] for x in log_lines(log_since(port, mark), rf'player copy in slot {to}:|copy of slot \d+ to {to}\b')]


def transform_done(port, mark, to):
    """done() for copy_dialogs: the hook's log line for slot `to` is there and, after a rewrite (or a failed one), the
    mod's "Multiplayer" box was seen."""
    def done(seen):
        ln = copy_lines(port, mark, to)
        return bool(ln) and (not re.search(r'player copy in slot|failed', ln[0])
                             or any(d['cls'] == '#32770' and d['title'] == 'Multiplayer' for d in seen))
    return done


def sort_dialogs(seen):
    """(confirmations, the mod's "Multiplayer" boxes, the game's other boxes)."""
    conf = [d for d in seen if d['confirm']]
    mp = [d for d in seen if not d['confirm'] and d['cls'] == '#32770' and d['title'] == 'Multiplayer']
    return conf, mp, [d for d in seen if d not in conf and d not in mp]


def copy_with_button(ctx, slot):
    """The player's path: the strategic screen's "Copy game" (TBitBtn btbnSaveToOtherSlot) -> TdlgInputNumber
    (TSpinEdit seNumber, OK, Cancel) -> `slot` -> OK. Posted clicks and WM_SETTEXT only; nothing else answers the
    client's dialogs meanwhile. Returns ('ok' | 'skip', detail)."""
    cp = ctx.cp
    btn = next((h for top in windows_of(cp, 'TfrmBuildCamp') for h in children(top)
                if e2e_test.class_name(h) == 'TBitBtn' and caption(h) == 'Copy game'), None)
    if not btn:
        return 'skip', 'no "Copy game" TBitBtn on the client\'s TfrmBuildCamp'
    if not (u.IsWindowVisible(btn) and u.IsWindowEnabled(btn)):
        return 'skip', f'"Copy game" visible {bool(u.IsWindowVisible(btn))} enabled {bool(u.IsWindowEnabled(btn))}'
    u.PostMessageW(btn, 0x00F5, 0, 0)  # BM_CLICK
    dlg = wait_window(cp, 'TdlgInputNumber', 8)
    if not dlg:
        return 'skip', f'no TdlgInputNumber after BM_CLICK; windows: {describe_windows(cp)}'
    kids = children(dlg)
    spin = next((h for h in kids if e2e_test.class_name(h) == 'TSpinEdit'), None)
    ok = next((h for h in kids if e2e_test.class_name(h) == 'TButton' and caption(h) == 'OK'), None)
    cancel = next((h for h in kids if e2e_test.class_name(h) == 'TButton' and caption(h) == 'Cancel'), None)
    shown = text(spin) if spin else None
    if spin and ok:
        _u32t.SendMessageW(spin, 0x000C, 0, str(slot))  # WM_SETTEXT
        time.sleep(0.3)
    got = text(spin) if spin else None
    if got != str(slot):
        if cancel:
            u.PostMessageW(cancel, 0x00F5, 0, 0)
        wait_window(cp, 'TdlgInputNumber', 5, gone=True)
        return 'skip', f'TSpinEdit {bool(spin)}, OK {bool(ok)}; text {shown!r} -> {got!r}; cancelled'
    u.PostMessageW(ok, 0x00F5, 0, 0)
    gone = wait_window(cp, 'TdlgInputNumber', 5, gone=True)
    return 'ok', f'TdlgInputNumber "{e2e_test.window_text(dlg)}": seNumber {shown!r} -> {got!r}, OK (closed {gone})'


def buildcamp_idle(pid):
    """The strategic screen is visible and enabled and no dialog is open."""
    return not visible_boxes(pid) and any(u.IsWindowEnabled(h) for h in windows_of(pid, 'TfrmBuildCamp')
                                          if u.IsWindowVisible(h))


def single_player_month(ctx, slot, timeout=MONTH_TIMEOUT):
    """The client, out of the session, processes one month of the campaign in `slot` on its own: Turn, the game's
    dialogs answered (events: first answer). The game does not write the slot at the end of a month (the host's
    session saves it itself), so the month counts as done once the game's turn report (TdlgCampTurnRep "Turn
    messages") was answered and the strategic screen is idle for 3 s; no bridge call before that (the game's main
    thread is busy with the month). Then `save` writes the slot (a throwaway copy) and its date is read. Stops without
    answering anything if the battle screen (TfrmMain) or a dialog whose class names a battle shows up."""
    cp, d0, t0, n0 = ctx.cp, save_date(slot), time.time(), len(ANSWERED)
    r = cmd(C, 'turn')
    quiet = None
    while True:
        if time.time() - t0 > timeout:
            return dict(ok=False, why=f'timeout (turn report answered: {any("TdlgCampTurnRep" in a[2] for a in ANSWERED[n0:])}'
                        f'); windows: {describe_windows(cp)}', turn=r, d0=d0, d1=None, dt=time.time() - t0,
                        answered=ANSWERED[n0:])
        assert_alive()
        battle = [f'{e2e_test.class_name(h)}:"{e2e_test.window_text(h)[:40]}"' for h in top_windows(cp)
                  if e2e_test.class_name(h) == 'TfrmMain' or 'battle' in e2e_test.class_name(h).lower()]
        if battle:
            return dict(ok=False, why=f'battle: {battle}', turn=r, d0=d0, d1=None, dt=time.time() - t0,
                        answered=ANSWERED[n0:])
        select_first_answer(cp)
        answer_dialogs(cp, 'client')
        if any('TdlgCampTurnRep' in a[2] for a in ANSWERED[n0:]) and buildcamp_idle(cp):
            quiet = quiet or time.time()
            if time.time() - quiet >= 3:
                break
        else:
            quiet = None
        time.sleep(1.0)
    dt = time.time() - t0
    rs = cmd(C, 'save')
    time.sleep(1)
    return dict(ok=rs == 'ok', why='' if rs == 'ok' else f'save: {rs}', turn=r, d0=d0, d1=save_date(slot), dt=dt,
                answered=ANSWERED[n0:])


def next_month(d):
    y, m = int(d[0]), int(d[1])
    return (str(y + (m == 12)), str(m % 12 + 1))


def fmt_diffs(ds, n=5):
    return '; '.join(f'[{s}] {k}: want {e!r} got {a!r}' for s, k, e, a in ds[:n]) + (f' (+{len(ds) - n})' if len(ds) > n else '')


# ---------------------------------------------------------------- relations v2, B4: peace with the computer's nations

_u32p = ctypes.WinDLL('user32')  # own instance: list box messages with a signed lParam
_u32p.SendMessageW.restype = ctypes.c_ssize_t
_u32p.SendMessageW.argtypes = [wt.HWND, wt.UINT, ctypes.c_size_t, ctypes.c_ssize_t]
_u32p.PostMessageW.argtypes = [wt.HWND, wt.UINT, ctypes.c_size_t, ctypes.c_ssize_t]
_POSS_TRIES = {}  # TdlgPossessions window -> (answers in a row, last time)
PEACE_SENT = r'peace for nation \d+ sent \(|\] peace: '  # the client's proposal / test sent, or why none
PEACE_APPLIED = r'relations v2: peace of nation \d+ with '  # the host applied a peace of a joined nation


def answer_possessions(pid, who='client'):
    """The game's peace dialog "Select possessions as part of peace agreement" (TdlgPossessions: a multi-select list
    box, OK) of one copy: the entry of the lowest value ("Value: n") is selected (LB_SETSEL, then the list's
    LBN_SELCHANGE through the form, as a click does) and OK pressed; if the dialog is still there on the next pass (the
    game refused its value), no entry. The game's own messages over the dialog (bnOKClick) come first, one click a pass:
    "Total value of selected possessions is higher than permitted total value!" gets OK, "You have not selected any
    possessions. ..." (Confirm) Yes (the unused points become resources). Returns the answers; the callers skip
    answer_dialogs in that pass (one click per dialog)."""
    out = []
    tops = [t for t in windows_of(pid, 'TdlgPossessions') if u.IsWindowVisible(t)]
    if tops:
        for mf in (h for h in windows_of(pid, 'TMessageForm') if u.IsWindowVisible(h)):
            kids = []
            u.EnumChildWindows(mf, e2e_test.EnumProc(lambda h, l: kids.append(h) or True), 0)
            btns = {e2e_test.window_text(h).replace('&', '').strip().lower(): h for h in kids
                    if e2e_test.class_name(h) == 'TButton'}
            b = btns.get('yes') or btns.get('ok')
            if b:
                _u32p.PostMessageW(b, 0x00F5, 0, 0)  # BM_CLICK
                a = f'TdlgPossessions message "{e2e_test.window_text(mf)}"->{"Yes" if "yes" in btns else "OK"}'
                ANSWERED.append((time.time(), who, a))
                log(f'  {who} dialog answered: {a}')
                out.append(a)
                time.sleep(0.5)
                return out
    for top in tops:
        kids = []
        u.EnumChildWindows(top, e2e_test.EnumProc(lambda h, l: kids.append(h) or True), 0)
        lb = next((h for h in kids if e2e_test.class_name(h) == 'TListBox'), None)
        ok = next((h for h in kids if e2e_test.class_name(h) == 'TButton'
                   and e2e_test.window_text(h).replace('&', '').strip().lower() == 'ok'), None)
        if not lb or not ok or not u.IsWindowEnabled(top):
            continue
        n_try, last = _POSS_TRIES.get(top, (0, 0))
        n_try = n_try if time.time() - last < 4 else 0
        _POSS_TRIES[top] = (n_try + 1, time.time())
        n = _u32p.SendMessageW(lb, 0x018B, 0, 0)  # LB_GETCOUNT
        values = []
        for i in range(max(0, min(n, 200))):
            ln = _u32p.SendMessageW(lb, 0x018A, i, 0)  # LB_GETTEXTLEN
            buf = ctypes.create_unicode_buffer(max(0, min(ln, 2000)) + 2)
            if 0 <= ln <= 2000:
                _u32p.SendMessageW(lb, 0x0189, i, ctypes.addressof(buf))  # LB_GETTEXT
            m = re.search(r'Value: (\d+)', buf.value)
            values.append(int(m[1]) if m else 1 << 30)
        _u32p.SendMessageW(lb, 0x0185, 0, -1)  # LB_SETSEL: none
        pick = n > 0 and n_try == 0
        first = min(range(len(values)), key=lambda i: values[i]) if values else 0
        if pick:
            _u32p.SendMessageW(lb, 0x0185, 1, first)  # the entry of the lowest value
        _u32p.SendMessageW(top, 0x0111, (1 << 16) | (u.GetDlgCtrlID(lb) & 0xFFFF), lb)  # WM_COMMAND, LBN_SELCHANGE
        time.sleep(0.3)
        _u32p.PostMessageW(ok, 0x00F5, 0, 0)  # BM_CLICK
        a = f'TdlgPossessions:{n} entries->{f"entry {first} (value {values[first]})" if pick else "none"}'
        ANSWERED.append((time.time(), who, a))
        log(f'  {who} dialog answered: {a}')
        out.append(a)
    return out


def wait_peace(ctx, cmark, hmark, timeout=90, who='client'):
    """Relations v2 (B4): after `peacetest` or a proposal, answer the client's peace dialogs (the possessions dialog,
    picture messages, the treaty, questions, an event's answer) until the client logged the peace it sent (or why
    none) and the host applied it, then until no dialog came for 2 s. Returns dict(client, host = their log lines,
    seconds)."""
    t0 = time.time()

    def lines(port, mark, pat):
        return [x.split('] ', 1)[-1] for x in log_lines(log_since(port, mark), pat)]

    while time.time() - t0 < timeout:
        assert_alive()
        if not answer_possessions(ctx.cp, who):
            select_first_answer(ctx.cp)
            answer_dialogs(ctx.cp, who)
        c = lines(C, cmark, PEACE_SENT)
        if c and (lines(H, hmark, PEACE_APPLIED) or ' sent (' not in c[-1]):
            break
        time.sleep(0.5)
    quiet, n = time.time(), len(ANSWERED)
    while time.time() - quiet < 2 and time.time() - t0 < timeout + 20:
        if not answer_possessions(ctx.cp, who):
            answer_dialogs(ctx.cp, who)
        if len(ANSWERED) != n:
            n, quiet = len(ANSWERED), time.time()
        time.sleep(0.4)
    rec = dict(client=lines(C, cmark, PEACE_SENT), host=lines(H, hmark, PEACE_APPLIED), seconds=round(time.time() - t0, 1))
    log(f'  peace: client {[x[:200] for x in rec["client"]]}; host {[x[:220] for x in rec["host"]]} ({rec["seconds"]} s)')
    return rec


def peacelast(port):
    """`peacelast` as a dict of its words (client: ran, code, event, args, accepted, winner, enemies, lands, ships,
    taken, delta, lost, treaty, kwar, shipids 'id:from>to,', landnames 'name~from>to|' (may hold spaces), host, month;
    host: nation, kind, code, event, args, accepted, winner, enemies, lands, ships, states, nations, skipped, blockade,
    vp and '<J>:war|peace,blockade=b' per enemy)."""
    r = value(cmd(port, 'peacelast')) or ''
    d = dict(raw=r)
    m = re.search(r'landnames=(.*?)(?= host=|$)', r)
    if m:
        d['landnames'] = [x for x in m[1].split('|') if x]
        r = r[:m.start()] + r[m.end():]
    for w in r.split(' '):
        if '=' in w:
            k, v = w.split('=', 1)
            d.setdefault(k, v)
    return d


def kwarvp(K=1):
    """Host `kwarvp K`: nation K's war scores with the computer's nations -> dict(vp, evp, pairs={J: (K's, J's)},
    kept={J: (K's, J's)} (also ended wars not erased), peace = used/open, kwar), or None."""
    m = re.match(r'^ok nation=\d+ rules=(\d) vp=(-?\d+) evp=(-?\d+) pairs=(\S*) kept=(\S*) peace=(\w+) kwar=(-?\d+)',
                 cmd(H, f'kwarvp {K}'))
    if not m:
        return None
    pairs = lambda s: {int(f[0]): (int(f[1]), int(f[2])) for f in (x.split(':') for x in s.split(',') if x) if len(f) == 3}
    return dict(rules=m[1] == '1', vp=int(m[2]), evp=int(m[3]), pairs=pairs(m[4]), kept=pairs(m[5]), peace=m[6],
                kwar=int(m[7]))


def nflag(port, n, field):
    v = value(cmd(port, f'nflag {n} {field}'))
    return int(v) if v is not None and v.lstrip('-').isdigit() else None


def ship_holders(port, sid):
    """`findship <id>`: the nations whose ship list holds the ship (one entry per holder)."""
    return [int(x.split(':', 1)[0]) for x in items(cmd(port, f'findship {sid}')) if x.split(':', 1)[0].isdigit()]


def peace_war(K, J, t=50):
    """A war (or peace, t <= 40) between nations K and J on both copies at once (`settension`; no month needed); a war
    started this way gets K's war counter as the game's WarStartsWithNation sets it (1) when it was at peace."""
    for port in (H, C):
        cmd(port, f'settension {K} {J} {t}')
    kw = (kwar_counters(H) or {}).get(K)
    if t > 40 and kw is not None and kw <= 0:
        cmd(H, f'kwar {K} 1')
    return rel(K, J), value(cmd(C, f'rel {K} {J}'))


def scenario_battle_generator(ctx):
    """0.6.0 (B6): the player's battle generator for nation 1 under the player's rules, at war with a computer nation J
    (`settension` on both copies). a) both logs "Player's battle generator for joined nations: ok", the client's hello
    "battle generator 1"; b) `battles gen 1` x20 (CheckForBattles2 in nation 1's view on the host, a dry run): attempts
    with nation 1 on one side and a computer nation on the other only, the host's relations unchanged, all attempts
    (decision 1: < 64, the old cap of 4 gone); `battles gen 1 fault` (decision 3: a game exception in the view): the
    game's error box recorded, not shown, no request, the next run works; c) up to 3
    processed months: the generator runs once a month for nation 1, at most one request of kind 1, no request of the
    computer's generator for nation 1 against a computer nation (suppressed), the request reaches the client, which
    replays its attempts in order (fought: merged); d) risk 4: a request of each kind (`battles injectgen`, `battles inject`)
    declined on the client is merged ("the player declined battle"), never resolved by the game (a preview without an
    enabled Decline is fought); e) `battles aitest 1 J area`: the game's resolution with its result box captured, no
    box on the host; e2) (0.6.1) `battles aitest` where nation J has no ship that can fight: no battle, the game's routine
    not called (it read a nil ship: "Error in DoBattleBetweenAINations procedure!"). The war ends at the end."""
    K = 1
    for port, who in ((H, 'host'), (C, 'client')):
        ln = log_lines(log_since(port), r"Player's battle generator for joined nations")
        check(f'a) {who} log "Player\'s battle generator for joined nations: ok"', any(': ok' in x for x in ln), ln[:2])
    ln = log_lines(log_since(H), r"Player's battle generator: its error box")
    check('a) host log "Player\'s battle generator: its error box in a joined nation\'s view goes to the log" (decision 3: '
          'the ShowMessage of CheckForBattles2\'s except handler hooked)', any('goes to the log' in x for x in ln), ln[:1])
    hl = log_lines(log_since(H), r'battle generator \d')
    check('a) the host logged the client\'s hello with "battle generator 1" (or 2: also surprise attacks, B6 piece 2; 3: '
          'also raider checks, 0.7.0; 4: also invasions, 0.7.0)', any(re.search(r'battle generator [1234]\b', x) for x in hl), hl[:2])
    rr = relrules(H)
    if rr is None or K not in rr:
        log('  nation 1 not under the player\'s rules: forced', cmd(H, f'relrules {K} 1'))
    if not cstate().get('fight'):  # (scenario battles ends with the client joined with `fightbattles 0`)
        log('  the client does not fight its battles: joins again with fightbattles 1', rejoin(ctx, K, True)[0])
    humans = set(kwar_counters(H) or {}) | {0, K, STANDIN}
    cands = [c for c in battle_pairs(K) if c[2] not in humans]
    if not check(f'setup: a computer nation with a possession in a sea area where nation {K} has >= 4 ships', cands,
                 cands[:3]):
        return
    _, _, J, area = cands[0]
    t0 = rel(K, J).get('tension', '5')
    hr, cr = peace_war(K, J)
    check(f'setup: nation {K} at war with computer nation {J} on both copies (was {t0}); battles in {area}',
          hr.get('war') == '1' and 'war=1' in (cr or ''), dict(host=hr, client=cr))
    # b) dry runs
    pairs = [(a, b) for a in range(9) for b in range(a + 1, 9)]
    before = {p: rel(*p).get('tension') for p in pairs}
    reps = [cmd(H, f'battles gen {K}') for _ in range(20)]
    flat = []
    for r in reps:
        for part in [x.strip() for x in (r.split('attempts=', 1)[1] if 'attempts=' in r else '').split(';') if x.strip()]:
            m = re.match(r'^(\d+)>(\d+)', part)
            if m:
                flat.append((int(m[1]), int(m[2])))
    opps = sorted({b if a == K else a for a, b in flat})
    check(f'b) `battles gen {K}` x20: all ok, attempts in {sum(1 for r in reps if "attempts=" in r and r.split("attempts=", 1)[1].strip())}'
          f'/20; every attempt has nation {K} on one side and a computer nation on the other (opponents {opps})',
          all(r.startswith('ok') for r in reps) and flat and all(K in p for p in flat) and not set(opps) & humans,
          reps[:2])
    after = {p: rel(*p).get('tension') for p in pairs}
    check('b) the host\'s relations unchanged by the dry runs', before == after,
          [p for p in pairs if before[p] != after[p]][:6])
    # b) decision 1: the attempts in the generator's order until it has none left (the cap of 64 only bounds a runaway)
    counts = [len([x for x in (r.split('attempts=', 1)[1] if 'attempts=' in r else '').split(';') if x.strip()])
              for r in reps]
    dist = {n: counts.count(n) for n in sorted(set(counts))}
    log(f'  b) attempts per dry run (attempts: runs): {dist}')
    check(f'b) decision 1: every dry run below the cap of 64 attempts (max {max(counts)})', max(counts) < 64, dist)
    if max(counts) > 4:
        check(f'b) decision 1: the old cap of 4 is gone (a dry run with {max(counts)} attempts)', True)
    else:
        log(f'  SKIP b) decision 1: no dry run had more than 4 attempts (the generator\'s own count): {dist}')
    # b) decision 3: a game exception inside the generator in nation K's view: no box, no request
    ids0, t_f, hm = set((battles_list() or {}).get('battles', {})), time.time(), log_mark(H)
    rf = cmd(H, f'battles gen {K} fault')
    tops = [e2e_test.class_name(w) for w in top_windows(ctx.hp)]
    fl = log_lines(log_since(H, hm), rf"the player's battle generator for nation {K}: ")
    ids1 = set((battles_list() or {}).get('battles', {}))
    check(f'b) decision 3: `battles gen {K} fault` -> error "exception in the game\'s battle generator: Error in '
          f'CheckForBattles procedure! ..." (the game\'s except handler\'s box recorded), the host log line, no new '
          f'request, no box on the host (windows, answered error boxes)',
          rf.startswith('error') and "exception in the game's battle generator" in rf and 'Error in CheckForBattles' in rf
          and any('Error in CheckForBattles' in x for x in fl) and not ids1 - ids0 and not game_error_boxes(t_f)
          and not any(c == 'TMessageForm' or c.startswith('Tdlg') for c in tops),
          dict(reply=rf[:160], log=fl[:1], new=sorted(ids1 - ids0), windows=tops))
    r2 = cmd(H, f'battles gen {K}')
    check(f'b) decision 3: a normal `battles gen {K}` after it works', r2.startswith('ok id=0 '), r2[:160])
    # c) months
    fought = None
    for m in range(1, 4):
        if rel(K, J).get('war') != '1':
            log('  the war had ended:', peace_war(K, J))
        hm = log_mark(H)
        drv = BattleDriver(ctx, {}, K, J, fight_any=True)
        drv.label = f'battlegen M{m}'
        run_month(ctx, drv.label, driver=drv)
        hlog = log_since(H, hm)
        gens = log_lines(hlog, rf"the player's battle generator for nation {K} ")
        reqs = log_lines(hlog, r"battle request \d+ \(the player's generator\)")
        comp = [x for x in log_lines(hlog, r'battle request \d+: nation \d+ vs \d+ in ')
                if re.search(rf'nation (?:{K} vs (?!{STANDIN}\b)\d+|\d+ vs {K}) in', x)]
        outs = {b: r.get('outcome') for b, r in drv.rec.items()}
        bids = [int(re.search(r'battle request (\d+)', x)[1]) for x in reqs]
        check(f'c) {drv.label}: the generator ran once for nation {K}; {len(reqs)} request(s) of kind 1 (<= 1), each sent '
              f'to the client with an outcome; no request of the computer\'s generator for nation {K} against a computer '
              f'nation ({len(log_lines(hlog, "left to the player"))} suppressed)',
              len(gens) == 1 and len(reqs) <= 1 and not comp and all(b in outs for b in bids),
              dict(gen=gens, req=reqs, comp=comp[:2], outcomes=outs))
        if drv.fought() is not None:
            fought = drv.fought()
            check(f'c) battle {fought} of the player\'s generator fought on the client and merged on the host',
                  re.search(rf'battle {fought} applied: ', hlog), log_lines(hlog, rf'battle {fought} applied'))
            break
    log('  c) fought:', fought)
    # decision 1: every request of the player's generator so far (also of earlier scenarios' months) was replayed in
    # order on the client: (request, its attempts, the client's "attempt i ... found no battle" indices)
    call = log_since(C)
    replay = [(int(mm[1]), int(mm[2]), [int(i) for i in re.findall(rf'\] battle {mm[1]}: attempt (\d+) \(', call)])
              for mm in re.finditer(r"battle request (\d+) \(the player's generator\): .*?, (\d+) attempt\(s\)",
                                    log_since(H))]
    log(f'  c) requests (id, attempts, attempts the client found no battle in): {replay}')
    if any(r[2] for r in replay):
        check('c) decision 1: the client replayed each request\'s attempts in order (attempt 0, 1, ... found no battle, '
              'then the battle or its decline)', all(ix == list(range(len(ix))) and len(ix) <= n for _, n, ix in replay),
              replay)
    else:
        log('  SKIP c) decision 1 replay order: no request had an attempt that found no battle')
    # d) risk 4: declines merged
    if rel(K, J).get('war') != '1':
        log('  the war had ended:', peace_war(K, J))
    hm = log_mark(H)
    cm = log_mark(C)
    # B6 round 3: stale month state on the client first (wrong ship-type flags; the month's battle fields as an earlier
    # battle leaves them): the month's load and the battle slot must put the month's own values back
    st_set = cmd(C, 'ls shiptypes 010101'), cmd(C, 'battles monthstate set')
    r1 = cmd(H, f'battles injectgen {K} {J} {area}')
    b1 = int(r1.split()[1]) if r1.startswith('ok ') else None
    b0, r0 = inject(K, J, area)
    drv = BattleDriver(ctx, {b: 'decline' for b in (b1, b0) if b}, K, J)
    drv.label = 'battlegen decline'
    run_month(ctx, drv.label, driver=drv)
    hlog = log_since(H, hm)
    month_state_checks(ctx, K, log_since(C, cm), st_set, (b1, b0))
    for b in (b1, b0):
        rec_b = drv.rec.get(b, {})
        o = rec_b.get('outcome')
        merged = re.search(rf'battle {b} applied: .*the player declined battle', hlog)
        game = re.search(rf'battle {b} resolved by the game', hlog)
        check(f'd) battle {b} ({"the player" if b == b1 else "the computer"}\'s generator) declined on the client '
              f'({o}): merged with the decline\'s consequences, never resolved by the game (the enemy\'s decline, no '
              f'battle or a preview without Decline: as such)',
              b is not None and not game and ((o == 'declined' and merged) or o in ('avoided', 'nobattle') or
                                               (o == 'fought' and rec_b.get('no_decline'))),
              dict(outcome=o, lines=log_lines(hlog, rf'battle {b}\b')[-3:]))
    # e) the game's resolution: its box captured
    hm = log_mark(H)
    r = cmd(H, f'battles aitest {K} {J} {area}')
    m = re.match(r'^ok fought=(\d) captured=(\d+)', r)
    check('e) `battles aitest`: the game\'s resolution of a battle of nation 1 ran; its result box (one when it '
          'fought) captured on the host (log "picture message captured"), none shown',
          m and (m[1] == '0' or int(m[2]) >= 1) and not any(e2e_test.class_name(w) == 'TdlgPictureMessage'
                                                           for w in top_windows(ctx.hp)),
          dict(reply=r, log=log_lines(log_since(H, hm), r'picture message captured|ResolveAIBattle')))
    # e2) 0.6.1: the game's routine picks each round's ship without a nil check; a side without a ship that can fight
    # in the area is no battle, the routine is not called (before: the box "Error in DoBattleBetweenAINations
    # procedure! Access violation ... Read of address 000000AC", which held the host's main thread)
    theirs = fighting_ships_by_area(J)
    empty = next((a for a, n in sorted(fighting_ships_by_area(K).items(), key=lambda x: -x[1])
                  if theirs.get(a, 0) == 0), None)
    if empty:
        hm, t_e = log_mark(H), time.time()
        r = cmd(H, f'battles aitest {K} {J} {empty}')
        ln = log_lines(log_since(H, hm), r'ResolveAIBattle')
        check(f'e2) `battles aitest {K} {J} {empty}` (nation {J} has no ship there that can fight): "ok fought=0 '
              f'captured=0", host log "ResolveAIBattle {K}-{J} in {empty}: no battle (ships that can fight there: n/0; '
              f'...)", no game error box',
              r == 'ok fought=0 captured=0' and any(f'ResolveAIBattle {K}-{J} in {empty}: no battle (ships that can '
                                                    f'fight there: ' in x and '/0;' in x for x in ln)
              and not game_error_boxes(t_e), dict(reply=r, log=ln[-2:]))
    else:
        log(f'  e2) no area where nation {K} has ships and nation {J} none: not checked')
    peace_war(K, J, int(t0) if str(t0).lstrip('-').isdigit() else 5)


def month_state_checks(ctx, K, clog, st_set, bids):
    """B6 round 3 (0.6.0): the month's state on a joined player's PC. Before the month the client's ship-type flags
    were set to 010101 and the month's battle fields to 1 (`ls shiptypes 010101`, `battles monthstate set`). The battle
    phase comes before the new month reaches the client: its first battle slot computes the flags with the game's
    CheckShipTypesExist (010101 -> the host's, which its month's ReduceTimeLimits set) and resets the month's fields
    (the 1s -> 0); the new month's load computes them again (-> the host's)."""
    hs = re.search(r'shiptypes=([0-9a-f]{6})', cmd(H, 'ls shiptypes') or '')
    host = hs[1] if hs else None
    check('month state: the client\'s stale values were set (ls shiptypes 010101, battles monthstate set)',
          st_set[0].startswith('ok shiptypes=010101') and 'surprise=1 possession=1 heroic=1 loss=1 convoy=1' in st_set[1],
          st_set)
    slots = [m for m in re.finditer(r"battle (\d+): the month's state in the battle slot: ship-type flags (\w+) -> "
                                    r"(\w+), surprise attack (\d+) -> 0, possession battle (\d+) -> 0, HeroicVictory "
                                    r"(-?\d+) tmpBattlePrestigeLoss (\d+) ImportantConvoy (\d+) -> 0", clog)]
    played = [int(m[1]) for m in slots]
    check(f'month state: every battle slot of the month ({[b for b in bids if b]}) logged its month state, the flags '
          f'equal to the host\'s ({host})', slots and all(b in played for b in bids if b) and
          all(m[3] == host for m in slots), [m[0] for m in slots])
    first = slots[0] if slots else None
    check('month state: the first battle slot computed the flags with the game\'s routine (010101 -> the host\'s) and '
          'reset the month\'s fields left as an earlier battle leaves them (possession battle, HeroicVictory, '
          'tmpBattlePrestigeLoss, ImportantConvoy 1 -> 0)',
          first and first[2] == '010101' and first[3] == host and first[5] == '1' and first[6] == '1' and
          first[7] == '1' and first[8] == '1', first[0] if first else None)
    mm = re.search(r'month: ship-type flags (\w+) -> (\w+)', clog)
    check(f'month state: the new month\'s load computed the ship-type flags with the game\'s routine, equal to the '
          f'host\'s ({host}) (log "month: ship-type flags ... -> ...")', host and mm and mm[2] == host,
          dict(host=host, line=mm[0] if mm else None))
    after = cmd(C, 'battles monthstate')
    check(f'month state: after the battles the client\'s flags are the host\'s ({host}) (`battles monthstate`)',
          host and after.startswith(f'ok flags={host} '), after)


def scenario_battle_surprise(ctx):
    """0.6.0 (B6 piece 2): surprise attacks and takeovers at a war's start for nation 1 under the player's rules (its
    relation turn in its view on the client; a host with welcome `gen` 2). a) both logs "Surprise attacks and takeovers
    at a war's start for a joined nation: ok (CheckForWar's call sites 1/3/1)", the client's hello "battle generator 2",
    the client's `battles state` hostgen=2; b) at peace with everyone, `battles testsa J` (J: Japan, the computer nation
    of the 1896-1924 missions' area) and a month: nation 1's relation turn has J start its war with a takeover (the
    area's first unowned possession, a test pick) and a surprise attack (CheckSurpriseAttack(J, 1) recorded, not run);
    the host: the war 1-J, the takeover applied by name (J owns the possession on both copies), one request of kind 2
    (J>1), the chat lines; c) `battles sadry J k` and `battles sadry J` (DoSurpriseAttack alone in nation 1's view): the
    pairs 1>J (no "No opportunity found" box) and J>1, nothing sent; d) `battles injectsa 1 J` (nation 1 strikes J),
    `battles saretry 10` on the client and a month with a battle driver: both requests of kind 2 reach the client, which
    plays them with the game's CheckSurpriseAttack (its random gates passed by asking again): each a battle (fought,
    declined or avoided: merged) or a clean no-battle (its reason, the host's "No surprise attack" chat), never resolved
    by the game, none of their dialogs on the host. Ends at peace."""
    K = 1
    for port, who in ((H, 'host'), (C, 'client')):
        ln = log_lines(log_since(port), r"Surprise attacks and takeovers at a war's start for a joined nation")
        check(f'a) {who} log "Surprise attacks and takeovers at a war\'s start for a joined nation: ok (CheckForWar\'s '
              f'call sites 1/3/1)"', any("ok (CheckForWar's call sites 1/3/1)" in x for x in ln), ln[:2])
    rr = relrules(H)
    if rr is None or K not in rr:
        log('  nation 1 not under the player\'s rules: forced', cmd(H, f'relrules {K} 1'))
    if not cstate().get('fight'):
        log('  the client does not fight its battles: joins again with fightbattles 1', rejoin(ctx, K, True)[0])
    hl = log_lines(log_since(H), r'battle generator \d')
    check('a) the host logged the client\'s hello with "battle generator 2" (3 since 0.7.0: also raider checks; 4: '
          'invasions)', any(re.search(r'battle generator [234]\b', x) for x in hl), hl[-2:])
    cs = cstate()
    check('a) the client\'s `battles state`: hostgen=2 (the host\'s welcome `gen` 2: surprise attacks and takeovers; 3 '
          'since 0.7.0; 4 with invasions)', cs.get('hostgen') in (2, 3, 4), cs.get('raw'))
    humans = set(kwar_counters(H) or {}) | {0, K, STANDIN}
    nt = nation_table()
    J = 5 if 5 not in humans and 5 in nt else next((j for j in range(3, 9) if j not in humans and j in nt), None)
    if not check('setup: a computer nation J for the surprise (Japan preferred)', J is not None, nt):
        return
    for j in range(9):  # the landing block needs nation 1 at peace (its war counter <= 0 at the relation turn)
        if j != K and rel(K, j).get('war') == '1':
            log(f'  peace {K}-{j} first:', peace_war(K, j, 5))
    kw = (kwar_counters(H) or {}).get(K)
    if kw is not None and kw > 0:  # as the game's DoPeace (War := 0) for the wars `settension` ended
        log(f'  nation {K}\'s war counter {kw} -> 0 (at peace now):', cmd(H, f'kwar {K} 0'))
    t0 = rel(K, J).get('tension', '5')
    hm, cm, hp0 = log_mark(H), log_mark(C), chat(ctx.hp)
    cmd(H, 'mpwindow')
    rt = cmd(C, f'battles testsa {J}')
    check(f'b) `battles testsa {J}` on the client: the next relation turn has nation {J} start its war on nation {K} '
          f'with a surprise', rt.startswith(f'ok testsa={J}'), rt)
    poss0 = pnames(poss_list(H, f'possessions {J}'))
    run_month(ctx, 'battlesa M1')
    hlog, clog = log_since(H, hm), log_since(C, cm)
    sa_c = log_lines(clog, rf'relations v2: surprise attack: nation {J} may strike nation {K}')
    tk_c = log_lines(clog, rf'relations v2: surprise move: nation {J} takes over ')
    pick = log_lines(clog, r'surprise move: test: the takeover picks ')
    sent = log_lines(clog, rf'relations for nation {K} sent: ')
    # the game's CheckForWar runs its landing/takeover step only in 50 % (with the trait 95 %, game.cpp "Surprise attacks
    # and takeovers"): without it the test's pick never runs and the war starts with the surprise attack alone
    plan = log_lines(clog, rf'relations v2: surprise: test: nation {J} plans its war on nation {K} .*the takeover picks')
    no_step = bool(plan and sa_c and not pick and not tk_c)
    if no_step:
        log(f'  SKIP-note b) the takeover: the game\'s CheckForWar skipped its landing/takeover step this time (50 %, '
            f'with the trait 95 %; no "test: the takeover picks" line): the war and the surprise attack alone are checked')
    check(f'b) the client\'s relation turn: nation {J}\'s takeover and its surprise attack recorded in nation {K}\'s view '
          f'(CheckSurpriseAttack({J}, {K}) not run) and sent ("ksa={J},{K};", "sland=1"; without the game\'s takeover '
          f'step "sland=0")',
          sa_c and (tk_c or no_step) and sent and f'ksa={J},{K};' in sent[-1]
          and ('sland=0' if no_step else 'sland=1') in sent[-1],
          dict(sa=sa_c[-1:], take=tk_c[-1:], pick=pick[-1:], sent=[x.split('] ', 1)[-1][-160:] for x in sent[-1:]]))
    name = re.search(r'takes over (.+?) \(owner -1', tk_c[-1])[1] if tk_c and '(owner -1' in tk_c[-1] else None
    req = log_lines(hlog, rf'battle request (\d+) \(surprise attack\): nation {K} vs {J}, 1 attempt\(s\): {J}>{K}')
    app = log_lines(hlog, rf'relations of .* \(nation {K};')
    poss1, cposs = pnames(poss_list(H, f'possessions {J}')), pnames(poss_list(C, f'possessions {J}'))
    took = (not no_step and name and name not in poss0 and name in poss1 and name in cposs and app
            and f'takeover {name} -1->{J}' in app[-1]) or (no_step and app and 'takeover' not in app[-1])
    check(f'b) the host: the war {K}-{J}, the takeover of {name} applied by name (nation {J} owns it on both copies, '
          f'it did not before; without the game\'s takeover step none), one battle request of kind 2 ({J}>{K}) for the '
          f'battle phase',
          rel(K, J).get('war') == '1' and took and len(req) == 1 and app and f'surprise {J}>{K}' in app[-1],
          dict(war=rel(K, J), name=name, req=req, applied=[x.split('] ', 1)[-1][-220:] for x in app[-1:]]))
    hc = chat(ctx.hp)
    want = ([] if no_step else [f'* In a surprise move, {nt[J]["name"]} has taken control of {name}!']) + \
        [f'* Surprise attack? {nt[J]["name"]} may strike {nt[K]["name"]} at the war\'s start.']
    check('b) the chat lines of the takeover and of the surprise attack', not new_chat_missing(hp0, hc, want),
          new_chat_missing(hp0, hc, want))
    bl = battles_list() or {}
    sa1 = int(re.search(r'battle request (\d+)', req[0])[1]) if req else None
    check(f'b) `battles list`: request {sa1} of kind 2 queued (one attempt)',
          sa1 in bl.get('battles', {}) and 'kind=2:att=1' in bl.get('raw', ''), bl.get('raw', '')[:240])
    # c) DoSurpriseAttack alone in nation 1's view (the war 1-J is on): both branches, nothing sent
    cm, t_c = log_mark(C), time.time()
    r1, r2 = cmd(C, f'battles sadry {J} k'), cmd(C, f'battles sadry {J}')
    boxes = [b for b in BOX_SEEN if b[0] >= t_c and 'opportunity' in b[3]]
    tops = [e2e_test.class_name(w) for w in top_windows(ctx.cp)]
    check(f'c) `battles sadry {J} k`: nation {K} strikes {J} (its trait: the pair {K}>{J}, True: no "No opportunity '
          f'found" box); `battles sadry {J}`: {J}>{K}; nothing sent',
          r1 == f'ok ran=1 pairs={K}>{J};' and r2 == f'ok ran=1 pairs={J}>{K};' and not boxes and
          'TMessageForm' not in tops and not log_lines(log_since(C, cm), rf'relations for nation {K} sent'),
          dict(r1=r1, r2=r2, boxes=boxes, windows=tops))
    # d) both directions played on the client
    r3 = cmd(H, f'battles injectsa {K} {J}')
    sa2 = int(r3.split()[1]) if r3.startswith('ok ') else None
    r4 = cmd(C, 'battles saretry 10')
    check(f'd) `battles injectsa {K} {J}` (request {sa2}, kind 2) and `battles saretry 10` on the client',
          sa2 is not None and r4 == 'ok saretry=10', dict(inject=r3, retry=r4))
    hm, cm, hp0, t_d = log_mark(H), log_mark(C), chat(ctx.hp), time.time()
    # both planned 'fight': the first that comes to a battle is fought, the other declined (the driver's rule; a
    # defence has no Decline: fought too)
    drv = BattleDriver(ctx, {b: 'fight' for b in (sa1, sa2) if b}, K, J)
    drv.label = 'battlesa M2'
    run_month(ctx, drv.label, driver=drv)
    hlog, clog, hc = log_since(H, hm), log_since(C, cm), chat(ctx.hp)
    for b, (att, dfn) in ((sa1, (J, K)), (sa2, (K, J))):
        if b is None:
            continue
        o = drv.rec.get(b, {}).get('outcome')
        sw = lambda v: 0 if v == K else K if v == 0 else v
        st = log_lines(clog, rf'StartSurpriseAttack {sw(att)} attacks {sw(dfn)} -> ')
        merged = re.search(rf'battle {b} applied: ', hlog)
        nob = log_lines(hlog, rf'battle {b} \(kind 2\): no battle \(')
        game = re.search(rf'battle {b} resolved by the game', hlog)
        check(f'd) request {b} ({att} strikes {dfn}): sent to the client, played with the game\'s CheckSurpriseAttack '
              f'(slot indices {sw(att)}>{sw(dfn)}); {o}: merged, or a clean no-battle with its reason; never resolved '
              f'by the game', re.search(rf'battle {b} sent to ', hlog) and st and not game and
              ((o in ('fought', 'declined', 'avoided') and merged) or (o == 'nobattle' and nob)),
              dict(outcome=o, start=[x.split('] ', 1)[-1] for x in st[-2:]], nobattle=nob[-1:],
                   answers=drv.rec.get(b, {}).get('answers', [])[:6], lines=log_lines(hlog, rf'battle {b}\b')[-3:]))
    hb = [b for b in BOX_SEEN if b[0] >= t_d and b[1] == 'host' and re.search(r'urprise|Mobiliz', b[3])]
    check('d) none of the surprise attacks\' dialogs on the host (map message, mobilization question, boxes)', not hb, hb)
    log('  d) chat:', [x for x in hc.splitlines()[-12:] if 'urprise' in x or 'battle' in x.lower()])
    cmd(C, 'battles saretry 0')
    peace_war(K, J, int(t0) if str(t0).lstrip('-').isdigit() and int(t0) <= 40 else 5)


# The host's log when a ship a joined nation's peace hands over is not that nation's on the host (game.cpp HandOverShip).
PEACE_SHIP_SKIPPED = r"relations v2: peace of nation {K}: ship (\d+) \(.*?\) skipped: not among nation {K}'s ships"


def raider_merge_check(drv, bid, K, J, tag, forced_line):
    """0.7.0: a raider battle's result in the host's save. Every field of nation K's and J's ships that the battle slot
    changed (relative to the host's save at the battle phase's start; intel fields, BuildingNationIdx and Used excluded:
    a raider battle's merge keeps the host's Used marks) has the slot's value in the merged save, sunk ships are gone;
    the two ships the test put in place (`battles testraid`) have their own status and area back (unless sunk)."""
    s0, g87, s1 = drv.s0, drv.g87.get(bid), drv.s1.get(bid)
    if not check(f'{tag}: the saves for the merge check (phase start, battle slot, merged)', s0 and g87 and s1,
                 dict(s0=bool(s0), g87=bool(g87), s1=bool(s1))):
        return
    skip = ('PlayerIntel', 'EnemyClassName', 'EnemySpeed', 'EnemyBelt', 'BuildingNationIdx', 'Used')
    bad, changed, sunk = [], 0, 0
    for slot_n, host_n in ((0, K), (J, J)):
        before = ships_by_id(s0.get(f'Nation{host_n}Ships'))
        after = ships_by_id(g87.get(f'Nation{slot_n}Ships'))
        merged = ships_by_id(s1.get(f'Nation{host_n}Ships'))
        for sid, f0 in before.items():
            fa = after.get(sid)
            if fa is None or fa.get('Status') == '8':
                sunk += 1
                if sid in merged and merged[sid].get('Status') != '8':
                    bad.append((host_n, sid, 'sunk in the battle slot, afloat in the merged save'))
                continue
            for k, v in fa.items():
                if k in skip or f0.get(k) == v:
                    continue
                changed += 1
                if merged.get(sid, {}).get(k) != v:
                    bad.append((host_n, sid, k, v, merged.get(sid, {}).get(k)))
    check(f'{tag}: merged on the host: every ship field of nations {K} and {J} the battle changed ({changed}) has the '
          f'battle slot\'s value, sunk ships ({sunk}) gone (the Used marks stay the host\'s)', not bad, bad[:5])
    m = re.search(r'raider (.+?) \(status (\d+)\) and patrol (.+?) \(status (\d+)\) in (.+)$', forced_line or '')
    if not m:
        return
    leak = []
    for name in (m[1], m[3]):
        for host_n in (K, J):
            f0 = next((f for f in ships_by_id(s0.get(f'Nation{host_n}Ships')).values() if f.get('Name') == name), None)
            f1 = next((f for f in ships_by_id(s1.get(f'Nation{host_n}Ships')).values() if f.get('Name') == name), None)
            if f0 and f1 and f1.get('Status') != '8' and (f0.get('Status'), f0.get('LocationAreaName')) != \
                    (f1.get('Status'), f1.get('LocationAreaName')):
                leak.append((host_n, name, f0.get('Status'), f1.get('Status'), f0.get('LocationAreaName'),
                             f1.get('LocationAreaName')))
    check(f'{tag}: the test\'s own setup did not reach the host (the raider {m[1]} and the patrol {m[3]}: status and '
          f'sea area in the merged save as sent, unless sunk)', not leak, leak)


def scenario_battle_raider(ctx):
    """0.7.0: raiders against patrols for nation 1 under the player's rules, at war with a computer nation J. a) both logs
    "Raiders against patrols for joined nations: ok", the client's hello "battle generator 3", its `battles state`
    hostgen=3 testraid=off; b) `battles gen 1` x20 (dry runs): the game's raider checks recorded in nation 1's view
    ("raider check" attempts: up to two a month, each after Random(100) < 30), the host's relations unchanged; c) four
    months, each with a request of one raider check (`battles injectraid 1`) and the client's `battles testraid <side> J`
    (the next raider check: the pair put in place in the battle slot, CheckRaiderInterceptions' draws 0): side 0 (our
    raider intercepted) and side 1 (our patrol intercepts), each fought (RaiderBattleDialog "Fight Battle") and
    auto-resolved ("Auto resolve": QuickResolveRaiderBattle): the game's CheckRaiderVsPatrols found the interception
    with its "thwarts" lines; outcome fought, merged on the host ("; a raider battle[, auto-resolved]"), the merge
    cross-checked, the test's setup not merged; the "thwarts" lines in nation 1's news (the client's chat with the new
    month), not in the host's chat; the host unchanged (nation 0's ships as at the phase start, no raider box on the
    host); the host's chat line. The war ends at the end."""
    K = 1
    for port, who in ((H, 'host'), (C, 'client')):
        ln = log_lines(log_since(port), r'Raiders against patrols for joined nations')
        check(f'a) {who} log "Raiders against patrols for joined nations: ok"', any(': ok' in x for x in ln), ln[:1])
    hl = log_lines(log_since(H), r'battle generator \d')
    check('a) the host logged the client\'s hello with "battle generator 3" (raider checks, 0.7.0; 4: also invasions)',
          any(re.search(r'battle generator [34]\b', x) for x in hl), hl[-1:])
    rr = relrules(H)
    if rr is None or K not in rr:
        log('  nation 1 not under the player\'s rules: forced', cmd(H, f'relrules {K} 1'))
    if not cstate().get('fight'):
        log('  the client does not fight its battles: joins again with fightbattles 1', rejoin(ctx, K, True)[0])
    cs = cstate()
    check('a) the client\'s `battles state`: hostgen=3 (the host\'s welcome `gen` 3; 4 with invasions), testraid=off',
          cs.get('hostgen') in (3, 4) and cs.get('testraid') == 'off', cs.get('raw'))
    humans = set(kwar_counters(H) or {}) | {0, K, STANDIN}
    cands = [c for c in battle_pairs(K) if c[2] not in humans]
    if not check(f'setup: a computer nation with a possession in a sea area where nation {K} has >= 4 ships', cands,
                 cands[:3]):
        return
    _, _, J, _ = cands[0]
    nt = nation_table()
    t0 = rel(K, J).get('tension', '5')
    hr, cr = peace_war(K, J)
    check(f'setup: nation {K} at war with computer nation {J} on both copies (was {t0})',
          hr.get('war') == '1' and 'war=1' in (cr or ''), dict(host=hr, client=cr))
    pairs = [(a, b) for a in range(9) for b in range(a + 1, 9)]
    before = {p: rel(*p).get('tension') for p in pairs}
    reps = [cmd(H, f'battles gen {K}') for _ in range(20)]
    runs = sum(1 for r in reps if 'raider check' in r)
    check(f'b) `battles gen {K}` x20: all ok; the game\'s raider checks recorded in nation {K}\'s view as attempts '
          f'({sum(r.count("raider check") for r in reps)} in {runs} of 20 runs; at most 2 a run)',
          all(r.startswith('ok') for r in reps) and runs >= 1 and all(r.count('raider check') <= 2 for r in reps),
          [r[:160] for r in reps if 'raider check' in r][:2] or reps[:2])
    after = {p: rel(*p).get('tension') for p in pairs}
    check('b) the host\'s relations unchanged by the dry runs', before == after,
          [p for p in pairs if before[p] != after[p]][:6])
    names = {0: 'our raider intercepted', 1: 'our patrol intercepts'}
    cmd(H, 'mpwindow')
    cmd(C, 'mpwindow')
    for side, action in ((0, 'fight'), (0, 'quick'), (1, 'fight'), (1, 'quick')):
        tag = f'c) side {side} ({names[side]}), {"fought" if action == "fight" else "auto-resolved"}'
        if rel(K, J).get('war') != '1':
            log('  the war had ended:', peace_war(K, J))
        rt = cmd(C, f'battles testraid {side} {J}')
        r1 = cmd(H, f'battles injectraid {K}')
        bid = int(r1.split()[1]) if r1.startswith('ok ') else None
        if not check(f'{tag}: `battles testraid {side} {J}` (client), `battles injectraid {K}` (host)',
                     rt == f'ok testraid={side}:{J}' and bid, dict(testraid=rt, inject=r1)):
            continue
        hm, cm, hc0, cc0, t_b = log_mark(H), log_mark(C), chat(ctx.hp), chat(ctx.cp), time.time()
        drv = BattleDriver(ctx, {bid: action}, K, J)
        drv.label = f'battleraid {side}{action[0]}'
        run_month(ctx, drv.label, driver=drv)
        hlog, clog = log_since(H, hm), log_since(C, cm)
        rec = drv.rec.get(bid, {})
        forced = log_lines(clog, rf'StartRaiderCheck: TEST: forced interception \(side {side}, nation {J}\): raider ')
        res = log_lines(clog, r'StartRaiderCheck: True, interception yes')
        nmsg = re.search(r', (\d+) new turn message', res[-1]) if res else None
        check(f'{tag}: the client put the pair in place and the game\'s CheckRaiderVsPatrols found the interception '
              f'(nation {J}, side {side}) with its "thwarts" lines (new turn messages)',
              forced and res and f'(nation {J}, side {side},' in res[-1] and nmsg and int(nmsg[1]) >= 1,
              dict(forced=[x.split('] ', 1)[-1][-150:] for x in forced[-1:]], res=[x.split('] ', 1)[-1] for x in res[-1:]]))
        want = 'auto-resolved' if action == 'quick' else 'fought'
        att = log_lines(clog, rf'battle {bid}: attempt 0 \(raider check\): ')
        check(f'{tag}: battle {bid}: the raider battle {want} on the client (RaiderBattleDialog answered '
              f'"{"Auto resolve" if action == "quick" else "Fight Battle"}"), sent as fought',
              att and f'({want})' in att[-1] and rec.get('outcome') == 'fought' and rec.get('raider_dialog'),
              dict(att=[x.split('] ', 1)[-1] for x in att[-1:]], outcome=rec.get('outcome'), answers=rec.get('answers')))
        applied = log_lines(hlog, rf'battle {bid} applied: ')
        tail = 'a raider battle, auto-resolved' if action == 'quick' else 'a raider battle'
        check(f'{tag}: the host merged it ("battle {bid} applied: ...; {tail}")',
              applied and applied[-1].rstrip().endswith(tail), [x.split('] ', 1)[-1] for x in applied[-1:]])
        raider_merge_check(drv, bid, K, J, tag, forced[-1] if forced else None)
        thwart = [x.split(f'news for nation {K}: ', 1)[1] for x in log_lines(hlog, rf'battle {bid}: news for nation {K}: ')]
        cc1, hc1 = chat(ctx.cp), chat(ctx.hp)
        check(f'{tag}: the "thwarts" lines in nation {K}\'s news (host log; the client\'s chat with the new month), not '
              f'in the host\'s chat', thwart and any(' thwarts ' in t for t in thwart) and
              not new_chat_missing(cc0, cc1, ['* ' + t for t in thwart]) and not any(t in hc1 for t in thwart),
              dict(news=thwart[:3], missing=new_chat_missing(cc0, cc1, ['* ' + t for t in thwart])[:2]))
        s0, s1 = drv.s0, drv.s1.get(bid)
        host_boxes = [b[2:] for b in BOX_SEEN if b[0] >= t_b and b[1] == 'host' and
                      (b[2] == 'TdlgMapMessage' or 'raider' in b[3].lower() or 'intercept' in b[3].lower())]
        check(f'{tag}: the host unchanged: nation 0\'s ships in the merged save as at the phase start; no raider dialog '
              f'or box on the host; no game error box', s0 and s1 and s0.get('Nation0Ships') == s1.get('Nation0Ships')
              and not host_boxes and not game_error_boxes(t_b), dict(boxes=host_boxes[:3], errors=game_error_boxes(t_b)))
        pat = (rf'\* The raider battle of {re.escape(nt[K]["name"])} against {re.escape(nt[J]["name"])}.* was '
               rf'{want} by ')
        check(f'{tag}: the host\'s chat "* The raider battle of ... was {want} by ..."',
              not new_chat_missing(hc0, hc1, [], pat), pat)
    natural = log_lines(log_since(H), r"battle request \d+ \(the player's generator\): .*raider check")
    log(f'  natural requests with raider checks this run: {len(natural)}; the client\'s raider checks without an '
        f'interception: {len(log_lines(log_since(C), r"attempt \d+ \(raider check\) found no interception"))}')
    peace_war(K, J, int(t0) if str(t0).lstrip('-').isdigit() else 5)


def scenario_battle_invasion(ctx):
    """0.7.0: invasions for nation 1 under the player's rules (hello `gen` 4), at war with a computer nation J. a) both
    logs "Invasions for joined nations: ok", the client's hello "battle generator 4", `inv form` hostgen=4; b) month 1:
    the client's invasion target (`inv pick`, the form's InvasionTarget as the game's button sets it) on the host's
    possession -> refused ("a person plays its owner"); nation 1 invading J's possession p1 (`inv set p1 1 2`) with the
    routine's own draws low (`inv rnd 1`) -> CheckRebellionAndInvasions in nation 1's view after the month: its texts in
    nation 1's news (host log, the client's turn report), p1 captured (owner 1) or the invasion defeated (not invaded), the
    host's own call hid it (once, logged); the host's own invasion of J's possession q begun this month (`inv set q 0 1
    itt`) kept across the turn's reload (InvadedThisTurn: "kept across the reload: 1 of 1") and skipped by the host's
    routine (still invaded, the mark consumed); c) month 2: the client's target t (J's, value < 10) taken (count 0), J
    invading nation 1's possession kp (`inv set kp J 0`), draws low: kp repelled or taken by J; the plan's months or its
    start in the news; the target's cost in nation 1's month ("invasion target -N"); the client's form holds nation
    1's plan after the load; the host's relations unchanged; no box on the host. e) P3, invasion battles in nation 1's
    battle slot (`battles injectinv 1`, client `battles testinv 1`: a plain check): e1) its own battle at J's t2 where it
    has ships (pending 1), fought, merged, the slot's state back = the host's; e2) J's pending landing at nation 1's
    possession where it has most ships, declined in the preview (or fought): the outcome's state back and applied; e3)
    fix-afb: its own battle at J's possession where J is the strongest against its ships, the setup as an intelligence
    coup's ambush (client `battles testcoup 1`): the game's reinforcements of its side get its nation, no
    AdjustForcesForBattle box, declined (env RTW3_INV_COUP=2, diagnosis: the game's own path, its box). f) P5: its peace with J
    (`peacetest 100 2 1`) ends its invasions with J and its plan; g) P4: `battles testsa J2 land` and a month: J2's
    surprise landing in its possession recorded (`kland`) and applied (invaded, marked); h) P7: `inv escort J2` (+80
    for its invasion, the escort's points for its possession in J2's plan) and a month's AI calls; i) i1 a computer
    start in its month, i2 its capture of J's possession, i3 the host's `inv hostcheck` refusal; j) the host's
    DoPeace (`inv hostpeace`) leaves its invasions."""
    K = 1
    for port, who in ((H, 'host'), (C, 'client')):
        ln = log_lines(log_since(port), r'Invasions for joined nations')
        check(f'a) {who} log "Invasions for joined nations: ok"', any(': ok' in x for x in ln), ln[:1])
    rr = relrules(H)
    if rr is None or K not in rr:
        log('  nation 1 not under the player\'s rules: forced', cmd(H, f'relrules {K} 1'))
    if not cstate().get('fight'):
        log('  the client does not fight its battles: joins again with fightbattles 1', rejoin(ctx, K, True)[0])
    hl = log_lines(log_since(H), r'battle generator \d')
    check('a) the host logged the client\'s hello with "battle generator 4" (invasions)',
          any(re.search(r'battle generator 4\b', x) for x in hl), hl[-1:])
    f0 = cmd(C, 'inv form')
    check('a) the client\'s `inv form`: hostgen=4 (the host\'s welcome `gen` 4)', 'hostgen=4' in f0, f0)
    humans = set(kwar_counters(H) or {}) | {0, K, STANDIN}
    J, small = None, []
    for j in range(1, 9):
        if j in humans:
            continue
        pl = [p for p in (poss_list(H, f'possessions {j}') or []) if 0 < p['value'] < 10]
        if len(pl) >= 3:
            J, small = j, pl
            break
    kp = [p for p in (poss_list(H, f'possessions {K}') or []) if p['value'] < 200]
    hp = poss_list(H, 'possessions 0') or []
    if not check('setup: a computer nation J with 3 possessions of value 1..9, nation 1 and the host with possessions',
                 J and kp and hp, dict(J=J, kp=len(kp), hp=len(hp))):
        return
    u = lambda n: n.replace(' ', '_')
    p1, q = small[0]['name'], small[1]['name']
    t = next((p['name'] for p in small[2:] if p['area'] != small[0]['area']), small[2]['name'])
    k1 = kp[0]['name']
    t0 = rel(K, J).get('tension', '5')
    hr, cr = peace_war(K, J)
    check(f'setup: nation {K} at war with computer nation {J} on both copies (was {t0})',
          hr.get('war') == '1' and 'war=1' in (cr or ''), dict(host=hr, client=cr))
    pairs = [(a, b) for a in range(9) for b in range(a + 1, 9)]

    def owner_of(name):
        for n in range(9):
            if any(p['name'] == name for p in (poss_list(H, f'possessions {n}') or [])):
                return n
        return -1

    def inv_of(name):
        m = re.search(rf';{re.escape(name)}:(-?\d+):(-?\d+):(-?\d+)(:itt)?;', ';' + cmd(H, 'inv state').split(' all=', 1)[-1])
        return (int(m.group(1)), int(m.group(2)), int(m.group(3)), bool(m.group(4))) if m else None

    def inv_box(text):  # a box with nation 1's invasion texts (the host's own month shows its own boxes)
        return any(n in text for n in (p1, k1, t)) or 'nvasion' in text or 'troops' in text

    # b) month 1
    rp = cmd(C, f'inv pick {u(hp[0]["name"])}')
    r1 = cmd(H, f'inv set {u(p1)} {K} 2')
    r2 = cmd(H, f'inv set {u(q)} 0 1 itt')
    r3 = cmd(H, 'inv rnd 1')
    check('b) setup: client `inv pick` (the host\'s possession), host `inv set` p1 (nation 1 invades, support 2), q (the '
          'host invades, marked this month), `inv rnd 1`', all(x.startswith('ok') for x in (rp, r1, r2, r3)),
          dict(pick=rp[:120], p1=r1[-200:], q=r2[-120:], rnd=r3))
    before = {p: rel(*p).get('tension') for p in pairs}
    hm, cm, hc0, cc0, t_b = log_mark(H), log_mark(C), chat(ctx.hp), chat(ctx.cp), time.time()
    run_month(ctx, 'invasion 1', driver=BattleDriver(ctx, {}, K, J))  # (its invasion battles: declined or fought)
    cmd(H, 'inv rnd 0')
    hlog, clog, hc1, cc1 = log_since(H, hm), log_since(C, cm), chat(ctx.hp), chat(ctx.cp)
    ref = log_lines(hlog, rf'invasions: nation {K}\'s target {re.escape(hp[0]["name"])} refused \(a person plays its owner')
    check(f'b) the host\'s possession as nation 1\'s target refused ("a person plays its owner")', ref, ref)
    kept = log_lines(hlog, r'host turn: invaded this month kept across the reload: \d+ of \d+')
    marks = cmd(H, 'inv marks')
    check('b) the host\'s own invasion of q begun this month: its InvadedThisTurn set again after the turn\'s reload ("1 '
          'of 1": the load had cleared it) and still set after the month (`inv marks`; the host at peace: the game '
          'cancels the invasion, not the mark)', kept and re.search(r': 1 of 1', kept[0]) and f'{q}/' in marks and
          inv_of(q) is None, dict(kept=kept, marks=marks, q=inv_of(q)))
    cmd(H, f'inv set {u(q)} -1 0')
    hid = log_lines(hlog, r'invasions: the host\'s own routines and the joined nations\' invasions this month: ')
    check('b) the host\'s own CheckRebellionAndInvasions hid nation 1\'s invasion (logged once this month)',
          len(hid) == 1 and re.search(r'CheckRebellionAndInvasions 1x \([1-9]\d* hidden\)', hid[0]), hid)
    run = log_lines(hlog, rf'invasions of nation {K} \(war counter -?\d+\): ')
    news = [m.group(1) for m in (re.search(rf'invasions of nation {K}: "(.*)"$', x) for x in hlog.splitlines()) if m]
    o1, i1 = owner_of(p1), inv_of(p1)
    took = o1 == K and log_lines(hlog, rf'invasions: nation {K}\'s month: {re.escape(p1)} passes from nation {J} to nation {K}')
    lost = o1 == J and (i1 is None or i1[1] == -1) and any('defeated' in n for n in news)
    check(f'b) nation {K}\'s month resolution ran in its view: p1 {p1} taken (owner {K}, the game\'s ChangePossessionOwner) '
          f'or the invasion defeated; its texts in nation {K}\'s news', run and news and (took or lost or
          (o1 == J and i1 and i1[1] == K)), dict(run=run[:1], news=news[:4], owner=o1, inv=i1))
    shown = [int(m.group(1)) for m in (re.search(r'economy: showing (\d+) message\(s\)', x) for x in clog.splitlines()) if m]
    check('b) the news shown in the client\'s turn report with the new month ("economy: showing N message(s)", N >= the '
          'invasion texts)', news and shown and max(shown) >= len(news), dict(shown=shown, news=len(news)))
    hbox = [b[2:] for b in BOX_SEEN if b[0] >= t_b and b[1] == 'host' and inv_box(b[3])]
    check('b) no invasion box on the host (the routine\'s pictures and turn messages went to nation 1; the host\'s own '
          'month shows its own)', not hbox, hbox[:3])
    # c) month 2
    rp = cmd(C, f'inv pick {u(t)}')
    r1 = cmd(H, f'inv set {u(k1)} {J} 0')
    cmd(H, 'inv rnd 2')  # high: the plan's gate Random(20) > Value passes; the fights neither repelled nor lost
    hm, cm, cc0 = log_mark(H), log_mark(C), chat(ctx.cp)
    run_month(ctx, 'invasion 2', driver=BattleDriver(ctx, {}, K, J))  # (its invasion battles: declined or fought)
    cmd(H, 'inv rnd 0')
    hlog, clog, cc1 = log_since(H, hm), log_since(C, cm), chat(ctx.cp)
    st = cmd(H, f'inv state {K}')
    taken = log_lines(hlog, rf'invasions: nation {K}\'s target - -> {re.escape(t)}$')
    check(f'c) the client\'s target t {t} (J\'s, value < 10) taken by the host with its turn', rp.startswith('ok') and taken,
          dict(pick=rp[:100], log=taken, state=st[:200]))
    news = [m.group(1) for m in (re.search(rf'invasions of nation {K}: "(.*)"$', x) for x in hlog.splitlines()) if m]
    plan = [n for n in news if t in n]
    check(f'c) nation {K}\'s plan resolved in its month (the game\'s texts about {t}: delayed, invaded or a battle next '
          f'month)', plan or 'pending=1' in st or re.search(rf'(?:=|;){re.escape(t)}:{J}:{K}:', st), dict(plan=plan[:2], state=st[:200]))
    ok2, ik = owner_of(k1), inv_of(k1)
    check(f'c) J\'s invasion of nation {K}\'s possession kp {k1}: repelled, taken by J (owner {J}) or still fought, in '
          f'nation {K}\'s news', any(k1 in n for n in news) and (ok2 == J or (ok2 == K and (ik is None or ik[1] == J))),
          dict(news=[n for n in news if k1 in n][:2], owner=ok2, inv=ik))
    cost = log_lines(hlog, r'invasion target -\d+')
    check(f'c) the target\'s monthly cost in nation {K}\'s month ("invasion target -N", N > 0)',
          any(re.search(r'invasion target -[1-9]\d*', x) for x in cost), cost[:1])
    form = log_lines(clog, rf'invasions: nation {K}\'s plan in the form \(the month\'s load\): ')
    f1 = cmd(C, 'inv form')
    tgt = re.search(r' target=([^ ]*(?: [^ =]+)*) count=', st)
    check('c) the client\'s form holds nation 1\'s plan after the load (`inv form` = the host\'s `inv state` target)',
          form and tgt and f1.startswith(f'ok target={tgt.group(1)} '), dict(form=form[:1], inv_form=f1, state=st[:160]))
    # d) nation 1's month resolution now (`inv run`), draws high: the host's relations and boxes unchanged
    if not taken:
        cmd(H, f'inv target {K} {u(t)}')
    before = {p: rel(*p).get('tension') for p in pairs}
    cmd(H, 'inv rnd 2')
    t_b, s0 = time.time(), cmd(H, f'inv state {K}')
    rr = cmd(H, f'inv run {K}')
    cmd(H, 'inv rnd 0')
    hbox = [b[2:] for b in BOX_SEEN if b[0] >= t_b and b[1] == 'host' and inv_box(b[3])]
    check(f'd) `inv run {K}`: the routine ran in nation {K}\'s view (its plan: a text about {t} or its months +1), the '
          f'host\'s relations unchanged, no box on the host', rr.startswith('ok') and (t in rr or 'plan ' + t + '/' in rr)
          and before == {p: rel(*p).get('tension') for p in pairs} and not hbox,
          dict(run=rr[:300], before=s0[:120], boxes=hbox[:2], changed=[p for p in pairs if before[p] != rel(*p).get('tension')][:4]))
    # e) P3: invasion battles in nation 1's battle slot (the game's CheckForInvasionBattles, `battles injectinv`), each
    #    check plain (client `battles testinv 1`: the computer does not decline, the player is not caught out)
    nt = nation_table()
    cmd(H, 'mpwindow')  # (the chat lines are read from the window)

    def clear_k():
        for e in (cmd(H, f'inv state {K}').split(' poss=', 1)[-1].split(' cost=', 1)[0]).split(';'):
            if e.count(':') >= 3:
                cmd(H, f'inv set {u(e.split(":")[0])} -1 0')

    def inv_battle(tag, plan_cmds, action, poss):
        clear_k()
        for port, c in plan_cmds:
            log(f'  {c}:', cmd(port, c))
        ti = cmd(C, 'battles testinv 1')
        r1 = cmd(H, f'battles injectinv {K}')
        bid = int(r1.split()[1]) if r1.startswith('ok ') else None
        if not check(f'{tag}: client `battles testinv 1`, host `battles injectinv {K}` (a request with the invasion check)',
                     bid and ti == 'ok testinv=1', dict(inject=r1, testinv=ti)):
            return None
        hm, cm, t_b = log_mark(H), log_mark(C), time.time()
        drv = BattleDriver(ctx, {bid: action}, K, J)
        drv.label = f'invbattle {action}'
        run_month(ctx, drv.label, driver=drv)
        hlog, clog = log_since(H, hm), log_since(C, cm)
        g = lambda txt, pat: [x.split('] ', 1)[-1] for x in log_lines(txt, pat)]
        hbox = [b[2:] for b in BOX_SEEN if b[0] >= t_b and b[1] == 'host' and (poss in b[3] or 'nvasion' in b[3])]
        return dict(bid=bid, rec=drv.rec.get(bid, {}), hlog=hlog, hbox=hbox, errors=game_error_boxes(t_b),
                    put=g(clog, rf'battle {bid}: the nation\'s invasions in the battle slot: '),
                    att=g(clog, rf'battle {bid}: attempt 0 \(invasion check\)'),
                    back=g(clog, rf'battle {bid}: the nation\'s invasions after it: '),
                    took=g(hlog, rf'battle {bid}: nation {K}\'s invasions after it: '),
                    appl=g(hlog, rf'battle phase: nation {K}\'s invasions after its battles: '),
                    applied=g(hlog, rf'battle {bid} applied: '),
                    setup=g(clog, r'battle setup: '))

    # e1) nation 1's own invasion battle at a possession t2 of J where nation 1 has ships (a battle pending for it:
    #     `inv plan 1 0 - 1`), fought
    jp = poss_list(H, f'possessions {J}') or []
    areas = [c[3] for c in battle_pairs(K) if c[2] == J]
    t2 = next((p['name'] for a in areas for p in jp if p['area'] == a and 0 < p['value'] < 16), t)

    def same_state(e, name, who):
        """The client's state after the battle (its log) = what the host took for the battle (its log)."""
        mc = re.search(r'invasions after it: plan (.*?), enemy plan (.*?), (\d+) invasion', e['back'][-1]) if e['back'] else None
        mh = re.search(r'invasions after it(?: \(unchanged\))?: plan (.*?), enemy plan (.*?), (\d+) mark', e['took'][-1]) \
            if e['took'] else None
        return mc and mh and mc.group(1) == mh.group(1) and mc.group(2) == mh.group(2)

    e1 = inv_battle('e1) nation 1\'s invasion battle', [(C, f'inv pick {u(t2)}'), (H, f'inv target {K} {u(t2)}'),
                                                     (H, f'inv plan {K} 0 - {K}')], 'fight', t2)
    if e1:
        s1 = cmd(H, f'inv state {K}')
        check(f'e1) the client put nation {K}\'s plan in its battle slot (target {t2}, its own battle pending; the save\'s '
              f'invasions cleared); the game\'s CheckForInvasionBattles (plain) set up the battle at {t2} against nation '
              f'{J} (our invasion)', e1['put'] and f'plan {t2}/0, enemy plan -/{K}' in e1['put'][-1] and e1['att'] and
              'TEST: plain' in e1['att'][-1] and f'at {t2} (' in e1['att'][-1] and
              f'against nation {J} (our invasion)' in e1['att'][-1],
              dict(put=e1['put'][-1:], att=e1['att'][-1:], areas=areas[:3]))
        check(f'e1) battle {e1["bid"]}: fought on the client (the preview accepted), merged on the host; the host\'s '
              f'chat "The invasion battle of ... was fought by"', e1['rec'].get('outcome') == 'fought' and
              e1['applied'] and re.search(rf'\* The invasion battle of {re.escape(nt[K]["name"])} against '
                                          rf'{re.escape(nt[J]["name"])}.* was fought by ', chat(ctx.hp)),
              dict(outcome=e1['rec'].get('outcome'), answers=e1['rec'].get('answers'), applied=e1['applied'][-1:]))
        landed = re.search(rf'(?:=|;){re.escape(t2)}:{J}:{K}:', s1)
        check(f'e1) the battle slot\'s invasions came back with the result (the game\'s HandleInvasionResults) and the '
              f'host took the same plan and applied them: the battle pending no more; {t2} invaded by nation {K} after a '
              f'won battle (else not) on the host as on the client', e1['back'] and same_state(e1, t2, 'e1') and
              'pending=-1' in s1 and (landed is not None) == (f'{t2} {K}/' in e1['took'][-1]) and
              (not landed or f'{t2} new: invader {K}' in ''.join(e1['appl'])),
              dict(back=e1['back'][-1:], took=e1['took'][-1:], appl=e1['appl'][-1:], state=s1[:240]))
        check('e1) no invasion box on the host, no game error box', not e1['hbox'] and not e1['errors'],
              dict(boxes=e1['hbox'][:2], errors=e1['errors']))
    # e2) the enemy's invasion of nation 1's possession kp2 where nation 1 has ships (pending: `inv plan 1 0 kp2 J`),
    #     declined at the preview if the game lets the defender decline (DoPlayerDecline: J lands, marked this month),
    #     else fought (HandleInvasionResults: averted or landed); the outcome merged on the host either way
    bcs = read_save(save_path(HOST_SLOT)) or {}
    kships = {}
    for f in ships_by_id(bcs.get(f'Nation{K}Ships')).values():
        kships[f.get('LocationAreaName')] = kships.get(f.get('LocationAreaName'), 0) + 1
    own = sorted((p for p in (poss_list(H, f'possessions {K}') or []) if 0 < p['value'] < 200),
                 key=lambda p: -kships.get(p['area'], 0))
    kp2 = own[0]['name'] if own else None
    if check('e2) setup: a possession of nation 1 (the one in the sea area with most of its ships)', kp2,
             [(p['name'], p['area'], kships.get(p['area'], 0)) for p in own[:3]]):
        for e2try in range(3):
            e2 = inv_battle('e2) the enemy\'s invasion battle', [(C, 'inv pick -'), (H, f'inv target {K} -'),
                                                                (H, f'inv plan {K} 0 {u(kp2)} {J}')], 'decline', kp2)
            # The game drops an enemy's pending battle when the player is much stronger in the area (Random(100) < 40)
            # or the area is out of the enemy's mission range (GAME-INTERNALS, CheckForInvasionBattles): no battle.
            dropped = bool(e2 and e2['att'] and 'gave no battle' in e2['att'][-1] and e2['back'] and
                           f'enemy plan {kp2}/-1, 0 invasion(s)' in e2['back'][-1])
            if not dropped:
                break
            log(f'  e2) attempt {e2try + 1}: the game dropped the enemy\'s pending battle at {kp2} (no battle, the plan '
                f'over): {e2["att"][-1]}')
        if dropped:
            log(f'  SKIP-note e2) the game dropped the enemy\'s pending battle at {kp2} in all 3 attempts (the player '
                f'much stronger in the area: Random(100) < 40)')
            e2 = None
        if e2:
            s2, i2 = cmd(H, f'inv state {K}'), inv_of(kp2)
            check(f'e2) the client put the enemy\'s plan in its battle slot (nation {J} pending at {kp2}); the game\'s '
                  f'CheckForInvasionBattles (plain) played it: a possession battle at {kp2} against nation {J} (the '
                  f'enemy\'s invasion)', e2['put'] and f'enemy plan {kp2}/{J}' in e2['put'][-1] and e2['att'] and
                  'TEST: plain' in e2['att'][-1] and f'possession battles: {kp2} ({J} attacks 0)' in e2['att'][-1],
                  dict(put=e2['put'][-1:], att=e2['att'][-1:], answers=e2['rec'].get('answers'),
                       buttons=e2['rec'].get('map_buttons')))
            landed = i2 is not None and i2[0] == K and i2[1] == J
            check(f'e2) battle {e2["bid"]}: {e2["rec"].get("outcome")}; the slot\'s invasions came back (the enemy\'s '
                  f'plan over) and the host took the same plan; {kp2} invaded by nation {J} on the host iff the client '
                  f'reported it (the landing applied by name)', e2['rec'].get('outcome') in ('fought', 'declined') and
                  e2['applied'] and same_state(e2, kp2, 'e2') and 'enemy plan -/-1' in e2['back'][-1] and
                  landed == (f'{kp2} {J}/' in e2['took'][-1]) and
                  (not landed or f'{kp2} new: invader {J}' in ''.join(e2['appl'])),
                  dict(outcome=e2['rec'].get('outcome'), answers=e2['rec'].get('answers'), applied=e2['applied'][-1:],
                       back=e2['back'][-1:], took=e2['took'][-1:], appl=e2['appl'][-1:], inv=i2, state=s2[:200]))
            check('e2) no invasion box on the host, no game error box', not e2['hbox'] and not e2['errors'],
                  dict(boxes=e2['hbox'][:2], errors=e2['errors']))
    clear_k()
    # e3) fix-afb: nation 1's own invasion battle at J's possession in the sea area where J is the strongest against
    #     nation 1's ships there, its setup an intelligence coup's ambush that finds nation 1's side the weaker (client
    #     `battles testcoup 1`: the ambush's flag, side 1's count + 1000 for the routine's own calls): J's extra divisions
    #     go and the game's reinforcements of nation 1's side get its nation; no AdjustForcesForBattle box; declined in
    #     the preview. Diagnosis (env RTW3_INV_COUP=2): without the mod's nation, the game's own path, its box.
    coup = os.environ.get('RTW3_INV_COUP') if os.environ.get('RTW3_INV_COUP') in ('1', '2') else '1'
    bcs = read_save(save_path(HOST_SLOT)) or {}

    def locs(n):
        out = {}
        for f in ships_by_id(bcs.get(f'Nation{n}Ships')).values():
            out[f.get('LocationAreaName')] = out.get(f.get('LocationAreaName'), 0) + 1
        return out

    kl, jl = locs(K), locs(J)
    weak = sorted(((jl.get(p['area'], 0) - kl.get(p['area'], 0), p['name'], p['area'], jl.get(p['area'], 0),
                    kl.get(p['area'], 0)) for p in (poss_list(H, f'possessions {J}') or [])
                   if 0 < p['value'] < 16 and kl.get(p['area'], 0) >= 1), reverse=True)
    want = os.environ.get('RTW3_INV_E3_TARGET')  # diagnosis: that candidate first (e.g. "Northern Russia")
    if want and any(w[1] == want for w in weak):
        weak = [w for w in weak if w[1] == want] + [w for w in weak if w[1] != want]
    if check('e3) setup: a possession of J in the sea area where J is the strongest against nation 1\'s ships there '
             '(nation 1 has ships there)', weak, weak[:3]):
        t3 = weak[0][1]
        on = cmd(C, f'battles testcoup {coup}')
        e3 = inv_battle('e3) nation 1\'s invasion battle, its setup as an intelligence coup\'s ambush',
                        [(C, f'inv pick {u(t3)}'), (H, f'inv target {K} {u(t3)}'), (H, f'inv plan {K} 0 - {K}')],
                        'decline', t3)
        off = cmd(C, 'battles testcoup 0')
        if e3:
            runs = [int(m.group(1)) if m else -1 for m in (re.search(r' forced=(\d+)', x) for x in (on, off))]
            amb = runs[0] >= 0 and runs[1] == runs[0] + 1
            rein = [x for x in e3['setup'] if 'reinforcements of side 0' in x]
            afb = [b for b in e3['errors'] if 'AdjustForcesForBattle' in b[1]]
            if coup == '2':
                check(f'e3) DIAGNOSIS (RTW3_INV_COUP=2): battle {e3["bid"]} at {t3} as an ambush without the mod\'s '
                      f'nation for its reinforcements: the game\'s AdjustForcesForBattle box (0.7.0 RC1: Read of address '
                      f'02EBC02F)', amb and rein and afb,
                      dict(testcoup=(on, off), att=e3['att'][-1:], setup=e3['setup'][-2:], boxes=afb,
                           answers=e3['rec'].get('answers')))
            else:
                e3what = (f'e3) battle {e3["bid"]} at {t3} ({weak[0][3]} ships of J, {weak[0][4]} of nation 1 in '
                          f'{weak[0][2]}), its setup an intelligence coup\'s ambush (`battles testcoup 1`: forced=+1)')
                e3ok = amb and not afb and e3['rec'].get('outcome') in ('declined', 'fought')
                e3ev = dict(testcoup=(on, off), att=e3['att'][-1:], setup=e3['setup'][-2:], boxes=afb,
                            answers=e3['rec'].get('answers'))
                if rein or weak[0][0] > 0:
                    check(f'{e3what}: the reinforcements of nation 1\'s side got its nation ("had no nation ... gave '
                          f'them nation 0"), no AdjustForcesForBattle box, {e3["rec"].get("outcome")}',
                          e3ok and rein and 'gave them nation 0' in rein[-1], e3ev)
                else:
                    # nation 1 not outnumbered in the area (0.7.0 RC2: the default run's only candidate Northern Russia,
                    # 9 v 16 in Northern Europe, and `--only battle_invasion` with RTW3_INV_E3_TARGET there, 14 v 33:
                    # forced +1, no line, no box): the reinforcement step meets no unset nation there, so the fix's path
                    # is not exercised: the battle still checks for the box
                    check(f'{e3what}: no AdjustForcesForBattle box, {e3["rec"].get("outcome")}', e3ok, e3ev)
                    log(f'  SKIP-note e3) no "battle setup: the ambush\'s reinforcements" line at {t3}: nation 1 is not '
                        f'outnumbered there ({weak[0][3]} ships of J, {weak[0][4]} of nation 1 in {weak[0][2]}; the '
                        f'candidates {weak[:3]}), so the reinforcement step met no unset nation: the fix\'s path is '
                        f'not exercised in this battle')
        clear_k()
    # f) P5: nation 1's peace with J (client `peacetest 100 2 1`: the game's DoPeace in its view, B4's peace part) ends
    #    its invasions with J (the possessions' war state, `ptaken`) and its invasion plan (the host resets it)
    if rel(K, J).get('war') != '1':
        peace_war(K, J)
    jpf = [p['name'] for p in (poss_list(H, f'possessions {J}') or []) if 0 < p['value'] < 10]
    kpf = [p['name'] for p in (poss_list(H, f'possessions {K}') or []) if 0 < p['value'] < 200]
    if check('f) setup: a possession of J and two of nation 1', len(jpf) >= 1 and len(kpf) >= 2, dict(J=jpf[:3], K=kpf[:3])):
        pf, kf, ke = jpf[0], kpf[0], kpf[1]
        for port in (H, C):  # (both copies: the client's peace reads its own)
            cmd(port, f'inv set {u(pf)} {K} 1')
            cmd(port, f'inv set {u(kf)} {J} 0')
        cmd(C, f'inv pick {u(pf)}')
        cmd(H, f'inv target {K} {u(pf)}')
        cmd(H, f'inv plan {K} 1 {u(ke)} -1')
        cmark, hmark = log_mark(C), log_mark(H)
        r = cmd(C, 'peacetest 100 2 1')
        rec = wait_peace(ctx, cmark, hmark)
        pc, hl = peacelast(C), log_since(H, hmark)
        reset = log_lines(hl, rf'invasions: nation {K}\'s peace ends its invasion plan \(target {re.escape(pf)}/1, enemy '
                              rf'target {re.escape(ke)}/-1')
        sf = cmd(H, f'inv state {K}')
        check(f'f) the client\'s peace with J accepted (peacetest 100 2 1) and applied once on the host; the host reset '
              f'nation {K}\'s invasion plan ("peace ends its invasion plan": target {pf}, enemy target {ke}) and its '
              f'invasions with J are over on the host ({pf}, {kf}: the possessions\' war state from the client\'s DoPeace)',
              r == 'ok' and pc.get('accepted') == '1' and len(rec['host']) == 1 and reset and
              ' target= count=0 enemy= pending=-1 itt= ' in sf and inv_of(pf) is None and inv_of(kf) is None,
              dict(reply=r, accepted=pc.get('accepted'), host=rec['host'], reset=reset, state=sf[:200],
                   pf=inv_of(pf), kf=inv_of(kf)))
        f1 = cmd(C, 'inv form')
        check('f) the client\'s form: no invasion target after its peace (the game\'s DoPeace in its view)',
              f1.startswith('ok target= '), f1)
    # g) P4: a surprise landing in nation 1's possession at a war's start (client `battles testsa J2 land`: J2 plans its
    #    war with the SurpriseAttack trait; the landing's pick and strength test forced): recorded in nation 1's relation
    #    turn (`kland`) and applied by name on the host (invaded by J2, marked this month)
    humans2 = set(kwar_counters(H) or {}) | {0, K, STANDIN}
    J2 = 5 if 5 not in humans2 and 5 in nt else next((j for j in range(3, 9) if j not in humans2 and j in nt and j != J), None)
    for j in range(9):  # the landing block needs nation 1 at peace (its war counter <= 0 at the relation turn)
        if j != K and rel(K, j).get('war') == '1':
            log(f'  peace {K}-{j} first:', peace_war(K, j, 5))
    kw = (kwar_counters(H) or {}).get(K)
    if kw is not None and kw > 0:
        log(f'  nation {K}\'s war counter {kw} -> 0 (at peace now):', cmd(H, f'kwar {K} 0'))
    t2j = rel(K, J2).get('tension', '5') if J2 else '5'
    rt = cmd(C, f'battles testsa {J2} land') if J2 else 'no J2'
    if check(f'g) `battles testsa {J2} land` on the client (nation {J2}\'s war on nation {K} with a surprise and its landing)',
             rt.startswith(f'ok testsa={J2} land'), rt):
        hm, cm = log_mark(H), log_mark(C)
        run_month(ctx, 'invasion landing', driver=BattleDriver(ctx, {}, K, J2))
        hlog, clog = log_since(H, hm), log_since(C, cm)
        pick = log_lines(clog, r'relations v2: surprise move: the landing pick (.+) \(value \d+\) \(TEST: forced')
        land = log_lines(clog, rf'relations v2: surprise move: nation {J2}\'s troops landed in (.+) \(nation {K}\'s; recorded')
        sent = log_lines(clog, rf'relations for nation {K} sent: ')
        lp = re.search(rf"troops landed in (.+?) \(nation {K}'s", land[-1])[1] if land else None
        if not pick and not land:
            log(f'  SKIP-note g) the landing: the game\'s CheckForWar skipped its landing/takeover step this time (with '
                f'the trait 95 %; no "the landing pick" line)')
        else:
            app = log_lines(hlog, rf'invasions: surprise landing of nation {K}\'s turn: nation {J2} invades {re.escape(lp or "?")} '
                                  rf'\(marked this month\)')
            sg, ig = cmd(H, f'inv state {K}'), inv_of(lp) if lp else None
            check(f'g) nation {K}\'s relation turn: nation {J2}\'s surprise landing in {lp} (the pick and its strength '
                  f'test forced) recorded and sent ("kland=1"); the host applied it by name: {lp} invaded by {J2}, '
                  f'support 0, marked this month (nation {K}\'s `itt`)', land and sent and 'kland=1' in sent[-1] and app
                  and ig and ig[0] == K and ig[1] == J2 and f'itt={lp}/' in sg,
                  dict(pick=pick[-1:], land=land[-1:], sent=[x.split('] ', 1)[-1][-120:] for x in sent[-1:]], app=app,
                       inv=ig, state=sg[:200]))
            if lp:
                cmd(H, f'inv set {u(lp)} -1 0')
    J2war = J2 and rel(K, J2).get('war') == '1'
    # h) P7: the computer's fleets: nation J2's most important area (GetMostImportantArea, host `inv escort J2`, the
    #    same draws with and without): nation 1's invasion of J2's possession counts as the player's (+80 "is invaded by
    #    player"), nation 1's possession J2's side plans to invade as the form's target (the escort's points)
    if J2 and not J2war:
        peace_war(K, J2)
    j2p = [p for p in (poss_list(H, f'possessions {J2}') or []) if 0 < p['value']] if J2 else []
    k2p = [p for p in (poss_list(H, f'possessions {K}') or []) if 0 < p['value'] < 200]
    if check(f'h) setup: nation {K} at war with {J2}, a possession of each', J2 and rel(K, J2).get('war') == '1' and j2p
             and k2p, dict(J2=J2, war=rel(K, J2) if J2 else None, j2=[p['name'] for p in j2p[:2]])):
        clear_k()
        pa, ka = j2p[0], next((p for p in k2p if p['area'] != j2p[0]['area']), k2p[0])

        def esc(tag):
            r = cmd(H, f'inv escort {J2}')
            pts = lambda which: {a: int(v) for a, v in re.findall(r'([^,=]+?):(-?\d+)', (re.search(
                rf'points\({which}\)=(.*?)(?: points| draws|$)', r) or [None, ''])[1])}
            return r, pts('without'), pts('with')

        cmd(H, f'inv set {u(pa["name"])} {K} 1')
        ra, wa, ha = esc('a')
        check(f'h) nation {K}\'s invasion of {J2}\'s {pa["name"]} shown to {J2}\'s call as the player\'s: {pa["area"]} '
              f'+80 points with it (the same draws), nothing shown without', 'draws=same' in ra and 'shown=1' in ra and
              ha.get(pa['area'], 0) - wa.get(pa['area'], 0) >= 80, dict(reply=ra[:300]))
        cmd(H, f'inv set {u(pa["name"])} -1 0')
        cmd(H, f'inv plan {K} 0 {u(ka["name"])} -1')
        rc, wc, hc = esc('c')
        check(f'h) nation {K}\'s possession {ka["name"]} as the computer\'s planned invasion target: {J2}\'s escort '
              f'points for {ka["area"]} (" If at War. Enemy invasion area": more with it; the draws after it differ)',
              'shown=1' in rc and hc.get(ka['area'], 0) > wc.get(ka['area'], 0), dict(reply=rc[:300]))
        cmd(H, f'inv plan {K} 0 - -1')
        # the month's AI moves see them (the host's month-end hide log counts the calls)
        cmd(H, f'inv set {u(pa["name"])} {K} 1')
        hm = log_mark(H)
        run_month(ctx, 'invasion escorts', driver=BattleDriver(ctx, {}, K, J2))
        hid = log_lines(log_since(H, hm), r"GetMostImportantArea: joined nations' invasions shown \d+x")
        check(f'h) the month\'s computer decisions saw nation {K}\'s invasion ("GetMostImportantArea: joined nations\' '
              f'invasions shown Nx" in the host\'s month-end log)', hid, hid[-1:])
    # i) the cases (nation 1 at war with J alone): i1) J starts an invasion of nation 1's possession in nation 1's month
    #    (`inv run`, draws high: the start's gates are the fleets' strengths in the area, Kiautschou Bay against J's
    #    Pacific squadron in the fixture); i2) nation 1 captures a possession (support 50); i3) the host's own invasion
    #    check refuses a battle at nation 1's invasion (host `inv hostcheck`)
    clear_k()
    for j in range(9):
        if j != K and rel(K, j).get('war') == '1':
            peace_war(K, j, 5)
    peace_war(K, J)
    start, runs = None, []
    for mode in [2] * 6 + [0] * 10:  # (draws high, then the game's)
        cmd(H, f'inv rnd {mode}')
        rr = cmd(H, f'inv run {K}')
        runs.append(rr[:220])
        if re.search(r'troops have invaded our possession|enemy plan [^-][^/]*/' + str(J), rr):
            start = rr
            break
    cmd(H, 'inv rnd 0')
    if start:
        check(f'i1) nation {K}\'s month (`inv run`): computer nation {J} starts an invasion of nation {K}\'s possession '
              f'(its landing "troops have invaded our possession" or its battle planned: the enemy plan)', start, runs[-1:])
    else:  # the start's gates are the fleets' strengths in the area (the enemy's over 2 G + 1 and 1.1 x the nation's)
        log(f'  SKIP-note i1) no start of computer nation {J} in {len(runs)} runs of nation {K}\'s month: {runs[-1:]}')
    clear_k()
    cmd(H, f'inv plan {K} 0 - -1')
    jcap = [p for p in (poss_list(H, f'possessions {J}') or []) if 0 < p['value'] < 16]
    areas_k = [c[3] for c in battle_pairs(K) if c[2] == J]
    pc2 = next((p['name'] for a in areas_k for p in jcap if p['area'] == a), None)
    if check(f'i2) setup: a possession of J where nation {K} has ships', pc2, dict(areas=areas_k, J=[p['name'] for p in jcap[:3]])):
        took, runs = False, []
        for mode in (1, 0, 0, 0):  # (draws low, then the game's: the fortifications' test)
            cmd(H, f'inv rnd {mode}')
            cmd(H, f'inv set {u(pc2)} {K} 50')
            hm = log_mark(H)
            rr = cmd(H, f'inv run {K}')
            runs.append(rr[:200])
            if log_lines(log_since(H, hm), rf'invasions: nation {K}\'s month: {re.escape(pc2)} passes from nation {J} to '
                                            rf'nation {K}'):
                took = 'taken control' in rr
                break
        cmd(H, 'inv rnd 0')
        check(f'i2) nation {K} captures {pc2} in its month (support 50, draws low then the game\'s: "Our forces have taken control of", '
              f'ChangePossessionOwner {J} -> {K})', took, runs[-2:])
    clear_k()
    jp3 = [p['name'] for p in (poss_list(H, f'possessions {J}') or []) if 0 < p['value'] < 10]
    if jp3:
        cmd(H, f'inv set {u(jp3[0])} {K} 1')
        refused = None
        for _ in range(8):
            rh = cmd(H, 'inv hostcheck')
            if 'DoPossessionBattle refused' in rh:
                refused = rh
                break
        hl = log_lines(log_since(H), rf'invasions: the host\'s invasion battles: none at {re.escape(jp3[0])} \(nation {K}\'s '
                                     rf'invasion of nation {J}\'s possession\)')
        check(f'i3) the host\'s own CheckForInvasionBattles picked nation {K}\'s invasion of {jp3[0]} (60 %) and gave no '
              f'battle there ("the host\'s invasion battles: none at")', refused and hl, dict(reply=refused, log=hl[-1:]))
    # j) P5: the host's own peace (its DoPeace, host `inv hostpeace`) leaves nation 1's invasions alone and clears its own
    clear_k()
    jp4 = [p['name'] for p in (poss_list(H, f'possessions {J}') or []) if 0 < p['value'] < 10]
    kp4 = [p['name'] for p in (poss_list(H, f'possessions {K}') or []) if 0 < p['value'] < 200]
    if check('j) setup: two possessions of J, one of nation 1', len(jp4) >= 2 and kp4, dict(J=jp4[:3], K=kp4[:2])):
        cmd(H, f'inv set {u(jp4[0])} {K} 1')
        cmd(H, f'inv set {u(kp4[0])} {J} 0')
        cmd(H, f'inv set {u(jp4[1])} 0 1')
        hm = log_mark(H)
        rp = cmd(H, 'inv hostpeace')
        drain(ctx.hp, 4)
        ran = log_lines(log_since(H, hm), r'invasions: TEST: the host\'s DoPeace ran: ')
        a0, a1, a2 = inv_of(jp4[0]), inv_of(kp4[0]), inv_of(jp4[1])
        check(f'j) the host\'s DoPeace ran (its own invasion of {jp4[1]} over) and left nation {K}\'s invasions: '
              f'{jp4[0]} invaded by {K}, {kp4[0]} by {J} (support kept)', rp == 'ok' and ran and a2 is None and
              a0 and a0[1] == K and a0[2] == 1 and a1 and a1[1] == J, dict(ran=ran[-1:], a0=a0, a1=a1, a2=a2))
    clear_k()
    cmd(H, f'inv plan {K} 0 - -1')
    cmd(C, 'inv pick -')
    cmd(H, f'inv target {K} -')
    for n in (p1, q, k1):
        if inv_of(n) and inv_of(n)[1] != -1:
            cmd(H, f'inv set {u(n)} -1 0')
    if J2 and rel(K, J2).get('war') == '1':
        peace_war(K, J2, int(t2j) if str(t2j).lstrip('-').isdigit() else 5)
    peace_war(K, J, int(t0) if str(t0).lstrip('-').isdigit() else 5)

def scenario_relations_peace(ctx):
    """Relations v2 (B4): peace with the computer's nations for a joined nation under the player's rules (nation 1).
    A computer nation J at war with nation 1 (`settension 1 J 50` on both copies: no month needed) and its war score
    (`kwarvp 1 J ...`); a) `peacetest 100 2 1` on the client (NegotiatePeace(100, 2, ForceBadPeace) in nation 1's view,
    the game's dialogs answered, the possessions dialog its first entry) -> the war over on both copies, the client's
    peace sent and the host's applied once, the possessions ceded to nation 1 on the host, J's changes, the war score
    erased, nation 1's war counter and blockade flags, the chat's "Peace treaty between" line; b) a second war and
    `peacetest 100 -3 1` (a defeat: ships handed over to J, held by J on both copies), J's BaseResources and HasLostWar
    as the client reported, nation 1's HasLostWar on its own copy; c) a third war and "Propose peace" (`diplo peace J`:
    the proposal path, NegotiatePeace(40, 0)): one a month (a second proposal refused; the session file keeps the month,
    `kpeacem`); d) a processed month: every ship handed over is held once (the merge, saveio DropForeignShips), the war
    counters stepped, the session file keeps the month of nation 1's relation turn (`krelm`). Ends at peace."""
    hp = ctx.hp
    K = 1
    for port, who in ((H, 'host'), (C, 'client')):
        ok = log_lines(log_since(port), r"Peace with the computer's nations for a joined nation: ok")
        check(f'start: {who} log "Peace with the computer\'s nations for a joined nation: ok"', ok,
              [x.split('] ', 1)[-1] for x in log_lines(log_since(port), r"Peace with the computer's nations")][:2])
    rr = relrules(H)
    pl0 = peacelast(C)
    check('start: nation 1 follows the player\'s rules (`relrules`) and the client has a B4 host (`peacelast` host=1)',
          rr is not None and K in rr and pl0.get('host') == '1', dict(relrules=rr, client=pl0.get('raw', '')[:200]))
    if not (rr and K in rr and pl0.get('host') == '1'):
        return
    cmd(H, 'mpwindow')
    cmd(C, 'mpwindow')
    nt = nation_table()
    humans = set(kwar_counters(H) or {}) | {0, K, STANDIN}
    cands = [j for j in range(3, 9) if j not in humans and j in nt and rel(K, j).get('war') == '0' and
             rel(K, j).get('ally') == '0' and not any(rel(j, x).get('war') == '1' for x in range(9) if x != j)]
    if not cands:
        check('setup: a computer nation at peace with everyone and not allied with nation 1', False, nt)
        return
    J = cands[0]
    nK, nJ = nt[K]['name'], nt[J]['name']
    others = lambda: [x for x in range(9) if x not in (K, J) and rel(K, x).get('war') == '1']
    log(f'  B4: nation {K} {nK} and the computer nation {J} {nJ}; nation {K}\'s other wars: {others()}')

    # a) a victory: peacetest 100 2 1
    hr, cr = peace_war(K, J)
    v = kwarvp(K)
    vs = value(cmd(H, f'kwarvp {K} {J} 400 100'))
    v2 = kwarvp(K)
    check(f'a) war {K}-{J} on both copies (settension) and its war score in the host\'s ledger (kwarvp {K}: '
          f'{J}:0:0 at first, then {J}:400:100)', hr.get('war') == '1' and 'war=1' in (cr or '') and v and
          v['pairs'].get(J) == (0, 0) and v2 and v2['pairs'].get(J) == (400, 100) and v2['vp'] >= 400,
          dict(host=hr, client=cr, before=v, set=vs, after=v2))
    p1 = pnames(poss_list(H, f'possessions {K}'))
    rJ0, pJ0 = nint(H, J, 'BaseResources'), nint(H, J, 'Prestige')
    hc0 = chat(hp)
    cmark, hmark = log_mark(C), log_mark(H)
    t_a = time.time()
    r = cmd(C, 'peacetest 100 2 1')
    rec = wait_peace(ctx, cmark, hmark)
    pc, ph = peacelast(C), peacelast(H)
    check('a) peacetest 100 2 1: the client ran the peace part (NegotiatePeace(100, 2, 1) in nation 1\'s view) and '
          'sent it; the host applied it once (one "relations v2: peace of nation 1 with" line)',
          r == 'ok' and pc.get('ran') == '1' and pc.get('args') == '100:2:1' and str(J) in pc.get('enemies', '') and
          len(rec['host']) == 1, dict(reply=r, client=pc.get('raw', '')[:300], host=rec['host']))
    hr, cr = rel(K, J), value(cmd(C, f'rel {K} {J}')) or ''
    check(f'a) the war {K}-{J} is over on both copies (the game\'s peace: tension 1..5)',
          pc.get('accepted') == '1' and hr.get('war') == '0' and 'war=0' in cr and 0 <= int(hr.get('tension', -1)) <= 5,
          dict(host=hr, client=cr, accepted=pc.get('accepted')))
    if tuple(int(x) for x in re.findall(r'\d+', (build_version() or '0.0.0').split('-')[0])[:3]) >= (0, 5, 0):
        sv = wait_until(lambda: log_lines(log_since(H, hmark), r'relations v2: campaign saved after a (peace proposal|'
                                                                r'relation turn) of nation \d+'), bool, 15) or []
        check('a) 0.5.0: the host saved its campaign right after applying the peace ("relations v2: campaign saved '
              'after a peace proposal of nation 1 (ok"): a restart in the month keeps it', any('(ok' in x for x in sv),
              [x.split('] ', 1)[-1][:160] for x in sv])
    lands = [x.split('~', 1) for x in pc.get('landnames', [])]
    to_k = [x[0] for x in lands if len(x) == 2 and x[1].endswith(f'>{K}')]
    p1b = pnames(poss_list(H, f'possessions {K}'))
    check(f'a) possessions the client ceded to nation {K} are nation {K}\'s on the host (winner {pc.get("winner")}: '
          f'{to_k or "none taken"})', all(n in p1b for n in to_k) and len(p1b) >= len(p1),
          dict(ceded=lands, before=len(p1), after=len(p1b)))
    dJ = {f[1]: int(f[2]) for f in (x.split(':') for x in pc.get('delta', '').split(';') if x) if len(f) == 3 and f[0] == str(J)}
    rJ1, pJ1 = nint(H, J, 'BaseResources'), nint(H, J, 'Prestige')
    check(f'a) nation {J}\'s BaseResources and Prestige changed on the host as the client reported ({dJ or "none"})',
          rJ1 - rJ0 == dJ.get('BaseResources', 0) and pJ1 - pJ0 == dJ.get('Prestige', 0),
          dict(reported=dJ, base=(rJ0, rJ1), prestige=(pJ0, pJ1)))
    v3, kw = kwarvp(K), kwar_counters(H) or {}
    no_war = not others()
    check(f'a) the war score {K}-{J} erased; nation {K}\'s war counter 0 and blockade flags of {K} and {J} 0 '
          f'(nation {K} without another war: {no_war})',
          v3 and J not in v3['kept'] and (not no_war or kw.get(K) == 0) and nflag(H, J, 'Blockaded') == 0 and
          (not no_war or nflag(H, K, 'Blockaded') == 0), dict(ledger=v3, kwar=kw, host=ph.get('raw', '')[:300]))
    # the chat names all of nation K's computer enemies of the peace ("Germany and Russia, Spain: ..."; the battles
    # scenario may leave a war with another computer nation)
    line_re = re.compile(rf'\* Peace treaty between {re.escape(nK)} and [^:\n]*{re.escape(nJ)}[^:\n]*: ')
    n_chat = len(line_re.findall(hc0))
    txt = wait_until(lambda: chat(hp), lambda t: len(line_re.findall(t)) > n_chat, 8)
    check(f'a) host chat: "* Peace treaty between {nK} and ...{nJ}...: ..." (and the treaty lines)',
          len(line_re.findall(txt)) > n_chat, txt[-400:])
    nt_lines = int(pc.get('treaty', '0') or 0)
    seen = [x for x in TREATY_SEEN if x['who'] == 'client' and x['t'] >= t_a]
    check(f'a) the client showed the game\'s "Peace treaty" dialog when the treaty has lines ({nt_lines} reported)',
          (nt_lines == 0) == (not seen), dict(reported=nt_lines, seen=[x['text'][:200] for x in seen]))

    # b) a defeat: peacetest 100 -3 1 (ships handed over)
    peace_war(K, J)
    rJ0, lost0 = nint(H, J, 'BaseResources'), nflag(H, J, 'HasLostWar')
    ships0 = {n: x['ships'] for n, x in nation_table().items()}
    cmark, hmark = log_mark(C), log_mark(H)
    r = cmd(C, 'peacetest 100 -3 1')
    rec = wait_peace(ctx, cmark, hmark)
    pc, ph = peacelast(C), peacelast(H)
    hr, cr = rel(K, J), value(cmd(C, f'rel {K} {J}')) or ''
    check(f'b) peacetest 100 -3 1: peace made and applied once; the war {K}-{J} over on both copies (winner '
          f'{pc.get("winner")}: 2 = nation {K} lost)', r == 'ok' and pc.get('accepted') == '1' and len(rec['host']) == 1 and
          hr.get('war') == '0' and 'war=0' in cr, dict(client=pc.get('raw', '')[:300], host=rec['host'], rel=(hr, cr)))
    sids = [(int(a), b) for a, b in (x.split(':', 1) for x in pc.get('shipids', '').split(',') if ':' in x)]
    held = {sid: (ship_holders(H, sid), ship_holders(C, sid)) for sid, _ in sids}
    # A ship the host does not have as nation K's is skipped there (game.cpp HandOverShip: "skipped: not among nation K's
    # ships"): a peace between players earlier in the same month (`treaty` h) can have handed it over on the host, and
    # the client's copy gets that only with the next month (default run of 2026-10-23: ship 495, France's on the host).
    skipped = {int(m[1]) for m in re.finditer(PEACE_SHIP_SKIPPED.format(K=K), log_since(H, hmark))}
    if skipped:
        log(f'  NOTE b) the host skipped ship(s) {sorted(skipped)}: not nation {K}\'s there (a peace between players '
            f'earlier in this month handed it over on the host; the client\'s copy gets that with the next month)', held)

    def held_ok(sid, d, h, c):
        to = int(d.split('>')[1])
        return (len(h) == 1 and h[0] not in (K, to) and c == [to]) if sid in skipped else (h == [to] and c == [to])
    ok_ships = all(held_ok(sid, d, *held[sid]) for sid, d in sids)
    moved = [(sid, d) for sid, d in sids if sid not in skipped]
    ships1 = {n: x['ships'] for n, x in nation_table().items()}
    check(f'b) ships handed over ({len(sids)}: {pc.get("shipids") or "none this time"}) are held by the receiver only, '
          f'on both copies (findship; a ship the host skipped as not nation {K}\'s stays where the host has it); ship '
          f'counts on the host follow',
          ok_ships and ships1.get(K, 0) - ships0.get(K, 0) == -sum(1 for _, d in moved if d.startswith(f'{K}>')) and
          ships1.get(J, 0) - ships0.get(J, 0) == sum(1 for _, d in moved if d.endswith(f'>{J}')),
          dict(ships=sids, held=held, skipped=sorted(skipped), before=ships0, after=ships1))
    dJ = {f[1]: int(f[2]) for f in (x.split(':') for x in pc.get('delta', '').split(';') if x) if len(f) == 3 and f[0] == str(J)}
    lostJ = {f[0]: f[1] for f in (x.split(':') for x in pc.get('lost', '').split(';') if x) if len(f) == 2}.get(str(J))
    rJ1, lost1 = nint(H, J, 'BaseResources'), nflag(H, J, 'HasLostWar')
    check(f'b) nation {J}\'s BaseResources and HasLostWar on the host as the client reported (delta {dJ}, HasLostWar '
          f'{lostJ}); nation {K}\'s own HasLostWar on its copy (comes with its turn)',
          rJ1 - rJ0 == dJ.get('BaseResources', 0) and (lostJ is None or lost1 == int(lostJ)) and
          (pc.get('winner') != '2' or not sids or nflag(C, K, 'HasLostWar') == 1),
          dict(base=(rJ0, rJ1), lost=(lost0, lost1, lostJ), clientK=nflag(C, K, 'HasLostWar'), winner=pc.get('winner')))

    # c) "Propose peace" (the Diplomacy list's computer row): one a month
    peace_war(K, J)
    time.sleep(1.5)
    rw = row(C, J)
    check(f'c) client diploview: a row for nation {J} (player "computer", At war, P only)',
          rw and rw['player'] == 'computer' and rw['relation'] == 'At war' and 'P' in rw['flags'] and
          'W' not in rw['flags'], rw)
    cmark, hmark = log_mark(C), log_mark(H)
    r = cmd(C, f'diplo peace {J}')
    rec = wait_peace(ctx, cmark, hmark)
    pc, ph = peacelast(C), peacelast(H)
    check('c) diplo peace J: the proposal ran (NegotiatePeace(40, 0, 0)) and the host applied it (kind=peace)',
          r == 'ok' and pc.get('args') == '40:0:0' and ph.get('kind') == 'peace' and len(rec['host']) == 1,
          dict(reply=r, client=pc.get('raw', '')[:300], host=ph.get('raw', '')[:300]))
    if rel(K, J).get('war') != '1':  # the computer accepted: another war for the refusal check
        peace_war(K, J)
        time.sleep(1.5)
    r2 = cmd(C, f'diplo peace {J}')
    rw = row(C, J)
    check('c) a second proposal this month is refused (client: "negotiated with the computer\'s nations this month '
          'already"; the row shows "peace negotiated this month", no P) and the host would ignore it too (kwarvp '
          'peace=used)', r2.startswith('error') and 'this month' in r2 and rw and 'P' not in rw['flags'] and
          (kwarvp(K) or {}).get('peace') == 'used', dict(reply=r2, row=rw, ledger=kwarvp(K)))
    sf = session_file()
    check(f'c) {SESSION_FILE} keeps the month of nation {K}\'s peace (kpeacem {K}:<Year*12+Month of diplomacyDate>: a '
          f'host that hosts again this month applies no second one)',
          session_month(sf) > 0 and session_months(sf, 'kpeacem').get(K) == session_month(sf),
          {k: sf.get(k) for k in ('kpeacem', 'krelm', 'diplomacyDate')})
    peace_war(K, J, 5)

    # d) a processed month: the merge keeps one copy of each ship handed over
    run_month(ctx, 'relations_peace M1')
    held2 = {sid: (ship_holders(H, sid), ship_holders(C, sid)) for sid, _ in sids}
    check('d) after the processed month every ship handed over is held once, by the receiver, on both copies (a ship '
          'the host skipped: by the host\'s holder on both)',
          all((h == c == held[sid][0] and len(h) == 1) if sid in skipped else
              (h == [int(d.split('>')[1])] and c == [int(d.split('>')[1])]) for (sid, d), (h, c) in
              ((s, held2[s[0]]) for s in sids)), held2)
    check(f'd) the war {K}-{J} is still over on the host and nation {K}\'s war score with {J} is gone',
          rel(K, J).get('war') == '0' and J not in (kwarvp(K) or {}).get('kept', {J: 0}), dict(rel=rel(K, J), ledger=kwarvp(K)))
    if any(f'relations for nation {K} sent' in x for x in (ctx.relturn or {}).get('lines', [])):
        sf = wait_until(session_file, lambda s: session_month(s) > 0 and
                        session_months(s, 'krelm').get(K) == session_month(s), 8)
        check(f'd) {SESSION_FILE} keeps the month of nation {K}\'s relation turn (krelm {K}:<Year*12+Month of the new '
              f'diplomacyDate>: a host that hosts again this month applies no second one)',
              session_month(sf) > 0 and session_months(sf, 'krelm').get(K) == session_month(sf),
              {k: sf.get(k) for k in ('krelm', 'kpeacem', 'diplomacyDate')})
    else:
        log(f'  NOTE d): no relation turn of nation {K} this month (relation turn lines: '
            f'{(ctx.relturn or {}).get("lines")}): krelm not checked')


def warfx_state(port=H, n=1):
    """`warfx n` -> dict(flags = the nations blockaded now, raw), or None (a host without the war effects)."""
    raw = cmd(port, f'warfx {n}') or ''
    if not raw.startswith('ok'):
        return None
    m = re.search(r'flags=(\S*)', raw)
    return dict(flags={int(x) for x in (m[1] if m else '').split(',') if x.isdigit()}, raw=raw)


def blockade_credits(txt):
    """Host log: 'victory points: nation G +v (blockade, in its war with nation L)' -> [(G, v, L)] (warfx.cpp)."""
    return [(int(a), int(b), int(c)) for a, b, c in
            re.findall(r'victory points: nation (\d+) \+(\d+) \(blockade, in its war with nation (\d+)\)', txt)]


SEA_WAR_BOX_RE = r'raider|submarine|merchant'
RESEARCH_LINE_RE = r'(Our (scientists|best brains|engineers|researchers)\b|Research breakthrough:)'


def sea_war_box_lines(text):
    """The lines of a host box (a turn report joins its lines with ' | ') that speak of raiders, submarines or merchant
    ships (war_effects M2 (c): none may show on the host), without the host's own research messages ("Our scientists
    report ...", the turn report's "Research breakthrough: Submarines, Early coastal submarine, ..." of a run of
    2026-10-23)."""
    return [ln for ln in (text or '').split(' | ') if re.search(SEA_WAR_BOX_RE, ln, re.I) and
            not re.match(RESEARCH_LINE_RE, ln.strip())]


def trade_credits(txt):
    """Host log: 'victory points: nation G +v (trade war, in its war with nation L)' -> [(G, v, L)] (warfx.cpp, (c))."""
    return [(int(a), int(b), int(c)) for a, b, c in
            re.findall(r'victory points: nation (\d+) \+(\d+) \(trade war, in its war with nation (\d+)\)', txt)]


def battle_war_score(txt, a, b):
    """Host log 'war score lo-hi: +x/+y ' (battles: OnBattleVP, CreditWarScore) of the pair a-b -> (a's, b's) summed."""
    x = y = 0
    for lo, hi, p, q in re.findall(r'war score (\d+)-(\d+): \+(\d+)/\+(\d+) ', txt):
        if {int(lo), int(hi)} == {a, b}:
            x, y = (x + int(p), y + int(q)) if int(lo) == a else (x + int(q), y + int(p))
    return x, y


TREATY_BOX = 'cancels the disarmament treaty'  # the game's CancelTreaty box (TMessageForm)
NO_LIMIT = 2147483647


def arms_treaty(port):
    """`armstreaty` (0.6.0): the disarmament treaty on a copy -> dict(months, disp, cal, subban, base, war, kept, ends,
    last) as ints (last a string), or None."""
    r = value(cmd(port, 'armstreaty'))
    if r is None:
        return None
    d = dict(w.split('=', 1) for w in r.split(' ') if '=' in w)
    return {k: (int(v) if v.lstrip('-').isdigit() else v) for k, v in d.items()}


def treaty_boxes(t0, who=None):
    """The game's 'The outbreak of war cancels the disarmament treaty!' boxes (TMessageForm; not a turn report's line)
    answered since t0 ((who, text) list)."""
    return [(w, t[:120]) for (tm, w, k, t) in BOX_SEEN
            if tm >= t0 and k == 'TMessageForm' and TREATY_BOX in t and (who is None or w == who)]


def treaty_same(h, c):
    return h and c and all(h.get(k) == c.get(k) for k in ('months', 'disp', 'cal', 'subban'))


def scenario_arms_treaty(ctx):
    """0.6.0: the disarmament treaty, the arms-control conference and a joined nation's war (nation 1 under the player's
    rules, a computer nation J at peace with everyone, no other war among nations 1-8). The game ends the campaign-wide
    treaty when a war breaks out (CancelTreaty: nation 0's war at the screen's refresh with its box "The outbreak of war
    cancels the disarmament treaty!", two computer nations' war when it breaks out); its conference
    (CreateArmsControlTreaty) ends at once while two of nations 1-8 are at war. a) both logs "Disarmament treaty with
    joined nations' wars: ok"; the host's own war under a treaty (TEST: `armstreaty set` and `armstreaty war 1` on the
    host, `armstreaty refresh`): the game's box on the host and the treaty ended there, as before (the host's war counter
    and the nations' DisplacementLimit/BuildConstraint put back). b) M1 at peace with the game's conference at the
    month's end (TEST `econtreaty 100`: CreateArmsControlTreaty(100) after ComputeExpenses, as its event does): a treaty
    signed at peace; its effect on nation 1 is in the month's record (`econ 1` conference=1, treaty= the scrap value of
    its ships under construction over the limits as the host log line has it, treatyBM < 0: the signing's -2) and in the
    0.5.0 money check; the same treaty on both copies, the client knows the host's rule (header `armstreaty`: host=1), no
    box. The treaty's tonnage limits are then lifted on both copies (`armstreaty set` with its own months and limits), so
    no Turn stops at them (if the conference cannot make one, the TEST treaty `armstreaty set 36 15000 12` on both copies
    stands in for c-e). c) war 1-J (`settension` on both copies): the client's screen refresh at war (`armstreaty war 1`,
    `armstreaty refresh` on the client) keeps the host's treaty with an older host's rule (TEST `armstreaty host 0`:
    "CancelTreaty left to the host") and ends it on its copy at once with this host's (`armstreaty host 1`, as the month's
    header says), never with a box; M2: the host ends the treaty once ("arms treaty: the war of nation(s) 1 ends the
    disarmament treaty"), chat "* The outbreak of war cancels the disarmament treaty! (...)", the game's line with the
    month in the client's turn report, no box on either copy, both copies without a treaty. d) M3 at war with the
    conference at the month's end (`econtreaty 100`): it sees the war through B2's mask (host log "the arms-control
    conference (CreateArmsControlTreaty) sees the war(s) of the nations people play: 1-J J-1"), ends with the game's "With
    a war already in progress" message: no treaty, nation 1's funds and BudgetModifier untouched by it (`econ 1`
    conference=1 treaty=0 treatyBM=0), the money check passes. e) M4 at war: no box, no treaty on either copy, no second
    end. The war months run with a BattleDriver (`war_month`). The suite's treaty guard is off meanwhile
    (ctx.keep_treaty). Ends at peace (peacetest 100 2 1), every nation's tonnage limit as it was."""
    ctx.keep_treaty = True
    try:
        _arms_treaty(ctx)
    finally:
        ctx.keep_treaty = False


def _arms_treaty(ctx):
    hp, cp = ctx.hp, ctx.cp
    K = 1
    for port, who in ((H, 'host'), (C, 'client')):
        ok = log_lines(log_since(port), r"Disarmament treaty with joined nations' wars: ok")
        check(f'start: {who} log "Disarmament treaty with joined nations\' wars: ok"', ok,
              [x.split('] ', 1)[-1] for x in log_lines(log_since(port), r"Disarmament treaty with")][:2])
    rr = relrules(H)
    h0, c0, t0 = arms_treaty(H), arms_treaty(C), econtreaty(H)
    hw = int(rel(0, 1).get('warCounter', '0'))
    check('start: nation 1 follows the player\'s rules, the host is at peace, `armstreaty` answers on both copies and '
          f'`econtreaty` on the host (host {h0}, client {c0})', rr is not None and K in rr and hw <= 0 and h0 and c0 and
          'armed' in t0, dict(relrules=rr, host_war=hw, econtreaty=t0))
    if not (rr and K in rr and hw <= 0 and h0 and c0 and 'armed' in t0):
        return
    cmd(H, 'mpwindow')
    cmd(C, 'mpwindow')
    # nation 1 starts at peace with everyone (an earlier scenario may leave a war with a computer nation)
    wars0 = [x for x in range(9) if x != K and rel(K, x).get('war') == '1']
    if wars0:
        cmark, hmark = log_mark(C), log_mark(H)
        cmd(C, 'peacetest 100 2 1')
        wait_peace(ctx, cmark, hmark)
    wars1 = [x for x in range(9) if x != K and rel(K, x).get('war') == '1']
    check(f'setup: nation {K} at peace with everyone (its wars at the start {wars0 or "none"} ended by peacetest 100 2 1)',
          not wars1, dict(before=wars0, after=wars1))
    if wars1:
        return
    nt = nation_table()
    humans = set(kwar_counters(H) or {}) | {0, K, STANDIN}
    cands = [j for j in range(3, 9) if j not in humans and j in nt and rel(K, j).get('war') == '0' and
             rel(K, j).get('ally') == '0' and not any(rel(j, x).get('war') == '1' for x in range(9) if x != j)]
    if not cands:
        check('setup: a computer nation at peace with everyone and not allied with nation 1', False, nt)
        return
    J = cands[0]
    others = [(a, b) for a in range(1, 9) for b in range(a + 1, 9) if a in nt and b in nt and rel(a, b).get('war') == '1']
    check('setup: no war among nations 1-8 (the conference at peace can make a treaty)', not others, others)
    log(f'  arms treaty: nation {K} {nt[K]["name"]} and the computer nation {J} {nt[J]["name"]}')

    # a) the host's own war under a treaty: the game's own box and end, as before
    ton = {n: (value(cmd(H, f'nfield {n} TreatyTonnageLimit')), value(cmd(C, f'nfield {n} TreatyTonnageLimit')))
           for n in range(9)}  # (the treaties below lift them: MaxInt, no tonnage limits)
    fields = ('DisplacementLimit', 'BuildConstraint')
    snap = {(n, f): value(cmd(H, f'nfield {n} {f}')) for n in range(9) for f in fields}
    cmd(H, 'armstreaty set 24 15000 12')
    hw0 = arms_treaty(H)['war']
    cmd(H, 'armstreaty war 1')
    t_a = time.time()
    r = cmd(H, 'armstreaty refresh')
    wait_until(lambda: (answer_dialogs(hp, 'host'), treaty_boxes(t_a, 'host'))[1], bool, 10)
    drain(hp, 2)
    ha = arms_treaty(H)
    cmd(H, f'armstreaty war {hw0}')
    for (n, f), v in snap.items():
        if v is not None:
            cmd(H, f'nfield {n} {f} {v}')
    cmd(H, 'armstreaty refresh')
    drain(hp, 2)
    ca = arms_treaty(C)
    check('a) the host\'s own war under a treaty (TEST armstreaty set 24 15000 12, war 1, refresh): the game\'s box '
          '"The outbreak of war cancels the disarmament treaty!" on the host, the treaty ended there (0 months, no '
          'limits), CancelTreaty not left to anyone; the client unchanged',
          r == 'ok' and len(treaty_boxes(t_a, 'host')) == 1 and ha and ha['months'] == 0 and ha['disp'] == NO_LIMIT and
          ha['cal'] == NO_LIMIT and ha['kept'] == h0['kept'] and ca and ca['months'] == c0['months'],
          dict(boxes=treaty_boxes(t_a), host=ha, client=ca))
    check(f'a) the host\'s war counter ({hw0}) and every nation\'s DisplacementLimit/BuildConstraint put back',
          arms_treaty(H)['war'] == hw0 and all(value(cmd(H, f'nfield {n} {f}')) == v for (n, f), v in snap.items()),
          snap)

    # b) M1 at peace: the game's conference at the month's end makes a treaty; its money for nation 1 in the record
    t_b = time.time()
    a = econtreaty(H, '100')
    hm = log_mark(H)
    run_month(ctx, 'arms_treaty M1')
    ht = log_since(H, hm)
    ran = re.findall(r'TEST: the arms-control conference ran: treaty months (-?\d+) -> (-?\d+)', ht)
    chg = [x.split('] ', 1)[-1] for x in log_lines(ht, rf'economy: nation {K}: the arms-control conference changed')]
    e = econ_kv(H, K)
    made = bool(ran) and int(ran[-1][1]) > 0
    old = int(e.get('fundsEnd', 0)) - int(e.get('after', 0)) - int(e.get('ruleFunds', 0))
    tf, tbm = int(e.get('treaty', '-1')), int(e.get('treatyBM', '0'))
    check(f'b) M1 at peace: the conference at the month\'s end (`econtreaty 100`) made a treaty ({ran}) and its effect on '
          f'nation {K} is in the month\'s record: `econ {K}` conference=1, treatyBM < 0 (the signing\'s -2), treaty= its '
          f'ships\' scrap value (>= 0) as the host log line has it, = the rest of the money check ({old:+d})',
          a.get('armed') == 100 and made and e.get('conference') == '1' and tbm < 0 and tf >= 0 and bool(chg) and
          f'by {tf:+d} and its BudgetModifier by {tbm:+d}' in chg[0] and old == tf,
          dict(ran=ran, line=chg[:1], econ={k: e.get(k) for k in (
              'conference', 'treaty', 'treatyBM', 'otherFunds', 'bm', 'after', 'ruleFunds', 'fundsEnd')}))
    hb, cb = arms_treaty(H), arms_treaty(C)
    check(f'b) M1: both copies show the same treaty (host {hb}, client {cb}); no box; the client knows the host\'s rule '
          '(header `armstreaty`: host=1)', made and treaty_same(hb, cb) and hb['months'] > 0 and hb['disp'] < NO_LIMIT and
          cb['host'] == 1 and not treaty_boxes(t_b), dict(boxes=treaty_boxes(t_b)))
    if made:  # its tonnage limits lifted (MaxInt) on both copies: no Turn stops at them
        for port in (H, C):
            cmd(port, f'armstreaty set {hb["months"]} {hb["disp"]} {hb["cal"]}')
    else:
        log('  NOTE b): no treaty from the conference: the TEST treaty (armstreaty set 36 15000 12) on both copies for c-e')
        for port in (H, C):
            cmd(port, 'armstreaty set 36 15000 12')
    hb, cb = arms_treaty(H), arms_treaty(C)

    # c) war 1-J; the client's screen at war: an older host's treaty stays, this host's ends there at once (no box);
    #    M2: the host ends it once
    hr, cr = peace_war(K, J)
    check(f'c) war {K}-{J} on both copies (settension) and nation {K}\'s war counter above 0 on the host',
          hr.get('war') == '1' and 'war=1' in (cr or '') and (kwar_counters(H) or {}).get(K, 0) > 0,
          dict(host=hr, client=cr, kwar=kwar_counters(H)))
    cw0 = cb['war']
    cmark, hmark, t_c = log_mark(C), log_mark(H), time.time()
    cmd(C, 'armstreaty host 0')
    cmd(C, 'armstreaty war 1')
    r = cmd(C, 'armstreaty refresh')
    wait_until(lambda: log_lines(log_since(C, cmark), r'arms treaty: CancelTreaty left to the host'), bool, 8)
    drain(cp, 2, 'client')
    cc = arms_treaty(C)
    kept = [x.split('] ', 1)[-1] for x in log_lines(log_since(C, cmark), r'arms treaty: CancelTreaty left to the host')]
    check('c) with an older host\'s rule (TEST armstreaty host 0, war 1, refresh): the client keeps the host\'s treaty '
          f'({cc and cc["months"]} months), no box, "CancelTreaty left to the host (a joined player\'s PC, an older host"',
          r == 'ok' and cc and treaty_same(cc, cb) and cc['kept'] > cb['kept'] and not treaty_boxes(t_c) and
          any('an older host' in x for x in kept), dict(client=cc, log=kept, boxes=treaty_boxes(t_c)))
    cmark = log_mark(C)
    cmd(C, 'armstreaty host 1')
    r = cmd(C, 'armstreaty refresh')
    wait_until(lambda: log_lines(log_since(C, cmark), r'arms treaty: ended on this PC'), bool, 8)
    drain(cp, 2, 'client')
    ce = arms_treaty(C)
    cmd(C, f'armstreaty war {cw0}')
    ended = [x.split('] ', 1)[-1] for x in log_lines(log_since(C, cmark), r'arms treaty: ended on this PC')]
    check('c) with this host\'s rule (host 1, as the month\'s header says): the client\'s refresh at war ends the treaty '
          'on its copy at once, without the box (0 months, no limits; "arms treaty: ended on this PC for its nation\'s '
          'war, as the host ends it")', r == 'ok' and ce and ce['months'] == 0 and ce['disp'] == NO_LIMIT and
          ce['cal'] == NO_LIMIT and ce['endedhere'] == cc['endedhere'] + 1 and len(ended) == 1 and
          not treaty_boxes(t_c), dict(client=ce, log=ended, boxes=treaty_boxes(t_c)))
    hc0 = chat(hp)
    cmark2 = log_mark(C)
    war_month(ctx, 'arms_treaty M2', K, J)
    drain(cp, 3, 'client')
    hl = log_since(H, hmark)
    ends = re.findall(rf'arms treaty: the war of nation\(s\) {K} ends the disarmament treaty \((\d+) month', hl)
    hc, cc = arms_treaty(H), arms_treaty(C)
    check(f'c) M2: the host ended the treaty once for nation {K}\'s war ("arms treaty: the war of nation(s) {K} ends '
          f'the disarmament treaty ({ends and ends[0]} month(s) left ...)"; armstreaty ends=1)', len(ends) == 1 and
          int(ends[0]) > 0 and hc and hc['ends'] == hb['ends'] + 1,
          [x.split('] ', 1)[-1] for x in log_lines(hl, r'arms treaty:')][:6])
    check('c) M2: no treaty on either copy (0 months, no limits); no box on either copy since the war',
          treaty_same(hc, cc) and hc['months'] == 0 and hc['disp'] == NO_LIMIT and hc['cal'] == NO_LIMIT and
          not treaty_boxes(t_c), dict(host=hc, client=cc, boxes=treaty_boxes(t_c)))
    line = '* The outbreak of war cancels the disarmament treaty! ('
    txt = wait_until(lambda: chat(hp), lambda t: t.count(line) > hc0.count(line), 8)
    reps = [t for (tm, w, k, t) in BOX_SEEN if tm >= t_c and w == 'client' and k == 'TdlgCampTurnRep']
    sent = log_lines(hl, rf'arms treaty: the turn report line of nation {K} goes with state seq')
    shown = log_lines(log_since(C, cmark2), r'economy: showing \d+ message')
    in_rep = any('The outbreak of war cancels the disarmament treaty!' in t for t in reps)
    log(f'  arms treaty: a recorded turn report of the client holds the line: {in_rep} ({len(reps)} recorded)')
    check('c) M2: host chat "* The outbreak of war cancels the disarmament treaty! (...)"; the game\'s line "The '
          'outbreak of war cancels the disarmament treaty!" went with the month and the client showed its turn report',
          txt.count(line) > hc0.count(line) and len(sent) == 1 and shown,
          dict(chat=txt[-300:], sent=sent, shown=shown, reports=[t[:400] for t in reps]))

    # d) M3 at war: the conference at the month's end sees nation 1's war and ends at once; nothing in the record
    others = [(a, b) for a in range(1, 9) for b in range(a + 1, 9) if K not in (a, b) and a in nt and b in nt and
              rel(a, b).get('war') == '1']
    a = econtreaty(H, '100')
    hm, t_d = log_mark(H), time.time()
    war_month(ctx, 'arms_treaty M3', K, J)
    ht = log_since(H, hm)
    seen = [x.split('] ', 1)[-1] for x in log_lines(ht, r'the arms-control conference \(CreateArmsControlTreaty\) sees')]
    ran = re.findall(r'TEST: the arms-control conference ran: treaty months (-?\d+) -> (-?\d+)', ht)
    pic = [t[:120] for (tm, w, k, t) in BOX_SEEN if tm >= t_d and w == 'host' and 'With a war already in progress' in t]
    e = econ_kv(H, K)
    hd, cd = arms_treaty(H), arms_treaty(C)
    check(f'd) M3: the conference at the month\'s end during the war {K}-{J} (`econtreaty 100`) saw the war through the '
          f'mask (host log "... sees the war(s) of the nations people play: {K}-{J} {J}-{K}"), ended with the game\'s '
          f'"With a war already in progress" message: no treaty on either copy, nation {K}\'s funds and BudgetModifier '
          f'untouched by it (`econ {K}` conference=1 treaty=0 treatyBM=0; other wars of nations 1..8: {others or "none"})',
          a.get('armed') == 100 and bool(seen) and f' {K}-{J}' in seen[0] and ran == [('0', '0')] and len(pic) >= 1 and
          e.get('conference') == '1' and e.get('treaty') == '0' and e.get('treatyBM') == '0' and hd and
          hd['months'] == 0 and treaty_same(hd, cd),
          dict(seen=seen[:1], ran=ran, boxes=pic, econ={k: e.get(k) for k in (
              'conference', 'treaty', 'treatyBM', 'otherFunds', 'bm')}, host=hd, client=cd))

    # e) one more month at war: no box, no treaty, no second end
    war_month(ctx, 'arms_treaty M4', K, J)
    he, ce = arms_treaty(H), arms_treaty(C)
    kw = (kwar_counters(H) or {}).get(K)
    check(f'e) M2-M4 at war (nation {K}\'s war counter {kw}): no box on either copy, no treaty on either copy, no '
          f'second end (ends={he and he["ends"]})', kw is not None and kw >= 3 and treaty_same(he, ce) and
          he['months'] == 0 and he['ends'] == hc['ends'] and not treaty_boxes(t_c), dict(host=he, client=ce,
                                                                                          boxes=treaty_boxes(t_c)))
    # ends at peace (the game's peace in nation 1's view)
    cmark, hmark = log_mark(C), log_mark(H)
    r = cmd(C, 'peacetest 100 2 1')
    wait_peace(ctx, cmark, hmark)
    hr = rel(K, J)
    check(f'end: peace {K}-{J} (peacetest 100 2 1): the war is over on the host', r == 'ok' and hr.get('war') == '0', hr)
    if (h0['disp'], h0['cal']) != (NO_LIMIT, NO_LIMIT):
        cmd(H, f'armstreaty set {h0["months"]} {h0["disp"]} {h0["cal"]}')
    for n, (vh, vc) in ton.items():  # every nation's tonnage limit as it was, on both copies (the client's own nation's
        for port, v in ((H, vh), (C, vc)):  # goes back to the host with its turn)
            if v is not None:
                cmd(port, f'nfield {n} TreatyTonnageLimit {v}')


def scenario_relations_war(ctx):
    """0.6.1: the tension bar above the war line (a 0.6.0 report: "The tension bar when exceeds the critical threshold
    and no war is declared for non host"). a) nation 1 under the player's rules, a computer nation J at peace with
    everyone and without a war plan against it, their tension 15 (+ nation 1's wars: CheckForWar declares at 13 + the
    nations at war with the player) on both copies, nation 1's war counter -10 for the month (`kwar 1 -10`: at War < -48
    CheckForWar's rumours (Random(180) < tension) may take the declaration's place): nation 1's relation turn of the
    next month (RandomTensionChanges, TensionEffectOfPreviousWars, then CheckForWar once, as the game's month) declares
    the war: war 1-J on both copies, the client's "relations for nation 1 sent: ... ran=...war" and the host's "war 1-J",
    the game's war message among the client's boxes. b) the tension between the players 25 on both copies (the host's
    war-line memory cleared first, `warline forget`): after the month the other player's tension bar on both PCs (host
    slot 1, client slot 1 = the host's nation) says that wars between players are declared only by the players (`relview`),
    no computer nation's bar does, `warline` lists the people's nations on both PCs, the chat line "* Tension between
    <host's nation> and <nation 1> is N, above the war line. ..." once on each PC and not again (`warline check`: told=0),
    no war 0-1; the stand-in's nation 2 (reserved, its player not connected) is a person's on both PCs too: its bar has
    the hint while at peace with it, `warline` lists it (0.6.1: the host saw it as a computer nation before). Ends at
    peace (`peacetest 100 2 1`), the tension 0-1 and nation 1's war counter as they were."""
    hp, cp = ctx.hp, ctx.cp
    K = 1
    ver = build_version() or ''
    if tuple(int(x) for x in re.findall(r'\d+', ver.split('-')[0])[:3]) < (0, 6, 1):
        log(f'  relations_war: the build under test is {ver or "unknown"}; the war line\'s messages came with 0.6.1: '
            f'skipped')
        return
    rr = relrules(H)
    pl0 = peacelast(C)
    check('start: nation 1 follows the player\'s rules (`relrules`) and the client has a B4 host (`peacelast` host=1)',
          rr is not None and K in rr and pl0.get('host') == '1', dict(relrules=rr, client=pl0.get('raw', '')[:200]))
    if not (rr and K in rr and pl0.get('host') == '1'):
        return
    cmd(H, 'mpwindow')
    cmd(C, 'mpwindow')
    nt = nation_table()
    humans = set(kwar_counters(H) or {}) | {0, K, STANDIN}
    will = (re.search(r'will=([\d.]+)', cmd(C, 'rellast')) or [None, ''])[1].split('.')
    cands = [j for j in range(3, 9) if j not in humans and j in nt and rel(K, j).get('war') == '0' and
             rel(K, j).get('ally') == '0' and (len(will) != 9 or will[j] == '0') and
             not any(rel(j, x).get('war') == '1' for x in range(9) if x != j)]
    if not cands:
        check('setup: a computer nation at peace with everyone, not allied with nation 1, no war plan against it', False,
              dict(nations=nt, will=will))
        return
    J = cands[0]
    nH, nK, nJ = nt[0]['name'], nt[K]['name'], nt[J]['name']
    wars = [x for x in range(9) if x != K and rel(K, x).get('war') == '1']
    t_kj = 15 + len(wars)
    kw0 = (kwar_counters(H) or {}).get(K)
    t01 = int(rel(0, K).get('tension', 5))
    log(f'  relations_war: nation {K} {nK} and the computer nation {J} {nJ} (tension {t_kj}; nation {K}\'s wars {wars}, '
        f'war counter {kw0}); the players {nH}-{nK} at {t01} -> 25')
    for port in (H, C):
        cmd(port, f'settension {K} {J} {t_kj}')
        cmd(port, f'settension 0 {K} 25')
    cmd(H, f'kwar {K} -10')
    wf = cmd(H, 'warline forget')
    hc0, cc0 = chat(hp), chat(cp)
    n_box = len(BOX_SEEN)
    hmark0, cmark0 = log_mark(H), log_mark(C)
    run_month(ctx, 'relations_war M1')

    # a) the computer nation's war, from nation 1's relation turn
    hr, cr = rel(K, J), value(cmd(C, f'rel {K} {J}')) or ''
    sent = [x.split('] ', 1)[-1] for x in log_lines(log_since(C, cmark0), r'relations for nation 1 sent: ')]
    applied = [x.split('] ', 1)[-1] for x in log_lines(log_since(H, hmark0), r'relations of .*\(nation 1;')]
    boxes = [t for _, w, _, t in BOX_SEEN[n_box:] if w == 'client' and nJ in t and re.search(
        r'declared war on us|state of war|War has broken out between|joined the war against', t)]
    check(f'a) nation {K}\'s relation turn ran CheckForWar after the tension routines and {nJ} went to war with it '
          f'(tension {t_kj}): war {K}-{J} on both copies, the client\'s "ran=...war", the host\'s "war {K}-{J}", the game\'s '
          f'war message on the client', hr.get('war') == '1' and 'war=1' in cr and
          any(re.search(r'ran=(tension,)?previous wars,war', x) for x in sent) and
          any(re.search(rf'war {K}-{J}(\D|$)', x) for x in applied) and bool(boxes),
          dict(host=hr, client=cr, sent=[x[:300] for x in sent], applied=[x[:300] for x in applied], boxes=boxes[:3]))

    # b) the players: the bars' hints, the chat line once, no war
    tail = (' - played by a person: wars between players are declared only in the Multiplayer window (Diplomacy), '
            'never by the game')
    line_re = re.compile(rf'\* Tension between {re.escape(nH)} and {re.escape(nK)} is (\d+), above the war line\. Wars '
                         r'between players are declared only by the players \(Multiplayer window, Diplomacy\); the game '
                         r'will not declare one\.')
    hc, cc = wait_month_chat(hp, hc0), wait_month_chat(cp, cc0)
    hn, cn = len(line_re.findall(hc)) - len(line_re.findall(hc0)), len(line_re.findall(cc)) - len(line_re.findall(cc0))
    told = [x.split('] ', 1)[-1] for x in log_lines(log_since(H, hmark0), r'war line: ')]
    wc = cmd(H, 'warline check')
    hc2, cc2 = chat(hp), wait_until(lambda: chat(cp), lambda t: len(line_re.findall(t)) > len(line_re.findall(cc)), 3)
    check(f'b) the chat line "* Tension between {nH} and {nK} is N, above the war line. ..." once on each PC '
          f'(got {hn}, {cn}) and not again (`warline check`: {wc})', wf.startswith('ok') and hn == 1 and cn == 1 and
          'told=0' in wc and len(line_re.findall(hc2)) == len(line_re.findall(hc)) and
          len(line_re.findall(cc2)) == len(line_re.findall(cc)),
          dict(host=line_re.findall(hc)[-1:], client=line_re.findall(cc)[-1:], log=[x[:300] for x in told]))
    hv, cv = relview(H), relview(C)
    hs, cs = (hv or {}).get('slots', {}), (cv or {}).get('slots', {})
    comp = [(who, i) for who, sl in (('host', hs), ('client', cs)) for i in range(1, 9)
            if i != K and i != STANDIN and sl.get(i, {}).get('hint', '').endswith(tail)]
    wh, wcl = cmd(H, 'warline'), cmd(C, 'warline')
    check(f'b) the other player\'s bar says wars between players come only from the players: host slot {K} '
          f'"Tension with {nK} is N{tail}", client slot {K} (the host\'s nation) "Tension with {nH} is N...", no '
          f'computer nation\'s bar; `warline` people: host {K}, client 0', bool(hs) and bool(cs) and
          hs.get(K, {}).get('hint', '').startswith(f'Tension with {nK} is ') and hs[K]['hint'].endswith(tail) and
          cs.get(K, {}).get('hint', '').startswith(f'Tension with {nH} is ') and cs[K]['hint'].endswith(tail) and
          not comp and re.search(rf'people=(\S*,)?{K},', wh) and re.search(r'people=0,', wcl),
          dict(host=hs.get(K), client=cs.get(K), computer=comp, warline=(wh, wcl)))
    if STANDIN in nt:  # 0.6.1: a nation reserved for a player who isn't connected is played by a person on both PCs
        hsd, csd = rel(0, STANDIN), value(cmd(C, f'rel {K} {STANDIN}')) or ''
        hh, ch = hs.get(STANDIN, {}).get('hint', ''), cs.get(STANDIN, {}).get('hint', '')
        ph, pc = hsd.get('war') == '0', 'war=0' in csd
        check(f'b) the stand-in\'s nation {STANDIN} {nt[STANDIN]["name"]} (reserved; players: '
              f'{lsn(H).get("players")}) is played by a person on both PCs: its bar has the hint at peace (host '
              f'{"at peace" if ph else "at war"} with it, client {"at peace" if pc else "at war"}), `warline` people '
              f'lists it on both', hh.endswith(tail) == ph and ch.endswith(tail) == pc and
              bool(re.search(rf'people=(\S*,)?{STANDIN},', wh)) and bool(re.search(rf'people=(\S*,)?{STANDIN},', wcl)),
              dict(host=hh, client=ch, rel=(hsd, csd), warline=(wh, wcl)))
    h01, c01 = rel(0, K), value(cmd(C, f'rel 0 {K}')) or ''
    check(f'b) no war between the players ({nH}-{nK}: tension {h01.get("tension")} on the host)',
          h01.get('war') == '0' and 'war=0' in c01 and int(h01.get('tension', 0)) >= 11, dict(host=h01, client=c01))

    # ends at peace (the game's peace in nation 1's view), the players' tension and nation 1's war counter as they were
    if any(rel(K, x).get('war') == '1' for x in range(1, 9) if x not in humans):
        cmark, hmark = log_mark(C), log_mark(H)
        r = cmd(C, 'peacetest 100 2 1')
        wait_peace(ctx, cmark, hmark)
        hr = rel(K, J)
        check(f'end: peace {K}-{J} (peacetest 100 2 1): the war is over on the host', r == 'ok' and hr.get('war') == '0',
              hr)
    for port in (H, C):
        cmd(port, f'settension 0 {K} {t01}')
    if kw0 is not None and not any(rel(K, x).get('war') == '1' for x in range(9) if x != K):
        cmd(H, f'kwar {K} {kw0}')


def scenario_war_effects(ctx):
    """0.6.0 (B5): the player's war effects for nation 1 under the player's rules. A computer nation J at war with nation 1
    and a computer ally X of nation 1 at war with J (`settension`/`setally` on both copies), the host at peace.
    M1: `warfxblk J 1` (TEST: J blockaded in the war effects' test, warfx.cpp) and `allyrand 0` (TEST: the allies' war
    help draws 0 on the client): the month's blockade check and J's DoBlockadeEffects credit nation 1 (two host lines,
    nation 1's VP and its war score with J in the ledger up by their sum), J's Blockaded flag on the host and on the
    client (`kblk`), nation 1's message "Gain x VP for blockade of enemy" in its turn report; the next month's relation
    turn runs the allies' war help on the client (war counter 2): X's operations add VP to nation 1 and the host applies
    them to its VP and its war score (`allyvp 1-J+n`). M2: `warfxblk J -1`, `warfxblk 1 1` (nation 1 blockaded): J credited
    twice (J's VP and its side of the score), nation 1's flag on both copies, its message "The enemy gains x VP for
    blockading us", the month's StopBlockadedMoves of the next month runs with War 1 (the host at peace: logged). The
    host's own VP and EnemyVP unchanged. M2 also (c) raiders, submarines and the trade war (0.6.0): `warfxsea 1 6` (TEST:
    six of nation 1's ships raid in J's build area in the month's sea war frame): its frame (its view, counter 2) sinks
    J's merchants (the frame's log line, J's MerchantsLostToRaidersThisTurn), the trade war credits nation 1 vs J (VP and
    its side of the war score), no enemy raiders against the blockaded nation 1, its report gets the raider's line and
    "Trade war this month: ...", the host shows no dialog for it. War weariness (0.6.0): nation 1 with government 2 and BudgetModifier 20 (`nfield`
    on both copies); M1 winning by its own score (`kwarvp 1 J 100 0`): the player's rule logs "no (not losing)" and the
    game's own rule runs for the eight other nations; M2 losing (`kwarvp 1 J 0 5000`, `warfxrand 0`): unrest +1 and the
    message "Our people is getting dissatisfied with the bad war situation!". M3 also the war loan (0.5.0's rule for
    nation 1, confirmed here at war) after the war budget of its own counter (0.6.0): `kwar 1 4`, `econrand 1`,
    BudgetModifier 3 and UnrestLevel 2 on both copies -> the war budget 3 -> 4 with "War budget means increased
    allocations to the navy!", `econ` loan=1 with the "... authorizes additional war loan! ..." text, BudgetModifier 5 on
    both copies (+ the new month's own changes of nation 1 by its PC's event and relation turn, as the host log has them:
    e.g. the intelligence result's "Give it maximum publicity ..." answer, BudgetModifier+1). Building for war (0.6.0):
    before M1 a ship of nation 1 under construction set to be built in J's yard
    and one of J's in nation 1's yard (TEST `shipbuilder`, both copies); nation 1's PC hands both over in its relation
    turn after M1, the host applies them (`findship` on both copies). The war months M1-M3 run with a BattleDriver
    (`war_month`): a battle of the month is declined, or fought on auto-run when the game allows no decline.
    M4 (the enemy-revolution rule, 0.6.0): the host's nation at war with nation 1 too (`diplo war 1`), `revotest 0 J:25
    0:25` on the client and nation 1's unrest 25 on both copies: J's revolution on nation 1's PC ends the war 1-J by the
    general peace, the host applies it; the war 0-1 stays out of the rule on both sides (logged on each) and goes on; a
    battle of the host against nation 1 in that month runs through the live months' tools (`ls_month`, drop12).
    Ends at peace (the wars, the alliance, the fields and the test knobs undone; the war 0-1 by the players' peace)."""
    K = 1
    hl = log_lines(log_since(H), r"warfx: the player's war effects for joined nations")
    cl = log_lines(log_since(C), r'War help from allies for a joined nation')
    check('start: host log "warfx: the player\'s war effects for joined nations: blockades ok", client log "War help '
          'from allies for a joined nation: ok"', any('blockades ok' in x for x in hl) and any(': ok' in x for x in cl),
          [x.split('] ', 1)[-1] for x in hl + cl][:3])
    rr = relrules(H)
    if not (rr and K in rr) or warfx_state() is None:
        check('start: nation 1 follows the player\'s rules (`relrules`) and the host answers `warfx`', False, rr)
        return
    cmd(H, 'mpwindow')
    cmd(C, 'mpwindow')
    nt = nation_table()
    humans = set(kwar_counters(H) or {}) | {0, K, STANDIN}
    cands = [j for j in range(3, 9) if j not in humans and j in nt and rel(K, j).get('war') == '0' and
             rel(K, j).get('ally') == '0' and not any(rel(j, x).get('war') == '1' for x in range(9) if x != j)]
    if len(cands) < 2 or rel(0, 1).get('warCounter', '0').lstrip('-').isdigit() and int(rel(0, 1)['warCounter']) > 0:
        check('setup: two computer nations at peace with everyone, the host at peace', False, cands)
        return
    J, X = cands[:2]
    log(f'  B5: nation {K} {nt[K]["name"]}, its enemy {J} {nt[J]["name"]}, its ally {X} {nt[X]["name"]}')
    hr, cr = peace_war(K, J)
    for port in (H, C):
        cmd(port, f'setally {K} {X} 24')
        cmd(port, f'settension {K} {X} 2')
        cmd(port, f'settension {X} {J} 50')
    check(f'setup: war {K}-{J}, alliance {K}-{X}, war {X}-{J} on both copies', hr.get('war') == '1' and
          'war=1' in (cr or '') and rel(K, X).get('ally') not in (None, '0') and rel(X, J).get('war') == '1' and
          'war=1' in (cmd(C, f'rel {X} {J}') or ''), dict(kj=hr, kx=rel(K, X), xj=rel(X, J)))
    cmd(H, f'warfxblk {J} 1')
    cmd(H, f'warfxblk {K} 0')
    cmd(C, 'allyrand 0')
    # 0.6.0 (round 4): the blockade tests count the allies from nation 1's side (its view on the host): its ally X at war
    # with J adds to its strength against J there, not on the host's frame (X is not the host's ally)
    sp = cmd(H, f'warfx strength {K} {J}') or ''
    sh, sv = (sp.split(' | view ', 1) + [''])[:2]
    check(f'setup: `warfx strength {K} {J}`: nation {K}\'s ally {X} ({nt[X]["name"]}, at war with {J}) counts in its view '
          f'(the game\'s account lists it), not on the host\'s frame', sp.startswith('ok') and
          nt[X]['name'] in sv.split(':', 1)[-1] and nt[X]['name'] not in sh, sp[:400])
    # war weariness (0.6.0): nation 1 with government 2 and BudgetModifier 20 on both copies, winning in M1
    gov0, bm0, un0 = ({p: nint(p, K, f) for p in (H, C)} for f in ('GovernmentType', 'BudgetModifier', 'UnrestLevel'))
    for port in (H, C):
        cmd(port, f'nfield {K} GovernmentType {(gov0[port] & ~0xFF) | 2}')
        cmd(port, f'nfield {K} BudgetModifier 20')
    cmd(H, f'kwarvp {K} {J} 100 0')
    # building for war (0.6.0): a ship of nation 1 under construction in J's yard and one of J's in nation 1's yard (TEST
    # `shipbuilder` on both copies): nation 1's PC takes J's and loses its own in its relation turn after M1
    bk, bj = ([x for x in (cmd(H, f'shipbuilder {n}') or '').split()[1:] if x.count(':') == 2] for n in (K, J))
    # the newest ship of each (the highest CShipId: laid down last, the most building time left): an older one can be
    # commissioned in M1 before nation 1's relation turn (a `--group relations` run of 2026-10-23: J's ship 262)
    newest = lambda lst: max(lst, key=lambda x: int(x.split(':')[1]))  # noqa: E731
    sk = tuple(int(v) for v in newest(bk).split(':')) if bk else None
    sj = tuple(int(v) for v in newest(bj).split(':')) if bj else None
    for port in (H, C):
        if sk and sj:
            cmd(port, f'shipbuilder {K} {sk[0]} {J}')
            cmd(port, f'shipbuilder {J} {sj[0]} {K}')
    vp0, e0, l0 = nint(H, K, 'VP'), value(cmd(H, 'ffield EnemyVP')), kwarvp(K)
    h0 = nint(H, 0, 'VP')
    hm, cm = log_mark(H), log_mark(C)
    war_month(ctx, 'war_effects M1', K, J)
    rl = [x.split('] ', 1)[-1] for x in wait_log(H, hm, r'relations of .*\(nation 1;', 30)]
    ht, ct = log_since(H, hm), log_since(C, cm)
    cr1 = blockade_credits(ht)
    gain = sum(v for g, v, lo in cr1 if g == K and lo == J)
    ah = [x.split('] ', 1)[-1] for x in log_lines(ct, r'war help from allies for nation 1 \(')]
    m = re.search(r'war counter (\d+)\): VP (-?\d+)', ah[-1]) if ah else None
    avp = int(m[2]) if m else 0
    vp1, l1 = nint(H, K, 'VP'), kwarvp(K)
    lk = lambda led: (led or {}).get('pairs', {}).get(J, (0, 0))
    check(f'M1: J\'s blockade: two credits to nation {K} in the host\'s log (the check\'s and the effects\') and no '
          f'other blockade credit', len([1 for g, v, lo in cr1 if g == K and lo == J]) == 2 and
          all(g == K for g, v, lo in cr1), cr1)
    check(f'M1: the allies\' war help ran on the client (war counter 2) and ally {X} added VP; the host applied it '
          f'(VP {avp}, allyvp {K}-{J}+{avp})', m is not None and m[1] == '2' and avp > 0 and
          any(f' VP {avp}' in x and f'allyvp {K}-{J}+{avp}' in x for x in rl), dict(client=ah[:2], host=rl[:2]))
    bk, bj = battle_war_score(ht, K, J)  # a battle of the month (declined or fought) has its own points
    check(f'M1: nation {K}\'s war score with {J} up by the blockade credits {gain} and the allies\' {avp} (+ the battles\' '
          f'{bk}/{bj}; kwarvp), its VP by at least as much', lk(l1)[0] - lk(l0)[0] == gain + avp + bk and
          lk(l1)[1] - lk(l0)[1] == bj and vp1 - vp0 >= gain + avp, dict(vp=(vp0, vp1), ledger=(lk(l0), lk(l1))))
    w = warfx_state()
    check(f'M1: J\'s Blockaded flag on the host and on the client (kblk), not nation {K}\'s',
          w and J in w['flags'] and K not in w['flags'] and nflag(C, J, 'Blockaded') == 1 and nflag(C, K, 'Blockaded') == 0,
          dict(host=w and w['raw'][:200], client=(nflag(C, J, 'Blockaded'), nflag(C, K, 'Blockaded'))))
    bm = [x.split('] ', 1)[-1] for x in log_lines(ht, r'warfx: blockade check \(month\)')]
    check(f'M1: the month\'s blockade tests of nation {K} ran in its own view (0.6.0: the allies from its side)',
          bool(bm) and f' {K}(war ' in bm[0] and '(its view);' in bm[0], bm[:1])
    check(f'M1: nation {K}\'s message "Gain x VP for blockade of enemy" went with the month and the client showed the '
          f'month\'s messages', log_lines(ht, r'warfx: message for nation 1: Gain \d+ VP for blockade of enemy') and
          log_lines(ct, r'economy: showing \d+ message'),
          [x.split('] ', 1)[-1] for x in log_lines(ht, r'warfx: message for nation 1')][:3])
    wl = [x.split('] ', 1)[-1] for x in log_lines(ht, r'warfx: war weariness')]
    kl = [x for x in wl if 'of nation 1 (' in x]
    sm = [x for x in wl if 'this month' in x]
    check(f'M1: nation {K}\'s war weariness by its own war counter and score (government 2, BM 20, winning): no unrest; '
          f'the game\'s own rule for the other eight nations', len(kl) == 1 and 'government 2, BM 20' in kl[0] and
          'no (not losing)' in kl[0] and bool(sm) and
          all(f'{n},' in sm[0].split("game's own for ", 1)[-1] for n in (0, 2, 3, 4, 5, 6, 7, 8)), wl[:3])
    cb = [x.split('] ', 1)[-1] for x in log_lines(ct, r'relations v2: building for war for nation 1 ')]
    if sk and sj:
        idk, idj = sk[1], sj[1]
        check(f'M1: building for war on nation {K}\'s PC (its counter 2): ship {idk} (its own, in {J}\'s yard) taken by '
              f'{J}, ship {idj} ({J}\'s, in its yard) taken by it; the host applied both; on both copies',
              bool(cb) and f'{idk}:{K}>{J}' in cb[0] and f'{idj}:{J}>{K}' in cb[0] and
              any(f'seized ship {idk} {K}->{J}' in x and f'seized ship {idj} {J}->{K}' in x for x in rl) and
              ship_holders(H, idk) == [J] and ship_holders(C, idk) == [J] and ship_holders(H, idj) == [K] and
              ship_holders(C, idj) == [K], dict(client=cb[:1], host=rl[:1]))
    else:
        # nation 1's ships under construction can all be complete by then (a --stress run of 2026-10-23: more months
        # before `war_effects`): the check can't be shown (no check)
        log(f'  SKIP-note M1 building for war: nation {K} or {J} has no ship under construction (`shipbuilder`: '
            f'{K} {sk}, {J} {sj})')

    # M2: nation 1 blockaded, and losing by its own score (war weariness with the war effects' draws 0)
    cmd(H, f'warfxblk {J} -1')
    cmd(H, f'warfxblk {K} 1')
    cmd(C, 'allyrand -1')
    cmd(H, f'settension {X} {J} 30')
    cmd(C, f'settension {X} {J} 30')
    cmd(H, f'kwarvp {K} {J} 0 5000')
    cmd(H, 'warfxrand 0')
    # (c) raiders, submarines and the trade war (0.6.0): six of nation 1's ships raid in J's build area for M2's sea war
    # frame (TEST `warfxsea`; nation 1 blockaded: no enemy raiders against it, the game's rule)
    sea_on = 'searule=1' in (cmd(H, f'warfx {K}') or '')
    if sea_on:
        cmd(H, f'warfxsea {K} 6')
        cmd(H, f'warfxblk {J} 0')  # J not blockaded (else its merchants stay at home: the game's raider rule)
    t2 = time.time()
    vj0, l0 = nint(H, J, 'VP'), kwarvp(K)
    hm, cm = log_mark(H), log_mark(C)
    war_month(ctx, 'war_effects M2', K, J)
    ht = log_since(H, hm)
    cr2 = blockade_credits(ht)
    jg = sum(v for g, v, lo in cr2 if g == J and lo == K)
    tc2 = trade_credits(ht)
    tk = sum(v for g, v, lo in tc2 if g == K and lo == J)
    tj = sum(v for g, v, lo in tc2 if g == J and lo == K)
    vj1, l1 = nint(H, J, 'VP'), kwarvp(K)
    bk, bj = battle_war_score(ht, K, J)
    check(f'M2: nation {K} blockaded: two credits to {J} (the check\'s and the effects\'), {J}\'s side of the war score up '
          f'by {jg} (+ the battles\' {bj}, the trade war\'s {tj}), its VP by at least as much',
          len([1 for g, v, lo in cr2 if g == J and lo == K]) == 2 and lk(l1)[1] - lk(l0)[1] == jg + bj + tj and
          vj1 - vj0 >= jg, dict(credits=cr2, trade=tc2, vp=(vj0, vj1), ledger=(lk(l0), lk(l1))))
    if sea_on:
        sl = [x.split('] ', 1)[-1] for x in log_lines(ht, rf'warfx: sea war of nation {K} \(')]
        m = re.search(rf' {J}: raiders (\d+)/(\d+), subs (\d+)/(\d+), VP \+(\d+)/\+(\d+);', sl[0]) if sl else None
        a = [int(x) for x in m.groups()] if m else [0] * 6
        lost = nint(H, J, 'MerchantsLostToRaidersThisTurn')
        check(f'M2 (c): nation {K}\'s raiders (TEST `warfxsea {K} 6`) sink {J}\'s merchants in its frame (its view, war '
              f'counter > 1): {J}\'s merchants lost (the frame\'s count), the trade war credits {K} +x vs {J} (the '
              f'frame\'s VP; its side of the war score up by at least x); no enemy raiders against the blockaded {K}',
              bool(sl) and 'its view' in sl[0] and 'TEST: 6 raider(s)' in sl[0] and a[0] > 0 and
              tk == a[4] > 0 and tj == a[5] and a[1] == 0 and 'blockaded (no enemy raiders)' in sl[0] and
              lk(l1)[0] - lk(l0)[0] >= tk, dict(frame=sl[:1], lost=lost, trade=tc2, ledger=(lk(l0), lk(l1))))
        news = [x.split('] ', 1)[-1] for x in log_lines(ht, rf'warfx: message for nation {K}: .*(sinks|Trade war this month)')]
        ct = log_since(C, cm)
        boxes = [c for t, who, c in ANSWERED if t >= t2 and who == 'host' and 'SubmarineWarfareSummary' in c] + \
            [ln[:120] for x in BOX_SEEN if x[0] >= t2 and x[1] == 'host' for ln in sea_war_box_lines(x[3])]
        drop = [x.split('] ', 1)[-1] for x in log_lines(ht, r'warfx: sea war: the computer\'s submarine sinkings dropped')]
        check(f'M2 (c): nation {K}\'s report gets the frame\'s lines (the raider\'s "... sinks n merchant ships in ..." and '
              f'"Trade war this month: ..."; client "economy: showing N message"), the host shows no dialog for it',
              any('sinks' in x for x in news) and any('Trade war this month' in x for x in news) and
              bool(log_lines(ct, r'economy: showing \d+ message')) and not boxes,
              dict(news=news[:3], host_boxes=boxes[:3], dropped=drop[:1]))
        cmd(H, f'warfxblk {J} -1')
    w = warfx_state()
    check(f'M2: nation {K}\'s Blockaded flag on both copies; its message "The enemy gains x VP for blockading us"',
          w and K in w['flags'] and nflag(C, K, 'Blockaded') == 1 and
          log_lines(ht, r'warfx: message for nation 1: The enemy gains \d+ VP for blockading us'),
          dict(host=w and w['raw'][:200], client=nflag(C, K, 'Blockaded')))
    kl = [x.split('] ', 1)[-1] for x in log_lines(ht, r'warfx: war weariness of nation 1 \(')]
    m = re.search(r'blockaded 1 -> unrest (\d+) -> (\d+)', kl[0]) if kl else None
    check(f'M2: nation {K} losing by its own score, blockaded, draws 0: the war weariness adds 1 unrest and its message '
          f'"Our people is getting dissatisfied with the bad war situation!"', m is not None and
          int(m[2]) == int(m[1]) + 1 and
          bool(log_lines(ht, r'warfx: message for nation 1: Our people is getting dissatisfied')), kl[:2])
    # M3: StopBlockadedMoves; the war budget and the war loan at nation 1's counter 4 (BudgetModifier 3: the war budget's
    # 3 < Random(16) + 8 -> 4, its text "War budget means increased allocations to the navy!" (counter even); econrand 1:
    # the loan's Random(4) + 2 = 3 < 4, Random(16) + 10 = 11 > 4 -> 5)
    cmd(H, 'warfxrand -1')
    for port in (H, C):
        cmd(port, f'nfield {K} BudgetModifier 3')
        cmd(port, f'nfield {K} UnrestLevel 2')
    cmd(H, f'kwar {K} 4')
    cmd(H, 'econrand 1')
    hm = log_mark(H)
    war_month(ctx, 'war_effects M3', K, J)
    ht = log_since(H, hm)
    sl = log_lines(ht, r'warfx: StopBlockadedMoves \(run with War 1')
    check(f'M3: the month\'s StopBlockadedMoves ran with War 1 for nation {K} (the host at peace: its flag since the load)',
          any(f' {K}:' in x for x in sl), [x.split('] ', 1)[-1] for x in sl][:2])
    e = cmd(H, f'econ {K}') or ''
    ln = [x.split('] ', 1)[-1] for x in log_lines(ht, r'economy: nation 1 news: .*war loan')]
    gl = [x.split('] ', 1)[-1] for x in log_lines(ht, r"warfx: building for war: nation 1's war budget: BudgetModifier 3 -> 4")]
    # the new month's own changes of nation 1 before this check, on both copies (its PC's event and relation turn; a run
    # of 2026-10-23: the intelligence result's "Give it maximum publicity ..." answer, BudgetModifier+1)
    wait_log(H, hm, rf'relations of .* \(nation {K}; ', 10)
    own = own_field_changes(log_since(H, hm), 'BudgetModifier', K)
    want = 5 + sum(d for _, d in own)
    check(f'M3: nation {K}\'s war budget (its counter 4: BudgetModifier 3 -> 4, "War budget means increased allocations to '
          f'the navy!") and war loan (econ loan=1, the text "... authorizes additional war loan! ..."): BudgetModifier 5 '
          f'(+ the new month\'s own changes by its PC\'s event and relation turn, host log: {own or "none"}) on both copies',
          re.search(r'\bloan=1\b', e) is not None and bool(gl) and bool(ln) and
          bool(log_lines(ht, r'warfx: message for nation 1: War budget means increased allocations to the navy!')) and
          nint(H, K, 'BudgetModifier') == want and nint(C, K, 'BudgetModifier') == want,
          dict(econ=e[:160], bm=(nint(H, K, 'BudgetModifier'), nint(C, K, 'BudgetModifier')), want=want, own=own,
               grant=gl[:1], news=ln[:1]))
    cmd(H, 'econrand -1')
    for port in (H, C):
        cmd(port, f'nfield {K} GovernmentType {gov0[port]}')
        cmd(port, f'nfield {K} BudgetModifier {bm0[port]}')
        cmd(port, f'nfield {K} UnrestLevel {un0[port]}')
    check('M1-M3: the host\'s own VP and EnemyVP unchanged (the host at peace)',
          nint(H, 0, 'VP') == h0 and value(cmd(H, 'ffield EnemyVP')) == e0,
          dict(vp=(h0, nint(H, 0, 'VP')), evp=(e0, value(cmd(H, 'ffield EnemyVP')))))
    cmd(H, f'warfxblk {K} -1')
    for port in (H, C):
        cmd(port, f'setally {K} {X} 0')
        cmd(port, f'settension {X} {J} 30')
    # M4 (0.6.0, the enemy-revolution rule): the host's nation at war with nation 1 too (`diplo war 1` + applydiplo);
    # `revotest 0 J:25 0:25` on the client (its next run's draws 0, J's and the host's nation's unrest 25 in nation 1's
    # copy) and nation 1's own unrest 25 on both copies (a candidate of the host's own rule). Nation 1's PC: J's revolution
    # ends the war 1-J by the general peace (DoPeace: no other computer enemy), the war 0-1 stays out (logged: "it would be
    # a candidate"); the host: its own rule keeps nation 1 out (logged), the war 0-1 goes on on both copies. A battle of
    # the host against nation 1 in the month is handled by the live months' own tools (ls_month, drop12).
    ls_quiet(ctx)
    r01 = ls_war01(ctx)
    for port in (H, C):
        cmd(port, f'nfield {K} UnrestLevel 25')
    rt = cmd(C, f'revotest 0 {J}:25 0:25')
    kw = [(kwar_counters(H) or {}).get(K)]
    check(f'M4 setup: the war 0-1 on the host (the client gets it with the month), the war {K}-{J} on both copies, nation '
          f'{K}\'s unrest 25 on both, the client\'s `revotest`',
          r01.get('war') == '1' and rel(K, J).get('war') == '1' and 'war=1' in (cmd(C, f'rel {K} {J}') or '') and
          nint(H, K, 'UnrestLevel') == 25 and nint(C, K, 'UnrestLevel') == 25 and (rt or '').startswith('ok revotest=0'),
          dict(r01=r01, kj=rel(K, J), client=(cmd(C, 'rel 0 1'), cmd(C, f'rel {K} {J}'), nint(C, K, 'UnrestLevel')),
               revotest=rt))
    rec = ls_month(ctx, 'war_effects M4', modes=('drop12',))
    rl = [x.split('] ', 1)[-1] for x in wait_log(H, rec['hmark'], r'relations of .*\(nation 1;', 30) or []]
    ht, ct = log_since(H, rec['hmark']), log_since(C, rec['cmark'])
    rv = [x.split('] ', 1)[-1] for x in log_lines(ct, r'relations v2: revolution: ')]
    rn = [x for x in rv if 'revolution: nation 1 ' in x]
    hr = [x.split('] ', 1)[-1] for x in log_lines(ht, r'relations v2: revolution \(host\)')]
    kw.append((kwar_counters(H) or {}).get(K))
    log(f'  M4: battles {[(b["bid"], b["mode"], b.get("error")) for b in rec["live"]]}; nation {K}\'s war counter '
        f'{kw[0]} -> {kw[1]}, unrest on the host {nint(H, K, "UnrestLevel")}; host: {hr[:1]} {rl[:1]}')
    check(f'M4: nation {K}\'s PC ran the enemy-revolution rule: J {J}\'s revolution ended the war {K}-{J} by the general '
          f'peace (DoPeace); the host applied it (peace {K}-{J})', bool(rn) and f'wars ended {J} (the general peace' in rn[0]
          and any(f'peace {K}-{J}' in x for x in rl), dict(client=rn[:1], host=rl[:1]))
    check(f'M4: the war 0-{K} stayed out of the rule on nation {K}\'s PC (logged: the host\'s nation "would be a '
          f'candidate") and on the host (nation {K} with unrest 25 kept out of the host\'s own rule, logged)',
          any('stay out' in x and '0 (unrest 25: it would be a candidate)' in x for x in rv) and
          any(re.search(rf' {K} \(unrest \d+: it would be a candidate\)', x) for x in hr), dict(client=rv[:2], host=hr[:1]))
    check(f'M4: the war 0-{K} goes on (host and client); the war {K}-{J} is over on both copies',
          rel(0, K).get('war') == '1' and 'war=1' in (cmd(C, f'rel 0 {K}') or '') and rel(K, J).get('war') == '0' and
          'war=0' in (cmd(C, f'rel {K} {J}') or ''), dict(r0k=rel(0, K), kj=rel(K, J)))
    for port in (H, C):
        cmd(port, f'nfield {K} UnrestLevel {un0[port]}')
    r01 = ls_peace01(ctx)
    check('M4 end: peace 0-1 (the players\' own peace: a compromise)', r01.get('war') == '0', r01)
    peace_war(K, J, 5)


def econ_kv(port=H, n=1):
    """`econ n` -> dict of its key=value fields ({} if unavailable)."""
    v = value(cmd(port, f'econ {n}') or '') or ''
    return dict(x.split('=', 1) for x in v.split() if '=' in x)


def econtreaty(port=H, arg=''):
    """`econtreaty [arg]` (TEST, economy.cpp) -> dict(armed, months, limit, calibre) as ints ({} if unavailable)."""
    v = value(cmd(port, f'econtreaty {arg}'.strip()) or '') or ''
    return {k: int(x) for k, x in (y.split('=', 1) for y in v.split() if '=' in y) if x.lstrip('-').isdigit()}


def scenario_player_copy(ctx):
    """0.2.7: a joined player's "Copy game" makes the copy the player's own campaign (nation K plays as nation 0, the
    host's nation becomes AI nation K). In the session: the client's copy (bridge `copygame` = the game's
    CopyGameToOtherSlot through the hook) checked key by key against the specification computed from slot 77; slot 77
    and the host's slot untouched; the host's own copy untouched; a copy cancelled at the overwrite prompt; the real
    "Copy game" button; one processed month (the session goes on). Out of the session: the client leaves, loads slot
    77 (it plays the host's nation there) and copies it (nation from rtw3mp_player.ini); then it loads its first copy
    and plays one month of it in single player."""
    hp, cp, K = ctx.hp, ctx.cp, 1
    st0, nat0 = ctl.status(C), nation_table(C)
    me, host = nat0[K]['name'], nat0[0]['name']
    src = slot_snapshot(CLIENT_SLOT)
    g1 = save_files(HOST_SLOT)
    eut = client_cooldowns()
    b77 = src['bcs']
    wars = [j for j in range(9) if j != K and int(b77.get(f'Nation{K}', {}).get('Tension', '0') if j == 0 else
                                                   b77.get(f'Nation{j}', {}).get(f'AITension{K}', '0') or 0) > 40]
    log(f'  start: client {st0.get("date")} slot {st0.get("slot")} playerIdx {st0.get("playerIdx")}; nation {K} '
        f'({me}) at war with {wars or "nobody"} in slot 77 (host: rel 0 1 {rel(0, 1)}, rel 1 2 {rel(1, 2)}); '
        f'client cooldowns {"from " + str(sum(1 for x in eut if x)) + " non-zero" if eut else "none"}; '
        f'slot 77 files {sorted(src["files"])}')

    # a) the client's copy in the session
    cm = log_mark(C)
    r = cmd(C, 'copygame 78')
    seen = copy_dialogs(cp, True, transform_done(C, cm, 78))
    conf, mp, game = sort_dialogs(seen)
    box = mp[0]['text'] if mp else ''
    want_box = [f'Slot 78 is your own copy of the campaign: you play {me}.',
                f'{host}, the host\'s nation, is run by the computer in this copy.']
    check(f'a) client `copygame 78`: the game\'s "Saved game copied" box (OK), then the mod\'s "Multiplayer" box naming '
          f'{me} and {host} (OK); no overwrite prompt, nothing left open',
          r == 'ok' and not conf and len(game) == 1 and game[0]['pressed'] == 'OK' and len(mp) == 1
          and mp[0]['pressed'] == 'OK' and all(w in box for w in want_box) and not visible_boxes(cp),
          f'{r}; {seen}; open: {describe_windows(cp)}')
    res = verify_copy(src, 78, K, eut, kwar=own_kwar(C))
    fx, dd, act = res['facts'], res['diffs'], res['act']['bcs'] or {}
    lines = copy_lines(C, cm, 78)
    m = re.search(PLAYER_COPY_RE, lines[0]) if lines else None
    want = ('78', me, host, str(K), str(fx['pairs']), str(fx['commanders']), str(fx['map_fields']), str(fx['div_kept']),
            str(fx['div_dropped']), 'at war' if fx['at_war'] else 'at peace')
    check(f'a) client log "player copy in slot 78: {me} is the player nation, {host} is nation {K} (AI); ..." with the '
          f'counts of the specification', len(lines) == 1 and m and m.groups() == want, f'{lines} (want {want})')
    check('a) Game78 files: RTWGame78.bcs/.sta/.off, MapData78.dat, DesignFiles0-8; .sta = the source\'s; no '
          'Autosave.sac/.off, BattleInfo.bbi or DesignFiles_swap.tmp', not res['files'],
          f'{res["files"]}; copy {fx["copy_files"]}; battle files in slot 77: {fx["battle_files_in_source"]}')
    log(f'  Game78: files {fx["copy_files"]}; slot 77 battle files {fx["battle_files_in_source"]}')
    s0, sk = src['bcs'], act
    names = (act.get('Nation0', {}).get('Name'), act.get(f'Nation{K}', {}).get('Name'))
    check(f'a) [Nation0] Name = {me}, [Nation{K}] Name = {host}; all {fx["pairs"]} [Nation0*]/[Nation{K}*] sections '
          f'traded (ship ids, coastal artillery, submarines, losses; other keys as the specification)',
          names == (me, host) and fx['pairs'] >= 4 and not dd.get('sections')
          and ship_ids(sk.get('Nation0Ships')) == ship_ids(s0.get(f'Nation{K}Ships'))
          and ship_ids(sk.get(f'Nation{K}Ships')) == ship_ids(s0.get('Nation0Ships')),
          f'names {names}; ships {len(ship_ids(sk.get("Nation0Ships")))}/{len(ship_ids(sk.get(f"Nation{K}Ships")))}; '
          f'{fmt_diffs(dd.get("sections", []))}')
    n1, n2 = sk.get(f'Nation{K}', {}), sk.get('Nation2', {})
    ex = (f'new Nation{K} ({host}) Tension {n1.get("Tension")} (old Nation{K} Tension {s0[f"Nation{K}"].get("Tension")}), '
          f'Nation2 Tension {n2.get("Tension")} (old Nation{K} AITension2 {s0[f"Nation{K}"].get("AITension2")}, old '
          f'Nation2 AITension{K} {s0["Nation2"].get(f"AITension{K}")}), Nation2 AITension{K} {n2.get(f"AITension{K}")} '
          f'(old Nation2 Tension {s0["Nation2"].get("Tension")})')
    check('a) relations exactly as specified (Tension/Allied/TechSharing/AITension*/AIAlliance* of Nation0-8, from '
          f'slot 77): {ex}', not dd.get('relations'), fmt_diffs(dd.get('relations', [])))
    log('  relations:', ex)
    check(f'a) nation numbers 0 <-> {K} (Ship*BuildingNationIdx, AU/AT*Nation, BattleAllied/EnemyAlliedNationIdx: '
          f'{fx["swaps"]} changed) and the host\'s ships without commanders ({fx["commanders"]} cleared)',
          not dd.get('numbers'), fmt_diffs(dd.get('numbers', [])))
    g0, g = s0['General'], act.get('General', {})
    check(f'a) [General]: War {g0.get("War")} -> {fx["war"][1]} ({me} at war with {fx["at_war"] or "nobody"}), EnemyVP '
          f'{fx["enemy_vp"]}, ScenarioInProgress -1, invasion targets XXX, ArmyOffensive/RevolutionPending 0, '
          f'LastMissionIdx 20; nothing else changed',
          not dd.get('general'), f'{fmt_diffs(dd.get("general", []))}; got War {g.get("War")} EnemyVP {g.get("EnemyVP")}')
    eut_src = [s0.get('EUT', {}).get(f'EUT{j}') for j in range(100)]
    check('a) [EUT] = the client\'s own event cooldowns' + (' (events_<hash>.ini)' if eut else
                                                             ' (no cooldown file: the source\'s values kept)'),
          not dd.get('eut'), fmt_diffs(dd.get('eut', [])))
    log(f'  EUT: client {[(j, x) for j, x in enumerate(eut or []) if x]} | source (host) '
        f'{[(j, x) for j, x in enumerate(eut_src) if x not in ("0", None)]}')
    check(f'a) MapData78: MineLevel 0/{K} and TakenFrom 0 <-> {K} ({fx["map_fields"]} fields changed), nothing else',
          not dd['map'], fmt_diffs(dd['map']))
    check(f'a) RTWGame78.off: officers kept, divisions {fx["div_kept"]} kept / {fx["div_dropped"]} dropped as specified',
          not dd['off'], fmt_diffs(dd['off']))
    check(f'a) design files swapped: DesignFiles0 = slot 77\'s DesignFiles{K}, DesignFiles{K} = its DesignFiles0, '
          f'the others identical', not [p for p in res['files'] if 'DesignFiles' in p], res['files'])
    check('a) nothing else in RTWGame78.bcs differs from slot 77', not dd.get('other'), fmt_diffs(dd.get('other', [])))

    # b) slot 77 and the host's slot untouched, the client still in the session
    st, nat = ctl.status(C), nation_table(C)
    check('b) slot 77 and the host\'s slot 1 byte-identical before and after the copy',
          save_files(CLIENT_SLOT) == src['files'] and save_files(HOST_SLOT) == g1,
          f'77 same {save_files(CLIENT_SLOT) == src["files"]}, 1 same {save_files(HOST_SLOT) == g1}')
    check('b) the client is still in the session: role client, planning, slot 77, playerIdx 1, same date and nations',
          (st.get('role'), st.get('phase'), st.get('slot'), st.get('playerIdx'), st.get('date')) ==
          ('client', 'planning', str(CLIENT_SLOT), str(K), st0.get('date')) and nat == nat0, f'{st} {nat == nat0}')

    # c) the host copies its own slot: untouched
    hm = log_mark(H)
    g1 = save_files(HOST_SLOT)
    r = cmd(H, 'copygame 79')
    seen = copy_dialogs(hp, True, lambda s: os.path.exists(save_path(79)) and any(d['pressed'] for d in s), who='host')
    conf, mp, game = sort_dialogs(seen)
    g79 = save_files(79)
    ren = {n.replace(f'RTWGame{HOST_SLOT}.', 'RTWGame79.').replace(f'MapData{HOST_SLOT}.', 'MapData79.'): h
           for n, h in g1.items()}
    diff79 = [n for n, h in g79.items() if ren.get(n) != h]
    n79 = (read_save(save_path(79)) or {}).get('Nation0', {}).get('Name')
    hl = log_lines(log_since(H, hm), r'player copy in slot|copy of slot')
    sth = ctl.status(H)
    check(f'c) host `copygame 79` from its own slot: the game\'s box only, Game79 = slot 1 file by file ([Nation0] '
          f'{n79}), no "player copy"/"copy of slot" line, the host still hosts slot 1 as nation 0',
          r == 'ok' and not conf and not mp and len(game) == 1 and 'RTWGame79.bcs' in g79 and not diff79
          and n79 == host and not hl and (sth.get('role'), sth.get('slot'), sth.get('playerIdx')) ==
          ('host', str(HOST_SLOT), '0'), f'{r}; {seen}; differ {diff79}; {n79}; {hl}; {sth}')

    # d) a copy cancelled at the game's overwrite prompt
    cm, g78 = log_mark(C), save_files(78)
    r = cmd(C, 'copygame 78')
    seen = copy_dialogs(cp, False, lambda s: bool(copy_lines(C, cm, 78)))
    conf, mp, game = sort_dialogs(seen)
    lines = copy_lines(C, cm, 78)
    check('d) client `copygame 78` onto the existing copy: the game\'s overwrite prompt answered No -> no other box, '
          'log "copy of slot 77 to 78: not copied", Game78 and slot 77 unchanged',
          r == 'ok' and len(conf) == 1 and conf[0]['pressed'] in ('No', 'Cancel') and not mp and not game
          and lines == ['copy of slot 77 to 78: not copied'] and save_files(78) == g78
          and save_files(CLIENT_SLOT) == src['files'], f'{r}; {seen}; {lines}; 78 same {save_files(78) == g78}')

    # g) the real "Copy game" button (its dialog takes slots 1-9: the highest slot that was free before the run)
    bs = _button_slot[0]
    if bs is None or os.path.exists(slot_dir(bs)):
        log(f'  SKIP g) the real "Copy game" button: no free slot in 3-9 (chosen {bs})')
        how, det = 'skip', ''
    else:
        cm = log_mark(C)
        how, det = copy_with_button(ctx, bs)
        log(f'  g) Copy game button: {how}: {det}')
    if how == 'ok':
        seen = copy_dialogs(cp, False, transform_done(C, cm, bs))
        conf, mp, game = sort_dialogs(seen)
        resb = verify_copy(src, bs, K, eut, kwar=own_kwar(C))
        lines = copy_lines(C, cm, bs)
        fb, f78 = resb['act']['files'], res['act']['files']
        same = (fb.get(f'RTWGame{bs}.bcs'), fb.get(f'MapData{bs}.dat')) == (f78.get('RTWGame78.bcs'), f78.get('MapData78.dat'))
        bad = [d for v in resb['diffs'].values() for d in v]
        check(f'g) the real "Copy game" button (BM_CLICK) -> TdlgInputNumber (seNumber {bs}, OK) -> the game\'s box and '
              f'the mod\'s box; "player copy in slot {bs}" line; Game{bs} as specified, its .bcs/MapData = Game78\'s',
              not conf and len(game) == 1 and len(mp) == 1
              and all(w.replace('Slot 78', f'Slot {bs}') in mp[0]['text'] for w in want_box) and len(lines) == 1
              and lines[0].startswith(f'player copy in slot {bs}: {me} is the player nation') and not bad
              and not resb['files'] and same, f'{det}; {seen}; {lines}; {fmt_diffs(bad)} {resb["files"]}; same as 78 {same}')
    elif det:
        log(f'  SKIP g) the real "Copy game" button: {det}')

    # the session goes on
    d0 = ctl.status(C).get('date')
    d1 = run_month(ctx, 'player_copy')
    st = ctl.status(C)
    merged = log_lines(log_since(H, ctx.month_marks[0]), rf'merge nation {K}\b')
    check('the session goes on after the copies: the month was processed (host "merge nation 1"), the client plans the '
          'new month in slot 77 as nation 1', d1 and d1 != d0 and merged and (st.get('role'), st.get('phase'),
          st.get('slot'), st.get('playerIdx')) == ('client', 'planning', str(CLIENT_SLOT), str(K)),
          f'{d0} -> {d1}; {merged[:1]}; {st}')

    # e) out of the session: the client leaves, opens slot 77 (the host's nation) and copies it
    cm = log_mark(C)
    rl = cmd(C, 'leave')
    time.sleep(1.5)
    role = ctl.status(C).get('role')
    try:
        with open(os.path.join(slot_dir(CLIENT_SLOT), 'rtw3mp_player.ini'), encoding='utf-8', errors='replace') as f:
            ini = f.read().strip()
    except OSError:
        ini = None
    r = cmd(C, f'load {CLIENT_SLOT} 0')
    st, nat = ctl.status(C), nation_table(C)
    boxes = [box_info(h)[0] for h in visible_boxes(cp)]
    check(f'e) client `leave` (role {role}), slot 77\'s rtw3mp_player.ini {ini!r}, `load 77 0`: slot 77 as nation 0 = '
          f'{host} (the host\'s nation, what the 0.2.6 copy played), no dialog',
          rl == 'ok' and role == 'none' and ini and re.search(rf'nation={K}\b', ini) and r == 'ok'
          and (st.get('slot'), st.get('playerIdx'), st.get('startBuild')) == (str(CLIENT_SLOT), '0', '2')
          and nat.get(0, {}).get('name') == host and not boxes, f'{r}; {st}; {nat.get(0)}; {boxes}')
    src80 = slot_snapshot(CLIENT_SLOT)
    cm = log_mark(C)
    r = cmd(C, 'copygame 80')
    seen = copy_dialogs(cp, False, transform_done(C, cm, 80))
    conf, mp, game = sort_dialogs(seen)
    lines = copy_lines(C, cm, 80)
    res80 = verify_copy(src80, 80, K, None)
    fx80 = res80['facts']
    m = re.search(PLAYER_COPY_RE, lines[0]) if lines else None
    want = ('80', me, host, str(K), str(fx80['pairs']), str(fx80['commanders']), str(fx80['map_fields']),
            str(fx80['div_kept']), str(fx80['div_dropped']), 'at war' if fx80['at_war'] else 'at peace')
    check('e) out of the session `copygame 80`: the game\'s box and the mod\'s box (naming both nations), the log line '
          f'"player copy in slot 80: {me} is the player nation, {host} is nation {K} (AI); ..." (nation from '
          'rtw3mp_player.ini)', r == 'ok' and not conf and len(game) == 1 and len(mp) == 1
          and all(w.replace('78', '80') in mp[0]['text'] for w in want_box) and m and m.groups() == want,
          f'{r}; {seen}; {lines} (want {want})')
    bad = [d for v in res80['diffs'].values() for d in v]
    a80 = res80['act']['bcs'] or {}
    check(f'e) Game80 as specified from slot 77\'s new month (relations, sections, numbers, [General], [EUT] kept '
          f'outside the session, MapData {fx80["map_fields"]} fields, divisions {fx80["div_kept"]}/{fx80["div_dropped"]}, '
          f'designs, files): [Nation0] {a80.get("Nation0", {}).get("Name")}, [Nation{K}] '
          f'{a80.get(f"Nation{K}", {}).get("Name")}', not bad and not res80['files']
          and (a80.get('Nation0', {}).get('Name'), a80.get(f'Nation{K}', {}).get('Name')) == (me, host),
          f'{fmt_diffs(bad)} {res80["files"]}')
    log(f'  Game80 facts: at war {fx80["at_war"]}, War {fx80["war"]}, EnemyVP {fx80["enemy_vp"]}, '
        f'{fx80["swaps"]} numbers, {fx80["commanders"]} commanders, {fx80["map_fields"]} map fields')

    # f) the key check: the copy is playable
    cm = log_mark(C)
    f78 = read_save(save_path(78))
    r = cmd(C, 'load 78 0')
    time.sleep(1.5)
    st, nat = ctl.status(C), nation_table(C)
    boxes = [box_info(h)[0] for h in visible_boxes(cp)]
    check('f) client `load 78 0`: slot 78, playerIdx 0, campaign loaded (startBuild 2), no dialog',
          r == 'ok' and (st.get('slot'), st.get('playerIdx'), st.get('startBuild')) == ('78', '0', '2') and not boxes,
          f'{r}; {st}; {boxes}')
    # the others as slot 77 (the copy's source) has them: the client's memory may hold later changes of the session
    # (relations_war's peace by `peacetest` on the client after slot 77's save: the game scraps the loser's ships, funds)
    f77 = {j: int(float(b77.get(f'Nation{j}', {}).get('Funds', nat0[j]['funds']))) for j in nat0 if j not in (0, K)}
    later = {j: (f77[j], nat0[j]['funds']) for j in f77 if f77[j] != nat0[j]['funds']}
    if later:
        log(f'  NOTE f): funds (slot 77, the client\'s memory) of nations changed after slot 77\'s save: {later}')
    want_nat = {0: nat0[K], K: nat0[0], **{j: dict(nat0[j], funds=f77[j]) for j in f77}}
    check(f'f) `nations`: nation 0 = {me} with its session funds/ships {nat0[K]["funds"]}/{nat0[K]["ships"]}, nation '
          f'{K} = {host} with {nat0[0]["funds"]}/{nat0[0]["ships"]}, the others as in slot 77', nat == want_nat,
          f'{nat} (want {want_nat})')
    rels = {j: dict(kv.split('=') for kv in (cmd(C, f'rel 0 {j}')[3:]).split()) for j in range(1, 9)}
    ai = {j: dict(kv.split('=') for kv in (cmd(C, f'rel {K} {j}')[3:]).split()) for j in range(2, 9)}
    ft = {j: f78[f'Nation{j}'].get('Tension') for j in range(1, 9)}
    fa = {j: f78[f'Nation{K}'].get(f'AITension{j}') for j in range(2, 9)}
    nwar = sum(1 for j in ft if int(ft[j]) > 40)
    check(f'f) relations in memory (the relation bars): `rel 0 j` = the copy\'s [Nation j] Tension, `rel {K} j` = '
          f'[Nation{K}] AITension j, warCounter = [General] War {f78["General"].get("War")}, hostWars {nwar}',
          all(rels[j].get('tension') == ft[j] and rels[j].get('war') == ('1' if int(ft[j]) > 40 else '0') for j in ft)
          and all(ai[j].get('tension') == fa[j] for j in fa) and rels[1].get('warCounter') == f78['General'].get('War')
          and rels[1].get('hostWars') == str(nwar),
          f'rel 0 j {[(j, rels[j].get("tension"), ft[j]) for j in ft]}; rel {K} j {[(j, ai[j].get("tension"), fa[j]) for j in fa]}; '
          f'{rels[1]}')
    p_host = poss_list(C, f'possessions {K}')
    if fx['at_war']:
        # a war the session left (battle_surprise's 1-J ends with the next month's relation turn) would let the copy's
        # month generate a battle (dist_rc060_2 --stress: its preview stopped the month and the run): peace in the copy
        ends = {j: cmd(C, f'settension 0 {j} 5') for j in fx['at_war']}
        log(f'  NOTE f) {me} is at war with {fx["at_war"]} in the copy: peace there before its month (`settension 0 j '
            f'5`, a throwaway copy; a battle would stop the month): {ends}')
    sp = single_player_month(ctx, 78)
    ctx.months.append(('player_copy (slot 78 alone)', '/'.join(sp['d0'] or ()), '/'.join(sp['d1'] or ()), sp['dt']))
    log(f'  single-player month on slot 78: {sp["d0"]} -> {sp["d1"]} in {sp["dt"]:.0f} s; {len(sp["answered"])} '
        f'dialogs answered: {[a[2] for a in sp["answered"]][:12]}' + (f'; {sp["why"]}' if sp['why'] else ''))
    check('f) one month of the copy in single player (`turn`, the game\'s dialogs answered up to its turn report, no '
          'battle), then `save` writes slot 78 with the next month\'s date', sp['ok'] and sp['d0']
          and sp['d1'] == next_month(sp['d0']), f'{sp["why"]}; {sp["d0"]} -> {sp["d1"]}')
    st, nat2 = ctl.status(C), nation_table(C)
    p_host2 = poss_list(C, f'possessions {K}')
    cl = log_since(C, cm)
    bad = log_lines(cl, r'(?i)exception|AI suppressed|merge nation|player copy')
    check(f'f) after the month: responsive (slot 78, playerIdx 0, not busy), nation 0 {me}, {host} (AI) still has ships '
          f'({nat.get(K, {}).get("ships")} -> {nat2.get(K, {}).get("ships")}) and possessions ({len(p_host or [])} -> '
          f'{len(p_host2 or [])}); no exception or session line in the client log',
          (st.get('slot'), st.get('playerIdx'), st.get('busy')) == ('78', '0', '0')
          and nat2.get(0, {}).get('name') == me and nat2.get(K, {}).get('name') == host
          and nat2.get(K, {}).get('ships', 0) > 0 and p_host2 and bad == [], f'{st}; {nat2}; {bad[:3]}')
    log(f'  after the month: {nat2}; {host} possessions {pnames(p_host)} -> {pnames(p_host2)}')


# ---------------------------------------------------------------- joined players' battles against AI nations

BATTLE_SLOT = CLIENT_SLOT + 10  # the client's battle slot (the mod's default: client slot + 10); deleted after the run
BATTLE_OK_RE = r"Joined players' battles: ok \(frmMain=\S+ checkAttack=\S+\)"
APPLIED_RE = (r'battle (\d+) applied: (\d+) ships changed \((\d+) fields\), (\d+) removed, VP (-?\d+)/(-?\d+), '
              r'prestige (-?\d+)(.*)$')
BATTLE_STATES = 'queued|fighting|fought|to the game|resolved by the game'
DEFAULT_BATTLE_TIMEOUT = 1800  # s: the host's default time limit for a battle (RTW3MP_BATTLE_TIMEOUT not set)
HOLD_LIMIT = 20  # s: `battles timeout` of the time-limit check
FIGHT_TIMEOUT = 900  # s a battle month may take longer than a normal one (a fought battle on auto-run)
SHIP_INTEL = ('PlayerIntel', 'EnemyClassName', 'EnemySpeed', 'EnemyBelt')  # the player's view of a ship, not merged
AUTORUN_AT = (1218 + 14, 5 + 14)  # sbAutoRunBattle (a 28x28 TSpeedButton) on TfrmMain.Panel1, form resource TFRMMAIN
BATTLE_UP = ('TdlgMapMessage', 'TdlgBattlePreview', 'TfrmMain', 'TdlgResults')
UNPLANNED = dict(answers=[])  # battle dialogs of months without a BattleDriver (declined; reported by `battles`)
_pressed = {}  # dialog window -> time the battle driver last pressed one of its buttons (a posted click takes a moment)


def battle_up(pid):
    """A battle dialog or the battle screen of a copy is up."""
    return any(e2e_test.class_name(h) in BATTLE_UP for h in top_windows(pid))


def dlg_buttons(top):
    """{caption (lower case, no '&'): hwnd} of the visible, enabled buttons of a dialog."""
    out = {}
    for h in children(top):
        if u.IsWindowVisible(h) and u.IsWindowEnabled(h) and e2e_test.class_name(h) in ('TButton', 'TBitBtn'):
            out.setdefault(caption(h).lower(), h)
    return out


def is_input_query(top):
    """Delphi's InputQuery form (the battle screen's "Add to history record"): an edit box with OK and Cancel."""
    k = e2e_test.class_name(top)
    if k in BATTLE_UP or k in ('TfrmBuildCamp', 'TMessageForm', 'TdlgEventAnswer', 'TdlgPictureMessage') \
            or k.startswith('RTW3MP_'):
        return False
    return any(e2e_test.class_name(h) == 'TEdit' for h in children(top)) and 'cancel' in dlg_buttons(top)


def select_radio(dlg, want):
    """Select the radio button captioned `want` of a TdlgEventAnswer (BM_CLICK, else the parent's BN_CLICKED)."""
    for h in children(dlg):
        if e2e_test.class_name(h) == 'TRadioButton' and caption(h) == want:
            if not u.SendMessageW(h, 0x00F0, 0, 0):  # BM_GETCHECK
                u.SendMessageW(h, 0x00F5, 0, 0)  # BM_CLICK
                if not u.SendMessageW(h, 0x00F0, 0, 0):
                    u.PostMessageW(u.GetParent(h), 0x0111, u.GetDlgCtrlID(h) & 0xFFFF, h)
                    time.sleep(0.3)
            return bool(u.SendMessageW(h, 0x00F0, 0, 0))
    return False


def battle_panel(frm):
    """TfrmMain's tool bar (Panel1: alTop, 39 px high); its speed buttons are graphic controls without a window."""
    best = None
    for h in children(frm):
        if e2e_test.class_name(h) != 'TPanel' or u.GetParent(h) != frm or not u.IsWindowVisible(h):
            continue
        r = _RECT()
        u.GetWindowRect(h, ctypes.byref(r))
        if r.bottom - r.top < 60 and r.right - r.left > 600 and (best is None or r.top < best[0]):
            best = (r.top, h)
    return best[1] if best else None


def click_autorun(frm):
    """The battle screen's "Auto run" speed button: a posted left click on Panel1 at the button's place (VCL hands
    the mouse messages of a panel to the graphic control under the point). Never the real mouse."""
    p = battle_panel(frm)
    if not p:
        return False
    lp = (AUTORUN_AT[1] << 16) | AUTORUN_AT[0]
    u.PostMessageW(p, 0x0200, 0, lp)  # WM_MOUSEMOVE
    u.PostMessageW(p, 0x0201, 1, lp)  # WM_LBUTTONDOWN (MK_LBUTTON)
    u.PostMessageW(p, 0x0202, 0, lp)  # WM_LBUTTONUP
    return True


def _press(rec, top, h, what):
    if h is None or time.time() - _pressed.get(top, 0) < 1.5:
        return False
    bt = dialog_text(top)  # before the click closes it
    if bt and (GAME_ERROR_RE.search(bt) or 'Missing ship' in bt):
        # the game's error boxes of a joined player's battle count like the other answerers' (game_error_boxes; 0.6.1
        # RC1's mixed run: a 0.6.0 player's "Error in CreateDivisionForBCBattle procedure! Access violation" boxes)
        BOX_SEEN.append((time.time(), rec.get('who', 'client'), e2e_test.class_name(top), bt))
    u.PostMessageW(h, 0x00F5, 0, 0)  # BM_CLICK
    _pressed[top] = time.time()
    entry = f'{e2e_test.class_name(top)}:"{e2e_test.window_text(top)[:40]}"->{what}'
    rec['answers'].append(entry)
    log('  client battle dialog:', entry + (f' (text: {bt!r})' if bt else ''))
    return True


def battle_dialogs(pid, action, rec):
    """One pass over a copy's battle dialogs, answered for `action`: 'fight' (map message and preview Accept, the
    battle screen's auto-run with its prompt "Yes", the results' "Exit battle", the history prompt Cancel), 'decline'
    (the preview's Decline) or 'hold' (the preview stays open until rec['release'] is set, then Decline). Other boxes:
    Yes before OK (Yes/No boxes in a battle ask to end the scenario), picture messages OK. `rec` collects what was
    seen. Never dismiss_dialogs while a battle is up: it would press the preview's first button."""
    for k in ('answers',):
        rec.setdefault(k, [])
    action = rec.get('force') or action  # a preview without an enabled Decline (the player's nation defends): fought
    tops = top_windows(pid)
    modal = any(e2e_test.class_name(w) == 'TMessageForm' or e2e_test.class_name(w).startswith('Tdlg') for w in tops)
    for top in tops:
        k = e2e_test.class_name(top)
        if k == 'TfrmMain':
            rec['frm'] = rec.get('frm') or time.time()
            if action == 'fight' and not rec.get('autorun') and rec.get('autorun_clicks', 0) < 3 \
                    and time.time() - rec.get('autorun_t', 0) > 8 and not modal:
                if click_autorun(top):
                    rec['autorun_clicks'] = rec.get('autorun_clicks', 0) + 1
                    rec['autorun_t'] = time.time()
                    log('  client battle screen: auto-run button clicked (posted)')
            continue
        query = is_input_query(top)
        if not (k == 'TMessageForm' or k.startswith('Tdlg') or query):
            continue
        b = dlg_buttons(top)
        first = next(iter(b.values()), None)
        if query:
            rec['inputquery'] = rec.get('inputquery') or e2e_test.window_text(top) or '?'
            _press(rec, top, b.get('cancel'), 'Cancel')
        elif k == 'TdlgMapMessage':
            rec['map'] = rec.get('map') or time.time()
            if 'fight battle' in b or 'auto resolve' in b:  # 0.7.0: a raider battle's dialog (RaiderBattleDialog)
                rec['raider_dialog'] = rec.get('raider_dialog') or dialog_text(top) or '?'
                if action in ('quick', 'decline') and 'auto resolve' in b:
                    _press(rec, top, b['auto resolve'], 'Auto resolve')
                else:
                    _press(rec, top, b.get('fight battle') or first, 'Fight Battle')
            else:  # (1.01.44's MapMessageDialog hides its Decline: one button, "Generate battle")
                rec['map_buttons'] = rec.get('map_buttons') or sorted(b)
                _press(rec, top, b.get('accept') or first, 'Accept')
        elif k == 'TdlgBattlePreview':
            rec['preview_t'] = rec.get('preview_t') or time.time()
            rec['preview_buttons'] = sorted(b)
            if action == 'fight':
                _press(rec, top, b.get('accept'), 'Accept')
            elif action == 'decline' or (action == 'hold' and rec.get('release')):
                if 'decline' in b:
                    _press(rec, top, b['decline'], 'Decline')
                elif _press(rec, top, b.get('accept'), 'Accept (Decline disabled)'):
                    rec['no_decline'] = True  # the game allows no decline here (the player's nation defends)
                    rec['force'] = 'fight'
                    rec['autorun'], rec['autorun_clicks'] = False, 0
        elif k == 'TdlgEventAnswer':
            radios = [caption(h) for h in children(top) if e2e_test.class_name(h) == 'TRadioButton'
                      and u.IsWindowVisible(h)]
            if 'Yes' in radios and 'No' in radios:  # "auto run the battle with both sides on AI ...?"
                rec['autorun_prompt'] = radios
                if select_radio(top, 'Yes') and _press(rec, top, b.get('ok'), 'OK [Yes]'):
                    rec['autorun'] = True
            else:
                select_first_answer(pid)
                _press(rec, top, b.get('ok') or first, 'OK')
        elif k == 'TdlgResults':
            rec['results'] = rec.get('results') or time.time()
            if _press(rec, top, b.get('exit battle') or b.get('view map') or first, 'Exit battle') and rec is UNPLANNED:
                for key in ('force', 'autorun', 'autorun_clicks', 'autorun_t', 'frm', 'results', 'preview_t'):
                    rec.pop(key, None)  # the next battle without a plan starts as 'decline' again
        elif k == 'TdlgPictureMessage':
            _press(rec, top, b.get('ok') or b.get('yes') or first, 'OK')
        elif k == 'TMessageForm':
            pick = 'yes' if 'yes' in b else 'ok' if 'ok' in b else None
            _press(rec, top, b.get(pick) if pick else first, pick or 'first')
        else:
            pick = next((p for p in ('ok', 'close', 'continue', 'yes', 'accept') if p in b), None)
            _press(rec, top, b.get(pick) if pick else first, pick or 'first')


def battles_list():
    """Host `battles list` -> dict(phase, timeout, battles={id: dict(K, J, area, state, why)}, raw) or None."""
    r = cmd(H, 'battles list')
    m = re.match(r'^ok phase=(\d) timeout=(\d+) battles=(.*)$', r)
    if not m:
        return None
    out = dict(phase=int(m[1]), timeout=int(m[2]), battles={}, raw=r)
    for e in m[3].split('; '):
        e = e.strip().rstrip(';').strip()
        mm = re.match(rf'^(\d+):(\d+)-(\d+):(.*?):({BATTLE_STATES})(?::(.*))?$', e)
        if mm:
            out['battles'][int(mm[1])] = dict(K=int(mm[2]), J=int(mm[3]), area=mm[4], state=mm[5], why=mm[6] or '')
    return out


def cstate():
    """Client `battles state` -> dict(state, id, nation, opp, area, slot, slotMode, aftermath, fight, hostgen, raider,
    testraid, raw)."""
    r = cmd(C, 'battles state')
    m = re.match(r'^ok state=(\S+) id=(-?\d+) nation=(-?\d+) opp=(-?\d+) area=(.*) slot=(\d+) slotMode=(\d) '
                 r'aftermath=(\d) fight=(\d)(?: hostgen=(\d+))?(?: raider=(\d) testraid=(\S+))?$', r)
    if not m:
        return dict(raw=r)
    return dict(state=m[1], id=int(m[2]), nation=int(m[3]), opp=int(m[4]), area=m[5], slot=int(m[6]),
                slotMode=m[7] == '1', aftermath=m[8] == '1', fight=m[9] == '1',
                hostgen=int(m[10]) if m[10] else None, raider=int(m[11]) if m[11] else None, testraid=m[12], raw=r)


def ships_by_id(sec):
    """{ship id: {field: value}} of a [NationNShips] section of read_save."""
    tmp = {}
    for k, v in (sec or {}).items():
        m = re.match(r'^Ship(\d+)([A-Za-z].*)$', k)
        if m:
            tmp.setdefault(int(m[1]), {})[m[2]] = v
    return {f['Id']: f for f in tmp.values() if f.get('Id')}


def strategic_enabled(pid):
    w = [h for h in top_windows(pid) if e2e_test.class_name(h) == 'TfrmBuildCamp']
    return bool(u.IsWindowEnabled(w[0])) if w else None


def log_secs(line):
    """Seconds of the day of a mod log line ('HH:MM:SS.mmm [tid] ...')."""
    m = re.match(r'^(\d\d):(\d\d):(\d\d)\.(\d{3})', line)
    return int(m[1]) * 3600 + int(m[2]) * 60 + int(m[3]) + int(m[4]) / 1000 if m else None


def fighting_ships_by_area(n):
    """Nation n's ships that can fight a battle the game resolves (DoBattleBetweenAINations), by area, from the host's
    save of the latest month: in play, not under repair, status active, trade protection, raider or colonies (the
    game's CountShipsInArea(stAll, area, [ssActive, ssTradeProtection, ssRaider, ssColonies]))."""
    bcs = read_save(save_path(HOST_SLOT)) or {}
    out = {}
    for f in ships_by_id(bcs.get(f'Nation{n}Ships')).values():
        if f.get('Status') in ('0', '3', '4', '6') and f.get('RepairTime', '0') == '0' and f.get('InPlay') == '1':
            a = f.get('LocationAreaName')
            out[a] = out.get(a, 0) + 1
    return out


def battle_pairs(K, slot=HOST_SLOT, exclude=(STANDIN,)):
    """Candidates (J's ships there, K's ships there, J, area) for an injected battle, best first: an AI nation J with
    a possession in a sea area where nation K has at least 4 ships (the game's CheckAttackLocation: a possession
    battle needs a possession of the defender in the area and the attacker's strength there > 3; a home-area battle
    a home area of both). From the host's save of the latest month (slot) and `possessions`; not the nations in exclude."""
    bcs = read_save(save_path(slot)) or {}

    def locs(n):
        out = {}
        for f in ships_by_id(bcs.get(f'Nation{n}Ships')).values():
            a = f.get('LocationAreaName')
            out[a] = out.get(a, 0) + 1
        return out

    mine, cands = locs(K), []
    for j in range(1, 9):
        if j == K or j in exclude:
            continue
        theirs = locs(j)
        for area in sorted({p['area'] for p in poss_list(H, f'possessions {j}') or []}):
            if mine.get(area, 0) >= 4:
                cands.append((theirs.get(area, 0), mine[area], j, area))
    return sorted(cands, reverse=True)


def inject(K, J, area):
    """Host `battles inject K J area` -> (battle id or None, reply)."""
    r = cmd(H, f'battles inject {K} {J} {area}')
    m = re.match(r'^ok (\d+)$', r)
    return (int(m[1]) if m else None), r


class BattleDriver:
    """run_month's client side for a month whose battle phase sends battles to the client. plan: {battle id: 'fight' |
    'decline' | 'hold'}; a battle the month found by itself (not in the plan) is declined. The battle being fought is
    the latest `battle N sent to` line of the host (one battle per player at a time). Records per battle: the dialogs
    answered, the battle slot as the client shows it, timings; the host's save when the battle phase began (s0) with
    the host's view then (only from that moment on the host's bridge is polled: its month is over), and the battle
    slot's save right after each fought battle (g87)."""
    extra_timeout = FIGHT_TIMEOUT

    def __init__(self, ctx, plan, K, J, fight_any=False):
        self.ctx, self.plan, self.K, self.J, self.fight_any = ctx, dict(plan), K, J, fight_any
        self.hmark, self.cmark = log_mark(H), log_mark(C)
        self.rec, self.g87, self.s1 = {}, {}, {}
        self.g87_stale = {}  # battle id -> why the battle slot read after "fought" was the next battle's copy
        self.s0 = self.phase = self.label = None
        self.t0, self.t_phase, self.t_state = time.time(), None, 0

    def r(self, bid):
        """A battle's record. Planned 'fight' or 'hold' becomes 'decline' once a battle of the month was fought or held
        (several candidates are injected: the AI often avoids a battle); a battle not in the plan is fought if
        fight_any and none was fought yet, else declined."""
        if bid not in self.rec:
            planned = self.plan.get(bid)
            held = any(r['action'] == 'hold' and r.get('preview_t') for r in self.rec.values())
            if planned == 'fight' and self.fought() is not None or planned == 'hold' and held:
                action = 'decline'
            else:
                action = planned or ('fight' if self.fight_any and not self.fought() else 'decline')
            self.rec[bid] = dict(id=bid, action=action, planned=planned, answers=[], sent=time.time())
        return self.rec[bid]

    def fought(self):
        return next((b for b, r in self.rec.items() if r.get('outcome') == 'fought'), None)

    def current(self, h, c, last_sent):
        """The battle the client is busy with: the one the host had sent last when the client started its latest
        battle slot (`player copy in slot 87`), until its outcome line; before the first start, the last one sent.
        After a time limit the host sends the next battle while the client still shows the old one."""
        day0 = self.t0 - time.mktime(time.localtime(self.t0)[:3] + (0, 0, 0, 0, 0, -1))  # seconds of day at start

        def secs(line):
            t = log_secs(line)
            return t + 86400 if t is not None and t < day0 - 3600 else t  # past midnight

        starts = [secs(x) for x in log_lines(c, rf'player copy in slot {BATTLE_SLOT}:')]
        if not starts:
            return last_sent
        sends = [(secs(x), int(re.search(r'battle (\d+) sent to', x)[1])) for x in log_lines(h, r'battle \d+ sent to')]
        before = [b for t, b in sends if t is not None and t <= starts[-1] + 0.05]
        if not before:
            return last_sent
        cur = before[-1]
        return last_sent if self.rec.get(cur, {}).get('outcome') else cur

    def poll(self):
        h, c = log_since(H, self.hmark), log_since(C, self.cmark)
        if self.phase is None and 'battle phase: ' in h:
            self.t_phase = time.time()
            self.s0 = read_save(save_path(HOST_SLOT))
            time.sleep(1.0)  # the first battle is sent and the status set in the same tick
            st = ctl.status(H)
            self.phase = dict(status=st, list=battles_list(), enabled=strategic_enabled(self.ctx.hp),
                              nations=nation_table(H), vp=vpinfo(H), prestige=nint(H, self.K, 'Prestige'))
            log(f'  battle phase: host busy={st.get("busy")} status "{st.get("status")}", strategic screen enabled='
                f'{self.phase["enabled"]}, {self.phase["list"] and self.phase["list"]["raw"]}')
        for b in re.findall(r'battle (\d+) applied: ', h):  # the merged save, before the host loads it again
            if int(b) not in self.s1:
                s1 = read_save(save_path(HOST_SLOT))
                if s1 and 'General' in s1 and f'Nation{self.J}Ships' in s1:
                    self.s1[int(b)] = s1
        for b in re.findall(r'\] battle (\d+): (fought|declined|nobattle|avoided|failed|finished)', c):  # before the next one
            r2 = self.r(int(b[0]))
            if 'done' not in r2:
                r2['done'], r2['outcome'] = time.time(), b[1]
                if b[1] == 'fought':
                    # the client may copy the next battle into slot 87 within a second of "fought" (run 14 of
                    # 2026-10-17: 0.34 s): then this read is the next battle's copy. The mod saves the slot before it
                    # logs "fought", and its writes wait while the file is open here: a write time after "fought"
                    # BEFORE the read = stale
                    mt = file_time(save_path(BATTLE_SLOT))
                    self.g87[int(b[0])] = read_save(save_path(BATTLE_SLOT))
                    pre = log_since(C, self.cmark).split(f'] battle {b[0]}: fought', 1)[0].rsplit('\n', 1)[-1]
                    t_f, t_m = log_secs(pre), (log_secs(mt) if mt != '-' else None)
                    if t_f is not None and t_m is not None and 0.05 < t_m - t_f < 3600:
                        self.g87_stale[int(b[0])] = f'"fought" at {pre[:12]}, slot {BATTLE_SLOT} written at {mt}'
                        log(f'  battle {b[0]}: slot {BATTLE_SLOT} was rewritten for the next battle before it was read '
                            f'({self.g87_stale[int(b[0])]})')
                log(f'  battle {b[0]}: {b[1]} after {r2["done"] - r2["sent"]:.0f} s; answered {r2["answers"]}')
        sent = re.findall(r'battle (\d+) sent to', h)
        if not sent:
            if battle_up(self.ctx.cp):  # should not happen: a battle before the host sent one
                battle_dialogs(self.ctx.cp, 'decline', UNPLANNED)
            return
        rec = self.r(self.current(h, c, int(sent[-1])))
        bid = rec['id']
        # a "resolved without you" notice counts for this battle only if it came after the battle became the current one
        # (an earlier battle that outlived the time limit, e.g. one whose Decline was disabled, logged one too)
        notices = len(re.findall(r'resolved (this|your) battle without you', c))
        rec.setdefault('notices0', notices)
        if rec['action'] == 'hold' and not rec.get('release') and (
                notices > rec['notices0'] or time.time() - rec['sent'] > HOLD_LIMIT + 60):
            rec['release'] = time.time()
            log(f'  battle {bid}: the host resolved it without the client; the preview is answered now')
        tops = top_windows(self.ctx.cp)
        act = rec.get('force') or rec['action']  # 'decline' becomes 'fight' when the preview allows no decline
        if act == 'fight' and 'aftermath_view' not in rec and (rec.get('results') or rec.get('frm')) \
                and any(is_input_query(w) or (rec.get('results') and e2e_test.class_name(w) == 'TMessageForm')
                        for w in tops):
            rec['aftermath_view'] = cstate()  # before the box after the results is answered (the slot mode ends then)
            log(f'  battle {bid} after its results: {rec["aftermath_view"].get("raw")}')
        battle_dialogs(self.ctx.cp, rec['action'], rec)
        act = rec.get('force') or rec['action']
        if 'slot_view' not in rec and (rec.get('frm') or rec.get('preview_t')) and act == 'fight':
            rec['slot_view'] = dict(status=ctl.status(C), nations=nation_table(C), state=cstate())
            log(f'  battle {bid} on the client: slot {rec["slot_view"]["status"].get("slot")} playerIdx '
                f'{rec["slot_view"]["status"].get("playerIdx")}, nation 0 '
                f'{rec["slot_view"]["nations"].get(0, {}).get("name")}; {rec["slot_view"]["state"].get("raw")}')
        if act == 'fight' and rec.get('frm') and 'done' not in rec and time.time() - self.t_state > 15 \
                and not any(e2e_test.class_name(w) != 'TfrmMain' for w in top_windows(self.ctx.cp)
                            if e2e_test.class_name(w) in BATTLE_UP or e2e_test.class_name(w).startswith('Tdlg')
                            or e2e_test.class_name(w) == 'TMessageForm'):
            self.t_state = time.time()
            ps = value(cmd(C, 'pocstate')) or ''
            log(f'  battle {bid} running: {ps[:150]}')
            rec.setdefault('states', []).append(ps)
            stalled = 'running=0 moving=0' in ps and 'finished=1' in ps and 'endgame=0' in ps
            if stalled and rec.get('autorun') and len(rec['states']) > 1 and 'running=0 moving=0' in rec['states'][-2]:
                log('  battle stalled at a boundary: pocrun 100000', cmd(C, 'pocrun 100000'))
            if rec.get('autorun_clicks', 0) >= 3 and not rec.get('autorun') and time.time() - rec['autorun_t'] > 10:
                # the auto-run button did not open its prompt: both sides to the AI, fastest speed, run (POC commands)
                rec['autorun'] = 'poc'
                for line in ('pocsideai 0 1 0', 'pocsideai 1 1 0', 'pocspeed 5', 'pocrun 100000'):
                    log(f'  {line}:', cmd(C, line)[:100])


def war_month(ctx, label, K, J):
    """run_month for a month of a war of nation K with the computer nation J (no battle planned): a battle the month sends
    the client is declined, or fought on auto-run when its preview allows no decline (the player's nation defends); the
    BattleDriver restarts a run stalled at a minute boundary and gives the month FIGHT_TIMEOUT more (a run of
    2026-10-23: arms_treaty M1's undeclinable battle, answered without a driver, outlived MONTH_TIMEOUT)."""
    drv = BattleDriver(ctx, {}, K, J)
    drv.label = label
    return run_month(ctx, label, driver=drv)


def ship_changes(s0, g87, K, J, slot_k=0):
    """The battle's changes from the host's save as sent (s0, host numbering) and the battle slot after the battle
    (g87: K is nation `slot_k` there (0 in a battle slot), J keeps its number): ({(n, id): {field: (before, after)}},
    {(n, id) sunk})."""
    changed, sunk = {}, set()
    for n, slot_n in ((K, slot_k), (J, J)):
        before = ships_by_id((s0 or {}).get(f'Nation{n}Ships'))
        after = ships_by_id((g87 or {}).get(f'Nation{slot_n}Ships'))
        for sid, f0 in before.items():
            f1 = after.get(sid)
            if f1 is None:
                sunk.add((n, sid))
                continue
            ch = {k: (f0.get(k), v) for k, v in f1.items()
                  if f0.get(k) != v and k not in SHIP_INTEL and k != 'BuildingNationIdx'}
            if ch:
                changed[(n, sid)] = ch
    return changed, sunk


def merged_mismatches(s2, changed, sunk):
    """Where the host's save after the merge (s2) differs from the battle slot: [(n, id, field, want, got)], the sunk
    ships still there and the changed ships missing."""
    bad, still, missing = [], [], []
    by = {}
    for (n, sid), ch in changed.items():
        ships = by.setdefault(n, ships_by_id(s2.get(f'Nation{n}Ships')))
        f2 = ships.get(sid)
        if f2 is None:
            missing.append((n, sid))
            continue
        bad += [(n, sid, k, v[1], f2.get(k)) for k, v in ch.items() if f2.get(k) != v[1]]
    for n, sid in sunk:
        if sid in by.setdefault(n, ships_by_id(s2.get(f'Nation{n}Ships'))):
            still.append((n, sid))
    return bad, still, missing


def rejoin(ctx, K, fight):
    """The client leaves the session and joins again with `fightbattles fight`: the host gives the returning player
    ("Captain") its nation back and sends the month again (host `state seq N -> Captain (nation K, ...`, client
    `LoadCampaign slot 77 player K`). Returns (client status, host lines, client lines)."""
    cmd(C, 'leave')
    wait_until(lambda: ctl.status(H).get('players'), lambda p: p == '1', 15)
    hm, cm = log_mark(H), log_mark(C)
    r1 = cmd(C, f'fightbattles {1 if fight else 0}')
    r2 = cmd(C, f'join Captain 127.0.0.1 {MP_PORT}')
    log(f'  rejoin with fightbattles {1 if fight else 0}: {r1}, join {r2}')
    hpat, cpat = rf'state seq \d+ -> Captain \(nation {K},', rf'LoadCampaign slot {CLIENT_SLOT} player {K} -> ok'
    sent = wait_log(H, hm, hpat, 25)
    if not sent:
        log('  the nation was not given back: claim', cmd(C, f'claim {K}'))
        sent = wait_log(H, hm, hpat, 60)
    loaded = wait_log(C, cm, cpat, 60)
    st = wait(C, lambda s: s.get('phase') == 'planning' and s.get('myNation') == str(K) and s.get('playerIdx') == str(K)
              and s.get('slot') == str(CLIENT_SLOT), 60, 'the returning player plans its nation', pids=(ctx.hp,))
    time.sleep(2)
    cmd(C, 'mpwindow')
    time.sleep(1)
    return st, sent, loaded


def scenario_battles(ctx):
    """Joined players fight their battles against AI nations on their own PC (after 0.2.8). The host defers a battle
    the game would resolve between a joined nation and an AI nation, runs a battle phase after the month (save, lock,
    one battle per player at a time), the client fights it in its battle slot (Game87, its nation as nation 0; the
    game's CheckAttackLocation, preview, battle screen, results), the host merges the result (ships, losses, VP,
    prestige) and sends the new month. Battles are injected with `battles inject` (processed at the end of the next
    month) against an AI nation at war with nation 1 (`settension`). a) startup lines and defaults; b) one battle
    fought to its end on auto-run (two candidates a month, up to 3 months: the AI often avoids a battle) and its merge
    cross-checked against the battle slot's save; c) a declined battle and d) a battle left open past `battles timeout
    20` (three candidates each a month, up to 3 months); c2) decision 4: a declined battle under an emulated older host
    (the client's `battles hostgen 0`: the decline alone, the game resolves it, its box captured; up to 2 months); e) the
    client joins again with `fightbattles 0`: nothing is deferred. The war ends at the end."""
    K = 1
    hl, cl = [log_lines(log_since(p), r"Joined players' battles: ") for p in (H, C)]
    ok = any(re.search(BATTLE_OK_RE, x) for x in hl) and any(re.search(BATTLE_OK_RE, x) for x in cl)
    check('a) both logs: "Joined players\' battles: ok (frmMain=... checkAttack=...)"', ok, f'host {hl}; client {cl}')
    log('  ', hl[:1], cl[:1])
    if not ok:
        check('a) joined players\' battles available: the scenario stops here', False, 'startup line missing/UNAVAILABLE')
        return
    cs, bl = cstate(), battles_list()
    check(f'a) defaults: client `battles state` none, slot {BATTLE_SLOT}, slotMode 0, fight 1; host `battles list` '
          f'phase 0, timeout {DEFAULT_BATTLE_TIMEOUT}, no battles',
          cs.get('state') == 'none' and cs.get('slot') == BATTLE_SLOT and cs.get('slotMode') is False
          and cs.get('fight') is True and bl and bl['phase'] == 0 and bl['timeout'] == DEFAULT_BATTLE_TIMEOUT
          and not bl['battles'], f'{cs.get("raw")}; {bl and bl["raw"]}')
    nat = nation_table(H)
    me = nat[K]['name']
    cands = battle_pairs(K)
    log('  candidates (J ships there, K ships there, J, area):', cands[:5])
    if not check(f'setup: an AI nation with a possession in a sea area where nation {K} has >= 4 ships', cands, cands):
        return
    _, _, J, area = cands[0]
    them = nat[J]['name']
    tension0 = rel(K, J).get('tension', '5')
    cmd(H, f'settension {K} {J} 50')
    r = rel(K, J)
    check(f'setup: nation {K} ({me}) at war with AI nation {J} ({them}) (`settension {K} {J} 50`; was {tension0}); '
          f'battles in {area}', r.get('war') == '1', r)
    other = next(j for j in range(3, 9) if j not in (J, STANDIN))
    refused = {f'battles inject {K} {J} Nowhere Sea': 'no sea area',
               f'battles inject {other} {J} {area}': "K must be a joined player's nation",
               f'battles inject {K} {STANDIN} {area}': "K must be a joined player's nation",
               'battles resolve 99': 'ok 0'}
    got = {q: cmd(H, q) for q in refused}
    check('inject refused for an unknown area, an AI nation as K, the stand-in player nation as J; `battles resolve` of '
          'an unknown id resolves nothing', all(w in got[q] for q, w in refused.items()), got)

    # b) one battle fought to its end: two injected candidates a month (the AI often avoids a battle; the second is
    # declined once the first was fought), else a battle the month found by itself; up to 3 months
    fought, att, drivers = None, [], []
    for attempt in range(1, 4):
        hm = log_mark(H)
        cands_ids = [inject(K, J, area) for _ in range(2)]
        bid, rr = cands_ids[0]
        bl = battles_list()
        if attempt == 1:
            check(f'b) `battles inject {K} {J} {area}` -> ok <id>; host log "battle request <id> injected: nation {K} vs '
                  f'{J} in {area}"; `battles list` has it queued',
                  bid is not None and wait_log(H, hm, rf'battle request {bid} injected: nation {K} vs {J} in '
                                                       rf'{re.escape(area)}', 3)
                  and bl and bl['battles'].get(bid, {}).get('state') == 'queued', f'{rr}; {bl and bl["raw"]}')
        if bid is None:
            break
        if rel(K, J).get('war') != '1':
            log('  the war ended (AI peace?): again', cmd(H, f'settension {K} {J} 50'))
        drv = BattleDriver(ctx, {b: 'fight' for b, _ in cands_ids if b is not None}, K, J, fight_any=True)
        drv.label = f'battles A{attempt}'
        drivers.append(drv)
        date0 = ctl.status(C).get('date')
        date1 = run_month(ctx, drv.label, driver=drv)
        att += [(b, r.get('action'), r.get('outcome')) for b, r in sorted(drv.rec.items())]
        if drv.fought() is not None:
            fought = (drv.fought(), drv, date0, date1)
            break
        log(f'  no battle fought (attempt {attempt}): {[(b, r.get("outcome")) for b, r in drv.rec.items()]}; host: '
            f'{log_lines(log_since(H, drv.hmark), r"battle \d+: resolved")}')
    check('b) a battle fought on the client (attempts: id, action, outcome; "nobattle" = the game found no battle, '
          '"avoided" = the enemy declined battle: since 0.4.1 its VP gain is merged and the game resolves nothing)', fought,
          att)
    if fought:
        battle_fought_checks(ctx, K, J, area, me, them, *fought)
    report_unplanned()

    # c) declined and d) left past the time limit, in one month (up to 2 months)
    r = cmd(H, f'battles timeout {HOLD_LIMIT}')
    bl = battles_list()
    check(f'd) `battles timeout {HOLD_LIMIT}` -> ok, `battles list` timeout={HOLD_LIMIT}',
          r == 'ok' and bl and bl['timeout'] == HOLD_LIMIT, f'{r}; {bl and bl["raw"]}')
    want, done, notes = ['decline', 'hold'], {}, []
    for drv in drivers:  # a battle the month found by itself and the driver declined in its preview counts for c)
        for b, rec in sorted(drv.rec.items()):
            if rec['action'] == 'decline' and rec.get('preview_t') and not rec.get('no_decline') \
                    and 'decline' not in done:
                done['decline'] = (b, drv)
    for attempt in range(1, 4):
        plan = {}
        for action in want:  # three candidates per missing action; a second preview of a 'hold' is declined
            for _ in range(3):
                bid, rr = inject(K, J, area)
                if bid is not None:
                    plan[bid] = action
        if rel(K, J).get('war') != '1':
            log('  the war ended (AI peace?): again', cmd(H, f'settension {K} {J} 50'))
        drv = BattleDriver(ctx, plan, K, J)
        drv.label = f'battles B{attempt}'
        drivers.append(drv)
        run_month(ctx, drv.label, driver=drv)
        for bid, rec in sorted(drv.rec.items()):
            action = rec['action']
            notes.append((bid, action, rec.get('outcome'), rec.get('preview_buttons'), rec.get('answers')))
            if rec.get('preview_t') and not (action == 'decline' and rec.get('no_decline')) \
                    and (action not in done or bid in plan and done[action][0] not in plan):
                done[action] = (bid, drv)
        want = [a for a in ('decline', 'hold') if a not in done]
        if not want:
            break
        log(f'  no battle preview for {want} (attempt {attempt}): {notes}')
    check('c/d) a declined and a held battle reached the game\'s battle preview (attempts: id, action, outcome, '
          'preview buttons, answers)', not want, notes)
    if 'decline' in done:
        battle_declined_checks(ctx, K, J, area, me, them, *done['decline'])
    if 'hold' in done:
        battle_timeout_checks(ctx, K, J, area, me, them, *done['hold'])
    r = cmd(H, f'battles timeout {DEFAULT_BATTLE_TIMEOUT}')
    check(f'd) `battles timeout {DEFAULT_BATTLE_TIMEOUT}` restores the default', r == 'ok'
          and (battles_list() or {}).get('timeout') == DEFAULT_BATTLE_TIMEOUT, r)
    natural_request_checks(ctx, K, J, me, them, drivers)
    report_unplanned()

    # c2) decision 4: the decline under an older host (the client's `battles hostgen 0`)
    battle_oldhost_checks(ctx, K, J, area, me, them)
    report_unplanned()

    # e) opt-out: the client joins again with `fightbattles 0`
    st, sent, loaded = rejoin(ctx, K, fight=False)
    cs, hrow = cstate(), row(H, K)
    check(f'e) the client left and joined again with `fightbattles 0`: the host gave Captain nation {K} back and sent '
          f'the month (`state seq N -> Captain (nation {K}, ...`), the client loaded it and plans nation {K} in slot '
          f'{CLIENT_SLOT} (myNation {K}); `battles state` fight=0, none, slotMode 0',
          sent and loaded and hrow and hrow['player'] == 'Captain' and st.get('myNation') == str(K)
          and st.get('playerIdx') == str(K) and st.get('slot') == str(CLIENT_SLOT) and cs.get('fight') is False
          and cs.get('state') == 'none' and cs.get('slotMode') is False,
          f'{sent} {loaded}; host row {hrow}; {st}; {cs.get("raw")}')
    bid, rr = inject(K, J, area)
    check(f'e) `battles inject {K} {J} {area}` refused: "no connected player who fights battles for nation {K}"',
          bid is None and f'no connected player who fights battles for nation {K}' in rr, rr)
    if rel(K, J).get('war') != '1':
        log('  the war ended (AI peace?): again', cmd(H, f'settension {K} {J} 50'))
    hm, t0 = log_mark(H), time.time()
    run_month(ctx, 'battles C')
    hlog = log_since(H, hm)
    req = log_lines(hlog, r'battle request|battle phase|battle \d+ sent')
    pics = [a[2] for a in ANSWERED if a[0] >= t0 and a[1] == 'host' and 'TdlgPictureMessage' in a[2]]
    check(f'e) a processed month with nation {K} at war with {J} ({them}) and the opt-out: no "battle request", '
          f'battle phase or sent line in the host log (the game resolves its AI battles itself)', not req, req[:4])
    log(f'  e) host picture messages that month (the game\'s AI battle news, among others): {pics[:6]}')

    # end: the war is over, nothing left
    cmd(H, f'settension {K} {J} {tension0}')
    r, cs, bl = rel(K, J), cstate(), battles_list()
    check(f'end: nation {K} at peace with {J} again (tension {tension0}); client `battles state` none, slotMode 0; host '
          f'`battles list` phase 0, no battles', r.get('war') == '0' and cs.get('state') == 'none'
          and cs.get('slotMode') is False and bl and bl['phase'] == 0 and not bl['battles'],
          f'{r}; {cs.get("raw")}; {bl and bl["raw"]}')
    report_unplanned()


def report_unplanned():
    if UNPLANNED['answers']:
        log('  battle dialogs of months without a plan (declined):', UNPLANNED['answers'])
        UNPLANNED['answers'] = []


def battle_fought_checks(ctx, K, J, area, me, them, bid, drv, date0, date1):
    """b) after the month whose battle was fought: the battle phase, the battle slot, the dialogs, the client's and the
    host's log lines, the merged values (the host's save right after the merge = the save as sent + the battle's
    deltas; ship fields cross-checked with the battle slot's save), the values after the month on host and client."""
    hlog, clog, rec = log_since(H, drv.hmark), log_since(C, drv.cmark), drv.rec[bid]
    ph = drv.phase or {}
    pst, plist = ph.get('status', {}), ph.get('list') or {}
    req = log_lines(log_since(H), rf'battle request {bid}[ :]')  # an injected one was logged before the month
    barea = battle_area(log_since(H), bid, area)  # the fought battle's area (one the game found may be elsewhere)
    check(f'b) host log: the request of battle {bid}, "battle phase: N battle(s)", "battle {bid} sent to Captain"',
          req and re.search(r'battle phase: \d+ battle\(s\)', hlog) and re.search(rf'battle {bid} sent to Captain', hlog),
          req + log_lines(hlog, r'battle phase|battle \d+ sent'))
    first = min(plist.get('battles', {}) or [0])
    want_status = f'Battles in progress: Captain: {me} vs {them} in {area}'
    check(f'b) host during the battle phase: strategic screen locked (status busy=1, TfrmBuildCamp disabled), status '
          f'"{want_status}", `battles list` phase=1 with the first battle {first}:{K}-{J}:{area}:fighting',
          pst.get('busy') == '1' and ph.get('enabled') is False and pst.get('status') == want_status
          and plist.get('phase') == 1 and plist.get('battles', {}).get(first, {}).get('state') == 'fighting'
          and (plist['battles'][first]['K'], plist['battles'][first]['J'], plist['battles'][first]['area']) == (K, J, area),
          f'busy {pst.get("busy")}, enabled {ph.get("enabled")}, status "{pst.get("status")}", {plist.get("raw")}')
    sv = rec.get('slot_view') or {}
    sst, snat, scs = sv.get('status', {}), sv.get('nations', {}), sv.get('state', {})
    check(f'b) client in the battle slot: status slot {BATTLE_SLOT}, playerIdx 0; `nations` 0 = {me}; `battles state` '
          f'starting/fighting nation {K} opp {J} area {barea}, slot {BATTLE_SLOT}, slotMode 1',
          sst.get('slot') == str(BATTLE_SLOT) and sst.get('playerIdx') == '0' and snat.get(0, {}).get('name') == me
          and scs.get('state') in ('starting', 'fighting') and (scs.get('nation'), scs.get('opp'), scs.get('area'))
          == (K, J, barea) and scs.get('slotMode') is True,
          f'{sst.get("slot")}/{sst.get("playerIdx")}; nation 0 {snat.get(0, {}).get("name")}; {scs.get("raw")}')
    av = rec.get('aftermath_view') or {}
    check('b) client dialogs: the battle preview (Accept), the battle screen, its auto-run prompt (Yes), the results '
          '("Scenario results" -> Exit battle); `battles state` aftermath=1 at the next box (HandleBattleAftermath ran '
          'in the battle slot); the history prompt answered Cancel if the game asked',
          rec.get('preview_t') and rec.get('frm') and rec.get('autorun') is True and rec.get('results')
          and av.get('aftermath') is True and av.get('slotMode') is True,
          f'answers {rec.get("answers")}; autorun {rec.get("autorun")} prompt {rec.get("autorun_prompt")}; history '
          f'prompt {rec.get("inputquery")}; after the results {av.get("raw")}')
    log(f'  b) battle {bid}: preview after {(rec.get("preview_t") or 0) - rec["sent"]:.0f} s, battle screen after '
        f'{(rec.get("frm") or 0) - rec["sent"]:.0f} s, results after {(rec.get("results") or 0) - rec["sent"]:.0f} s, '
        f'done after {(rec.get("done") or 0) - rec["sent"]:.0f} s; history prompt {rec.get("inputquery")}; last states '
        f'{rec.get("states", [])[-1:]}')
    skips = log_lines(clog, r'battle slot: \w+ skipped')
    check('b) client log: "battle slot: DoStrategicTurn skipped" (the battle screen\'s close runs no month)',
          any('DoStrategicTurn skipped' in x for x in skips), skips)
    pair = rf'(0 attacks {J}|{J} attacks 0) in {re.escape(barea)} -> battle'
    starts = log_lines(clog, rf'StartPlayerBattle {pair}|battle {bid}: (fighting|fought)')
    check(f'b) client log: "StartPlayerBattle 0 attacks {J} (or {J} attacks 0) in {barea} -> battle", "battle {bid}: '
          f'fighting nation {K} vs {J} in {barea} (slot {BATTLE_SLOT})", "battle {bid}: fought"',
          any(re.search(pair, x) for x in starts) and any(f'fighting nation {K} vs {J} in {barea} (slot {BATTLE_SLOT})'
                                                          in x for x in starts) and any(': fought' in x for x in starts),
          starts)
    st, cs = ctl.status(C), cstate()
    check(f'b) client back in slot {CLIENT_SLOT} as nation {K} in the new month ({date0} -> {date1}); `battles state` '
          f'none, slotMode 0', st.get('slot') == str(CLIENT_SLOT) and st.get('playerIdx') == str(K)
          and date1 != date0 and cs.get('state') == 'none' and cs.get('slotMode') is False, f'{st}; {cs.get("raw")}')
    ap = [re.search(APPLIED_RE, x) for x in log_lines(hlog, rf'battle {bid} applied: ')]
    ap = ap[0] if ap else None
    check(f'b) host log: "battle {bid} applied: N ships changed (F fields), R removed, VP a/b, prestige p (player: ...)" '
          f'with N + R > 0', ap and int(ap[2]) + int(ap[4]) > 0, log_lines(hlog, rf'battle {bid} (applied|NOT)'))
    s0, g87 = drv.s0 or {}, drv.g87.get(bid) or {}
    stale = drv.g87_stale.get(bid)
    s2 = read_save(save_path(HOST_SLOT)) or {}
    others = log_lines(hlog, r'resolved by the game: battle') + [  # the month's other battles, after this merge
        x for x in log_lines(hlog, r'battle \d+ applied: ') if f'battle {bid} applied' not in x]
    s1 = drv.s1.get(bid) or ({} if others else s2)  # the merged save (read at once), else the month's own save
    # a battle slot read too late (the next battle's copy): the merge's own changes (as sent -> merged) stand in for it
    changed, sunk = ship_changes(s0, s1, K, J, slot_k=K) if stale else ship_changes(s0, g87, K, J)
    bad1, still1, missing1 = merged_mismatches(s1, changed, sunk) if s1 else ([], [], ['no merged save read'])
    bad2, still2, missing2 = merged_mismatches(s2, changed, sunk)
    dmg = {key: ch for key, ch in changed.items() if 'RepairTime' in ch or 'Fate' in ch}
    ex = next(iter(dmg.items() or changed.items()), None)
    ex_txt = ''
    if ex:
        (n, sid), ch = ex
        f2 = ships_by_id(s2.get(f'Nation{n}Ships')).get(sid, {})
        ex_txt = (f'e.g. nation {n} ship {sid} {f2.get("Name")}: ' +
                  ', '.join(f'{k} {v[0]}->{v[1]} (host after the month {f2.get(k)})' for k, v in list(ch.items())[:5]))
    log(f'  b) battle slot vs the save as sent: {len(changed)} ships changed ({len(dmg)} with RepairTime/Fate), '
        f'{len(sunk)} sunk {sorted(sunk)[:6]}; {ex_txt}')
    check('b) cross-check: every ship field the battle changed (battle slot Game87 after the battle vs the host save as '
          'sent) has the battle slot\'s value in the host\'s merged save; the sunk ships are gone from it'
          + (f' (NOT cross-checked this time: the client had copied the next battle into slot {BATTLE_SLOT} before the '
             f'runner read it, {stale}; the merge changed ships)' if stale else ''),
          s0 and s1 and changed and (stale or g87 and not bad1 and not still1 and not missing1),
          f'{len(changed)} changed, {len(sunk)} sunk; mismatches {bad1[:5]}; sunk still there {still1[:5]}; missing '
          f'{missing1[:5]}')
    check('b) ... and after the month: the host loaded the merged save (with another battle of the month merged or '
          'resolved by the game afterwards, its changes are reported instead)',
          (not bad2 and not still2 and not missing2) or others,
          f'mismatches {bad2[:5]}; sunk still there {still2[:5]}; missing {missing2[:5]}; other battles: {others}')
    if others and (bad2 or still2 or missing2):
        log(f'  b) after the month, changed again by the month\'s other battles ({others}): {bad2[:5]} missing '
            f'{missing2[:5]}')
    if ap:
        vp_k, vp_j, pres = int(ap[5]), int(ap[6]), int(ap[7])
        # the month's battles merged before this one are in the merged save as well (since 0.4.1 an avoided battle's VP
        # gain is merged: dist_rc041_2's --stress run, battle 1 "avoided" with VP 360/0 merged before battle 2)
        inj = {}
        for x in log_lines(log_since(H), r'battle request \d+ injected: nation \d+ vs \d+'):
            mi = re.search(r'battle request (\d+) injected: nation (\d+) vs (\d+)', x)
            if mi:
                inj[mi[1]] = (int(mi[2]), int(mi[3]))
        prior, unknown = [], []
        for x in log_lines(hlog, r'battle \d+ applied: '):
            mi = re.search(APPLIED_RE, x)
            if not mi:
                continue
            if mi[1] == str(bid):
                break
            if inj.get(mi[1]) == (K, J):
                prior.append((int(mi[5]), int(mi[6]), int(mi[7]), mi[1]))
            else:
                unknown.append(x)
        vp_k += sum(p[0] for p in prior)
        vp_j += sum(p[1] for p in prior)
        pres += sum(p[2] for p in prior)
        num = lambda d, n, k: int((d.get(f'Nation{n}') or {}).get(k, 0) or 0)  # noqa: E731
        b = (num(s0, K, 'VP'), num(s0, J, 'VP'), num(s0, K, 'Prestige'))
        m1 = (num(s1, K, 'VP'), num(s1, J, 'VP'), num(s1, K, 'Prestige'))
        if unknown:
            log(f'  SKIP-note b) the merged save\'s VP and Prestige not checked: a battle of other nations was merged before '
                f'this one ({unknown[:2]})')
        else:
            check(f'b) the merged save: VP of {K} {b[0]}{vp_k:+d}, VP of {J} {b[1]}{vp_j:+d}, Prestige of {K} '
                  f'{b[2]}{pres:+d} (the save as sent + the deltas of the applied line'
                  + (f' and of the battles merged before it: {[p[3] for p in prior]}' if prior else '') + ')',
                  s1 and m1 == (b[0] + vp_k, b[1] + vp_j, b[2] + pres), f'{b} -> {m1}; merged before: {prior}')
        vp, p_now = vpinfo(H), nint(H, K, 'Prestige')
        mem = (vp and vp['vp'].get(K), vp and vp['vp'].get(J), p_now)
        f2 = (num(s2, K, 'VP'), num(s2, J, 'VP'), num(s2, K, 'Prestige'))
        check(f'b) host after the month: VP {K}/{J} and Prestige {K} in memory = its save, = the merged values unless the '
              f'game resolved another battle afterwards ({len(others)})', mem == f2 and (mem == m1 or others),
              f'memory {mem}, save {f2}, merged {m1}; {others}')
        n_now = nation_table(H)
        n_ph = ph.get('nations') or {}
        sk = sum(1 for n, _ in sunk if n == K)
        sj = sum(1 for n, _ in sunk if n == J)
        check(f'b) host `nations` ship counts: {me} {n_ph.get(K, {}).get("ships")} - {sk} sunk, {them} '
              f'{n_ph.get(J, {}).get("ships")} - {sj} sunk; the applied line removed {ap[4]}',
              n_ph and (n_now[K]['ships'] == n_ph[K]['ships'] - sk and n_now[J]['ships'] == n_ph[J]['ships'] - sj
                        or others) and int(ap[4]) >= sk + sj,
              f'{me} {n_ph.get(K, {}).get("ships")} -> {n_now[K]["ships"]}, {them} {n_ph.get(J, {}).get("ships")} -> '
              f'{n_now[J]["ships"]}')
        cp_, cv = nint(C, K, 'Prestige'), vpinfo(C)
        check(f'b) the client got the values with the new month: Prestige of {K}, VP of {K} and its ship count = host\'s',
              cp_ == p_now and cv and cv['vp'].get(K) == mem[0]
              and nation_table(C).get(K, {}).get('ships') == n_now[K]['ships'],
              f'client Prestige {cp_}, ships {nation_table(C).get(K, {}).get("ships")}; vp {cv and cv["raw"]}')
    ch_after = chat(ctx.cp)
    lines = [f'* The battle of {me} against {them} in {barea} was fought by Captain.', '* Battle result sent to the host (']
    check('b) client chat: "* Battle result sent to the host (...)" and the host\'s "* The battle of ... was fought by '
          'Captain."', all(x in ch_after for x in lines), [x for x in lines if x not in ch_after])
    exc = log_lines(hlog, r'(?i)exception') + log_lines(clog, r'(?i)exception')
    bl = battles_list()
    check('b) no exception in either log during the month; host `battles list` phase 0 and empty afterwards',
          not exc and bl and bl['phase'] == 0 and not bl['battles'], f'{exc[:3]}; {bl and bl["raw"]}')


def battle_declined_checks(ctx, K, J, area, me, them, bid, drv):
    """c) a battle declined in the game's preview: the client reports it as declined with the game's consequences of
    the decline on its PC, and the host merges them (0.6.0, risk 4; before, the host let the game resolve it and its
    result box waited for the host's player)."""
    hlog, clog, rec = log_since(H, drv.hmark), log_since(C, drv.cmark), drv.rec[bid]
    area = battle_area(log_since(H), bid, area)
    out = log_lines(clog, rf'\] battle {bid}: ')
    check(f'c) battle {bid}: the client declined it in the game\'s preview (buttons {rec.get("preview_buttons")})',
          any('BattlePreview' in a and a.endswith('->Decline') for a in rec['answers']), rec['answers'])
    lines = log_lines(hlog, rf'battle {bid} applied: .*the player declined battle')
    ch = chat(ctx.cp)
    want = f'* Captain declined battle for {me} against {them} in {area}.'
    check(f'c) reported as declined: client log "battle {bid}: declined", host "battle {bid} applied: ...; the player '
          f'declined battle", both chat lines ("{want}", "* You declined the battle (VP ...")',
          any(x.endswith(f'battle {bid}: declined') for x in out) and lines and want in ch
          and '* You declined the battle (' in ch, f'client {out}; host {lines}; chat has {want in ch}')
    gone = log_lines(hlog, rf'battle {bid}: resolved by the game|battle {bid} resolved by the game')
    check(f'c) the game did not resolve it (no "battle {bid}: resolved by the game"); the month went on',
          not gone and any(m[0] == drv_month(drv) for m in ctx.months), gone)
    # decision 2: the nation's own decline counts in the battle slot and back to the host (session file `kdecl`)
    cl = [re.search(r'counts (-?\d+)/(-?\d+) in the battle slot', x) for x in
          log_lines(clog, rf'\] battle {bid}: the nation\'s decline counts -?\d+/-?\d+ in the battle slot')]
    hl = [re.search(r'counts (-?\d+)/(-?\d+) \(were (-?\d+)/(-?\d+)\)', x) for x in
          log_lines(hlog, rf'battle {bid}: nation {K}\'s decline counts ')]
    last = [re.search(r'counts (-?\d+)/(-?\d+) \(were', x) for x in
            log_lines(log_since(H), rf'battle \d+: nation {K}\'s decline counts ')][-1:]
    kd = {e.split(':')[0]: e.split(':', 1)[1] for e in session_file().get('kdecl', '').split(',') if e.count(':') == 2}
    check(f'c) decision 2: client "battle {bid}: the nation\'s decline counts a/b in the battle slot (the save\'s were '
          f'...)", host "battle {bid}: nation {K}\'s decline counts x/y (were a/b)"; {SESSION_FILE} kdecl has nation {K}\'s '
          f'latest counts', cl and hl and cl[0] and hl[0] and cl[0].groups() == hl[0].groups()[2:] and last and last[0]
          and kd.get(str(K)) == f'{last[0][1]}:{last[0][2]}',
          dict(client=[x[0] for x in cl if x], host=[x[0] for x in hl if x], kdecl=kd))


def battle_oldhost_checks(ctx, K, J, area, me, them):
    """c2) decision 4 (0.6.0): a decline under an older host. The client's `battles hostgen 0` takes the host's welcome
    as one without `gen` (a 0.5.0 host): the decline goes alone (client "battle N: declined", chat "* You declined the
    battle; the game resolves it."), the host has the game resolve it ("battle N: resolved by the game (Captain declined
    it)", after the battles "battle N resolved by the game: battle|no battle" with its result box captured, none shown).
    Three injected battles a month (nation K attacks: the preview's Decline is enabled), up to 2 months; then
    `battles hostgen` back to the welcome's value (1; 2 since B6 piece 2)."""
    g0 = cstate().get('hostgen') or 1
    r = cmd(C, 'battles hostgen 0')
    check('c2) client `battles hostgen 0` -> "ok hostgen=0", `battles state` hostgen=0',
          r == 'ok hostgen=0' and cstate().get('hostgen') == 0, r)
    found, notes, r1 = None, [], None
    try:
        for attempt in range(1, 3):
            if rel(K, J).get('war') != '1':
                log('  the war ended (AI peace?): again', cmd(H, f'settension {K} {J} 50'))
            drv = BattleDriver(ctx, {b: 'decline' for b, _ in [inject(K, J, area) for _ in range(3)] if b}, K, J)
            drv.label = f'battles D{attempt}'
            run_month(ctx, drv.label, driver=drv)
            for b, rec in sorted(drv.rec.items()):
                notes.append((b, rec.get('outcome'), rec.get('preview_buttons')))
                if not found and rec.get('outcome') == 'declined' and rec.get('preview_t') and not rec.get('no_decline'):
                    found = (b, drv)
            if found:
                break
            log(f'  c2) no battle declined in its preview (attempt {attempt}): {notes}')
    finally:
        r1 = cmd(C, f'battles hostgen {g0}')
    check(f'c2) a battle declined in its preview under the emulated older host (id, outcome, preview buttons); '
          f'`battles hostgen {g0}` after (the welcome\'s value)', found and r1 == f'ok hostgen={g0}',
          dict(notes=notes, restore=r1))
    if not found:
        return
    bid, drv = found
    hl, out = log_since(H, drv.hmark).splitlines(), log_lines(log_since(C, drv.cmark), rf'\] battle {bid}: ')
    gone = [x for x in hl if f'battle {bid}: resolved by the game (Captain declined it)' in x]
    fin = [i for i, x in enumerate(hl) if re.search(rf'battle {bid} resolved by the game: (battle|no battle)$', x)]
    caps, i = [], (fin[0] - 1 if fin else -1)
    while i >= 0 and not re.search(r'resolved by the game: (battle|no battle)$|battle phase', hl[i]):
        caps += [hl[i]] if 'picture message captured' in hl[i] else []
        i -= 1
    ch = chat(ctx.cp)
    want = [f'* The battle of {me} against {them} in {area} was resolved by the game (Captain declined it).',
            '* You declined the battle; the game resolves it.']
    check(f'c2) battle {bid}: client "battle {bid}: declined" sent alone (no "battle {bid} applied" on the host), host '
          f'"battle {bid}: resolved by the game (Captain declined it)", both chat lines',
          any(x.endswith(f'battle {bid}: declined') for x in out) and gone
          and not any(f'battle {bid} applied' in x for x in hl) and all(x in ch for x in want),
          dict(client=out[-2:], host=gone[:1], chat_missing=[x for x in want if x not in ch]))

    def day_secs(ts):
        lt = time.localtime(ts)
        return lt.tm_hour * 3600 + lt.tm_min * 60 + lt.tm_sec + ts % 1

    t_a, t_b = (log_secs(gone[0]), log_secs(hl[fin[0]]) + 2) if gone and fin else (None, None)
    shown = [a[2] for a in ANSWERED if t_a is not None and a[1] == 'host' and 'TdlgPictureMessage' in a[2]
             and t_a <= day_secs(a[0]) <= t_b]
    res = hl[fin[0]] if fin else ''
    check(f'c2) after the battles the host had the game resolve it ("battle {bid} resolved by the game: battle|no '
          f'battle"), its result box captured ("picture message captured" when it fought), none shown on the host',
          fin and (res.endswith('no battle') or caps) and not shown,
          dict(result=res[-40:], captured=[x[-90:] for x in caps[:2]], shown=shown[:2]))


def drv_month(drv):
    """The label of the month a BattleDriver ran (set by scenario_battles)."""
    return getattr(drv, 'label', None)


def battle_area(hlog, bid, default):
    """The sea area of battle `bid` from its request line in the host log (injected or found by the game; 0.6.0: the
    player's generator's "... in <area>, N attempt(s), fought by Captain")."""
    req = log_lines(hlog, rf'battle request {bid}[ :]')
    m = re.search(r' in (.+?)(?:, \d+ attempt\(s\).*| \(\d+:\d+ ships\).*)?$', req[0]) if req else None
    return m[1] if m else default


def natural_request_checks(ctx, K, J, me, them, drivers):
    """Battles the game itself found in the battle months (DoBattleBetweenAINations of nation K and the AI nation at
    war with it): deferred with the request line and the host's chat line, sent to the player and settled (fought,
    or resolved by the game)."""
    reqs, missing, chat_lines, seen = [], [], [], set()
    ch = chat(ctx.cp)
    for drv in drivers:
        hlog = log_since(H, drv.hmark)
        for m in re.finditer(r'battle request (\d+): nation (\d+) vs (\d+) in (.+?) \((\d+):(\d+) ships\), fought by '
                             r'(\S+)', hlog):
            bid, a, b, area = int(m[1]), int(m[2]), int(m[3]), m[4]
            if bid in seen:  # a driver's log runs on to the end: later months are in it too
                continue
            seen.add(bid)
            reqs.append((bid, a, b, area, m[5] + ':' + m[6], m[7]))
            settled = re.search(rf'battle {bid} (applied|resolved by the game): ', hlog)
            if {a, b} != {K, J} or m[7] != 'Captain' or not re.search(rf'battle {bid} sent to Captain', hlog) \
                    or not settled:
                missing.append(bid)
            chat_lines.append(f'* Battle! {me} meets {them} in {area}. Captain fights it after the month.')
    if not reqs:
        log(f'  SKIP natural requests: the game found no battle of {me} and {them} by itself in the battle months')
        return
    log(f'  battles the game found by itself (id, a, b, area, ships, player): {reqs}')
    check(f'b) battles the game found by itself ({len(reqs)}): "battle request N: nation a vs b in <area> (x:y ships), '
          f'fought by Captain", sent to Captain and settled (merged or resolved by the game); the host\'s chat line "* '
          f'Battle! {me} meets {them} in <area>. Captain fights it after the month."',
          not missing and all(x in ch for x in chat_lines), f'{reqs}; not settled {missing}; chat missing '
          f'{[x for x in set(chat_lines) if x not in ch]}')


def battle_timeout_checks(ctx, K, J, area, me, them, bid, drv):
    """d) the battle left open (preview) past `battles timeout 20`: the host resolves it, the client's late answer is
    ignored, the month goes on."""
    hlog, clog, rec = log_since(H, drv.hmark), log_since(C, drv.cmark), drv.rec[bid]
    sent = log_lines(hlog, rf'battle {bid} sent to')
    gone = log_lines(hlog, rf'battle {bid}: resolved by the game \(time limit\)')
    dt = log_secs(gone[0]) - log_secs(sent[0]) if sent and gone else None
    check(f'd) host log: "battle {bid}: resolved by the game (time limit)" {HOLD_LIMIT}-{HOLD_LIMIT + 10} s after '
          f'"battle {bid} sent"', dt is not None and HOLD_LIMIT <= dt <= HOLD_LIMIT + 10, f'{dt} s; {sent} {gone}')
    t_sent = log_secs(sent[0]) if sent else None
    told = [x for x in log_lines(clog, r'resolved (this|your) battle without you')
            if t_sent is not None and log_secs(x) >= t_sent]  # not an earlier battle's notice
    check('d) client: "The host resolved this battle without you (time limit) ..." while its preview was open',
          told and '(time limit)' in told[0] and rec.get('preview_t'), told)
    late = log_lines(hlog, rf'battle result {bid} from Captain ignored') + \
        log_lines(clog, rf'battle {bid}: finished after the host resolved it; result not sent')
    check(f'd) the client\'s later answer is not used: host "battle result {bid} from Captain ignored" (or the client '
          f'sent none)', late, log_lines(clog, rf'battle {bid}') + late)
    fin = log_lines(hlog, rf'battle {bid} resolved by the game: ')
    st, cs = ctl.status(C), cstate()
    check(f'd) the month went on: the game resolved it ({fin}), the client plans the new month in slot {CLIENT_SLOT}, '
          f'slot mode off', fin and st.get('slot') == str(CLIENT_SLOT) and st.get('playerIdx') == str(K)
          and cs.get('slotMode') is False and cs.get('state') == 'none', f'{st}; {cs.get("raw")}')


# ---------------------------------------------------------------- campaign divisions of a joined player (0.6.1)

FO_TAB = 'Fleet organization'  # the strategic screen's tab of the division editor (TabControl1, index 9)
FO_BUTTONS = ('New division', 'Expand all', 'Collapse all', 'Clear assignments')
DIVS_RE = re.compile(r'^ok n=(\d+)(?: nation=(-?\d+))? list=(.*)$')
DIV_ERR_RE = re.compile(r'(?i)\bexception\b|Access violation|Error in FillDivisionList2|Missing ship')
DIV_HOST = (('RT Host Div A', 'RHA', 'CA'), ('RT Host Div B', 'RHB', 'BX'))  # (name, abbreviation, type) of the host's
DIV_K = (('RT K Div 1', 'RK1', 'CA'), ('RT K Div 2', 'RK2', 'BX'))  # nation 1's; the second renamed DIV_K_RENAMED
DIV_K_RENAMED = 'RT K Div 2R'


def parse_divs(reply):
    """`divs` (either copy: the divisions in memory) / `divstore <K>` (host: nation K's stored list) -> dict(n, nation
    (PlayerNation's index; None for divstore), divs=[dict(id, name, ships, ids)], raw); None for an error or a malformed
    reply. Entries '<CDivId>:<name>:<ship count>:<ship id.ship id...>' joined by '|' ('|' and ':' in names are '_', a
    nil ship's id is 'nil', a nil division the entry 'nil')."""
    m = DIVS_RE.match(reply or '')
    if not m:
        return None
    out = []
    for e in (x for x in m[3].split('|') if x):
        if e == 'nil':
            out.append(dict(id=None, name=None, ships=0, ids=[]))
            continue
        p = e.split(':')
        if len(p) != 4 or not p[2].isdigit():
            return None
        out.append(dict(id=p[0], name=p[1], ships=int(p[2]), ids=[x for x in p[3].split('.') if x]))
    if len(out) != int(m[1]):
        return None
    return dict(n=int(m[1]), nation=int(m[2]) if m[2] is not None else None, divs=out, raw=reply)


def off_divisions(sec):
    """[CampaignDivisions] of a parsed .off (read_save) -> dict(no=CampDivNo (None if missing), divs=[dict(id, name,
    ids)]) (the entries CampDiv<i>... up to CampDivNo)."""
    sec = sec or {}
    no = sec.get('CampDivNo')
    n = int(no) if (no or '').lstrip('-').isdigit() else None
    divs = []
    for i in range(max(0, n or 0)):
        p = f'CampDiv{i}'
        sc = sec.get(p + 'ShipCount', '0')
        divs.append(dict(id=sec.get(p + 'CDivId'), name=sec.get(p + 'Name'),
                         ids=[sec.get(f'{p}ShipId{j}') for j in range(int(sc) if sc.isdigit() else 0)]))
    return dict(no=n, divs=divs)


def slot_divisions(slot, fname=None):
    """off_divisions of a slot's RTWGame<slot>.off (or another .off of the slot folder: Autosave.off); None without."""
    s = read_save(os.path.join(slot_dir(slot), fname or f'RTWGame{slot}.off'))
    return None if s is None else off_divisions(s.get('CampaignDivisions'))


def nation_ships(n, slot=HOST_SLOT):
    """Ship ids (strings) of nation n in a slot's .bcs."""
    return set(ships_by_id((read_save(save_path(slot)) or {}).get(f'Nation{n}Ships')))


def div_summary(d):
    """'name[ids]; ...' of parse_divs / off_divisions results (a check's detail)."""
    if not d:
        return repr(d)
    return '; '.join(f'{x["name"]}[{".".join(x["ids"])}]' for x in d['divs']) or '(none)'


def fo_frm(pid):
    return next((h for h in top_windows(pid) if e2e_test.class_name(h) == 'TfrmBuildCamp'), None)


def fo_tabs(pid):
    """(TabControl1, [tab texts]): the strategic screen's TTabControl with the most tabs (Map ... Fleet organization),
    (None, []) without it."""
    f = fo_frm(pid)
    best = None
    for h in children(f) if f else []:
        if e2e_test.class_name(h) == 'TTabControl':
            n = _u32.SendMessageW(h, 0x1304, 0, 0)  # TCM_GETITEMCOUNT
            if n >= 9 and (best is None or n > best[1]):
                best = (h, n)
    if not best:
        return None, []
    texts = []
    with RemoteBuf(pid) as rb:
        for i in range(min(best[1], 24)):
            rb.write(64, bytes(256))
            rb.write(0, struct.pack('<IIIIiii', 1, 0, 0, rb.addr + 64, 120, 0, 0))  # TCITEMW, TCIF_TEXT
            _u32.SendMessageW(best[0], 0x133C, i, rb.addr)  # TCM_GETITEMW
            texts.append(rb.read(64, 240).decode('utf-16-le', 'replace').split('\x00')[0])
    return best[0], texts


def fo_set_tab(pid, want, refresh=False):
    """Select a tab of TabControl1 (index or text) as a click does: TCM_SETCURFOCUS posted (the control sends
    TCN_SELCHANGING / TCN_SELCHANGE: the screen's TabControl1Change fills the panel), posted arrow keys if it did not
    move. refresh: already on it -> away and back, so the panel is filled anew. True when the tab is selected."""
    tc, texts = fo_tabs(pid)
    idx = want if isinstance(want, int) else (texts.index(want) if want in texts else None)
    if not tc or idx is None:
        return False

    def cur():
        return _u32.SendMessageW(tc, 0x130B, 0, 0)  # TCM_GETCURSEL

    if cur() == idx and not refresh:
        return True
    if cur() == idx:
        away = 0 if idx else 1
        u.PostMessageW(tc, 0x1330, away, 0)  # TCM_SETCURFOCUS
        wait_until(cur, lambda v: v == away, 6)
        time.sleep(0.8)
    u.PostMessageW(tc, 0x1330, idx, 0)
    if wait_until(cur, lambda v: v == idx, 8) != idx:
        for _ in range(14):
            c = cur()
            if c == idx:
                break
            vk = 0x27 if c < idx else 0x25  # VK_RIGHT / VK_LEFT
            u.PostMessageW(tc, 0x0100, vk, 1)
            u.PostMessageW(tc, 0x0101, vk, 0xC0000001 - (1 << 32))
            time.sleep(0.5)
    time.sleep(1.5)
    return cur() == idx


def fo_controls(pid):
    """The division editor of the Fleet organization tab: its buttons (children of the panel of "New division") and
    lvDivisions (the TListView beside that panel). dict(btn={caption: hwnd}, lv, shown)."""
    f = fo_frm(pid)
    ks = children(f) if f else []
    nd = next((h for h in ks if e2e_test.class_name(h) == 'TButton' and caption(h) == 'New division'), None)
    btn, lv = {}, None
    if nd:
        bar = u.GetParent(nd)
        for h in ks:
            if e2e_test.class_name(h) == 'TButton' and u.GetParent(h) == bar and caption(h) in FO_BUTTONS:
                btn.setdefault(caption(h), h)
        pan = u.GetParent(bar)
        lv = next((h for h in ks if e2e_test.class_name(h) == 'TListView' and u.GetParent(h) == pan), None)
    return dict(btn=btn, lv=lv, shown=bool(nd and u.IsWindowVisible(nd)))


def fo_name_col(pid, lv):
    """The "Name" column of lvDivisions (column 0 is the +/- marker)."""
    cols = []
    with RemoteBuf(pid) as rb:
        for c in range(16):
            rb.write(128, bytes(480))
            rb.write(0, struct.pack('<IiiIiiiiiii', 0x4, 0, 0, rb.addr + 128, 200, 0, 0, 0, 0, 0, 0))  # LVCF_TEXT
            if not _u32.SendMessageW(lv, 0x105F, c, rb.addr):  # LVM_GETCOLUMNW
                break
            cols.append(rb.read(128, 400).decode('utf-16-le', 'replace').split('\x00')[0])
    return cols.index('Name') if 'Name' in cols else 1


def fo_list(pid):
    """lvDivisions as the player sees it (the tab selected): dict(divisions=[the division rows' names] (after Collapse
    all), rows=['name | role/class | size'] (after Expand all, the state it is left in)); None without the list."""
    if not fo_set_tab(pid, FO_TAB):
        return None
    d = fo_controls(pid)
    lv = d['lv']
    if not lv:
        return None
    nc = fo_name_col(pid, lv)
    co, ex = d['btn'].get('Collapse all'), d['btn'].get('Expand all')
    divs = None
    if co:
        u.PostMessageW(co, 0x00F5, 0, 0)  # BM_CLICK
        time.sleep(1.2)
        divs = [t[nc].strip() for _, _, t in lv_rows(pid, lv, nc + 1)]
    if ex:
        u.PostMessageW(ex, 0x00F5, 0, 0)
        time.sleep(1.2)
    return dict(divisions=divs, rows=[' | '.join(x.strip() for x in t[nc:nc + 3]) for _, _, t in lv_rows(pid, lv, nc + 3)])


def fo_set_text(h, s):
    b = ctypes.create_unicode_buffer(s)
    _u32.SendMessageW(h, 0x000C, 0, ctypes.addressof(b))  # WM_SETTEXT
    return text(h)


def fo_division_dialog(pid, dlg, name, abbr=None, typ=None):
    """Fill the game's TdlgCreateDivision (New division / Rename division): the type (CB_SETCURSEL and the parent's
    CBN_SELCHANGE, so cbTypeChange runs and proposes a name), the name (the upper edit) and abbreviation, OK. Returns
    dict(ok, ...) (Cancel when the dialog is not as expected)."""
    ks = children(dlg)
    edits = sorted((h for h in ks if e2e_test.class_name(h) == 'TEdit' and u.IsWindowVisible(h)), key=screen_top)
    combo = next((h for h in ks if e2e_test.class_name(h) == 'TComboBox'), None)
    b = dlg_buttons(dlg)
    items = combo_items(combo)[0] if combo else []
    out = dict(caption=caption(dlg), types=items, ok=False)
    if not edits or 'ok' not in b or (typ is not None and typ not in items):
        u.PostMessageW(b.get('cancel') or dlg, 0x00F5 if 'cancel' in b else 0x0010, 0, 0)
        wait_window(pid, 'TdlgCreateDivision', 5, gone=True)
        out['why'] = f'unexpected dialog: {len(edits)} edits, buttons {sorted(b)}'
        return out
    if typ is not None:
        _u32.SendMessageW(combo, 0x014E, items.index(typ), 0)  # CB_SETCURSEL
        u.PostMessageW(u.GetParent(combo), 0x0111, (1 << 16) | (u.GetDlgCtrlID(combo) & 0xFFFF), combo)  # CBN_SELCHANGE
        time.sleep(0.8)
    out['name'] = fo_set_text(edits[0], name)
    if abbr is not None and len(edits) > 1:
        out['abbr'] = fo_set_text(edits[1], abbr)
    time.sleep(0.4)
    u.PostMessageW(b['ok'], 0x00F5, 0, 0)
    out['ok'] = bool(wait_window(pid, 'TdlgCreateDivision', 6, gone=True))
    if not out['ok']:
        b = dlg_buttons(dlg)
        if 'cancel' in b:
            u.PostMessageW(b['cancel'], 0x00F5, 0, 0)
            wait_window(pid, 'TdlgCreateDivision', 4, gone=True)
    time.sleep(1.0)
    return out


def fo_new_division(pid, name, abbr, typ):
    """"New division" (BM_CLICK posted) -> the game's TdlgCreateDivision: type, name, abbreviation, OK."""
    nd = fo_controls(pid)['btn'].get('New division')
    if not (nd and u.IsWindowVisible(nd)):
        return dict(ok=False, why='"New division" not shown')
    u.PostMessageW(nd, 0x00F5, 0, 0)
    dlg = wait_window(pid, 'TdlgCreateDivision', 8)
    if not dlg:
        return dict(ok=False, why=f'no TdlgCreateDivision; windows {describe_windows(pid)}')
    return fo_division_dialog(pid, dlg, name, abbr, typ)


def fo_row(pid, lv, name):
    nc = fo_name_col(pid, lv)
    names = [t[nc].strip() if len(t) > nc else '' for _, _, t in lv_rows(pid, lv, nc + 1)]
    return names.index(name) if name in names else None


def fo_popup(pid, lv, row_name, label):
    """Pick `label` of the popup menu of lvDivisions's row `row_name`: only that row selected (the list is multi-select
    and the menu's actions take the first selected row; LVM_SETITEMSTATE on item -1 clears it), then popup_pick."""
    i = fo_row(pid, lv, row_name)
    if i is None:
        return f'no row {row_name!r}'
    with RemoteBuf(pid) as rb:
        rb.write(0, _lvitem(state=0, state_mask=0x3))
        _u32.SendMessageW(lv, LVM_SETITEMSTATE, 0xFFFFFFFF, rb.addr)
    time.sleep(0.2)
    lv_select(pid, lv, i)
    time.sleep(0.4)
    return popup_pick(pid, lv, label, f' on row {i} {row_name!r}')


def fo_lb_items(lb):
    out = []
    for i in range(max(0, min(u.SendMessageW(lb, 0x018B, 0, 0), 400))):  # LB_GETCOUNT
        b = ctypes.create_unicode_buffer(max(u.SendMessageW(lb, 0x018A, i, 0), 0) + 2)  # LB_GETTEXTLEN
        u.SendMessageW(lb, 0x0189, i, b)  # LB_GETTEXT
        out.append(b.value)
    return out


def fo_add_ships(pid, lv, div, n=2):
    """"Add ships to division" on the division's row -> the game's TdlgSelectShip (the player's ships of the division's
    type): the first n offered selected (LB_SETSEL in its multi-select list box, else LB_SETCURSEL; LBN_SELCHANGE to
    the dialog), OK. Returns dict(popup, items, picked)."""
    out = dict(popup=fo_popup(pid, lv, div, 'Add ships to division'), items=[], picked=[])
    if 'picked' not in out['popup']:
        return out
    dlg = wait_window(pid, 'TdlgSelectShip', 6)
    if not dlg:
        out['why'] = f'no TdlgSelectShip; windows {describe_windows(pid)}'
        return out
    lb = next((h for h in children(dlg) if e2e_test.class_name(h) == 'TListBox'), None)
    b = dlg_buttons(dlg)
    out['items'] = items = fo_lb_items(lb) if lb else []
    pick = list(range(min(n, len(items))))
    if not lb or not pick or 'ok' not in b:
        u.PostMessageW(b.get('cancel') or dlg, 0x00F5 if 'cancel' in b else 0x0010, 0, 0)
        wait_window(pid, 'TdlgSelectShip', 5, gone=True)
        return out
    if _u32w.GetWindowLongW(lb, -16) & 0x0808:  # LBS_MULTIPLESEL | LBS_EXTENDEDSEL
        for k in pick:
            u.SendMessageW(lb, 0x0185, 1, k)  # LB_SETSEL
    else:
        pick = pick[:1]
        u.SendMessageW(lb, 0x0186, pick[0], 0)  # LB_SETCURSEL
    u.PostMessageW(u.GetParent(lb), 0x0111, (1 << 16) | (u.GetDlgCtrlID(lb) & 0xFFFF), lb)  # LBN_SELCHANGE
    time.sleep(0.6)
    out['picked'] = [items[k] for k in pick]
    u.PostMessageW(b['ok'], 0x00F5, 0, 0)
    out['closed'] = bool(wait_window(pid, 'TdlgSelectShip', 6, gone=True))
    time.sleep(1.0)
    return out


def fo_rename(pid, lv, old, new):
    """"Rename division" on the division's row -> the game's TdlgCreateDivision: the name := new, OK."""
    r = fo_popup(pid, lv, old, 'Rename division')
    if 'picked' not in r:
        return dict(ok=False, popup=r)
    dlg = wait_window(pid, 'TdlgCreateDivision', 6)
    if not dlg:
        return dict(ok=False, popup=r, why=f'no TdlgCreateDivision; windows {describe_windows(pid)}')
    return fo_division_dialog(pid, dlg, new)


def fo_make(pid, who, specs, rename=None):
    """New divisions on one copy's Fleet organization through the game's own dialogs: per (name, abbreviation, type) a
    New division with the first two ships the game offers for it; rename: (old name, new name). Returns a record."""
    rec = dict(tab=fo_set_tab(pid, FO_TAB, refresh=True))
    lv = fo_controls(pid)['lv']
    if not lv:
        rec['error'] = 'lvDivisions not found'
        return rec
    for name, abbr, typ in specs:
        rec[name] = dict(new=fo_new_division(pid, name, abbr, typ))
        close_menus(pid)
        rec[name]['ships'] = fo_add_ships(pid, lv, name)
        close_menus(pid)
    if rename:
        rec['rename'] = fo_rename(pid, lv, *rename)
        close_menus(pid)
    drain(pid, 1, who)
    return rec


def division_lines(port, mark):
    """The mod log's campaign-division lines since mark (without the time and thread)."""
    return [ln.split('] ', 1)[-1] for ln in log_lines(log_since(port, mark), r'(?i)divisions')]


def scenario_divisions(ctx):
    """0.6.1: each joined player's own campaign divisions (the Fleet organization). The host and the client make two
    divisions each through the game's own dialogs (New division, Add ships to division, one Rename division on the
    client); then two processed months (the first with the Fleet organization shown on both copies: the list is filled
    again inside the load; the second on the map). a) the client's hello "campaign divisions 1", `divs` on both;
    b) the host's divisions never reach the client (`divs`, its Fleet organization list); c) the client's two (nation
    1's ships only); after each month d) the client keeps exactly its own two (`divs`, the Fleet organization list, slot
    77's .off), the host stored them (`divstore 1`, "divisions of nation 1: 2 stored" / "2 in its month", the client's
    "the month holds nation 1's own 2"), the host keeps exactly its own two (`divs`, its list, slot 1's .off and
    Autosave.off CampDivNo; no duplicates after its reload: "... from before the load dropped"); e) no exception, access
    violation, "Error in FillDivisionList2" or "Missing ship" in either log or box. The divisions stay for the later
    scenarios (the runner restores slot 1 after the run)."""
    K = 1
    m0h, m0c, t0 = log_mark(H), log_mark(C), time.time()
    hello = log_lines(log_since(H), r'campaign divisions \d')
    dh0, dc0 = parse_divs(cmd(H, 'divs')), parse_divs(cmd(C, 'divs'))
    check('a) host log: the client\'s hello with "campaign divisions 1"; `divs` answers on both copies (host nation 0, '
          f'client nation {K})', any(re.search(r'campaign divisions 1\b', x) for x in hello) and dh0 and dc0
          and dh0['nation'] == 0 and dc0['nation'] == K, f'{hello[-1:]}; {dh0 and dh0["raw"]}; {dc0 and dc0["raw"]}')
    if not (dh0 and dc0):
        return
    h_ids, k_ids = nation_ships(0), nation_ships(K)
    check(f'a) the client\'s divisions at the start are nation {K}\'s own (none with a ship of another nation): '
          f'{div_summary(dc0)}', all(set(d['ids']) <= k_ids for d in dc0['divs']), div_summary(dc0))

    # b) the host's own: two new divisions through its Fleet organization
    hrec = fo_make(ctx.hp, 'host', DIV_HOST)
    dh1 = parse_divs(cmd(H, 'divs'))
    hnew = [d for d in (dh1 or {}).get('divs', []) if d['name'] in {x[0] for x in DIV_HOST}]
    host_names = sorted(d['name'] for d in (dh1 or {}).get('divs', []))
    check('b) host: two new divisions made in its Fleet organization (New division, Add ships to division), each with '
          f'ships of the host nation only: `divs` {dh0["n"]} -> {dh1 and dh1["n"]} ({div_summary(dh1)})',
          dh1 and dh1['n'] == dh0['n'] + 2 and len(hnew) == 2 and all(d['ids'] and set(d['ids']) <= h_ids for d in hnew),
          hrec)
    dc1, fl = parse_divs(cmd(C, 'divs')), fo_list(ctx.cp)
    check('b) client: none of the host\'s divisions or ships, neither in `divs` nor in its Fleet organization list '
          f'({div_summary(dc1)}; list {fl and fl["divisions"]})',
          dc1 and fl and fl['divisions'] is not None and not set(host_names) & ({d['name'] for d in dc1['divs']}
                                                                             | set(fl['divisions']))
          and not any(set(d['ids']) & h_ids for d in dc1['divs']), f'{dc1 and dc1["raw"]}; {fl}')

    # c) the client's own two, one renamed
    crec = fo_make(ctx.cp, 'client', DIV_K, rename=(DIV_K[1][0], DIV_K_RENAMED))
    dc2 = parse_divs(cmd(C, 'divs'))
    k_names = sorted([DIV_K[0][0], DIV_K_RENAMED])
    knew = [d for d in (dc2 or {}).get('divs', []) if d['name'] in k_names]
    check(f'c) client: two new divisions with nation {K}\'s ships ("{DIV_K[1][0]}" renamed "{DIV_K_RENAMED}"): `divs` '
          f'{div_summary(dc2)}', dc2 and dc2['n'] == dc0['n'] + 2 and len(knew) == 2
          and all(d['ids'] and set(d['ids']) <= k_ids for d in knew), crec)
    if not (dh1 and dc2 and len(hnew) == 2 and len(knew) == 2):
        return
    want_k = {d['name']: sorted(d['ids']) for d in dc2['divs']}
    want_h = {d['name']: sorted(d['ids']) for d in dh1['divs']}
    k_all = sorted(want_k)

    # d) two processed months
    for m in (1, 2):
        if m == 2:
            for pid in (ctx.cp, ctx.hp):
                fo_set_tab(pid, 0)  # the map (the screen's default)
        hm, cm = log_mark(H), log_mark(C)
        t_m = time.time()
        run_month(ctx, f'divisions M{m}')
        where = 'the Fleet organization shown' if m == 1 else 'on the map'
        dc, dh, ds = parse_divs(cmd(C, 'divs')), parse_divs(cmd(H, 'divs')), parse_divs(cmd(H, f'divstore {K}'))
        got_k = {d['name']: sorted(d['ids']) for d in (dc or {}).get('divs', [])}
        got_h = {d['name']: sorted(d['ids']) for d in (dh or {}).get('divs', [])}
        got_s = {d['name']: sorted(d['ids']) for d in (ds or {}).get('divs', [])}
        check(f'd) M{m} ({where}): client `divs` = its own {len(want_k)} with the same ships, nation {K}, none twice '
              f'({div_summary(dc)})', dc and dc['nation'] == K and dc['n'] == len(want_k) and got_k == want_k,
              f'{dc and dc["raw"]}; want {want_k}')
        check(f'd) M{m}: host `divstore {K}` = the client\'s {len(want_k)} ({div_summary(ds)})',
              ds and ds['n'] == len(want_k) and got_s == want_k, f'{ds and ds["raw"]}; want {want_k}')
        check(f'd) M{m}: host `divs` = its own {len(want_h)}, none twice, none of nation {K}\'s ({div_summary(dh)})',
              dh and dh['nation'] == 0 and dh['n'] == len(want_h) and got_h == want_h,
              f'{dh and dh["raw"]}; want {want_h}')
        so, sa = slot_divisions(HOST_SLOT), slot_divisions(HOST_SLOT, 'Autosave.off')
        sa_new = os.path.exists(os.path.join(slot_dir(HOST_SLOT), 'Autosave.off')) and \
            os.path.getmtime(os.path.join(slot_dir(HOST_SLOT), 'Autosave.off')) >= t_m
        sk = slot_divisions(CLIENT_SLOT)
        check(f'd) M{m}: saved: slot {HOST_SLOT} .off CampDivNo {so and so["no"]} = {len(want_h)} (the host\'s; '
              f'Autosave.off {sa and sa["no"]}{"" if sa_new else " (not written this month)"}), slot {CLIENT_SLOT} .off '
              f'{sk and sk["no"]} = the client\'s {len(want_k)}',
              so and so['no'] == len(want_h) and sorted(x['name'] for x in so['divs']) == sorted(want_h)
              and (not sa_new or sa and sa['no'] == len(want_h)) and sk and sk['no'] == len(want_k)
              and sorted(x['name'] for x in sk['divs']) == k_all, f'{so}; {sa}; {sk}')
        hl, cl = division_lines(H, hm), division_lines(C, cm)
        need_h = [rf'divisions of nation {K}: {len(want_k)} stored \(repeats dropped: 0 divisions, 0 ship ids',
                  rf'divisions of nation {K}: {len(want_k)} in its month \(',
                  rf'campaign divisions: {len(want_h)} loaded$',
                  rf'campaign divisions: {len(want_h)} from before the load dropped; the campaign\'s {len(want_h)} kept']
        need_c = [rf"divisions: the month holds nation {K}'s own {len(want_k)} \(kept by the host; 0 with other ships\)",
                  rf'campaign divisions: {len(want_k)} of nation {K} loaded$',
                  rf'campaign divisions: {len(want_k)} from before the load dropped; the campaign\'s {len(want_k)} kept']
        if m == 1:
            need_c.append(r'campaign divisions: the Fleet organization list filled again')
        miss = [p for p in need_h if not any(re.search(p, x) for x in hl)] + \
            [p for p in need_c if not any(re.search(p, x) for x in cl)]
        check(f'd) M{m}: the logs: host "divisions of nation {K}: {len(want_k)} stored" / "... in its month", its reload '
              f'"{len(want_h)} loaded" and "{len(want_h)} from before the load dropped"; client "the month holds nation '
              f'{K}\'s own {len(want_k)}", "{len(want_k)} of nation {K} loaded", "... from before the load dropped"'
              + (', "the Fleet organization list filled again"' if m == 1 else ''), not miss,
              f'missing {miss}; host {hl[-8:]}; client {cl[-8:]}')
        fc, fh = fo_list(ctx.cp), fo_list(ctx.hp)
        check(f'd) M{m}: the Fleet organization lists: client {fc and fc["divisions"]} (its own only), host '
              f'{fh and fh["divisions"]} (its own only)',
              fc and fh and sorted(fc['divisions'] or []) == k_all and sorted(fh['divisions'] or []) == sorted(want_h),
              f'client {fc}; host {fh}')
    for pid in (ctx.cp, ctx.hp):
        fo_set_tab(pid, 0)

    # e) no errors
    bad = [(w, x[:200]) for w, port, mk in (('host', H, m0h), ('client', C, m0c))
           for x in log_since(port, mk).splitlines() if DIV_ERR_RE.search(x)]
    boxes = [(w, t[:200]) for ts, w, _, t in BOX_SEEN if ts >= t0 and re.search(r'Error in \w*Division|Missing ship', t)]
    check('e) no exception, access violation, "Error in FillDivisionList2" or "Missing ship" in either log, no such box '
          f'(the scenario\'s {time.time() - t0:.0f} s)', not bad and not boxes, f'{bad[:4]}; {boxes[:4]}')


# ---------------------------------------------------------------- live player-vs-player battles (lockstep)

K2 = 47703  # lockstep_pvp: the second joined player's bridge (a third game copy)
K2_SLOT = 76  # its slot (its battle slot K2_SLOT + 10); neither may exist before the run, both are deleted afterwards
K2_NAME = 'Bot'  # it joins as the stand-in player of `session`: the host gives it the reserved nation 2 back
HOST_NAME, CLIENT_NAME = 'Admiral', 'Captain'
PVP_AREA = 'Northern Europe'
LS_HASH_RE = re.compile(r'lockstep hash ([AB]) t=(\S+) min=(\d+) all=([0-9a-f]+) .*? rng=([0-9a-f]+)')
LS_IDENT_RE = re.compile(r'lockstep hash [AB] t=\S+ min=(\d+) all=[0-9a-f]+ .*? ident=([0-9a-f]+)')  # 0.3.3: compared
IDENT_LINE_RE = (r"lockstep: the simulation's ship identification as the battle save leaves it \(type (\d+), no class\); "
                 r"this PC's display had identified (\d+) ship\(s\) during the load and keeps that")  # 0.3.3, every load
LS_LOADED_RE = r'lockstep: battle loaded from slot \d+ '
IDENT_LOG = []  # 0.3.3: (scenario, what, minutes compared, minutes whose `ident=` differ) of ls_compare and ls_ready
LS_BAD_RE = (r'lockstep: (FATAL|exception)|lockstep hook \S+(: no target| failed)|lockstep hooks: INCOMPLETE|'
             r'exception handling|load of slot \d+ FAILED|could not be loaded again|The live battle failed')
LS_NOTE_RE = r'lockstep: WARNING|context frame .* dropped|FPU control word'
LS_LEAK_RE = r'lockstep: LEAK '  # `ls leakcheck 1`: the simulation state changed between two simulation steps
LS_TEST_EXC = 'e0545354'  # the exception code of `ls throw` (a test's own exception, not a failure)
LS_HOOKS_RE = r'lockstep hooks: (ok|INCOMPLETE)'
LS_EXCUSED = set()  # log lines a test provoked on purpose (the guard's negative control: its LEAK lines)
LEAKCHECK = {}  # port -> (pid, reply of `ls leakcheck 1`) for the copy now running on that port
LS_HOLD = 'lockstep: battle held at its start'
LS_CLOSE_RE = (r'battle slot: DoStrategicTurn skipped|AI suppressed: |DoEndOfTurn finished|live battle: leaving the battle '
               r'slot|LoadCampaign slot|battle \d+: (fought|finished)')  # a battle screen's close has begun
LS_GAME_END_RE = (r"lockstep: (minute|end) box '(No opposing ships|.*scenario is over|.*no ships left|Objective reached|"
                  r"Scenario absolute time limit|All ships belonging)")  # the game's own end of a battle
LS_OFF = (r'live battle ended \(|lockstep: start abandoned|lockstep: hold released|live battle with .* not started|'
          r'fought against the AI|lockstep: battle \d+ refused|The live battle could not start')
LS_MONTH_EXTRA = 1800  # s a month with live battles may take on top of MONTH_TIMEOUT (a battle: ~1.5 minutes per s)
LS_MODELESS = ('TdlgShowAirFormations', 'TdlgDivisionReport', 'TdlgForceOrders', 'TdlgSelectLead', 'TdlgTorpTargets',
               'TdlgStrike', 'TdlgMissileFire', 'TfrmTargets')  # the battle screen's modeless tool windows (0.3.2)
MEM_GROWTH_MAX = 25  # MB a copy's private memory may grow per live battle (average over the repeated battles)
OPTS = dict(stress=False)  # --stress: the long variants and the lockstep_stress scenario
K2PROC = [None]  # the third copy's Popen while lockstep_pvp runs
_ANS = [None]  # the dialog answerer thread of the live battles (LsAnswerer)
KEPT_LOGS = []  # logs of copies that were killed and started again (copied before the restart)
KEPT_LOG_RE = r'^rtw3mp_\d+\.(kill|hostkill|restart|k2restart|level|afterend|relay|vanilla|clean|twopc)\d+\.log$'  # (removed
# at the next run's start)
LS_MATRIX = []  # (case, checks passed, checks, seconds, note) of the lockstep scenarios' cases


def scmd(port, line, timeout=60):
    """cmd() that does not raise: a copy that is gone (killed) or does not answer gives 'error ...'."""
    try:
        return cmd(port, line, timeout)
    except OSError as e:
        return f'error {e!r}'


def sstatus(port):
    try:
        return ctl.status(port)
    except OSError:
        return {}


def kvs(reply):
    """'ok a=1 b=x' -> {'a': '1', 'b': 'x'} ({} for an error reply)."""
    return dict(x.split('=', 1) for x in reply[3:].split() if '=' in x) if reply.startswith('ok') else {}


def lss(port):
    """`ls status` of a copy (on, role, st, bid, epoch, side, boundary, running, left, peer, peerDone, resyncs, end,
    proposal, leave, ...)."""
    return kvs(scmd(port, 'ls status', 30))


def lsn(port):
    """`ls session` of a copy (enabled, available, role, hostOpp, hostBid, testSlotMode, leave, slotMode, players)."""
    return kvs(scmd(port, 'ls session', 30))


def pst(port):
    return kvs(scmd(port, 'pocstate', 30))


def ls_lines(port, mark, pattern):
    return [ln.split('] ', 1)[-1] for ln in log_lines(log_since(port, mark), pattern)]


def ls_wait(fn, timeout, what, step=0.5):
    """Poll fn() until it returns something true; RuntimeError after `timeout` s."""
    end, v = time.time() + timeout, None
    while time.time() < end:
        assert_alive()
        v = fn()
        if v:
            return v
        time.sleep(step)
    raise RuntimeError(f'timeout ({timeout} s): {what}; last {v}')


def k2_pid():
    p = K2PROC[0]
    return p.pid if p is not None and p.poll() is None else None


_NATION1 = [None]


def nation1():
    """The name of nation 1 (the client's), for `claim <name>` (a claim by index needs the lobby list of the client)."""
    if not _NATION1[0]:
        _NATION1[0] = nation_table(H).get(1, {}).get('name') or '1'
    return _NATION1[0]


def who_of(port):
    return {H: 'host', C: 'client', K2: 'k2'}[port]


def pid_of(ctx, port):
    return {H: ctx.hp, C: ctx.cp, K2: k2_pid()}[port]


def ls_leakcheck(ctx, ports):
    """`ls leakcheck 1` on these copies (a per-process switch: again after a copy was started again). Every live battle
    of the suite runs with it; `ls_log_scan` asserts that no `lockstep: LEAK` line was logged."""
    for p in ports:
        pid = pid_of(ctx, p)
        if pid and LEAKCHECK.get(p, (None,))[0] == pid and LEAKCHECK[p][1] == 'ok leakcheck=1':
            continue
        r = scmd(p, 'ls leakcheck 1')
        LEAKCHECK[p] = (pid, r)
        log(f'  leak check on the {who_of(p)} (PID {pid}): {r}')


class LsAnswerer(threading.Thread):
    """Answers the dialogs of the game copies in the background while live battles run (posted BM_CLICK and radio
    selections only): battle preview and map message Accept (unless the copy is in `hold`), results "Exit battle",
    the ended battle screen's "View results" (copies in `view_results`), the auto-run prompt "Yes" for copies in
    `autorun` (else "No"), the history InputQuery Cancel, Yes/OK boxes, picture messages OK, event dialogs with their
    first answer ("Not now" if offered, a nation picked if needed), "Select Officer" with the first officer, the turn
    report Close, forms with a "Not now" button. The battle screen's modeless tool windows (LS_MODELESS: air formations,
    division report, ...) are left alone while the battle screen is enabled. Paused while run_month answers with
    answer_dialogs."""

    def __init__(self):
        super().__init__(daemon=True)
        self.pids = {}
        self.paused = True
        self.stop = False
        self.autorun, self.view_results, self.hold = set(), set(), set()
        self.pressed = {}
        self.seen = []  # (time, who, 'Class:"title"->what')
        self.exit_t = {}  # who -> when "Exit battle" was last pressed on its results
        self.exit_mark = {}  # who -> its log size then (the battle screen's close shows in the log: LS_CLOSE_RE)
        self.probe = []  # (time, s after "Exit battle", who, screen enabled, "View results" shown, closing): no dialog up

    def press(self, who, top, h, what):
        if h is None or time.time() - self.pressed.get(top, 0) < 1.5:
            return False
        bt = dialog_text(top)  # before the click closes it
        u.PostMessageW(h, 0x00F5, 0, 0)  # BM_CLICK
        self.pressed[top] = time.time()
        e = f'{e2e_test.class_name(top)}:"{e2e_test.window_text(top)[:40]}"->{what}'
        self.seen.append((time.time(), who, e))
        ANSWERED.append((time.time(), who, e))
        if bt:
            BOX_SEEN.append((time.time(), who, e2e_test.class_name(top), bt))
        log(f'  {who} dialog: {e}' + (f' (text: {bt!r})' if bt else ''))
        return True

    def once(self, pid, who):
        tops = top_windows(pid)
        frm, pressed = None, False
        on = any(e2e_test.class_name(t) == 'TfrmMain' and u.IsWindowEnabled(t) for t in tops)
        for top in tops:
            k = e2e_test.class_name(top)
            if k == 'TfrmMain':
                frm = top
                continue
            if k.startswith('RTW3MP') or k in ('TfrmBuildCamp', '#32770'):
                continue
            if k in LS_MODELESS and (on or not u.IsWindowEnabled(top)):
                # the battle screen's tool windows (it stays enabled): not questions; disabled, another modal box (e.g.
                # the game's "You now have reconnaisance aircraft at your disposal!") is in front of both: not this one
                continue
            query = is_input_query(top)
            b = dlg_buttons(top)
            first = next(iter(b.values()), None)
            if not (k == 'TMessageForm' or k.startswith('Tdlg') or query):
                if 'not now' in b:  # e.g. a design ready for construction
                    pressed |= self.press(who, top, b['not now'], 'Not now')
                continue
            pressed = True  # a dialog is up: the battle screen is disabled behind it
            if query:
                self.press(who, top, b.get('cancel'), 'Cancel')
            elif k in ('TdlgBattlePreview', 'TdlgMapMessage'):
                if who not in self.hold:
                    self.press(who, top, b.get('accept') or first, 'Accept')
            elif k == 'TdlgResults':
                if self.press(who, top, b.get('exit battle') or b.get('view map') or first, 'Exit battle'):
                    self.exit_t[who] = time.time()
                    self.exit_mark[who] = log_mark({'host': H, 'client': C, 'k2': K2}[who])
            elif k == 'TdlgEventAnswer':
                radios = [caption(h) for h in children(top) if e2e_test.class_name(h) == 'TRadioButton'
                          and u.IsWindowVisible(h)]
                if 'Yes' in radios and 'No' in radios:  # the auto-run prompt
                    want = 'Yes' if who in self.autorun else 'No'
                    if select_radio(top, want):
                        self.press(who, top, b.get('ok'), f'OK [{want}]')
                else:
                    select_event_nation(pid)
                    self.press(who, top, b.get('ok') or first, 'OK')
            elif k == 'TdlgSelectOfficer':
                select_officer(pid)
                self.press(who, top, b.get('ok') or first, 'OK')
            elif k == 'TdlgPictureMessage':
                self.press(who, top, b.get('ok') or b.get('yes') or first, 'OK')
            elif k == 'TMessageForm':
                pick = 'yes' if 'yes' in b else 'ok' if 'ok' in b else None
                self.press(who, top, b.get(pick) if pick else first, pick or 'first')
            else:
                pick = next((p for p in ('ok', 'close', 'continue', 'yes', 'accept', 'not now') if p in b), None)
                self.press(who, top, b.get(pick) if pick else first, pick or 'first')
        if frm is None:
            self.exit_t.pop(who, None)
            self.exit_mark.pop(who, None)
            return
        btn = results_button(frm)
        since_exit = time.time() - self.exit_t.get(who, 0)
        port = {'host': H, 'client': C, 'k2': K2}.get(who)
        closing = who in self.exit_mark and bool(log_lines(log_since(port, self.exit_mark[who]), LS_CLOSE_RE))
        if since_exit < 30 and not pressed:  # the battle was left: is its screen still usable while the month runs?
            self.probe.append((time.time(), round(since_exit, 1), who, bool(u.IsWindowEnabled(frm)), bool(btn),
                               closing))
        # "View results" only as a player could press it: no dialog up, the screen enabled, and not while the screen is
        # closing after "Exit battle" (its close runs the rest of the month: a second press would run it again)
        if who in self.view_results and btn and not pressed and u.IsWindowEnabled(frm) and since_exit > 10 \
                and not closing:
            self.press(who, frm, btn, 'View results')

    def run(self):
        while not self.stop:
            if not self.paused:
                for pid, who in list(self.pids.items()):
                    try:
                        if pid:
                            self.once(pid, who)
                    except Exception as e:  # noqa: BLE001
                        log('  answerer:', repr(e))
            time.sleep(0.4)


def results_button(frm):
    """The ended battle screen's "View results" button (a TButton on TfrmMain), or None."""
    for h in children(frm):
        if e2e_test.class_name(h) == 'TButton' and u.IsWindowVisible(h) and u.IsWindowEnabled(h) \
                and 'result' in caption(h).lower():
            return h
    return None


def ls_ans(ctx):
    """The answerer thread (started once), its copies updated (a copy started again has a new PID)."""
    a = _ANS[0]
    if a is None:
        a = _ANS[0] = LsAnswerer()
        a.start()
    a.pids = {ctx.hp: 'host', ctx.cp: 'client'}
    if k2_pid():
        a.pids[k2_pid()] = 'k2'
    return a


def ls_quiet(ctx):
    """Pause the answerer (run_month and the other scenarios answer the dialogs themselves)."""
    a = ls_ans(ctx)
    a.paused = True
    a.view_results.clear()
    a.autorun.clear()
    a.hold.clear()
    time.sleep(0.8)
    return a


def ls_answered(ans, who, since, what):
    return [e for t, w, e in ans.seen if t >= since and w == who and what in e]


MONTHS = 'Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec'.split()


def month_after(d):
    """'Aug 1900' -> 'Sep 1900' (None if d is not such a date)."""
    try:
        m, y = d.split()
        i = MONTHS.index(m[:3])
        return f'{MONTHS[(i + 1) % 12]} {int(y) + (i == 11)}'
    except (ValueError, AttributeError):
        return None


def ls_both_running(A, B):
    a, b = lss(A), lss(B)
    return (a, b) if a.get('st') == 'running' and b.get('st') == 'running' and a.get('bid') == b.get('bid') else None


def ls_idle_equal(A, B):
    """Both copies between minutes at the same boundary, A's clock stopped, B's report of it in."""
    a, b = lss(A), lss(B)
    if a.get('st') == b.get('st') == 'running' and a.get('running') == b.get('running') == '0' and \
            a.get('left') == '0' and a.get('boundary') == b.get('boundary') and a.get('peerDone') == a.get('boundary'):
        return a, b
    return None


def ls_over(A):
    return lss(A).get('on') != '1'


def ls_run(A, B, n, frm, timeout=None):
    """`ls run n` asked by one copy; waits until both are idle at the same boundary (or A's live battle is over).
    Returns the minutes advanced."""
    a0 = int(lss(A).get('boundary') or 0)
    scmd(frm, f'ls run {n}')
    time.sleep(1.0)
    ls_wait(lambda: ls_idle_equal(A, B) or ls_over(A), timeout or 60 + 20 * min(n, 50), f'ls run {n}')
    return int(lss(A).get('boundary') or 0) - a0


def ls_run_total(A, B, n, frm):
    """n minutes in all (a break stops a run: run again)."""
    done = 0
    for _ in range(n + 5):
        if done >= n or ls_over(A):
            break
        done += max(0, ls_run(A, B, n - done, frm))
    return done


def ls_hashes(port, mark):
    out = {}
    for m in LS_HASH_RE.finditer(log_since(port, mark)):
        out.setdefault(int(m[3]), []).append((m[4], m[5]))
    return out


def ls_idents(port, mark):
    """{minute: [ident]} of a copy's per-minute hash lines since the mark (`ident=`: the simulation's identification)."""
    out = {}
    for m in LS_IDENT_RE.finditer(log_since(port, mark)):
        out.setdefault(int(m[1]), []).append(m[2])
    return out


def ls_compare(A, ma, B, mb, label=''):
    """Per-minute state hashes (`lockstep hash A|B ... min=<m> all=<state> ... rng=<rng>`) of both copies since the
    marks: every minute both logged must be equal (the last line of a minute: a resync loads a minute again). The
    minutes whose `ident=` (the simulation's ship identification, not part of `all`) differ are returned too and
    recorded for ls_log_scan's identification check (0.3.3: equal; up to 0.3.2 they differed in every minute)."""
    a, b = ls_hashes(A, ma), ls_hashes(B, mb)
    both = sorted(set(a) & set(b))
    differ = [m for m in both if a[m][-1] != b[m][-1]]
    ia, ib = ls_idents(A, ma), ls_idents(B, mb)
    idiff = [m for m in both if (ia.get(m) or [None])[-1] != (ib.get(m) or [None])[-1]]
    IDENT_LOG.append((_scenario[0], label, len(both), idiff))
    res = dict(minutes=len(both), first=both[0] if both else None, last=both[-1] if both else None, differ=differ,
               ident_differ=idiff)
    log(f'  hashes {label}: {len(both)} minutes compared ({res["first"]}..{res["last"]}), differ {differ[:8]}, ident= '
        f'differs {idiff[:8]}')
    return res


def ls_ready(A, B, tag):
    """0.3.3: right after a live load (the start or a resync, before any minute ran) `ls hash` on both copies: `all` and
    the simulation's identification `ident=` equal (up to 0.3.2 each copy kept the identification its own display drew
    during the load). Recorded for ls_log_scan's identification check; returns the two replies (None if the copies were
    not idle at the same boundary within 30 s)."""
    try:
        ls_wait(lambda: ls_idle_equal(A, B), 30, f'{tag}: both idle at the boundary of the load')
    except RuntimeError as e:
        log(f'  !! {tag}: the READY hash is not compared: {e}')
        return None
    ha, hb = kvs(scmd(A, 'ls hash')), kvs(scmd(B, 'ls hash'))
    if not ha.get('min') or ha.get('min') != hb.get('min'):
        log(f'  !! {tag}: the READY hash is not compared: minute {ha.get("min")} / {hb.get("min")}')
        return None
    bad = [f'READY {k}' for k in ('ident', 'all') if not ha.get(k) or ha.get(k) != hb.get(k)]
    IDENT_LOG.append((_scenario[0], f'{tag} READY', 1, bad))
    log(f'  {tag}: READY (`ls hash` at minute {ha.get("min")}): all {ha.get("all")}/{hb.get("all")}, ident '
        f'{ha.get("ident")}/{hb.get("ident")}' + (f' DIFFER: {bad}' if bad else ''))
    return ha, hb


def ident_loads(port, mark):
    """0.3.3: a copy's live loads since the mark ("battle loaded from slot") and how many of them logged the simulation's
    identification line right before: dict(loads, with_line, types, shown: ships its display had identified)."""
    return ident_loads_text(log_since(port, mark))


def ident_loads_text(text):
    """ident_loads over a log text (a run of a copy that was killed and started again: ll_scan_text)."""
    loads, good, types, shown, pending = 0, 0, set(), [], 0
    for x in log_lines(text, f'{IDENT_LINE_RE}|{LS_LOADED_RE}'):
        m = re.search(IDENT_LINE_RE, x)
        if m:
            pending += 1
            types.add(m[1])
            shown.append(int(m[2]))
            continue
        loads += 1
        good += pending == 1
        pending = 0
    return dict(loads=loads, with_line=good, types=sorted(types), shown=shown[:12])


def ident_scan_checks(label, idl):
    """The scans' two identification checks (ls_log_scan, ll_scan_text): every live load of each copy (or run of a copy:
    idl = {key: ident_loads}) logged the simulation's identification line right before it, and `ident=` was equal on
    both copies at READY (ls_ready) and in every comparison this scenario recorded (IDENT_LOG: ls_compare, the whole
    battles of lockstep_ui g), lockstep_air k) and lockstep_limits k)); the scenario's entries are used up."""
    check(f'{label}: 0.3.3 every live load (the start, each resync, each rejoin) logged the simulation\'s identification '
          f'on each copy right before "battle loaded from slot": "the simulation\'s ship identification as the battle '
          f'save leaves it (type 22, no class); this PC\'s display had identified <n> ship(s) during the load and keeps '
          f'that"', all(v['loads'] == v['with_line'] and v['types'] in ([], ['22']) for v in idl.values()), idl)
    mine = [e for e in IDENT_LOG if e[0] == _scenario[0]]
    IDENT_LOG[:] = [e for e in IDENT_LOG if e[0] != _scenario[0]]
    ready = [e for e in mine if e[1].endswith(' READY')]
    minutes = sum(e[2] for e in mine if e not in ready)
    diff = [(e[1], e[3][:6]) for e in mine if e[3]]
    return check(f'{label}: 0.3.3 the simulation\'s identification (`ident=`, not part of `all`) equal on both copies at '
                 f'READY (`ls hash` right after {len(ready)} load(s)) and in every per-minute hash compared ({minutes} '
                 f'minutes in {len(mine) - len(ready)} comparisons; up to 0.3.2 it differed in every minute)', not diff,
                 diff[:6])


def expected_ctx_hooks():
    """The live-battle context hooks of this source tree (the entries of g_ctx[] in src/mod/lockstep.cpp, read only):
    every copy logs `lockstep hooks: ok (N of N context hooks, ...)` (0.3.3: 19, TdlgDivisionReport.FillShipList new)."""
    try:
        with open(os.path.join(REPO, 'src', 'mod', 'lockstep.cpp'), encoding='utf-8') as f:
            m = re.search(r'static CtxHook g_ctx\[\] = \{(.*?)\n\};', f.read(), re.S)
    except OSError:
        return None
    return len(re.findall(r'\{(?:nullptr|"\w+"), "\w+", K_\w+, (?:0x[0-9a-fA-F]+|\d+)\}', m[1])) if m else None


def ls_divs(port):
    out = []
    for e in scmd(port, 'ls divs')[3:].split(';'):
        p = e.strip().split(':')
        if len(p) >= 5 and p[0].isdigit():
            cs = p[3].split('/')
            try:
                out.append(dict(i=int(p[0]), side=int(p[1]), name=p[2], course=int(cs[0]), speed=int(cs[1]),
                                ships=int(p[4]), ai=len(p) > 5 and p[5] == 'ai'))
            except ValueError:
                pass
    return out


def ls_pick_div(port, side, min_ships=1):
    ds = [d for d in ls_divs(port) if d['side'] == side and d['ships'] >= min_ships]
    return next((d for d in ds if not d['ai']), ds[0] if ds else None)


def ls_all_ai(A, B):
    """Every division of each side to the game's AI, ordered by its own copy (`ls order i -1 -1 1`, an order batch):
    the AI seeks contact, so the battle has damage. Returns the number of orders."""
    n = 0
    for port, side in ((A, 0), (B, 1)):
        for d in ls_divs(port):
            if d['side'] == side and not d['ai'] and scmd(port, f'ls order {d["i"]} -1 -1 1') == 'ok':
                n += 1
    return n


def ls_end_both(A, B):
    """Both players ask for the end (`ls end` toggles a player's request: only the missing ones are sent)."""
    e = (lss(A).get('end') or '0/0').split('/')
    if e[0] != '1':
        scmd(A, 'ls end')
    if len(e) < 2 or e[1] != '1':
        scmd(B, 'ls end')


def ls_end_reset(A, B):
    """Withdraw end requests that are still pending (after a test of odd moments)."""
    for _ in range(3):
        e = (lss(A).get('end') or '0/0').split('/')
        if e == ['0', '0'] or lss(A).get('on') != '1':
            return e
        if e[0] == '1':
            scmd(A, 'ls end')
        if len(e) > 1 and e[1] == '1':
            scmd(B, 'ls end')
        time.sleep(1.5)
    return (lss(A).get('end') or '?').split('/')


def ls_drive_end(A, B, mode='agree', min_end=410, cap=900, chunk=60):
    """Drive a running live battle to its end at speed 5 in runs of `chunk` minutes asked alternately by A and B.
    'agree': from minute `min_end` both press End (the game refuses before 400 minutes / half the battle / with enemies
    near: 30 more minutes, then again). 'game': the game's own end; when the game proposes one (proposal=1, "far apart
    ... end the scenario?") both press End; the agreed end only from minute `cap`. Returns dict(minute, seconds,
    tries, refusals, proposals)."""
    t0, res, turn, last = time.time(), dict(tries=0, refusals=0, proposals=0), 0, {}
    scmd(A, 'ls speed 5')
    while True:
        a = lss(A)
        if a.get('on') != '1':
            break
        last = a
        if a.get('st') != 'running':
            time.sleep(1)
            continue
        m, prop = int(a.get('boundary') or 0), a.get('proposal') == '1'
        if mode == 'agree' and m < min_end:
            prop = False  # 'agree' plays on to the long agreed end; the game's proposal is the 'game' mode's end
        if prop or (mode == 'agree' and m >= min_end) or m >= cap:
            res['tries'] += 1
            res['proposals'] += int(prop)
            if res['tries'] > 20:
                raise RuntimeError(f'the battle did not end after {res["tries"]} agreed end requests')
            mk = log_mark(A)
            ls_end_both(A, B)
            ls_wait(lambda: ls_over(A) or ls_lines(A, mk, r"can't end yet"), 150, 'the agreed end')
            if not ls_over(A):
                res['refusals'] += 1
                ls_run_total(A, B, 30, A)  # 30 battle minutes, also when breaks stop each run after a minute
            continue
        ls_run(A, B, chunk, A if turn % 2 == 0 else B, timeout=480)
        turn += 1
        if time.time() - t0 > LS_MONTH_EXTRA - 120:
            raise RuntimeError(f'the battle did not end within {LS_MONTH_EXTRA - 120} s (minute {m})')
    res.update(minute=int(last.get('boundary') or 0), seconds=round(time.time() - t0, 1))
    log(f'  battle over at minute {res["minute"]} after {res["seconds"]} s ({mode}; {res["tries"]} end requests, '
        f'{res["refusals"]} refused, {res["proposals"]} proposed by the game)')
    return res


def ls_drive_endsoon(A, B, until=6):
    """'endsoon': the game itself ends the live battle INSIDE a minute (the path of 0.3.0's deferred close). From
    minute `until` (run there first) A sends `ls endsoon` (both copies shorten the scenario at the next released minute,
    so the game's own "Scenario absolute time limit is reached!" ends the battle inside it) and runs one minute; the
    answerer presses "Exit battle" in both results. Returns dict(minute, seconds, endsoon, endsoon_at, tries=0, ...)."""
    t0, res = time.time(), dict(tries=0, refusals=0, proposals=0, endsoon=None, endsoon_at=None)
    # (`ls endsoon` sets the length to max(1, m/2 - 1), so the game's limit, length + min(length, 600), is minute 2 at the
    # earliest: given at boundary 0 or 1 the battle ran on past "the end of minute m+1" and the wait timed out: dist_vp_2)
    until = max(until, 2)
    scmd(A, 'ls speed 5')
    m = int(lss(A).get('boundary') or 0)
    if m < until:
        ls_run_total(A, B, until - m, A)
    if not ls_over(A):
        ls_wait(lambda: ls_idle_equal(A, B), 60, 'both idle at a boundary before `ls endsoon`')
        res['endsoon_at'] = int(lss(A).get('boundary') or 0)
        res['endsoon'] = scmd(A, 'ls endsoon')
        scmd(A, 'ls run 1')
        ls_wait(lambda: ls_over(A), 240, 'the game ends the battle inside the next minute')
    res.update(minute=int(lss(A).get('boundary') or 0), seconds=round(time.time() - t0, 1), t_end=time.time())
    log(f'  battle over at minute {res["minute"]} after {res["seconds"]} s (`ls endsoon` at minute {res["endsoon_at"]}: '
        f'{res["endsoon"]})')
    return res


def ls_back(port, pid, slot, nation):
    """A joined player's copy back in its own slot as its nation: no live battle, no battle window, battle slot mode
    off. Returns its status or None."""
    st = sstatus(port)
    if st.get('slot') == str(slot) and st.get('playerIdx') == str(nation) and lss(port).get('on') == '0' \
            and lsn(port).get('slotMode') == '0' and not battle_up(pid):
        return st
    return None


def ls_client_back(ctx):
    return ls_back(C, ctx.cp, CLIENT_SLOT, 1)


def host_settled(ctx, tag, timeout=45):
    """Before a test battle (`pocbattle`) from the host's strategic screen (e.g. right after a processed month): wait
    until the host has settled: no game dialog or box up (the answerer, unpaused, answers them; their texts are
    logged), the strategic screen enabled, `status` not busy and planning, twice 1 s apart. Not when a battle screen
    is up (test battles follow each other there). Returns the seconds waited (None if it never settled)."""
    if battle_up(ctx.hp):
        return 0
    t0, ok_once, seen = time.time(), False, {}
    while time.time() - t0 < timeout:
        assert_alive()
        dlg = [t for t in top_windows(ctx.hp) if e2e_test.class_name(t) in ('TMessageForm', '#32770')
               or e2e_test.class_name(t).startswith('Tdlg')]
        for t in dlg:
            if t not in seen:
                seen[t] = f'{e2e_test.class_name(t)}:"{e2e_test.window_text(t)[:40]}"' + \
                    (f' (text: {box_text(t)[:200]!r})' if e2e_test.class_name(t) == 'TMessageForm' else '')
        st = sstatus(H)
        ok = not dlg and strategic_enabled(ctx.hp) and st.get('busy') == '0' and st.get('phase') == 'planning'
        if ok and ok_once:
            dt = time.time() - t0
            if seen or dt > 2.5:
                log(f'  {tag}: the host settled after {dt:.1f} s before the test battle; up meanwhile: '
                    f'{list(seen.values())}')
            return dt
        ok_once = ok
        time.sleep(1)
    log(f'  !! {tag}: the host did not settle within {timeout} s before the test battle: {list(seen.values())}; '
        f'windows {describe_windows(ctx.hp)}; status busy={sstatus(H).get("busy")} phase={sstatus(H).get("phase")}')
    return None


def ls_start_test(ctx, tag, timeout=150):
    """The host's battle against nation 1 outside a month: `pocbattle 1 0` (the debug Test battle = the game's DoBattle;
    the answerer accepts its preview; battle slot mode, so its close runs no month). Waits until both copies run it in
    lockstep (first, from the strategic screen, until the host has settled: host_settled). Reports slot 1's [General]
    date before the battle and in the battle's save, and the client's battle slot copy of it; compares both copies'
    `ls hash` at the start (ls_ready, 0.3.3). Returns dict(hm, cm, t0, dt, a, b, gen0, gen1, ready)."""
    ans = ls_ans(ctx)
    ans.paused = False
    ls_wait(lambda: ls_client_back(ctx), 120, 'the client idle in slot 77 before a new battle')
    host_settled(ctx, f'battle {tag}')
    d0 = gen_date(HOST_SLOT)
    hm, cm, t0 = log_mark(H), log_mark(C), time.time()
    r = cmd(H, 'pocbattle 1 0')

    def started():  # both running, or the game's DoBattle gave no battle (e.g. "Enemy unable to challenge our forces")
        return ls_both_running(H, C) or ('none' if re.search(r'pocbattle: DoBattle returned 0 after \d+ ms; battle '
                                                             r'screen closed', log_since(H, hm)) else None)
    res = ls_wait(started, timeout, f'battle {tag} running on both')
    if res == 'none':
        box = [t for ts, w, k, t in BOX_SEEN if ts >= t0 and w == 'host'][-1:]
        raise RuntimeError(f'battle {tag}: the game\'s DoBattle gave no battle ({box}): the earlier test battles\' results '
                           f'stay in the host\'s campaign in memory (TESTING.md, Known traps: the 0.6.0 release '
                           f'candidate); run the scenario again')
    a, b = res
    dt = time.time() - t0
    d1 = gen_date(HOST_SLOT)
    log(f'  battle {tag}: running on both after {dt:.1f} s ({r}); bid {a.get("bid")} epoch {a.get("epoch")}; '
        f'[General] slot 1 before {d0}, battle save {d1}, client slot {BATTLE_SLOT} '
        f'{gen_date(BATTLE_SLOT)}, slot {CLIENT_SLOT} {gen_date(CLIENT_SLOT)}')
    ready = ls_ready(H, C, f'battle {tag}')
    return dict(hm=hm, cm=cm, t0=t0, dt=dt, a=a, b=b, gen0=d0, gen1=d1, ready=ready)


LOADING_STUCK = []  # the game's progress box TdlgLoading still visible during a battle screen's auto-run: evidence


def loading_box_evidence(who, pid, port, lb, secs):
    """Evidence of the game's progress box `TdlgLoading` (shown during every battle load, hidden within a second) still
    visible `secs` seconds into a battle screen's auto-run step: its caption, place, owner and state, whether the
    battle screen under it is enabled (a player could still use it), the copy's windows, its `ls status` and its last
    battle-load lines."""
    frm = next((h for h in top_windows(pid) if e2e_test.class_name(h) == 'TfrmMain'), None)
    r = _RECT()
    u.GetWindowRect(lb, ctypes.byref(r))
    owner = u.GetWindow(lb, 4)  # GW_OWNER
    ev = dict(who=who, t=time.strftime('%H:%M:%S'), secs=round(secs), caption=e2e_test.window_text(lb)[:60],
              enabled=bool(u.IsWindowEnabled(lb)), rect=(r.left, r.top, r.right - r.left, r.bottom - r.top),
              owner=e2e_test.class_name(owner) if owner else None, screen_enabled=bool(frm and u.IsWindowEnabled(frm)),
              windows=describe_windows(pid)[:300])
    if port is not None:
        ev['ls'] = {k: v for k, v in lss(port).items() if k in ('on', 'st', 'bid', 'epoch', 'boundary', 'running')}
        txt = log_since(port, max(0, log_mark(port) - 400000))
        ev['loads'] = [x.split('] ', 1)[-1][:120] for x in log_lines(
            txt, r'battle loaded from slot|live battle \d+ (started|ended)|lockstep: battle \d+ epoch \d+ (running|sent)|'
                 r'DoBattle\(opponent')][-5:]
    return ev


def autorun_click(ctx, st, who, pid, frm, port=None):
    """One step of fighting a (not live) battle screen on auto-run: its "Auto run" button (a posted click on the tool
    bar; the answerer says "Yes" to the prompt), up to 3 tries 8 s apart, then the POC fallback (both sides AI, speed 5,
    run) when the copy's bridge may be used (port); later a stalled run is restarted (pocrun 100000). The game's progress
    box TdlgLoading still visible after 15 s is logged with its evidence (LOADING_STUCK, once per battle screen) and no
    longer waited for (2026-10-18: once on dist_vp_2 it stayed up after a live battle's start)."""
    ans = ls_ans(ctx)
    ans.autorun.add(who)
    ans.view_results.add(who)
    tops = top_windows(pid)
    now = time.time()
    lb = next((w for w in tops if e2e_test.class_name(w) == 'TdlgLoading'), None)
    if lb is None:
        st.pop('loading_since', None)
    else:
        secs = now - st.setdefault('loading_since', now)
        if secs > 15:
            if not st.get('loading_logged'):
                st['loading_logged'] = True
                ev = loading_box_evidence(who, pid, port, lb, secs)
                LOADING_STUCK.append(ev)
                log(f'  NOTE {who}: the game\'s progress box TdlgLoading is still visible {secs:.0f} s into the battle '
                    f'screen\'s auto-run step (no longer waited for): {ev}')
            tops = [w for w in tops if w != lb]
    if any(e2e_test.class_name(w) == 'TMessageForm' or e2e_test.class_name(w).startswith('Tdlg') for w in tops) \
            or results_button(frm):
        return
    if ls_answered(ans, who, st.setdefault('since', now), 'OK [Yes]') or st.get('poc'):
        if port is not None and now - st.get('t_state', 0) > 20:
            st['t_state'] = now
            ps = pst(port)
            stalled = ps.get('running') == '0' and ps.get('moving') == '0' and ps.get('finished') == '1' \
                and ps.get('endgame') == '0'
            if stalled and st.get('stalled'):
                log(f'  {who} battle stalled at a boundary: pocrun 100000', scmd(port, 'pocrun 100000'))
            st['stalled'] = stalled
        return
    if st.get('clicks', 0) < 3 and now - st.get('t', 0) > 8:
        if click_autorun(frm):
            st['clicks'] = st.get('clicks', 0) + 1
            st['t'] = now
            log(f'  {who} battle screen: auto-run button clicked (posted)')
    elif st.get('clicks', 0) >= 3 and port is not None and now - st.get('t', 0) > 12:
        st['poc'] = True
        for line in ('pocsideai 0 1 0', 'pocsideai 1 1 0', 'pocspeed 5', 'pocrun 100000'):
            log(f'  {who} {line}:', scmd(port, line)[:80])


def ls_finish_host(ctx, timeout=600):
    """The host's open battle screen (no longer live) fought to its end on auto-run and closed (results "Exit
    battle"). Outside a month the battle slot mode then ends (no month runs). Returns True when it is closed."""
    ans = ls_ans(ctx)
    ans.paused = False
    close_modeless(ctx.hp)  # (a dialog left open by a test, e.g. a division report, blocks the battle screen's buttons)
    st, t0, gone = {}, time.time(), None
    while time.time() - t0 < timeout:
        assert_alive()
        if not battle_up(ctx.hp):  # closed for 3 s (the screen hides for a moment between its result dialogs)
            gone = gone or time.time()
            if time.time() - gone >= 3:
                break
            time.sleep(0.5)
            continue
        gone = None
        frm = next((h for h in top_windows(ctx.hp) if e2e_test.class_name(h) == 'TfrmMain'), None)
        if frm is not None and lss(H).get('on') != '1':
            autorun_click(ctx, st, 'host', ctx.hp, frm, H)
        time.sleep(1)
    ans.autorun.discard('host')
    ans.view_results.discard('host')
    closed = not battle_up(ctx.hp)
    log(f'  the host\'s battle {"closed" if closed else "NOT closed"} after {time.time() - t0:.0f} s')
    return closed


def ls_rejoin(ctx, fight=True):
    """The client leaves (if joined) and joins again as Captain with `fightbattles`; the host should give the
    returning player nation 1 back and send the month. If it does not within 25 s, `claim 1`. Returns (status, host
    line, client line, claimed)."""
    if sstatus(C).get('role') == 'client':
        scmd(C, 'leave')
        ls_wait(lambda: 'Captain(' not in lsn(H).get('players', 'Captain('), 20, 'the host saw the client leave')
    hm, cm = log_mark(H), log_mark(C)
    scmd(C, f'fightbattles {1 if fight else 0}')
    r = cmd(C, f'join {CLIENT_NAME} 127.0.0.1 {NET_PROXY.get(C, MP_PORT)}')
    hpat, cpat = r'state seq \d+ -> Captain \(nation 1,', rf'LoadCampaign slot {CLIENT_SLOT} player 1 -> ok'
    sent, claimed = wait_log(H, hm, hpat, 25), False
    if not sent:
        claimed = True
        log(f'  the host did not give nation 1 back: claim {nation1()} ->', cmd(C, f'claim {nation1()}'))
        sent = wait_log(H, hm, hpat, 60)
    loaded = wait_log(C, cm, cpat, 60)
    st = wait(C, lambda s: s.get('phase') == 'planning' and s.get('myNation') == '1' and s.get('playerIdx') == '1'
              and s.get('slot') == str(CLIENT_SLOT), 60, 'the client plans nation 1 again')
    log(f'  rejoined with fightbattles {1 if fight else 0}: join {r}; {sent[:1]} {loaded[:1]}'
        + (' (claimed)' if claimed else ''))
    time.sleep(2)
    cmd(C, 'mpwindow')
    time.sleep(1)
    return st, sent, loaded, claimed


def ls_ensure_session(ctx):
    """The client is in the session as Captain, plans nation 1 in slot 77, fights battles and plays them live (after
    `battles` it fights none, after `player_copy` it left the session): otherwise it joins again."""
    st, hs = sstatus(C), lsn(H)
    nation1()
    ls_leakcheck(ctx, (H, C))
    if st.get('role') == 'client' and st.get('myNation') == '1' and st.get('slot') == str(CLIENT_SLOT) \
            and st.get('phase') == 'planning' and 'Captain(1,b,ls)' in hs.get('players', ''):
        return True
    log(f'  the client joins again for live battles (role {st.get("role")}, nation {st.get("myNation")}, slot '
        f'{st.get("slot")}; host players {hs.get("players")})')
    if lsn(C).get('enabled') != '1':
        scmd(C, 'ls enable 1')
    st, sent, loaded, _ = ls_rejoin(ctx, fight=True)
    return bool(sent and loaded)


def turn_button(pid):
    """(caption, visible, enabled) of the strategic screen's Turn/Submit button, or None."""
    for w in top_windows(pid):
        if e2e_test.class_name(w) == 'TfrmBuildCamp':
            for h in children(w):
                if e2e_test.class_name(h) in ('TButton', 'TBitBtn') and caption(h) in ('Turn', 'Submit'):
                    return caption(h), bool(u.IsWindowVisible(h)), bool(u.IsWindowEnabled(h))
    return None


def ls_after_checks(ctx, label):
    """j) after a live-battle case: no RTW3.exe but this run's copies, the client plans nation 1 in slot 77 (no live
    battle, battle slot mode off, no battle window, strategic screen enabled), the host's live battle and battle slot
    mode are off, slot 1's save readable as the host's month, and the host's month = the client's (a live battle's
    load moves the host's campaign date to the battle's own, sometimes into the next month: MODLOG, Testing
    2026-10-17). Reports both saves' [General] dates."""
    try:
        ls_wait(lambda: not battle_up(ctx.cp) and not battle_up(ctx.hp) and lss(H).get('on') == '0'
                and lsn(H).get('slotMode') == '0', 30, 'no battle left', step=1)
    except RuntimeError as e:
        log('  !!', e)
    mine = sorted(p.pid for p in PROCS if p.poll() is None)
    running = sorted(running_pids('RTW3.exe'))
    st, hst, cs, hn, cl = sstatus(C), sstatus(H), cstate(), lsn(H), lss(C)
    g = (read_save(save_path(HOST_SLOT)) or {}).get('General') or {}
    c77 = (read_save(save_path(CLIENT_SLOT)) or {}).get('General') or {}

    def as_date(gen):
        try:
            return f'{MONTHS[int(gen.get("Month")) - 1]} {gen.get("Year")}'
        except (TypeError, ValueError, IndexError):
            return None

    ok = running == mine and st.get('slot') == str(CLIENT_SLOT) and st.get('playerIdx') == '1' \
        and st.get('phase') == 'planning' and cs.get('slotMode') is False and cl.get('on') == '0' \
        and not battle_up(ctx.cp) and strategic_enabled(ctx.cp) and lss(H).get('on') == '0' \
        and hn.get('slotMode') == '0' and hn.get('hostOpp') == '-1' and not battle_up(ctx.hp) \
        and hst.get('slot') == str(HOST_SLOT) and hst.get('playerIdx') == '0' and as_date(g) == hst.get('date') \
        and as_date(c77) == st.get('date') and hst.get('date') == st.get('date')
    return check(f'{label}: j) no RTW3.exe left but this run\'s copies; the client plans nation 1 in slot 77 (no live '
                 f'battle, battle slot mode off, no battle window, strategic screen enabled; its slot 77 save readable '
                 f'and of its month); the host: no live battle, battle slot mode off, no battle window, slot 1 open and '
                 f'its save readable and of the host\'s month; host and client in the same month', ok,
                 f'RTW3.exe {running} (ours {mine}); client {st.get("slot")}/{st.get("playerIdx")}/{st.get("phase")} '
                 f'{st.get("date")} save77 {as_date(c77)} {cs.get("raw")} ls on={cl.get("on")} enabled='
                 f'{strategic_enabled(ctx.cp)}; host {hn} slot {hst.get("slot")} {hst.get("date")} save1 {as_date(g)} '
                 f'(ScenarioInProgress {g.get("ScenarioInProgress")}); [General] slot 1 {gen_date(HOST_SLOT)}, slot 77 '
                 f'{gen_date(CLIENT_SLOT)}')


def ls_log_scan(label, marks):
    """No lockstep error in the logs since the marks ({port: mark}); the hooks installed at most once per copy, each
    time all context hooks of this source tree (expected_ctx_hooks). The battle's chat lines (pause reasons, "Battle:
    ...") name no file path and no "Game saved" box (0.3.2). And the leak check (`ls leakcheck 1`, on in every live
    battle of the suite) logged no `lockstep: LEAK` line (lines a test provoked on purpose are in LS_EXCUSED); its own
    `display wrote N sighting fields` lines (the guard kept a display write out of the simulation) and WARNING lines are
    reported. 0.3.3, the simulation's identification: every live load logged its line on each copy (ident_loads), and
    `ident=` was equal on both copies at READY (ls_ready) and in every minute compared since the scenario's last scan
    (IDENT_LOG, filled by ls_compare)."""
    bad = {who_of(p): [x for x in ls_lines(p, m, LS_BAD_RE) if LS_TEST_EXC not in x][:4] for p, m in marks.items()}
    notes = {who_of(p): ls_lines(p, m, LS_NOTE_RE)[:4] for p, m in marks.items()}
    hooks = {who_of(p): [x.split('] ', 1)[-1] for x in log_lines(log_since(p), LS_HOOKS_RE)] for p in marks}
    want = expected_ctx_hooks()
    full = all(x.startswith(f'lockstep hooks: ok ({want} of {want} context hooks') for v in hooks.values() for x in v)
    leaks = {who_of(p): [x for x in ls_lines(p, m, LS_LEAK_RE) if x not in LS_EXCUSED] for p, m in marks.items()}
    excused = {who_of(p): sum(1 for x in ls_lines(p, m, LS_LEAK_RE) if x in LS_EXCUSED) for p, m in marks.items()}
    guard = {who_of(p): len(ls_lines(p, m, r'lockstep: the display wrote \d+ sighting fields')) for p, m in marks.items()}
    on = {who_of(p): LEAKCHECK.get(p, (None, 'never'))[1] for p in marks}
    if any(notes.values()):
        log(f'  {label}: lockstep notes (reported): {notes}')
    log(f'  {label}: leak check {on}; guard catches (display wrote sighting fields) {guard}; LEAK lines provoked on '
        f'purpose {excused}')
    check(f'{label}: no lockstep error in the logs (FATAL, exception, hook failed/INCOMPLETE, load FAILED, battle '
          f'failed); the lockstep hooks installed at most once per copy, all {want} context hooks of this source tree',
          not any(bad.values()) and all(len(v) <= 1 for v in hooks.values()) and want and full,
          f'{bad}; hooks lines {hooks}')
    chatl = {who_of(p): ls_lines(p, m, r'lockstep: (The battle paused \(|Battle: )') for p, m in marks.items()}
    leaky = {w: [x for x in v if PATH_RE.search(x) or 'Game saved' in x] for w, v in chatl.items()}
    check(f'{label}: the battle\'s chat lines (pause reasons, "Battle: <the game\'s text>") name no file path and no '
          f'"Game saved" box (0.3.2: the mod\'s own saves are no pause reason, paths are cut to the file name)',
          not any(leaky.values()), f'{[(w, len(v)) for w, v in chatl.items()]} lines; {leaky}')
    ident_scan_checks(label, {who_of(p): ident_loads(p, m) for p, m in marks.items()})
    return check(f'{label}: the leak check (`ls leakcheck 1` on every copy) found no display write into the simulation: '
                 f'no "lockstep: LEAK" line', all(v == 'ok leakcheck=1' for v in on.values())
                 and not any(leaks.values()), f'leak check {on}; LEAK lines {[(w, v[:3]) for w, v in leaks.items() if v]}')


def ls_keep_log(port, tag):
    """Copy a copy's log before it is started again (the mod renames it to .prev.log at start: one generation)."""
    dst = os.path.join(LOG_DIR, f'rtw3mp_{port}.{tag}.log')
    try:
        shutil.copyfile(log_path(port), dst)
        KEPT_LOGS.append(dst)
        log(f'  log of {who_of(port)} kept: {os.path.basename(dst)}')
    except OSError as e:
        log(f'  !! could not keep the log of {who_of(port)}: {e!r}')


def ls_kill(ctx, who):
    """taskkill /F of one of this run's copies (by its PID); it is taken out of PROCS first."""
    pid = ctx.hp if who == 'host' else ctx.cp
    p = next((x for x in PROCS if x.pid == pid), None)
    if p is not None:
        PROCS.remove(p)
    subprocess.run(['taskkill', '/PID', str(pid), '/F'], capture_output=True)
    if p is not None:
        try:
            p.wait(30)
        except subprocess.TimeoutExpired:
            log(f'  !! PID {pid} still running 30 s after taskkill')
    log(f'  killed the {who} (PID {pid}, taskkill /F)')


def ls_relaunch(ctx, who, extra=None, tag='restart'):
    """Start a killed copy again (same bridge, log tag and slot; extra environment for either copy, e.g.
    RTW3MP_TEST_LS_LEVEL)."""
    port = H if who == 'host' else C
    ls_keep_log(port, f'{tag}{len(KEPT_LOGS) + 1}')
    if who == 'host':
        p = launch(H, None, extra)
    else:
        p = launch(C, CLIENT_SLOT, dict({'RTW3MP_EVENT_CHANCE': str(ctx.event_chance)}, **(extra or {})))
    PROCS.append(p)
    if who == 'host':
        ctx.hp = p.pid
    else:
        ctx.cp = p.pid
    ok = wait_bridge(port)
    ls_ans(ctx)
    if ok:
        ls_leakcheck(ctx, (port,))
    log(f'  started the {who} again: PID {p.pid}, bridge {"up" if ok else "DOWN"}'
        + (f', env {extra}' if extra else ''))
    return ok


def restore_slot1_copy():
    """Slot 1 put back from this run's backup in the middle of the run (the backup is kept for the final restore)."""
    g1 = slot_dir(HOST_SLOT)
    for _ in range(10):
        try:
            if os.path.exists(g1):
                shutil.rmtree(g1)
            shutil.copytree(BACKUP, g1)
            if tree_digest(g1) == tree_digest(BACKUP):
                return True
        except OSError:
            pass
        time.sleep(1)
    return False


def k2_start(ctx):
    """lockstep_pvp: a third copy (bridge 47703, slot 76, battle slot 86) joins as "Bot"; the host gives it the reserved
    nation 2 back. Returns (join reply, host lines, status)."""
    p = launch(K2, K2_SLOT, {'RTW3MP_EVENT_CHANCE': '0'})
    PROCS.append(p)
    K2PROC[0] = p
    log('started the third copy PID', p.pid)
    if not wait_bridge(K2):
        raise RuntimeError('the third copy did not answer on its bridge')
    ls_leakcheck(ctx, (K2,))
    hm = log_mark(H)
    scmd(K2, 'fightbattles 1')
    r = cmd(K2, f'join {K2_NAME} 127.0.0.1 {MP_PORT}')
    sent = wait_log(H, hm, rf'state seq \d+ -> {K2_NAME} \(nation {STANDIN},', 30)
    if not sent:
        log('  the host did not give nation 2 back: claim 2 ->', cmd(K2, f'claim {STANDIN}'))
        sent = wait_log(H, hm, rf'state seq \d+ -> {K2_NAME} \(nation {STANDIN},', 60)
    st = wait(K2, lambda s: s.get('phase') == 'planning' and s.get('playerIdx') == str(STANDIN)
              and s.get('slot') == str(K2_SLOT), 90, 'the third copy plans nation 2 in slot 76')
    wait_relations_turn(ctx, 0, port=K2, pid=k2_pid(), nation=STANDIN, who='k2')  # relations v2: its first turn
    cmd(K2, 'mpwindow')
    ls_ans(ctx)
    return r, sent, st


def k2_stop(ctx):
    """The third copy leaves the session and is closed (its PID)."""
    p = K2PROC[0]
    if p is None:
        return
    scmd(K2, 'leave')
    try:
        ls_wait(lambda: f'{K2_NAME}(' not in lsn(H).get('players', f'{K2_NAME}('), 20, 'the host saw Bot leave')
    except RuntimeError as e:
        log('  !!', e)
    if p in PROCS:
        PROCS.remove(p)
    subprocess.run(['taskkill', '/PID', str(p.pid), '/F'], capture_output=True)
    try:
        p.wait(30)
    except subprocess.TimeoutExpired:
        pass
    K2PROC[0] = None
    ls_ans(ctx)
    log('closed the third copy PID', p.pid)


def ls_detect(k2):
    """A live battle running on two copies: B = a joined player's copy whose `ls status` shows a running battle as B,
    A = its peer (the host, or the other joined player). Returns (A, B) or None. Polls only the clients' bridges, and
    the host's only once its live battle runs (its month waits in the battle then)."""
    for p in [C] + ([K2] if k2 else []):
        b = lss(p)
        if b.get('on') == '1' and b.get('role') == 'B' and b.get('st') == 'running':
            A = {HOST_NAME: H, CLIENT_NAME: C, K2_NAME: K2}.get(b.get('peer'))
            if A is None or A == p:
                continue
            a = lss(A)
            if a.get('on') == '1' and a.get('role') == 'A' and a.get('st') == 'running' and a.get('bid') == b.get('bid'):
                return A, p
    return None


def host_live(rec):
    """From the host's log of the month (no bridge call): True while its battle is held/live, False once it ended or
    was refused, None if no live battle was tried."""
    lines = log_lines(log_since(H, rec['hmark']), rf'{LS_HOLD}|{LS_OFF}')
    return None if not lines else LS_HOLD in lines[-1]


def ls_tick_host(ctx, rec):
    """The host's battle screen when it is not (or no longer) live: fought on auto-run (the bridge is polled only for a
    stalled run while the battle screen is up)."""
    st = rec['autorun'].setdefault('host', {})
    frm = next((h for h in top_windows(ctx.hp) if e2e_test.class_name(h) == 'TfrmMain'), None)
    if frm is None:
        if st.get('since'):
            rec['autorun']['host'] = {}
        return
    st.setdefault('since', time.time())
    live = host_live(rec)
    if live or (live is None and time.time() - st['since'] < 15):
        return
    st.setdefault('why', 'not live' if live is None else 'live battle over')
    autorun_click(ctx, st, 'host', ctx.hp, frm, H)


def ls_tick_client(ctx, rec, port):
    """A joined player's battle screen that is not live (a battle against an AI nation, A's battle after it dropped B):
    fought on auto-run."""
    who, pid = who_of(port), pid_of(ctx, port)
    if not pid:
        return
    st = rec['autorun'].setdefault(who, {})
    frm = next((h for h in top_windows(pid) if e2e_test.class_name(h) == 'TfrmMain'), None)
    if frm is None:
        if st.get('since'):
            rec['autorun'][who] = {}
        return
    st.setdefault('since', time.time())
    ls = lss(port)
    if ls.get('on') == '1' or ls.get('leave') == '1' or time.time() - st['since'] < 6:
        return
    autorun_click(ctx, st, who, pid, frm, port)


def live_hook(rec, what, A, B, r):
    """A scenario's hook in a month's live battle (ls_month(live_hook=...)): called by ls_drive_live with 'load' right
    after the start check (both copies between minutes at the loaded boundary) and with 'minutes' after the live minutes,
    before the battle's end and the hash comparison (minutes the hook runs count). An exception is logged; the battle
    goes on."""
    fn = rec.get('live_hook')
    if fn:
        try:
            fn(what, rec, A, B, r)
        except Exception as e:  # noqa: BLE001
            log(f'  !! live battle hook ({what}): {e!r}')


def ls_drive_live(ctx, rec, A, B, mode):
    """Drive one live battle of a month (blocking; the answerer thread keeps answering every copy's dialogs). Every
    division goes to the AI (contact, damage), a few minutes run from both sides, B orders one of its divisions (AI off)
    and the order must show equally on both copies. Then by mode: 'drop<N>' = N live minutes, A drops B (A fights on
    alone on auto-run, B goes back to its slot); 'agree' / 'game' = ls_drive_end; 'killB' = the client's game is killed
    (taskkill /F) during a minute, the host must drop it, the client is started again (rec['relaunch_env']) and joins
    at once."""
    ans = ls_ans(ctx)
    a, b = lss(A), lss(B)
    r = dict(A=A, B=B, bid=a.get('bid'), epoch=a.get('epoch'), mode=mode, t=time.time(), a0=a, b0=b, sA=lsn(A),
             sB=lsn(B), pA=pst(A), pB=pst(B), hostOpp=lsn(H).get('hostOpp') if A == H else None)
    log(f'  live battle {r["bid"]}: A={who_of(A)} B={who_of(B)}, mode {mode}; A {r["sA"]}; B {r["sB"]}')
    r['ready'] = ls_ready(A, B, f'battle {r["bid"]}')
    if A == H:
        r['s_battle'] = read_save(save_path(HOST_SLOT))  # the campaign as the battle started (the live battle's save)
        env = (read_save(os.path.join(slot_dir(HOST_SLOT), f'RTWGame{HOST_SLOT}.sac')) or {}).get('Environment') or {}
        r['sac'] = (env.get('Year'), env.get('Month'), env.get('Day'))
        log(f'  live battle {r["bid"]}: the battle\'s own date ([Environment] of its .sac) {env.get("Year")}/'
            f'{env.get("Month")}/{env.get("Day")} {env.get("Hour")}:{env.get("Minute")}; the campaign\'s ([General] of '
            f'the battle save) {gen_date(HOST_SLOT)}')
    live_hook(rec, 'load', A, B, r)
    ma, mb = rec['marks'][A], rec['marks'][B]
    if mode == 'relayrejoin' and A == H:  # (lockstep_rejoin e): the host's own battle of that month is dropped early)
        mode = r['mode'] = 'drop3'
    try:
        r['ai'] = ls_all_ai(A, B)
        scmd(A, 'ls speed 3')
        r['run'] = ls_run_total(A, B, 2, A)
        d1 = ls_pick_div(B, 1)
        if d1:
            want = (d1['course'] + 90) % 360
            scmd(B, f'ls order {d1["i"]} {want} -1 0')
            r['run'] += ls_run_total(A, B, 2, B)
            da, db = {d['i']: d for d in ls_divs(A)}, {d['i']: d for d in ls_divs(B)}
            r['order'] = dict(div=d1['i'], want=want, A=da.get(d1['i'], {}).get('course'),
                              B=db.get(d1['i'], {}).get('course'))
        if mode.startswith('drop'):
            n = int(mode[4:] or 10)
            r['run'] += ls_run_total(A, B, max(1, n - r['run']), A)
            live_hook(rec, 'minutes', A, B, r)
            r['hash'] = ls_compare(A, ma, B, mb, f'battle {r["bid"]}')
            mk = log_mark(A)
            scmd(A, 'ls drop')
            ls_wait(lambda: ls_over(A), 60, 'A drops B')
            pidB = pid_of(ctx, B)
            slotB, natB = (CLIENT_SLOT, 1) if B == C else (K2_SLOT, STANDIN)
            t = time.time()
            ls_wait(lambda: ls_back(B, pidB, slotB, natB), 120, 'B back in its slot after the drop')
            r['back_s'] = round(time.time() - t, 1)
            r['drop'] = ls_lines(A, mk, r'dropping|left the live battle')
        elif mode in ('agree', 'game'):
            live_hook(rec, 'minutes', A, B, r)
            r.update(ls_drive_end(A, B, mode))
            r['t_end'] = time.time()
            r['hash'] = ls_compare(A, ma, B, mb, f'battle {r["bid"]}')
            ans.view_results.update((who_of(A), who_of(B)))
        elif mode == 'endsoon':
            live_hook(rec, 'minutes', A, B, r)
            r.update(ls_drive_endsoon(A, B))
            r['hash'] = ls_compare(A, ma, B, mb, f'battle {r["bid"]}')
            ans.view_results.update((who_of(A), who_of(B)))
        elif mode == 'killB':
            scmd(A, 'ls speed 0')
            ls_run(A, B, 1, A, timeout=180)
            r['hash'] = ls_compare(A, ma, B, mb, f'battle {r["bid"]}')
            scmd(A, 'ls run 5')
            ls_wait(lambda: lss(B).get('running') == '1', 60, 'B in the middle of a minute')
            r['kill_minute'] = lss(A).get('minute')
            mk, t = log_mark(H), time.time()
            ls_kill(ctx, 'client')
            rec['relaunched'] = True
            ls_wait(lambda: ls_lines(H, mk, r'left the live battle') and ls_over(H), 90,
                    'the host drops the killed client')
            r['drop_s'] = round(time.time() - t, 1)
            r['drop'] = ls_lines(H, mk, r'dropping Captain|left the live battle|live battle ended')
            ls_relaunch(ctx, 'client', rec.get('relaunch_env'), tag='kill')
            scmd(C, 'fightbattles 1')
            r['rejoin_mark'] = log_mark(H)
            r['join'] = cmd(C, f'join {CLIENT_NAME} 127.0.0.1 {NET_PROXY.get(C, MP_PORT)}')
            time.sleep(15)
            r['rejoin_during'] = sstatus(C)
            log(f'  the client joined again while the host\'s battle runs: myNation '
                f'{r["rejoin_during"].get("myNation")}, phase {r["rejoin_during"].get("phase")}')
        elif mode == 'relayrejoin':  # lockstep_rejoin e): a relayed battle's B killed, rejoined, killed, refused
            r.update(relay_rejoin_drive(ctx, rec, A, B))
    except Exception as e:  # noqa: BLE001
        r['error'] = repr(e)
        log('  !! live battle', r['bid'], repr(e))
        if lss(A).get('on') == '1':
            log('  A drops B so that the month can go on:', scmd(A, 'ls drop'))
    r['linesA'] = ls_lines(A, ma, r'lockstep: (battle \d+ epoch \d+ (sent|running)|The battle is over|The live battle|.*left '
                                  r'the live battle|dropping|DESYNC|Synchronising)|live battle ')
    r['linesB'] = ls_lines(B, mb, r'lockstep: (battle loaded|battle \d+ epoch \d+ running|The battle is over|The live '
                                  r'battle|DESYNC)|live battle') if not (mode == 'killB' and B == C) else []
    r['desync'] = ls_lines(A, ma, r'DESYNC')
    return r


def rejoin_back(ctx, hmark, during):
    """How a player who joined again while the host's battle screen was open got its nation back (0.3.0): at once by
    the hello (HELLO matching during a session: `myNation` 1 while the battle is still open, chat "* Captain joined as
    <nation>") or by the host's Tick (`RematchReservations`: `reservation: Captain gets nation 1 back`, chat "* Captain is
    back as <nation>"). Reads the client's chat (opens its Multiplayer window). Returns dict(ok, path, ...)."""
    n1 = nation1()
    res = ls_lines(H, hmark, rf'reservation: {CLIENT_NAME} gets nation 1 back')
    cmd(C, 'mpwindow')
    time.sleep(1.5)
    lines = [x.strip() for x in chat(ctx.cp).splitlines()
             if re.search(rf'\* {CLIENT_NAME} (joined|is back as)', x)]
    hello = during.get('myNation') == '1'
    path = 'hello' if hello else 'reservation' if res else None
    want = f'* {CLIENT_NAME} joined as {n1}' if hello else f'* {CLIENT_NAME} is back as {n1}'
    return dict(ok=path is not None and any(want in x for x in lines), path=path, during=during.get('myNation'),
                reservation=res[:1], chat=lines[-2:], want=want)


def ls_claim_if_needed(ctx, rec, d0file):
    """A client that was started again during the host's month: if the host gave it no nation by the time its month is
    over (its save has the new date and its strategic screen is back), it claims nation 1 (recorded)."""
    st = sstatus(C)
    if st.get('myNation') == '1' or st.get('role') != 'client':
        return
    done = save_date(HOST_SLOT) not in (None, d0file) and not battle_up(ctx.hp) and strategic_enabled(ctx.hp)
    if not done:
        return
    rec.setdefault('host_done_t', time.time())
    if time.time() - rec['host_done_t'] > 20:
        rec['claimed'] = dict(st, lobby=cmd(C, 'diploview')[:200])
        log(f'  the host\'s month is over but the returning client has no nation ({st.get("myNation")}): claim '
            f'{nation1()} ->', cmd(C, f'claim {nation1()}'))


class StageWatcher(threading.Thread):
    """Reads the saves of a month's idea-1 battle phase the moment the logs announce them, from a thread (the next step
    overwrites them within ~0.3 s): the host's save at `battle phase:` (s0: the month after DoEndOfTurn, with its live
    battle), the merged save after each `battle N applied` (s1[N]) and the client's battle slot after each `battle N:
    fought` (g87[N], the battle as the game left it). Raw bytes; `stages()` parses them. Also the order of the steps."""

    def __init__(self, hmark, cmark):
        super().__init__(daemon=True)
        self.pos = {H: hmark, C: cmark}
        self.raw = dict(s0=None, s1={}, g87={})
        self.steps = []  # (time, 'phase' | 'applied N' | 'resolved N <how>' | 'fought N' | 'g87 N missed')
        self.stop = False

    def tail(self, port):
        try:
            if os.path.getsize(log_path(port)) < self.pos[port]:  # the copy was started again: a new log
                self.pos[port] = 0
            with open(log_path(port), 'rb') as f:
                f.seek(self.pos[port])
                data = f.read()
        except OSError:
            return []
        cut = data.rfind(b'\n') + 1
        self.pos[port] += cut
        return [ln for ln in data[:cut].decode('utf-8', errors='replace').splitlines() if 'lockstep hash' not in ln]

    @staticmethod
    def grab(slot):
        for _ in range(5):
            try:
                with open(save_path(slot), 'rb') as f:
                    return f.read()
            except OSError:
                time.sleep(0.03)
        return None

    def run(self):
        while not self.stop:
            try:
                for ln in self.tail(H):
                    if self.raw['s0'] is None and 'battle phase: ' in ln:
                        self.raw['s0'] = self.grab(HOST_SLOT)
                        self.steps.append((time.time(), 'phase'))
                    m = re.search(r'\] battle (\d+) applied: ', ln)
                    if m and int(m[1]) not in self.raw['s1']:
                        self.raw['s1'][int(m[1])] = self.grab(HOST_SLOT)
                        self.steps.append((time.time(), f'applied {m[1]}'))
                    m = re.search(r'\] battle (\d+) resolved by the game: (.*)$', ln)
                    if m:
                        self.steps.append((time.time(), f'resolved {m[1]} {m[2]}'))
                for ln in self.tail(C):
                    m = re.search(r'\] battle (\d+): fought', ln)
                    if m and int(m[1]) not in self.raw['g87']:
                        self.raw['g87'][int(m[1])] = self.grab(BATTLE_SLOT)
                        self.steps.append((time.time(), f'fought {m[1]}'))
            except Exception as e:  # noqa: BLE001
                self.steps.append((time.time(), f'watcher error {e!r}'))
            time.sleep(0.1)

    def stages(self):
        """dict(s0, s1={N: save}, g87={N: save}, steps) with the saves parsed."""
        return dict(s0=parse_save(self.raw['s0']), s1={b: parse_save(r) for b, r in self.raw['s1'].items()},
                    g87={b: parse_save(r) for b, r in self.raw['g87'].items()}, steps=[s for _, s in self.steps])


def ls_month(ctx, label, modes=('agree',), k2=False, relaunch_env=None, live_hook=None):
    """One processed month that may hold live battles (the host's own battle against nation 1 found by the game's
    CheckForBattles2, live battles between joined players, joined players' battles against AI nations). The answerer
    thread answers every copy's dialogs; each live battle that starts is driven by the next of `modes` (ls_drive_live);
    a battle screen that is not live is fought on auto-run. The host's bridge is polled only while its live battle
    runs. Ends when the client (and K2) plan the new month; then the event roll and month_checks (the roll check is
    skipped when the client was started again). live_hook(what, rec, A, B, r): see live_hook(). Returns a record."""
    ans = ls_quiet(ctx)
    for hook in list(ctx.pre_month_hooks):
        hook(ctx, label, len(ctx.months) + 1)
    date0, d0file = sstatus(C).get('date'), save_date(HOST_SLOT)
    ports = [H, C] + ([K2] if k2 else [])
    rec = dict(label=label, date0=date0, live=[], marks={p: log_mark(p) for p in ports}, relaunched=False,
               autorun={}, relaunch_env=relaunch_env, claimed=None, chat0=chat(ctx.cp), t0=time.time(),
               live_hook=live_hook)
    rec['hmark'], rec['cmark'] = rec['marks'][H], rec['marks'][C]
    ctx.month_marks = (rec['hmark'], rec['cmark'])
    watcher = StageWatcher(rec['hmark'], rec['cmark'])
    watcher.start()
    cmd(C, 'submit')
    if k2:
        cmd(K2, 'submit')
    wait(C, lambda s: s.get('submitted') == '1' and s.get('submitting', '0') == '0', 30, 'client submitted',
         pids=(ctx.hp, ctx.cp))
    if k2:
        # (its Submit may ask the game's Turn questions too, since 0.4.1: answered like the client's)
        wait(K2, lambda s: s.get('submitted') == '1' and s.get('submitting', '0') == '0', 30, 'K2 submitted',
             pids=(ctx.hp, pid_of(ctx, K2)))
    wait(H, lambda s: 'All players are ready' in s.get('status', ''), 30, 'host sees everyone ready',
         pids=(ctx.hp, ctx.cp))
    log(f'  [General] before the turn: slot {HOST_SLOT} {gen_date(HOST_SLOT)}, slot {CLIENT_SLOT} (submitted) '
        f'{gen_date(CLIENT_SLOT)}')
    pf0 = poss_fields(HOST_SLOT)
    ctx.kwar_before = kwar_counters(H)
    relrules_pre_month(ctx)
    ans.paused = False
    t_turn = time.time()
    cmd(H, 'turn')
    modes, st = list(modes), {}
    end = time.time() + MONTH_TIMEOUT + LS_MONTH_EXTRA
    try:
        while True:
            if time.time() > end:
                raise RuntimeError(f'the month did not advance within {MONTH_TIMEOUT + LS_MONTH_EXTRA} s ({label}); host '
                                   f'windows: {describe_windows(ctx.hp)}; client windows: {describe_windows(ctx.cp)}')
            assert_alive()
            answer_host_box(ctx.hp)
            live = ls_detect(k2)
            if live:
                mode = modes.pop(0) if len(modes) > 1 else modes[0]
                rec['live'].append(ls_drive_live(ctx, rec, live[0], live[1], mode))
                continue
            ls_tick_host(ctx, rec)
            for p in ports[1:]:
                ls_tick_client(ctx, rec, p)
            if not any(battle_up(pid_of(ctx, p)) for p in ports if pid_of(ctx, p)):
                ans.view_results.clear()
            if rec['relaunched'] and rec['claimed'] is None:
                ls_claim_if_needed(ctx, rec, d0file)
            st = sstatus(C)
            done = st.get('phase') == 'planning' and st.get('date') not in (None, '', date0) \
                and st.get('slot') == str(CLIENT_SLOT) and st.get('playerIdx') == '1' and st.get('myNation') == '1'
            if done and k2:
                s2 = sstatus(K2)
                done = s2.get('phase') == 'planning' and s2.get('date') == st.get('date') and s2.get('slot') == str(K2_SLOT)
            if done:
                break
            time.sleep(1.0)
    finally:
        watcher.stop = True
    time.sleep(2)
    watcher.join(5)
    rec['stages'] = watcher.stages()
    ls_quiet(ctx)
    dt = time.time() - rec['t0']
    ctx.months.append((label, date0, st.get('date'), dt))
    log(f'month processed ({label}): {date0} -> {st.get("date")} in {dt:.0f} s; live battles '
        f'{[(b["bid"], b["mode"], b.get("error")) for b in rec["live"]]}')
    pch = poss_changes(pf0, poss_fields(HOST_SLOT))
    if pch:
        log(f'  possessions that changed hands this month (slot {HOST_SLOT} MapData, before the turn -> after the month): '
            f'{pch}')
    check(f'{label}: the month advanced by exactly one month ({date0} -> {st.get("date")})',
          st.get('date') == month_after(date0), log_lines(log_since(H, rec['hmark']), r'DoEndOfTurn finished'))
    wait_event_roll(ctx, 0 if rec['relaunched'] else rec['cmark'])
    wait_relations_turn(ctx, 0 if rec['relaunched'] else rec['cmark'])
    if k2 and k2_pid():
        wait_relations_turn(ctx, rec['marks'][K2], port=K2, pid=k2_pid(), nation=STANDIN, who='k2')
    month_checks(ctx, label, rec['hmark'], None if rec['relaunched'] else rec['cmark'])
    for hook in list(ctx.month_hooks):
        hook(ctx, label)
    rec.update(date1=st.get('date'), seconds=dt, answers=[(t, w, e) for t, w, e in ans.seen if t >= t_turn])
    return rec


def ls_host_battle(rec):
    """The host's battle of the month against nation 1 as its log shows it: 'live' (held and started), 'ai' (fought
    against the AI: the player's opt-out), 'none'."""
    hl = log_since(H, rec['hmark'])
    if re.search(r'battle against Captain: fought against the AI', hl):
        return 'ai'
    if LS_HOLD in hl:
        return 'live'
    return 'none'


def ls_case(ctx, name, fn):
    """Run one case of a lockstep scenario; an exception fails it (one check) and the scenario recovers (A drops B, the
    host's battle finished outside a month, the client back in the session) instead of stopping. Records the case for
    the stress matrix."""
    log(f'--- {name} ---')
    n0, t0, note = len(results), time.time(), ''
    try:
        note = fn() or ''
    except Exception as e:  # noqa: BLE001
        check(f'{name}: completed', False, repr(e))
        note = repr(e)[:160]
        for pid, who in ((ctx.hp, 'host'), (ctx.cp, 'client')):
            log(f'  {who} windows:', describe_windows(pid))
        for port in (H, C):
            log(f'  ls {who_of(port)}:', scmd(port, 'ls status'))
            log(f'  log {who_of(port)} tail:\n    ' + '\n    '.join(log_since(port).splitlines()[-10:]))
        ls_recover(ctx)
    rs = results[n0:]
    LS_MATRIX.append((name, sum(1 for r in rs if r[2]), len(rs), round(time.time() - t0), str(note)))


def ls_recover(ctx):
    """After a failed case outside a month: no live battle, the host's battle finished, the client in the session."""
    try:
        for pid in (ctx.hp, ctx.cp):  # the battle screen's tool windows a case left open
            close_modeless(pid)
        if lss(H).get('on') == '1':
            log('  recover: A drops B', scmd(H, 'ls drop'))
            time.sleep(3)
        if lss(C).get('on') == '1':
            log('  recover: B leaves', scmd(C, 'ls abort'))
        ls_wait(lambda: ls_client_back(ctx) or not sstatus(C), 120, 'the client back after the failure')
        if battle_up(ctx.hp):
            ls_finish_host(ctx)
        ls_ensure_session(ctx)
    except Exception as e:  # noqa: BLE001
        log('  !! recovery failed:', repr(e))
        raise


def ls_start_checks(tag, s):
    """b) a test battle started live: preview accepted, held, saved and sent by the host, loaded by the client from its
    battle slot; roles, sides, ids; the host's battle in battle slot mode (outside a month); each copy's hooks line has
    all the context hooks of this source tree (expected_ctx_hooks)."""
    ans = _ANS[0]
    a, b = s['a'], s['b']
    prev = ls_answered(ans, 'host', s['t0'], 'TdlgBattlePreview')
    held = ls_lines(H, s['hm'], re.escape(LS_HOLD))
    sent = ls_lines(H, s['hm'], rf'lockstep: battle {a.get("bid")} epoch 1 sent \(\d+ files, \d+ bytes')
    loaded = ls_lines(C, s['cm'], rf'lockstep: battle loaded from slot {BATTLE_SLOT} ')
    check(f'{tag}: the host\'s preview accepted, the battle held at its start, saved and sent ("battle <bid> epoch 1 sent '
          f'(n files, b bytes ...)"), loaded by the client from its battle slot {BATTLE_SLOT}; both run it within 150 s '
          f'(start {s["dt"]:.1f} s)', prev and held and sent and loaded, f'{prev[:1]} {held[:1]} {sent[:1]} {loaded[:1]}')
    pa, pb, hn, cn = pst(H), pst(C), lsn(H), lsn(C)
    check(f'{tag}: roles host A side 0 / client B side 1, same battle id and epoch; pocstate playerSide 0 / 1; host '
          f'`ls session` hostOpp=1 testSlotMode=1 slotMode=1; client role=B slotMode=1',
          a.get('role') == 'A' and a.get('side') == '0' and b.get('role') == 'B' and b.get('side') == '1'
          and a.get('bid') == b.get('bid') and a.get('epoch') == b.get('epoch') and pa.get('playerSide') == '0'
          and pb.get('playerSide') == '1' and hn.get('hostOpp') == '1' and hn.get('testSlotMode') == '1'
          and hn.get('slotMode') == '1' and cn.get('role') == 'B' and cn.get('slotMode') == '1',
          f'A {a.get("role")}/{a.get("side")}/{a.get("bid")}/{a.get("epoch")} B {b.get("role")}/{b.get("side")}/'
          f'{b.get("bid")}/{b.get("epoch")}; playerSide {pa.get("playerSide")}/{pb.get("playerSide")}; host {hn}; '
          f'client {cn}')
    want = expected_ctx_hooks()
    hk = {who_of(p): [x.split('] ', 1)[-1] for x in log_lines(log_since(p), LS_HOOKS_RE)] for p in (H, C)}
    check(f'{tag}: both copies installed the live-battle hooks once with all of them: "lockstep hooks: ok ({want} of '
          f'{want} context hooks, ...)" ({want} = the context hooks of this source tree, src/mod/lockstep.cpp; 0.3.3 '
          f'added TdlgDivisionReport.FillShipList: 18 -> 19)', want and all(
              len(v) == 1 and v[0].startswith(f'lockstep hooks: ok ({want} of {want} context hooks') for v in hk.values()),
          hk)


def ls_orders_check(tag, A=H, B=C):
    """Orders of both sides given at the same paused boundary are released with the next minute and applied
    identically on both copies."""
    ma, mb = log_mark(A), log_mark(B)
    d1, d0 = ls_pick_div(B, 1), ls_pick_div(A, 0)
    if not (d0 and d1):
        return check(f'{tag}: a division on each side for the orders', False, f'{d0} {d1}')
    w1, w0 = (d1['course'] + 90) % 360, (d0['course'] + 45) % 360
    r1 = scmd(B, f'ls order {d1["i"]} {w1} {max(d1["speed"] - 2, 4)}')
    r0 = scmd(A, f'ls order {d0["i"]} {w0} {max(d0["speed"] - 1, 4)}')
    time.sleep(1.0)
    ls_run(A, B, 1, A)
    da, db = {d['i']: d for d in ls_divs(A)}, {d['i']: d for d in ls_divs(B)}
    got = dict(B_on_A=da.get(d1['i'], {}).get('course'), B_on_B=db.get(d1['i'], {}).get('course'),
               A_on_A=da.get(d0['i'], {}).get('course'), A_on_B=db.get(d0['i'], {}).get('course'), want_B=w1, want_A=w0)
    rb, ra = ls_lines(A, ma, r'orders #\d+ of .* received'), ls_lines(B, mb, r'orders #\d+ of .* received')
    return check(f'{tag}: orders of both sides at the same paused boundary (B: division {d1["i"]} course {w1}, A: '
                 f'division {d0["i"]} course {w0}) applied identically on both copies with the next minute; each copy '
                 f'received the other\'s order batch', r0 == r1 == 'ok' and got['B_on_A'] == got['B_on_B'] == w1
                 and got['A_on_A'] == got['A_on_B'] == w0 and rb and ra, f'{r0} {r1} {got} recv A {rb[:1]} B {ra[:1]}')


def inject_desync(port, A=H):
    """`ls desync` on a copy (its next minute differs: division 0's DivisionCourse +37), the battle recorded so that the
    runner deletes the DESYNC reports it causes (RUN['desync_bids'])."""
    RUN['desync_bids'].add(str(lss(A).get('bid')))
    return scmd(port, 'ls desync')


DESYNC_REPORT_RE = r'lockstep: DESYNC report (ls_desync_([AB])_(\d+)_(\d+)_(\d+)\.txt) (written|NOT written)'


def desync_reports(port, mark):
    """The DESYNC reports a copy wrote since the mark: [(file, A|B, bid, epoch, minute, written)]."""
    return [(m[1], m[2], m[3], m[4], m[5], m[6] == 'written') for m in re.finditer(DESYNC_REPORT_RE, log_since(port, mark))]


def desync_diff(fa, fb):
    """tools/desync_diff.py over two reports in the mod's data folder: its output ('' if it could not run)."""
    try:
        r = subprocess.run([sys.executable, os.path.join(REPO, 'tools', 'desync_diff.py'), os.path.join(LOG_DIR, fa),
                            os.path.join(LOG_DIR, fb)], capture_output=True, text=True, timeout=120)
        return r.stdout + r.stderr
    except (OSError, subprocess.SubprocessError) as e:
        return f'desync_diff.py failed: {e!r}'


def desync_report_cleanup(since):
    """The DESYNC reports this run caused on purpose (their battles in RUN['desync_bids']; written since `since`)
    deleted from the mod's data folder; a report of a battle the suite did not corrupt is kept as evidence (logged).
    Returns (deleted, kept)."""
    deleted, kept = 0, []
    for fn in os.listdir(LOG_DIR) if os.path.isdir(LOG_DIR) else []:
        m = re.match(r'^ls_desync_[AB]_(\d+)_\d+_\d+\.txt$', fn)
        p = os.path.join(LOG_DIR, fn)
        if not m or os.path.getmtime(p) < since:
            continue
        if m[1] in RUN['desync_bids']:
            try:
                os.remove(p)
                deleted += 1
            except OSError:
                kept.append(fn)
        else:
            kept.append(fn)
    return deleted, kept


def ls_desync_check(tag, port, A=H, B=C):
    """An injected desync (`ls desync`: this copy's next minute differs) is caught at the next boundary and the battle
    is synchronised again (a new epoch; its READY hash compared, ls_ready); the minutes after it are equal. Engine level
    13: both copies wrote their DESYNC report of that minute (`ls_desync_<A|B>_<battle>_<epoch>_<minute>.txt`) and
    tools/desync_diff.py over the two names the corrupted field (DivisionCourse)."""
    mk, mkb, e0 = log_mark(A), log_mark(B), int(lss(A).get('epoch') or 0)
    inject_desync(port, A)
    ls_run(A, B, 1, A)
    ls_wait(lambda: int(lss(A).get('epoch') or 0) > e0 and ls_idle_equal(A, B), 120, f'resync after the {tag} desync')
    ls_ready(A, B, f'{tag} resync')
    ma, mb = log_mark(A), log_mark(B)
    ls_run_total(A, B, 2, B)
    after = ls_compare(A, ma, B, mb, f'{tag} after the resync')
    des, syn = ls_lines(A, mk, r'DESYNC at minute'), ls_lines(A, mk, r'Synchronising the battle again')
    check(f'{tag}: an injected desync on the {who_of(port)} is caught ("DESYNC at minute m"), the battle is '
          f'synchronised again (epoch {e0} -> {lss(A).get("epoch")}), the next 2 minutes are equal',
          des and syn and after['minutes'] >= 2 and not after['differ'], f'{des[:1]} {syn[:1]} {after}')
    ra, rb = desync_reports(A, mk), desync_reports(B, mkb)
    pair = next(((x, y) for x in ra for y in rb if x[1] == 'A' and y[1] == 'B' and x[2:5] == y[2:5] and x[5] and y[5]),
                None)
    out = desync_diff(pair[0][0], pair[1][0]) if pair else ''
    return check(f'{tag}: both copies wrote their DESYNC report of that minute (engine level 13: "DESYNC report '
                 f'ls_desync_A_<battle>_{e0}_<minute>.txt written" on A, the same battle, epoch and minute on B), and '
                 f'tools/desync_diff.py over the two names the field the test corrupted (DivisionCourse)',
                 pair is not None and pair[0][3] == str(e0) and 'DivisionCourse' in out,
                 f'A {ra[:2]} B {rb[:2]}; desync_diff {out[-300:]!r}')


def ls_detach_check(tag, A=H, B=C):
    """B detaches a ship of one of its divisions between minutes (`ls detach`, as the battle screen's Detach): the
    action runs at once on B and is replayed on A with the next release; both copies then have one division more and
    the next minutes are equal."""
    d1 = ls_pick_div(B, 1, 2)
    if not d1:
        return check(f'{tag}: a division of the client\'s side with 2 ships to detach from', False, ls_divs(B)[:6])
    ma, mb = log_mark(A), log_mark(B)
    n0 = (len(ls_divs(A)), len(ls_divs(B)))
    r = scmd(B, f'ls detach {d1["i"]} 1')
    time.sleep(1.5)
    ls_run_total(A, B, 2, A)
    n1 = (len(ls_divs(A)), len(ls_divs(B)))
    hc = ls_compare(A, ma, B, mb, 'after the detach')
    des = ls_lines(A, ma, r'DESYNC|Synchronising the battle again')
    return check(f'{tag}: the client detaches a ship of its division {d1["i"]} ({d1["name"]}) between minutes (`ls '
                 f'detach`): replayed on the host with the next minute, one division more on both copies ({n0} -> {n1}), '
                 f'the next 2 minutes equal, no DESYNC or resync', r.startswith('ok') and n0[0] == n0[1]
                 and n1[0] == n1[1] and n1[0] >= n0[0] + 1 and hc['minutes'] >= 2 and not hc['differ'] and not des,
                 f'{r}; {n0} -> {n1}; {hc}; {des[:2]}')


def ls_guard_check(tag, A=H, B=C):
    """The display's writes of the ships' sighting fields stay out of the simulation (the round-3 fix): `ls dispwrite`
    (every ship's sighting fields changed outside the simulation, as the battle map's GlobeRender does) on B, then on
    A, each followed by 2 minutes: the guard counted them ("the display wrote N sighting fields since the last boundary
    (kept out of the simulation)"), no LEAK, no DESYNC, the minutes equal."""
    res = {}
    for port in (B, A):
        ma, mb = log_mark(A), log_mark(B)
        r = scmd(port, 'ls dispwrite')
        ls_run_total(A, B, 2, A)
        mk = ma if port == A else mb
        res[who_of(port)] = dict(write=r, guard=ls_lines(port, mk, r'display wrote \d+ sighting')[:1],
                                 leak=ls_lines(port, mk, LS_LEAK_RE)[:2], desync=ls_lines(A, ma, r'DESYNC'),
                                 hash=ls_compare(A, ma, B, mb, f'after a display write on the {who_of(port)}'))
    ok = all(re.match(r'^ok [1-9]', v['write']) and v['guard'] and not v['leak'] and not v['desync']
             and v['hash']['minutes'] >= 2 and not v['hash']['differ'] for v in res.values())
    return check(f'{tag}: display writes of every ship\'s sighting fields (`ls dispwrite`, as GlobeRender) on the client, '
                 f'then on the host: kept out of the simulation ("the display wrote N sighting fields ... (kept out of the '
                 f'simulation)"), no LEAK, no DESYNC, the next 2 minutes equal each time', ok,
                 {w: dict(write=v['write'], guard=v['guard'], leak=v['leak'], desync=v['desync'][:1],
                          hash=(v['hash']['minutes'], v['hash']['differ'])) for w, v in res.items()})


def ls_drop_checks(ctx, tag, why='test'):
    """A drops B (`ls drop`): the AI commands side 1, the client goes back to slot 77 as nation 1, the host's battle
    goes on alone (2 more minutes)."""
    hm, cm, t = log_mark(H), log_mark(C), time.time()
    scmd(H, 'ls drop')
    st = ls_wait(lambda: ls_client_back(ctx), 120, 'the client back in slot 77 after the drop')
    dt = time.time() - t
    hl = ls_lines(H, hm, r'dropping Captain|left the live battle')
    cl = ls_lines(C, cm, r'The live battle ended on this PC|live battle: leaving the battle slot|'
                         rf'LoadCampaign slot {CLIENT_SLOT} player 1 -> ok')
    rj = parse_tail_why(scmd(H, 'ls rejoinable'))
    promise = [x for x in hl if 'joins the session again during this battle, Captain gets their ships back.' in x]
    to_end = [x for x in hl if 'to the end of this battle; it goes on here.' in x]
    check(f'{tag}: the host\'s drop chat promises the ships back only when a rejoin can work (engine level 12; `ls '
          f'rejoinable` on={rj.get("on")}): "... If Captain joins the session again during this battle, Captain gets their '
          f'ships back." with on=1, "... The AI commands <nation> to the end of this battle; it goes on here." with on=0',
          (bool(promise), bool(to_end)) == ((True, False) if rj.get('on') == '1' else (False, True)), hl[-1:])
    m0 = int(pst(H).get('min') or 0)
    scmd(H, 'pocrun 2')
    time.sleep(1)
    ps = ls_wait(lambda: (lambda p: p if int(p.get('min') or 0) >= m0 + 1 and p.get('running') == '0'
                          and p.get('moving') == '0' else None)(pst(H)), 120, 'the host runs 2 minutes alone')
    check(f'{tag}: the host drops the client: "dropping Captain: {why}", "Captain left the live battle ({why}). The AI '
          f'commands Germany ..."; the client back in slot 77 as nation 1 ({dt:.1f} s: "The live battle ended on this '
          f'PC", "leaving the battle slot", LoadCampaign slot 77); the host\'s battle goes on alone (pocrun 2: minute '
          f'{m0} -> {ps.get("min")})', len(hl) >= 2 and len(cl) >= 3 and st and int(ps.get('min') or 0) >= m0 + 1,
          f'{hl} | {cl}')
    return dt


def ls_end_refused_check(tag, A=H, B=C):
    """Both players ask for the end before minute 400: the game's End routine refuses on both copies at the next
    boundary and the battle goes on."""
    ma, mb = log_mark(A), log_mark(B)
    ls_end_both(A, B)
    ls_wait(lambda: ls_lines(A, ma, r"can't end yet") and ls_lines(B, mb, r"can't end yet"), 90, 'the refused end')
    time.sleep(1.5)
    a, b = lss(A), lss(B)
    return check(f'{tag}: both players ask for the end before minute 400: the game refuses on both copies ("The battle '
                 f'can\'t end yet: ...") and the battle goes on (both running, end requests cleared)',
                 a.get('st') == b.get('st') == 'running' and a.get('end') == '0/0',
                 f'{ls_lines(A, ma, "can.t end yet")[:1]} | A st={a.get("st")} end={a.get("end")}, B st={b.get("st")}')


def scenario_lockstep(ctx):
    """Live player-vs-player battles (lockstep), the host against the joined player, two copies (short; from the research
    driver ls_live.py). a) both copies offer live battles, the host lists Captain(1,b,ls); the client changes its plans
    (ResearchPct, not submitted). b) the host's battle against nation 1 (`pocbattle 1 0`: the debug Test battle = the
    game's DoBattle, outside a month, so in battle slot mode) starts live: preview, held, saved, sent, loaded by the
    client in its battle slot 87 as side 1. c) runs asked by both sides, equal per-minute hashes. d) orders of both sides
    at one paused boundary applied identically; the client detaches a ship (an action replayed on the host); display
    writes of the sighting fields on each copy (`ls dispwrite`) stay out of the simulation. e) an injected desync is
    caught and resynchronised. f) an end asked by
    both before minute 400 is refused by the game on both, the battle goes on. g) the host drops the client: the AI
    commands side 1, the host's battle goes on, the client is back in slot 77 with its plans (canLoad saved them). h)
    the host's battle on auto-run to its end, closed without a month. i) after-checks. k) one normal month: the plans
    reached the host. l) no lockstep error in the logs, the hooks installed once, no LEAK (the leak check is on in every
    live battle of the suite)."""
    marks0 = {H: log_mark(H), C: log_mark(C)}
    ls_ensure_session(ctx)
    hs, cs = lsn(H), lsn(C)
    avail = hs.get('available') == '1' and cs.get('available') == '1'
    check('a) both copies offer live battles: `ls session` enabled=1 available=1 on host and client; the host lists '
          'Captain(1,b,ls) (fights battles, plays them live)', avail and hs.get('enabled') == cs.get('enabled') == '1'
          and 'Captain(1,b,ls)' in hs.get('players', ''), f'host {hs}; client {cs}')
    if not avail:
        check('a) live battles available on both copies: the scenario stops here', False, f'{hs} {cs}')
        return
    pct0 = nint(C, 1, 'ResearchPct')
    plan = 9 if pct0 != 9 else 8
    cmd(C, f'nfield 1 ResearchPct {plan}')
    date0 = sstatus(H).get('date')
    log(f'  a) the client\'s plans (not submitted): nation 1 ResearchPct {pct0} -> {plan}')

    def battle():
        s = ls_start_test(ctx, 'lockstep')
        ls_start_checks('b)', s)
        scmd(H, 'ls speed 3')
        ra, rb = ls_run_total(H, C, 3, H), ls_run_total(H, C, 2, C)
        hc = ls_compare(H, s['hm'], C, s['cm'], 'runs')
        check(f'c) runs asked by the host ({ra} minutes) and by the client ({rb}) at speed 3: every minute\'s state hash '
              f'is equal on both copies (>= 5 minutes), no DESYNC', hc['minutes'] >= 5 and not hc['differ']
              and not ls_lines(H, s['hm'], 'DESYNC'), hc)
        ls_orders_check('d)')
        ls_detach_check('d) detach')
        ls_guard_check('d) guard')
        ls_desync_check('e)', C)
        ls_end_refused_check('f)')
        ls_drop_checks(ctx, 'g)')
        v = nint(C, 1, 'ResearchPct')
        check(f'g) the client\'s plans survived its live battle: nation 1 ResearchPct {v} (planned {plan}; canLoad saved '
              f'slot 77 before the battle was loaded)', v == plan, v)
        closed = ls_finish_host(ctx)
        hn = ls_wait(lambda: (lambda n: n if n.get('slotMode') == '0' else None)(lsn(H)), 30, 'slot mode off')
        hst, hl = sstatus(H), log_since(H, s['hm'])
        check('h) the host\'s battle (alone) fought to its end on auto-run and closed without a month ("battle slot: '
              'DoStrategicTurn skipped", the date unchanged); battle slot mode off afterwards',
              closed and hn.get('slotMode') == '0' and hst.get('date') == date0
              and 'battle slot: DoStrategicTurn skipped' in hl, f'{hn} date {date0} -> {hst.get("date")}')

    ls_case(ctx, 'lockstep: a live test battle', battle)
    ls_quiet(ctx)
    ls_after_checks(ctx, 'i)')
    run_month(ctx, 'lockstep')
    hv, cv = nint(H, 1, 'ResearchPct'), nint(C, 1, 'ResearchPct')
    check(f'k) one normal month afterwards: the client\'s plans reached the host (nation 1 ResearchPct host {hv}, client '
          f'{cv}, planned {plan})', hv == cv == plan, f'{hv} {cv}')
    ls_log_scan('l)', marks0)


# ---------------------------------------------------------------- the battle screen's own controls (0.3.2 hotfix)
TOOL_AT = dict(fastest=(912 + 14, 5 + 14), aircraft=(1060 + 14, 5 + 14), autorun=AUTORUN_AT,
               strike=(1121 + 14, 5 + 14))  # TfrmMain.Panel1 buttons (strike: sbStrike, "Order an airstrike")
LANDCAP_AT = (760 + 14, 363 + 14)  # TdlgDivisionReport.sbLandCAP: a 28x28 TSpeedButton on the form (form resource)
SPEED_REQ_RE = r'lockstep: (.+) set the game speed to (-?\d+) \(from the next minute\)'
FASTEST_LINE = 'lockstep: Fastest available is not available in a live battle yet; use the speed box.'
AUTORUN_LINE = 'lockstep: Auto-run is not available in a live battle; use Run (until a break).'
LANDCAP_LINE = 'lockstep: sbLandCAPClick is not available in a live battle (this version).'
HIDDEN_RE = r'lockstep: (\w+) hidden before the battle is loaded again \((ok|FAILED)\)'
RESOLVED_RE = r'lockstep: battle dialogs resolved'
TVM_GETNEXTITEM, TVM_SELECTITEM, TVM_GETITEMW, TVM_EXPAND, TVM_ENSUREVISIBLE = 0x110A, 0x110B, 0x113E, 0x1102, 0x1114
TCM_SETCURFOCUS = 0x1330


def battle_frm(pid):
    return next((h for h in top_windows(pid) if e2e_test.class_name(h) == 'TfrmMain'), None)


def post_click(h, x, y):
    """A left click as posted mouse messages at a client point of a window (VCL hands them to the graphic control under
    the point). Never the real mouse."""
    lp = (y << 16) | (x & 0xFFFF)
    u.PostMessageW(h, 0x0200, 0, lp)  # WM_MOUSEMOVE
    u.PostMessageW(h, 0x0201, 1, lp)  # WM_LBUTTONDOWN (MK_LBUTTON)
    u.PostMessageW(h, 0x0202, 0, lp)  # WM_LBUTTONUP


def click_tool(pid, name):
    """A tool bar speed button of the battle screen (TOOL_AT: fastest, aircraft, autorun, strike), posted on Panel1."""
    frm = battle_frm(pid)
    p = battle_panel(frm) if frm else None
    if p:
        post_click(p, *TOOL_AT[name])
    return bool(p)


def click_arrow(pid, up):
    """The speed arrows next to the speed box (TfrmMain.UpDown1, a TUpDown window: its upper half is "up")."""
    frm = battle_frm(pid)
    h = next((c for c in children(frm) if e2e_test.class_name(c) == 'TUpDown'), None) if frm else None
    if h:
        r = _RECT()
        u.GetWindowRect(h, ctypes.byref(r))
        w, hh = r.right - r.left, r.bottom - r.top
        post_click(h, w // 2, hh // 4 if up else (3 * hh) // 4)
    return bool(h)


def battle_tree(pid):
    frm = battle_frm(pid)
    return next((c for c in children(frm) if e2e_test.class_name(c) == 'TTreeView'), None) if frm else None


def ob_tab(pid):
    """The left panel's "OB" tab (the ship tree) as a click shows it (TCM_SETCURFOCUS notifies the tab control). A
    hidden tree must not be selected: the game's tvShipsChange then raises "Cannot focus a disabled or invisible
    window.". Returns the tree if it is visible."""
    frm = battle_frm(pid)
    tc = next((c for c in children(frm) if e2e_test.class_name(c) == 'TTabControl'), None) if frm else None
    if tc is not None and _u32.SendMessageW(tc, TCM_GETCURSEL, 0, 0) != 0:
        _u32.SendMessageW(tc, TCM_SETCURFOCUS, 0, 0)
        time.sleep(0.5)
    tv = battle_tree(pid)
    return tv if tv is not None and u.IsWindowVisible(tv) else None


def tv_items(pid, tv, expand=False):
    """[dict(lvl, text, h, kids)] of a tree view in a game copy (TVM_GETNEXTITEM, TVM_GETITEMW through RemoteBuf; with
    `expand` a node with children is expanded first, as the game fills nodes when they expand)."""
    out = []

    def send(m, w, lp):
        return _u32.SendMessageW(tv, m, w, lp) & 0xFFFFFFFF

    with RemoteBuf(pid, 2048) as rb:
        def item(h):
            rb.write(0, struct.pack('<IIIIIiiiii', 0x41, h, 0, 0, rb.addr + 64, 255, 0, 0, 0, 0))  # TVIF_TEXT|CHILDREN
            _u32.SendMessageW(tv, TVM_GETITEMW, 0, rb.addr)
            kids = struct.unpack('<i', rb.read(32, 4))[0]
            return dict(h=h, kids=kids, text=rb.read(64, 512).decode('utf-16-le', 'replace').split('\x00')[0].strip())

        def walk(h, lvl):
            while h and len(out) < 500:
                it = item(h)
                it['lvl'] = lvl
                out.append(it)
                c = send(TVM_GETNEXTITEM, 4, h)  # TVGN_CHILD
                if not c and expand and it['kids']:
                    send(TVM_EXPAND, 2, h)  # TVE_EXPAND
                    c = send(TVM_GETNEXTITEM, 4, h)
                if c:
                    walk(c, lvl + 1)
                h = send(TVM_GETNEXTITEM, 1, h)  # TVGN_NEXT

        walk(send(TVM_GETNEXTITEM, 0, 0), 0)  # TVGN_ROOT
    return out


def tree_tops(pid):
    """The top nodes of a copy's ship tree (its forces, "<nation> Main force", ...), or None."""
    tv = battle_tree(pid)
    return [i['text'] for i in tv_items(pid, tv) if i['lvl'] == 0] if tv else None


def divreport(pid):
    return next((h for h in top_windows(pid) if e2e_test.class_name(h) == 'TdlgDivisionReport'), None)


def open_divreport(pid, k=0):
    """A division report as a player opens it: the "OB" tab, a division node of the ship tree selected (the first, or
    the k-th, counted round; TVM_SELECTITEM; the game's tvShipsChange follows), the tree's popup menu "Status..."
    (TfrmMain.Status1Click). Returns (the report window or None, description)."""
    tv = ob_tab(pid)
    if tv is None:
        return None, 'the ship tree is not shown'
    its = tv_items(pid, tv, expand=True)
    nodes = [i for i in its if i['lvl'] == 1]
    # (a coastal battery's node has the same menu, but its "Status..." opens no division report: dist_vp_2's probe)
    nodes = [i for i in nodes if ' Battery ' not in f' {i["text"]} '] or nodes
    node = nodes[k % len(nodes)] if nodes else None
    if node is None:
        return None, f'no division in the tree: {[i["text"] for i in its][:6]}'
    _u32.SendMessageW(tv, TVM_ENSUREVISIBLE, 0, node['h'])
    _u32.SendMessageW(tv, TVM_SELECTITEM, 9, node['h'])  # TVGN_CARET
    time.sleep(0.4)
    r = popup_pick(pid, tv, 'Status...')
    d = wait_until(lambda: divreport(pid), lambda v: v is not None, 5)
    return d, f'{node["text"]!r}: {r}'


REPORT_SPEED_RE = (r"lockstep: the division report lowered (.+)'s current speed (-?\d+) -> (-?\d+) on this PC only: put "
                   r"back \(the next minute lowers it on both PCs\)")  # 0.3.3 (accec95)
TEST_SPEED = 45  # knots for `ls testcurspeed`: above every ship's maximum, as a worse weather leaves a ship's speed


def dump_file(port):
    """A path for a copy's `pocdump` without spaces (the bridge splits its arguments at spaces): the Windows temp folder
    (by its short name if it has a space), or None."""
    d = tempfile.gettempdir()
    if ' ' in d:
        b = ctypes.create_unicode_buffer(600)
        if ctypes.windll.kernel32.GetShortPathNameW(d, b, 600):
            d = b.value
    p = os.path.join(d, f'rtw3mp_regression_dump_{port}.txt')
    return None if ' ' in p else p


def pocdump_text(port):
    """A copy's `pocdump` (the hashed fields per division and ship, read only) as text ('' if it can't be read). The
    dump file is deleted at once."""
    p = dump_file(port)
    if not p:
        return ''
    try:
        if scmd(port, f'pocdump {p}') != 'ok':
            return ''
        with open(p, 'rb') as f:
            return f.read().decode('utf-8', errors='replace')
    except OSError:
        return ''
    finally:
        try:
            os.remove(p)
        except OSError:
            pass


def battle_ships(port):
    """{division index: [dict(name, sunk, speed)]} of a copy's battle (`pocdump`: the hashed fields per division and ship,
    read only; speed = CurrentSpeed in knots), {} if it can't be read. The dump file is deleted at once."""
    out = {}
    for ln in pocdump_text(port).splitlines():
        m = re.match(r'\s+S(\d+)\.\d+ (.+?) ShipLocation=', ln)
        sp, sunk = re.search(r' CurrentSpeed=([0-9a-f]{8})\b', ln), re.search(r' Sunk=([0-9a-f]{2})\b', ln)
        if m and sp:
            out.setdefault(int(m[1]), []).append(dict(name=m[2], sunk=bool(sunk and sunk[1] != '00'),
                                                      speed=int.from_bytes(bytes.fromhex(sp[1]), 'little', signed=True)))
    return out


def div_positions(port):
    """{division index: [(lat, lon) of its ships afloat]} of a copy's battle (`pocdump`'s ShipLocation: two int32,
    longitude first, in 1/5,400,000 degree), {} if it can't be read."""
    out = {}
    for ln in pocdump_text(port).splitlines():
        m = re.match(r'\s+S(\d+)\.\d+ .+? ShipLocation=([0-9a-f]{16})\b', ln)
        sunk = re.search(r' Sunk=([0-9a-f]{2})\b', ln)
        if m and not (sunk and sunk[1] != '00'):
            lon, lat = struct.unpack('<ii', bytes.fromhex(m[2]))
            out.setdefault(int(m[1]), []).append((lat / 5.4e6, lon / 5.4e6))
    return out


def bearing_nm(a, b):
    """The initial bearing (whole degrees) and the distance (nautical miles) from a to b ((lat, lon) in degrees)."""
    la1, lo1, la2, lo2 = map(math.radians, (a[0], a[1], b[0], b[1]))
    y = math.sin(lo2 - lo1) * math.cos(la2)
    x = math.cos(la1) * math.sin(la2) - math.sin(la1) * math.cos(la2) * math.cos(lo2 - lo1)
    h = math.sin((la2 - la1) / 2) ** 2 + math.cos(la1) * math.cos(la2) * math.sin((lo2 - lo1) / 2) ** 2
    return round((math.degrees(math.atan2(y, x)) + 360) % 360) % 360, 2 * 3440 * math.asin(min(1.0, math.sqrt(h)))


def ship_index(port, name, count):
    """The index of a ship (by name) in a copy's all-ships list, found with `ls testcurspeed` (its reply names the ship):
    each index tried gets its own speed back at once, so the copy's state does not change (between minutes only); the
    ship found keeps TEST_SPEED. Returns (index, its speed before) or (None, the last reply)."""
    r = ''
    for i in range(count):
        r = scmd(port, f'ls testcurspeed {i} {TEST_SPEED}')
        m = re.match(r'^ok ship=(.*) was=(-?\d+)$', r)
        if not m:
            return None, r
        if m[1] == name:
            return i, int(m[2])
        scmd(port, f'ls testcurspeed {i} {m[2]}')
    return None, r


def testcur_leak(line):
    """A LEAK line naming only the sighting guard's fields (group sight: SightingLevel, RadarSightingLevel): `ls
    testcurspeed` re-baselines the leak check between minutes while this PC's display set of those fields is in place,
    so where the display's sighting differs from the simulation's (an enemy ship seen otherwise here, e.g. at dawn) the
    next step reports a LEAK that is the test command's own (2026-10-18, dist_vp_2; reported, test-only)."""
    m = re.search(r'LEAK the simulation state changed outside the simulation \(sight\) .*?; display routines in between: '
                  r'[^;]*;(.*)$', line)
    fields = re.findall(r'\.(\w+) [0-9a-f]+->[0-9a-f]+', m[1]) if m else []
    return bool(fields) and all(f in ('SightingLevel', 'RadarSightingLevel') for f in fields)


def divreport_speed_check(ctx, tag, port, pid):
    """0.3.3 (accec95): a division report opened in a live battle no longer lowers ships' current speed on that copy only
    (TdlgDivisionReport.FillShipList clamps every listed ship's CurrentSpeed to its maximum in this weather: up to 0.3.2
    a `LEAK <ship>.CurrentSpeed`, a DESYNC and a resync). A ship of the division the copy's report shows (its ship
    tree's first division, open_divreport) gets a speed above its maximum on both copies (`ls testcurspeed <index> 45`,
    as a worse weather leaves a ship); the copy opens the report: it logs "the division report lowered <ship>'s current
    speed 45 -> n on this PC only: put back ...", the other copy logs none; with the report open the ship keeps 45 on
    both and `ls hash` (all, ident) is equal (if opening the report gave the division an order, "orders #n (paused",
    only `ord` may differ until the next minute applies it on both); report closed, 3 minutes: equal, no DESYNC, no
    LEAK, and the ship below 45
    on both copies again (the simulation's own ChangeSpeed, the same on both)."""
    other, who, side = (C, 'host', 0) if port == H else (H, 'client', 1)
    ls_wait(lambda: ls_idle_equal(H, C), 60, f'{tag}: both idle at a boundary')
    close_modeless(pid)
    tv = ob_tab(pid)
    node = next((i for i in (tv_items(pid, tv, expand=True) if tv else []) if i['lvl'] == 1), None)
    dname = re.sub(r' \([^()]*\)$', '', node['text']) if node else None
    divs = [d for d in ls_divs(port) if d['side'] == side]
    div = next((d for d in divs if d['name'] == dname), None) or \
        next((d for d in divs if dname and dname.startswith(d['name'])), None)
    ships = battle_ships(port).get(div['i']) if div else None
    ship = next((s for s in ships or [] if not s['sunk']), None)
    count = int(pst(port).get('allships') or 0)
    idx, was = ship_index(port, ship['name'], count) if ship else (None, None)
    if idx is None:
        return check(f'{tag}: a ship afloat in the {who}\'s first division (its ship tree) for the division report test',
                     False, f'node {node and node["text"]!r}; division {div}; ships {ships}; all-ships {count}; {was}')
    ro = scmd(other, f'ls testcurspeed {idx} {TEST_SPEED}')
    ma, mb = log_mark(H), log_mark(C)
    mp, mo = (ma, mb) if port == H else (mb, ma)
    d, how = open_divreport(pid)
    put = wait_until(lambda: [x for x in ls_lines(port, mp, REPORT_SPEED_RE) if re.search(REPORT_SPEED_RE, x)[1]
                              == ship['name']], bool, 6)
    time.sleep(0.5)
    speed = {who_of(p): next((s['speed'] for s in battle_ships(p).get(div['i'], []) if s['name'] == ship['name']), None)
             for p in (H, C)}
    ha, hb = kvs(scmd(H, 'ls hash')), kvs(scmd(C, 'ls hash'))
    # Opening the report can give the division an order on that copy (e.g. its speed order lowered to the weather's
    # maximum: "orders #n (paused, ...)"): sent to the other copy and applied by both from the next minute, so until then
    # the `ord` group (and `all`) may differ; every other group must not.
    orders = ls_lines(port, mp, r'lockstep: orders #\d+ \(paused')
    rest = ('pos', 'dmg', 'ammo', 'sight', 'ident', 'air', 'torp', 'ships', 'sunk', 'divs', 'af', 'torps', 'rng')
    same = bool(ha.get('all')) and (ha.get('all') == hb.get('all') or bool(orders) and all(
        ha.get(g) is not None and ha.get(g) == hb.get(g) for g in rest))
    hdiff = [g for g in ('ord',) + rest if ha.get(g) != hb.get(g)]
    close_modeless(pid)
    ran = ls_run_total(H, C, 3, H)
    hc = ls_compare(H, ma, C, mb, f'{tag} after the report')
    des = ls_lines(H, ma, r'DESYNC|Synchronising the battle again')
    leaks = {who_of(p): ls_lines(p, m, LS_LEAK_RE) for p, m in ((H, ma), (C, mb))}
    # (the first LEAK of a copy after the test's own writes, when it names only the sighting guard's fields, is the
    # test command's baseline: testcur_leak; any other LEAK fails)
    art = {w: [x for x in v[:1] if testcur_leak(x)] for w, v in leaks.items()}
    leaks = {w: [x for x in v if x not in art[w]] for w, v in leaks.items()}
    for v in art.values():  # (the scenario's own leak scan excuses them too: ls_log_scan, ll_scan_text)
        LS_EXCUSED.update(v)
        LS_EXCUSED.update(x.split('] ', 1)[-1] for x in v)
    elsewhere = ls_lines(other, mo, REPORT_SPEED_RE)
    after = {who_of(p): next((s['speed'] for s in battle_ships(p).get(div['i'], []) if s['name'] == ship['name']), None)
             for p in (H, C)}
    low = re.search(REPORT_SPEED_RE, put[0]) if put else None
    return check(f'{tag}: a division report opened on the {who} ({how}) in a live battle: {ship["name"]} (all-ships index '
                 f'{idx}, {was} knots) set to {TEST_SPEED} on both copies (`ls testcurspeed`); the {who} logs "the '
                 f'division report lowered {ship["name"]}\'s current speed {TEST_SPEED} -> n on this PC only: put back", '
                 f'the other copy no such line; with the report open {TEST_SPEED} on both and `ls hash` all/ident equal '
                 f'(only `ord` may differ while an order the report gave is pending: "orders #n (paused"); '
                 f'then {ran} minutes equal, no DESYNC, no LEAK, and the ship below {TEST_SPEED} knots on both (0.3.2: the '
                 f'report lowered it on one copy: LEAK <ship>.CurrentSpeed, DESYNC)',
                 d is not None and ro == f'ok ship={ship["name"]} was={was}' and low
                 and int(low[2]) == TEST_SPEED and int(low[3]) < TEST_SPEED and not elsewhere
                 and speed == {'host': TEST_SPEED, 'client': TEST_SPEED} and same
                 and ha.get('ident') == hb.get('ident') and ran >= 3 and hc['minutes'] >= 3 and not hc['differ']
                 and not hc['ident_differ'] and not des and not any(leaks.values()) and after['host'] is not None
                 and after['host'] == after['client'] and after['host'] < TEST_SPEED,
                 f'other copy {ro}; {put[:2]}; elsewhere {elsewhere[:2]}; open {speed}; ls hash all {ha.get("all")}/'
                 f'{hb.get("all")} ident {ha.get("ident")}/{hb.get("ident")} groups that differ {hdiff}; '
                 f'orders {orders[:2]}; hashes {hc}; {des[:2]}; LEAK '
                 f'{ {w: v[:2] for w, v in leaks.items() if v} }; the test command\'s own sighting LEAK '
                 f'{ {w: v[:1] for w, v in art.items() if v} }; after {after}')


def lsctl(port, cls, fld):
    """`ls ctl <form class> <field>` (0.3.2): {class, enabled, visible[, down, group][, hint]} ({} on an error; the hint,
    the last field, with its spaces)."""
    r = scmd(port, f'ls ctl {cls} {fld}')
    head, sep, hint = r.partition(' hint=')
    d = kvs(head)
    if sep and d:
        d['hint'] = hint
    return d


def airwin(port, show=False):
    """`ls airwin [show]` (0.3.2): {visible, items, af0, af1, afx, rows: [[col0, col1, col2], ...]}, or {error}."""
    r = scmd(port, 'ls airwin' + (' show' if show else ''))
    if not r.startswith('ok'):
        return dict(error=r, rows=[])
    head, *rows = r.split(' |')
    d = kvs(head)
    d['rows'] = [x.strip().split('~') for x in rows]
    return d


def air_rows(pid):
    """Every column of the "Air formations" window's list (TdlgShowAirFormations.lvAirFormations) of a copy, read
    cross-process (lv_rows): [[type and name, numbers, mission, base, status, ...]], or None if it is not open."""
    w = next((h for h in top_windows(pid) if e2e_test.class_name(h) == 'TdlgShowAirFormations'), None)
    lv = next((c for c in children(w) if e2e_test.class_name(c) == 'TListView'), None) if w else None
    return [r[2] for r in lv_rows(pid, lv, 6)] if lv else None


def close_modeless(pid, passes=4):
    """Close the battle screen's tool windows and dialogs of a copy (Close/Cancel; WM_CLOSE otherwise). Again while one
    stays visible (up to `passes`): a dialog under another one (the division report under its torpedo dialog) is
    disabled and takes no click until the top one closed. A popup menu left open is closed first (close_menus).
    Returns how many were closed."""
    n = len(open_menus(pid))
    if n:
        close_menus(pid)
    for k in range(passes):
        hs = [h for h in top_windows(pid) if e2e_test.class_name(h) in LS_MODELESS and (k == 0 or u.IsWindowVisible(h))]
        if not hs:
            break
        for h in hs:
            b = dlg_buttons(h)
            btn = b.get('close') or b.get('cancel')
            u.PostMessageW(btn, 0x00F5, 0, 0) if btn else u.PostMessageW(h, 0x0010, 0, 0)  # BM_CLICK / WM_CLOSE
        n += len(hs)
        time.sleep(1)
    return n


def panel_locked(port):
    """The missile panel's "Fire at will" and "Fire mode" disabled on a copy (`ls ctl`, 0.3.2 and 0.4.0): (ok, detail).
    Since engine level 9 only "Fire mode" stays disabled: see fire_panel."""
    a, b = lsctl(port, 'TfrmMain', 'cbFireAtWill'), lsctl(port, 'TfrmMain', 'rgMissileDoctrine')
    return a.get('enabled') == '0' and b.get('enabled') == '0', \
        f'cbFireAtWill {a.get("enabled")}/{a.get("visible")} rgMissileDoctrine {b.get("enabled")}/{b.get("visible")}'


def fire_panel(port, side, want=None):
    """The missile panel of a copy in a live battle since engine level 9: "Fire mode" (rgMissileDoctrine) disabled,
    "Fire at will" (cbFireAtWill) enabled and showing this copy's own side's setting (`ls missilestat`: box = faw[side],
    the agreed values = the copy's own, the feature on); `want` = the expected faw of both sides (e.g. '11'). (ok,
    faw, detail)."""
    a, b = lsctl(port, 'TfrmMain', 'cbFireAtWill'), lsctl(port, 'TfrmMain', 'rgMissileDoctrine')
    ms = parse_missilestat(scmd(port, 'ls missilestat'))
    faw = ms.get('faw', '')
    hints = (a.get('hint') or '').startswith(HINT_FAW) and (b.get('hint') or '').startswith(HINT_FIRE_MODE)
    ok = a.get('enabled') == '1' and b.get('enabled') == '0' and len(faw) == 2 and ms.get('agreed') == faw \
        and ms.get('box') == faw[side] and ms.get('boxEnabled') == '1' and (ms.get('feature') or '')[:1] == '1' \
        and (want is None or faw == want) and hints
    return ok, faw, (f'cbFireAtWill {a.get("enabled")}/{a.get("visible")} rgMissileDoctrine {b.get("enabled")}/'
                     f'{b.get("visible")}; faw {faw} agreed {ms.get("agreed")} box {ms.get("box")} boxEnabled '
                     f'{ms.get("boxEnabled")} feature {ms.get("feature")}; hints {a.get("hint", "-")[:40]!r} / '
                     f'{b.get("hint", "-")[:40]!r}')


HINT_FIRE_MODE = ('Fire mode: the game applies it to one side only, so in a live battle the computer sets the salvo size '
                  'of both sides\' automatic fire alike.')
HINT_FAW = 'Fire at will: your own missile ships fire on their own (the computer\'s rules), from the next minute.'


def panel_check(tag, when, want='11', A=H, B=C):
    """fire_panel on both copies (A side 0, B side 1), the same Fire at will values on both."""
    pa, pb = fire_panel(A, 0, want), fire_panel(B, 1, want)
    return check(f'{tag}: the missile panel {when} (engine level 9): "Fire mode" disabled on both copies with its hint '
                 f'("Fire mode: the game applies it to one side only, so ..."), "Fire at will" enabled with its hint and '
                 f'showing each copy\'s own side\'s setting (`ls missilestat` box = faw[side], the agreed values), faw '
                 f'{want} on both', pa[0] and pb[0] and pa[1] == pb[1],
                 f'host {pa[2]}; client {pb[2]}')


def autorun_button_check(ctx, tag, who, port, pid, side, A=H, B=C):
    """The battle screen's Auto-run button of one player in a live battle (engine level 4, posted clicks; the copy is
    out of the dialog answerer meanwhile, which would answer the game's question): the click shows the game's question
    (TdlgEventAnswer); "No" orders nothing; "Yes" orders auto-run, and the next release hands that side to the computer
    on both copies (its divisions on the AI, the clicked copy's button down, the chats; the game's own AutoRunBattle flag
    stays off; side 0: the simulation's PlayerSide 2); the button again, "Yes" (take back), gives the side back at the
    next release."""
    other = B if port == A else A
    sim_on = '2' if side == 0 else '0'
    n_side = None
    with ll_noans(ctx, pid):
        # 1) the question answered "No": nothing ordered
        m = log_mark(port)
        c1 = click_tool(pid, 'autorun')
        radios, title, p1 = ll_answer_question(pid, 'No')
        time.sleep(1.0)
        q1 = [x for x in ls_lines(port, m, AUTORUN_Q_RE)]
        pend1 = [p for p in parse_pending(scmd(port, 'ls pending')) if p['kind'] == 'autorun']
        ar1, btn1 = kvs(scmd(port, 'ls autorun')), lsctl(port, 'TfrmMain', 'sbAutoRunBattle')
        check(f'{tag}: Auto-run clicked on the {who}: the game\'s question ({title!r}: {radios}) answered "No": '
              f'`auto-run question (hand over) answered 3`, nothing ordered (`ls pending`), `ls autorun` mine=0, the '
              f'button up (down=0)', c1 and p1 and len(radios) == 3 and q1 == ['lockstep: auto-run question (hand over) '
                                                                              'answered 3'] and not pend1
              and ar1.get('mine') == '0' and btn1.get('down') == '0',
              f'clicked {c1}; {q1}; pending {pend1}; autorun {ar1}; button {btn1}')
        # 2) "Yes": ordered, then carried out at the release on both copies
        m, ma, mb = log_mark(port), log_mark(A), log_mark(B)
        click_tool(pid, 'autorun')
        radios, title, p2 = ll_answer_question(pid, 'Yes')
        time.sleep(1.0)
        q2 = ls_lines(port, m, AUTORUN_Q_RE)
        said = ls_lines(port, m, r'lockstep: Auto-run on ordered; it takes effect when the next minute starts\.')
        pend2 = [p for p in parse_pending(scmd(port, 'ls pending')) if p['kind'] == 'autorun']
        ll_release(A, B)
        rel_a, rel_b = ls_lines(A, ma, AUTORUN_REL_RE), ls_lines(B, mb, AUTORUN_REL_RE)
        ara, arb = kvs(scmd(A, 'ls autorun')), kvs(scmd(B, 'ls autorun'))
        btn, btn_o = lsctl(port, 'TfrmMain', 'sbAutoRunBattle'), lsctl(other, 'TfrmMain', 'sbAutoRunBattle')
        aic = {who_of(p): ai_count(p) for p in (A, B)}
        n_side = aic['host'][side][1]
        mine_chat = ls_lines(port, m, r'lockstep: The computer commands your ships now \(auto-run\)\. Press Auto-run '
                                      r'again to take them back\.')
        peer_chat = ls_lines(other, ma if other == A else mb, r'lockstep: \S+ handed their ships to the computer '
                                                              r'\(auto-run\)\.')
        side_ai = [ls_lines(p, mk, rf'lockstep: side {side} ai=1 human=0 ') for p, mk in ((A, ma), (B, mb))]
        sims = (kvs(scmd(A, 'ls simside')).get('sim'), kvs(scmd(B, 'ls simside')).get('sim'))
        auto = '10' if side == 0 else '01'
        check(f'{tag}: Auto-run clicked on the {who}, the question answered "Yes": `auto-run question (hand over) '
              f'answered 1` and the chat "Auto-run on ordered; ..." on that copy, the order pending until the release; '
              f'at the release both copies log `auto-run on for side {side} ... auto-run {auto}` and `side {side} ai=1 '
              f'human=0`, `ls autorun` auto{side}=1 on both, all {n_side} divisions of side {side} on the AI on both, the '
              f'clicked copy\'s button down (the other\'s up), the chats on both copies, the simulation\'s PlayerSide '
              f'{sim_on} on both, the game\'s own auto-run flag off (pocstate autorun=0)', p2 and q2 == [
                  'lockstep: auto-run question (hand over) answered 1'] and said and len(pend2) == 1
              and len(rel_a) == len(rel_b) == 1 and f'auto-run on for side {side} ' in rel_a[0] and rel_a[0].endswith(
                  f'auto-run {auto})') and rel_a == rel_b
              and ara.get(f'auto{side}') == arb.get(f'auto{side}') == '1' and all(v[side][0] == v[side][1] > 0
                                                                                   for v in aic.values())
              and btn.get('down') == '1' and btn_o.get('down') == '0' and mine_chat and peer_chat
              and all(side_ai) and sims == (sim_on, sim_on) and pst(port).get('autorun') == '0',
              f'{q2} {said[:1]} pending {pend2}; A {rel_a} B {rel_b}; autorun A {ara} B {arb}; divisions on the AI '
              f'{aic}; buttons {btn.get("down")}/{btn_o.get("down")}; chats {mine_chat[:1]} {peer_chat[:1]}; side lines '
              f'{[len(x) for x in side_ai]}; sim {sims}')
        ma2, mb2 = log_mark(A), log_mark(B)
        ls_run(A, B, 1, A)
        ll_minutes_check(tag, f'side {side} on auto-run', A, ma, B, mb, 2)
        # 3) the button again: "Take back command of your ships?" Yes: side back to its player at the release
        m = log_mark(port)
        click_tool(pid, 'autorun')
        radios, title, p3 = ll_answer_question(pid, 'Yes')
        time.sleep(1.0)
        q3 = ls_lines(port, m, AUTORUN_Q_RE)
        m3a, m3b = log_mark(A), log_mark(B)
        ll_release(A, B)
        back_l = [[re.search(AUTO_OFF_RE, x).groups() for x in ls_lines(p, mk, AUTO_OFF_RE)] for p, mk in
                  ((A, m3a), (B, m3b))]
        rel_a, rel_b = ls_lines(A, ma2, AUTORUN_REL_RE), ls_lines(B, mb2, AUTORUN_REL_RE)
        aic = {who_of(p): ai_count(p) for p in (A, B)}
        btn = lsctl(port, 'TfrmMain', 'sbAutoRunBattle')
        back = ls_lines(port, m, r'lockstep: You command your ships again \(auto-run off\)\.')
        peer_back = ls_lines(other, ma2 if other == A else mb2, r'lockstep: \S+ commands their ships again \(auto-run '
                                                                r'off\)\.')
        sims = (kvs(scmd(A, 'ls simside')).get('sim'), kvs(scmd(B, 'ls simside')).get('sim'))
        check(f'{tag}: the {who}\'s Auto-run again, "Take back command of your ships?" answered "Yes" ({radios}): '
              f'`auto-run question (take back) answered 1`; at the release `auto-run off for side {side} ... auto-run 00` '
              f'on both copies and, as in single player (engine level 12), "side {side} back to its player as in single '
              f'player: the lead divisions of <n> forces; <k> forces stay with the computer as before auto-run; <d> '
              f'divisions stay with the computer ..." alike on both copies, the divisions on the AI equal on both copies, '
              f'the player\'s chat "... As in single player, you get each force\'s lead division back (<n>) ...", the '
              f'button up, the chats, the '
              f'simulation\'s PlayerSide 0 on both', p3 and len(radios) == 2 and q3 == [
                  'lockstep: auto-run question (take back) answered 1'] and len(rel_a) == len(rel_b) == 1 and rel_a == rel_b
              and f'auto-run off for side {side} ' in rel_a[0] and rel_a[0].endswith('auto-run 00)')
              and len(back_l[0]) == 1 and back_l[0] == back_l[1] and back_l[0][0][0] == str(side)
              and aic['host'] == aic['client'] and btn.get('down') == '0' and back and peer_back
              and ls_lines(port, m, r'lockstep: You command your ships again \(auto-run off\)\. As in single player, you '
                                    r'get each force\'s lead division back \(\d+\)')
              and sims == ('0', '0'), f'{q3}; A {rel_a} B {rel_b}; {aic}; button {btn}; {back[:1]} {peer_back[:1]}; '
                                      f'sim {sims}')


def fastest_click_check(ctx, tag, who, port, pid, on, A=H, B=C):
    """"Fastest available" as a shared clock control (engine level 2): a posted click on a player's tool bar button asks
    A's clock: the request "<side> turned Fastest available on|off (from the next minute)." on both copies, the clicked
    copy's button shows the state in effect until the release (put back at once), A's `ls fastest` want=<new>; from the
    next minute both copies have it (pocstate fastest, `ls fastest` fastest/down, `Fastest available on|off` logged on
    both), the same speed on both, no DESYNC."""
    ma, mb = log_mark(A), log_mark(B)
    f0 = (pst(A).get('fastest'), pst(B).get('fastest'))
    want = '1' if on else '0'
    clicked = click_tool(pid, 'fastest')
    ra = wait_until(lambda: ls_lines(A, ma, FASTEST_REQ_RE), bool, 8)
    rb = wait_until(lambda: ls_lines(B, mb, FASTEST_REQ_RE), bool, 8)
    time.sleep(0.5)
    held = lsctl(port, 'TfrmMain', 'sbFastestAvailable').get('down')
    want_a = kvs(scmd(A, 'ls fastest')).get('want')
    ls_run(A, B, 1, A)
    fa, fb = kvs(scmd(A, 'ls fastest')), kvs(scmd(B, 'ls fastest'))
    pa, pb = pst(A), pst(B)
    s1 = (pa.get('speed'), pb.get('speed'))
    applied = [ls_lines(p, mk, rf'lockstep: Fastest available {"on" if on else "off"}$') for p, mk in ((A, ma), (B, mb))]
    des = ll_desyncs(A, ma)
    word = 'on' if on else 'off'
    return check(f'{tag}: "Fastest available" clicked on the {who} (Fastest {f0} before): one request "... turned Fastest '
                 f'available {word} (from the next minute)." on both copies, the clicked button put back to the state in '
                 f'effect ({f0[0]}) until the release, A wants {want}; after the next minute both copies have it {word} '
                 f'(pocstate fastest, `ls fastest` fastest and down, "Fastest available {word}" logged), the same speed '
                 f'on both, no DESYNC', clicked and len(ra) == len(rb) == 1 and ra[0].endswith(f'{word} (from the next '
                                                                                             f'minute).')
                 and held == f0[0] and want_a == want and fa.get('fastest') == fb.get('fastest') == want
                 and fa.get('down') == fb.get('down') == want and pa.get('fastest') == pb.get('fastest') == want
                 and all(applied) and s1[0] == s1[1] and not des,
                 f'clicked {clicked}; requests A {ra} B {rb}; button {held}; want {want_a}; after A {fa} B {fb}; pocstate '
                 f'{pa.get("fastest")}/{pb.get("fastest")}; applied {[len(x) for x in applied]}; speeds {s1}; {des[:2]}')


def speeds(A=H, B=C):
    return pst(A).get('speed'), pst(B).get('speed')


def ai_count(port):
    """{side: (divisions on the AI, divisions)} of a copy's live battle (`ls divs`)."""
    ds = ls_divs(port)
    return {s: (sum(1 for d in ds if d['side'] == s and d['ai']), sum(1 for d in ds if d['side'] == s)) for s in (0, 1)}


def teardown_lines(port, mark):
    """0.3.2: the game's battle teardown before every reload: [(ok, formations left)] from `battle data cleared (ok),
    air formations left <n>`."""
    return [(m[1] == 'ok', int(m[2])) for m in re.finditer(r'lockstep: battle data cleared \((\w+)\), air formations left '
                                                            r'(-?\d+)', log_since(port, mark))]


def arrow_check(ctx, tag, who, up, running, A=H, B=C):
    """One click on a copy's speed arrow (posted on its TUpDown), between minutes or while a minute runs: a shared speed
    request ("<nation> set the game speed to N (from the next minute)" on both copies, N one step from the speed in
    use), the speed in use unchanged while the minute runs, both copies at N in the next minute, no DESYNC (0.3.1: the
    clicked copy changed its own speed at once, also inside a minute -> DESYNC and a resync). Returns N or None."""
    port, pid = (A, ctx.hp) if who == 'host' else (B, ctx.cp)
    ma, mb, e0 = log_mark(A), log_mark(B), lss(A).get('epoch')
    s0, mid = speeds(A, B), None
    if running:
        scmd(A, 'ls run 1')
        ls_wait(lambda: lss(port).get('running') == '1', 30, f'a minute runs on the {who}', step=0.05)
    clicked = click_arrow(pid, up)
    req = wait_until(lambda: ls_lines(A, ma, SPEED_REQ_RE), bool, 8)
    if running:
        mid = (lss(port).get('running'), speeds(A, B))
    reqb = wait_until(lambda: ls_lines(B, mb, SPEED_REQ_RE), bool, 8)
    ls_wait(lambda: ls_idle_equal(A, B) or ls_over(A), 120, 'the boundary after the click')
    n = int(re.search(SPEED_REQ_RE, req[-1])[2]) if req else None
    ls_run(A, B, 1, A)
    s1 = speeds(A, B)
    des = ls_lines(A, ma, r'DESYNC|Synchronising the battle again')
    hc = ls_compare(A, ma, B, mb, tag)
    want = int(s0[0]) + (1 if up else -1) if (s0[0] or '').lstrip('-').isdigit() else None
    ok = clicked and len(req) == 1 and len(reqb) == 1 and n == want and s1 == (str(n), str(n)) and not des \
        and hc['minutes'] >= 1 and not hc['differ'] and lss(A).get('epoch') == e0 \
        and (mid is None or (mid[0] == '1' and mid[1] == s0))
    check(f'{tag}: the {who}\'s speed arrow {"up" if up else "down"} ({"while a minute runs" if running else "between minutes"}'
          f'): one shared request "... set the game speed to {want} (from the next minute)" on both copies'
          + (', the minute in progress went on at the old speed on both' if running else '')
          + f', both at {want} in the next minute, no DESYNC', ok,
          f'clicked {clicked}; speed {s0} -> {s1}; request A {req[-1:] or req} B {reqb[-1:] or reqb}; inside the minute '
          f'{mid}; {des[:2]}; hashes {hc}; epoch {e0} -> {lss(A).get("epoch")}')
    return n


def scenario_lockstep_ui(ctx):
    """0.3.2 hotfix, updated to engine level 11 (0.4.0): the battle screen's own controls in a live battle (the 1900
    fixture's test battle `pocbattle 1 0`: host A, side 0; client B, side 1). a) start: both running, the battle dialogs'
    variables resolved once per copy; B's ship tree ("OB" tab) lists B's own forces; the missile panel: "Fire mode"
    disabled, "Fire at will" each copy's own side's (level 9). b) the speed arrows (UpDown1Click, posted clicks on the
    TUpDown) of B and of A, up and down, between minutes and in the middle of a running minute: each one shared request,
    the same speed on both copies from the next minute, no DESYNC; two quick clicks on B step from the pending speed.
    c) Auto-run per player (level 4) on B and on A (posted tool bar clicks, the game's question answered by the test):
    "No" orders nothing; "Yes" hands the side to the computer at the next release on both copies; the button again
    ("take back") gives it back. d) "Fastest available" as a shared clock control (level 2): B's click turns it on for
    both from the next minute, a resync keeps it, A's click turns it off, A's `ls fastest 1` and then A's speed box
    (`ls speed 3`) releases it. e) 14 minutes with every division on the AI (contact): no DESYNC, Fastest off, the speeds
    equal; B's arrow up while engaged at speed 3 asks for nothing (the game's own rule); the missile panel per side.
    f) the air formations window (`ls airwin show`: no aircraft in 1900) and a division report (OB tab, the tree's
    "Status...") open on both copies since the start (the auto-run questions of c) do not close them); the report's
    land-CAP button put up again after a blocked click (1900: no airfield, so no land CAP); `ls resync` with both open on
    both copies: "<class> hidden before the battle is loaded again (ok)" for both on each copy, no crash, both running,
    the air window opens again; the land-CAP click + the report's Ok then 2 minutes equal; the missile panel per side
    after the resync. g) B's ship tree lists only B's own forces after each minute and after the reload (0.3.1/0.3.2:
    side 0's after every minute); every minute's `date=` the campaign's own (its `ident=` goes to the scan's
    identification check). k) 0.3.3: a division report's speed write (divreport_speed_check: `ls testcurspeed` 45 on a
    ship of the report's division on both copies, the client's report, then the host's: the put-back line on that copy
    only, equal hashes, no LEAK). h) the host drops the client and finishes alone; after-checks (the identification:
    every live load logged its line, `ident=` equal at READY and in every minute); no lockstep error, no LEAK."""
    marks0 = {H: log_mark(H), C: log_mark(C)}
    ls_ensure_session(ctx)
    hs, cs = lsn(H), lsn(C)
    if not check('a) both copies offer live battles and the host lists Captain(1,b,ls)', hs.get('available') == '1'
                 and cs.get('available') == '1' and 'Captain(1,b,ls)' in hs.get('players', ''), f'host {hs}; client {cs}'):
        return
    names = nation_table(H)
    n0, n1 = names.get(0, {}).get('name', '?'), names.get(1, {}).get('name', '?')
    trees = {}

    def battle():
        s = ls_start_test(ctx, 'lockstep_ui')
        snaps = [('the start', s['gen1'])]  # slot 1's [General] in each snapshot of A (the campaign date, 0.3.2)
        a0 = ls_wait(lambda: (lambda a: a if a.get('verified') not in (None, '-1') else None)(lss(H)), 30,
                     'A verified the start')
        res = {p: [x for x in log_lines(log_since(p), RESOLVED_RE)] for p in (H, C)}
        check(f'a) the live test battle runs on both copies ({s["dt"]:.0f} s; A verified the start); each copy logged '
              f'"battle dialogs resolved" once (0.3.2: the modeless battle dialogs are found once per process)', a0
              and all(len(v) == 1 for v in res.values()), f'verified {a0.get("verified") if a0 else None}; {res}')
        miss = {who_of(p): v[0].split('not found:', 1)[1].strip() for p, v in res.items() if v and 'not found' in v[0]}
        check('a) every modeless battle dialog the reloads hide was found ("battle dialogs resolved" without "not '
              'found"); a dialog not found is never hidden before a reload', not miss, f'not found {miss}')
        trees['load'] = tree_tops(ctx.cp)
        panel_check('a)', 'after the load')
        # report only (0.4.0 material, MODLOG 2026-10-17): does a resync hand side 1's divisions to the AI? And the
        # private memory a load costs
        before, mem0 = {who_of(p): ai_count(p) for p in (H, C)}, mem(ctx)
        e0 = int(lss(H).get('epoch') or 0)
        scmd(H, 'ls resync')
        ls_wait(lambda: int(lss(H).get('epoch') or 0) > e0 and ls_idle_equal(H, C), 150, 'the first resync')
        ls_ready(H, C, 'lockstep_ui a) the first resync')
        snaps.append(('the first resync', gen_date(HOST_SLOT)))
        after, mem1 = {who_of(p): ai_count(p) for p in (H, C)}, mem(ctx)
        log(f'  NOTE a) (not checked in 0.3.2) divisions on the AI per side (on the AI, all) before a resync {before}, '
            f'after it {after}; private memory host/client before {mem0} MB, after {mem1} MB')
        trees['resync0'] = tree_tops(ctx.cp)
        # a division report on each copy, opened while the trees list the own side (right after a load); they stay open
        rep = {who_of(p): open_divreport(pid) for p, pid in ((H, ctx.hp), (C, ctx.cp))}
        log(f'  division reports opened: {[(w, bool(d), how) for w, (d, how) in rep.items()]}')
        # b) the speed arrows
        arrow_check(ctx, 'b) speed arrows 1', 'client', True, False)
        trees['minute'] = tree_tops(ctx.cp)
        arrow_check(ctx, 'b) speed arrows 2', 'host', False, False)
        scmd(H, 'ls speed -1')  # slow minutes (~8 s): a click lands inside a running minute
        ls_run(H, C, 1, H)
        arrow_check(ctx, 'b) speed arrows 3', 'client', False, True)
        arrow_check(ctx, 'b) speed arrows 4', 'host', True, True)
        ma, mb = log_mark(H), log_mark(C)
        s0 = speeds()
        c1 = click_arrow(ctx.cp, True)
        time.sleep(1.5)
        c2 = click_arrow(ctx.cp, True)
        req = wait_until(lambda: ls_lines(H, ma, SPEED_REQ_RE), lambda v: len(v) >= 2, 8)
        ls_run(H, C, 1, H)
        s1, want = speeds(), int(s0[0]) + 2
        ns = [int(re.search(SPEED_REQ_RE, x)[2]) for x in req]
        check(f'b) two clicks on the client\'s arrow up 1.5 s apart (between minutes) step from the pending speed: '
              f'requests {int(s0[0]) + 1} then {want}, both copies at {want} in the next minute, no DESYNC',
              c1 and c2 and ns == [want - 1, want] and s1 == (str(want), str(want))
              and not ls_lines(H, ma, 'DESYNC'), f'{s0} -> {s1}; requests {ns}; {req[:2]}')
        # c) Auto-run per player (engine level 4): the game's question, the order at the release, the take-back
        for who, port, pid, side in (('client', C, ctx.cp, 1), ('host', H, ctx.hp, 0)):
            ll_part(f'c) the {who}\'s Auto-run', autorun_button_check, ctx, 'c)', who, port, pid, side)
        # d) Fastest available as a shared clock control (engine level 2); f) checks that a resync keeps it
        fastest_click_check(ctx, 'd)', 'client', C, ctx.cp, True)
        fastest_click_check(ctx, 'd)', 'host', H, ctx.hp, False)
        m, mc = log_mark(H), log_mark(C)
        r1 = scmd(H, 'ls fastest 1')
        ls_run(H, C, 1, H)
        f1 = (pst(H).get('fastest'), pst(C).get('fastest'))
        r3 = scmd(H, 'ls speed 3')
        rel = wait_until(lambda: ls_lines(C, mc, r'lockstep: .+ set the game speed to 3 \(Fastest available off\) '
                                                 r'\(from the next minute\)\.'), bool, 8)
        ls_run(H, C, 1, H)
        f2, s2 = (pst(H).get('fastest'), pst(C).get('fastest')), speeds()
        check('d) `ls fastest 1` on the host turns it on for both from the next minute; the host\'s speed box (`ls speed 3`) '
              'then releases it: "<side> set the game speed to 3 (Fastest available off) (from the next minute)." on '
              'both copies, both off and at the same speed after the next minute (3, or lower when the game\'s contact '
              'rule caps it: the fleets may be engaged by now)', r1 == r3 == 'ok' and f1 == ('1', '1')
              and rel and ls_lines(H, m, r'set the game speed to 3 \(Fastest available off\)') and f2 == ('0', '0')
              and s2[0] == s2[1] and (s2[0] or '9').lstrip('-').isdigit() and int(s2[0]) <= 3,
              f'{r1} {f1}; {r3} {rel[:1]}; after {f2} {s2}')
        # e) contact
        scmd(H, 'ls speed 3')
        n_ai = ls_all_ai(H, C)
        ma, mb = log_mark(H), log_mark(C)
        ran = ls_run_total(H, C, 14, H)
        hc = ls_compare(H, ma, C, mb, 'contact')
        pa, pb = pst(H), pst(C)
        des = ls_lines(H, ma, r'DESYNC|Synchronising the battle again')
        check(f'e) {ran} minutes with every division on the AI ({n_ai} orders; engaged {pa.get("engaged")}/'
              f'{pb.get("engaged")}): every minute equal, no DESYNC, "Fastest available" off on both (the host\'s speed '
              f'box released it in d)), the same speed',
              ran >= 12 and hc['minutes'] >= 12 and not hc['differ'] and not des and pa.get('fastest') == pb.get(
                  'fastest') == '0' and pa.get('speed') == pb.get('speed'),
              f'hashes {hc}; {des[:2]}; fastest {pa.get("fastest")}/{pb.get("fastest")}; speed {pa.get("speed")}/'
              f'{pb.get("speed")}')
        pa, pb = pst(H), pst(C)
        if pa.get('engaged') == pb.get('engaged') == '1':
            m, s0 = log_mark(H), speeds()
            for _ in range(4):
                click_arrow(ctx.cp, True)
                time.sleep(1.5)
            req = [int(re.search(SPEED_REQ_RE, x)[2]) for x in ls_lines(H, m, SPEED_REQ_RE)]
            ls_run(H, C, 1, H)
            s1 = speeds()
            check(f'e) the client\'s arrow up clicked 4 times while the fleets are engaged (speed {s0[0]}): the requests '
                  f'stop at 2 (the game allows "up" in contact only below Fast), both copies at the same speed after the '
                  f'next minute', len(req) < 4 and all(b == a + 1 for a, b in zip(req, req[1:]))
                  and (not req or req[-1] == 2) and s1[0] == s1[1], f'requests {req}; speed {s0} -> {s1}')
        else:
            log(f'  SKIP-note e): the fleets are not engaged (engaged {pa.get("engaged")}/{pb.get("engaged")}): the '
                f'arrow cap in contact is not checked')
        panel_check('e)', 'at a boundary after the minutes in contact')
        # f) the tool windows across a resync (the division reports are open since the start)
        aw = {who_of(p): airwin(p, show=True) for p in (H, C)}
        rep_up = {w: bool(d and u.IsWindowVisible(d)) for w, (d, _) in rep.items()}
        cap = lsctl(C, 'TdlgDivisionReport', 'sbLandCAP')
        lc0 = (parse_landcap(scmd(H, 'ls landcap')), parse_landcap(scmd(C, 'ls landcap')))
        if rep_up['client'] and cap.get('visible') == '1':
            m = log_mark(C)
            post_click(rep['client'][0], *LANDCAP_AT)
            time.sleep(1.0)
            boxes = ll_answer_boxes(ctx.cp, quiet=0.8)
            cap1 = lsctl(C, 'TdlgDivisionReport', 'sbLandCAP')
            lc1 = (parse_landcap(scmd(H, 'ls landcap')), parse_landcap(scmd(C, 'ls landcap')))
            check('f) the division report\'s land-CAP button clicked on the client (engine level 6: a land-CAP request is '
                  'an order): no "not available" chat line, the button down (`ls ctl TdlgDivisionReport sbLandCAP` down=1 '
                  'group=6), nothing requested before the report\'s OK (`ls landcap` side 1 unchanged on both copies)',
                  not ls_lines(C, m, re.escape(LANDCAP_LINE)) and cap1.get('down') == '1' and cap1.get('group') == '6'
                  and lc1[0].get('landcap1') == lc0[0].get('landcap1') and lc1[1].get('landcap1') == lc0[1].get('landcap1'),
                  f'before {cap}; after {cap1}; boxes {boxes}; landcap1 {[x.get("landcap1") for x in lc0]} -> '
                  f'{[x.get("landcap1") for x in lc1]}')
        else:
            log(f'  SKIP-note f): the land-CAP button is not shown (report open {rep_up}; button {cap}): land CAP is '
                f'checked in lockstep_air')
        opened = all(v.get('visible') == '1' and v.get('items') == '0' for v in aw.values()) and all(rep_up.values())
        rf1 = scmd(H, 'ls fastest 1')  # Fastest available on into the resync: the start message carries it
        ls_run(H, C, 1, H)
        e0, ma, mb, mem2 = int(lss(H).get('epoch') or 0), log_mark(H), log_mark(C), mem(ctx)
        r = scmd(H, 'ls resync')
        ls_wait(lambda: int(lss(H).get('epoch') or 0) > e0 and ls_idle_equal(H, C), 150, 'the resync with the windows open')
        snaps.append(('the resync with the windows open', gen_date(HOST_SLOT)))
        mem3 = mem(ctx)
        log(f'  NOTE f) private memory host/client before this resync {mem2} MB, after {mem3} MB (a load: '
            f'{mem3[0] - mem2[0]:+.1f} / {mem3[1] - mem2[1]:+.1f} MB)')
        trees['resync'] = tree_tops(ctx.cp)
        hid = {who_of(p): ls_lines(p, mk, HIDDEN_RE) for p, mk in ((H, ma), (C, mb))}
        gone = {who: airwin(p).get('visible') == '0' and not (divreport(pid) and u.IsWindowVisible(divreport(pid)))
                for who, p, pid in (('host', H, ctx.hp), ('client', C, ctx.cp))}
        alive = all(sstatus(p) and lss(p).get('st') == 'running' for p in (H, C))
        aw2 = {who_of(p): airwin(p, show=True) for p in (H, C)}
        want = {'TdlgShowAirFormations', 'TdlgDivisionReport'}
        check('f) `ls resync` with the air formations window (no aircraft in 1900: 0 rows) and a division report open on '
              'both copies since the start: both hidden before the load on each copy ("<class> hidden before the battle '
              'is loaded again (ok)"), no crash, both running again, the air window opens again', opened
              and r.startswith('ok') and all({re.search(HIDDEN_RE, x)[1] for x in v} >= want
                                             and 'FAILED' not in ' '.join(v) for v in hid.values())
              and all(gone.values()) and alive and all(v.get('visible') == '1' for v in aw2.values()),
              f'opened: air {aw} reports {rep_up} {[how for _, how in rep.values()]}; resync {r}; hidden {hid}; closed '
              f'{gone}; running {alive}; reopened {aw2}')
        fa, fb = kvs(scmd(H, 'ls fastest')), kvs(scmd(C, 'ls fastest'))
        sent = ls_lines(H, ma, r'lockstep: battle \d+ epoch \d+ sent \(.*fastest 1')
        check('f) the resync with "Fastest available" on (the host\'s `ls fastest 1` before it): the start message carries '
              'it ("... epoch <e> sent (..., fastest 1, ...)") and both copies have it on after the load (`ls fastest` '
              'fastest=1 down=1)', rf1 == 'ok' and sent and fa.get('fastest') == fb.get('fastest') == '1'
              and fa.get('down') == fb.get('down') == '1', f'{rf1}; {sent[-1:]}; A {fa} B {fb}')
        scmd(H, 'ls fastest 0')
        ls_run(H, C, 1, H)
        d, how = open_divreport(ctx.cp)  # right after the load: the client's tree lists its own divisions
        clicked = False
        if d is not None and lsctl(C, 'TdlgDivisionReport', 'sbLandCAP').get('visible') == '1':
            with ll_noans(ctx, ctx.cp):
                post_click(d, *LANDCAP_AT)
                time.sleep(1)
                ll_answer_boxes(ctx.cp, quiet=0.8)
            clicked = lsctl(C, 'TdlgDivisionReport', 'sbLandCAP').get('down') == '1'
        div = re.match(r"'(.*?)(?: \(.*\))?'", how or '')
        b = dlg_buttons(d) if d is not None else {}
        mc0 = log_mark(C)
        if b.get('ok'):
            u.PostMessageW(b['ok'], 0x00F5, 0, 0)  # the report's Ok (bnOkClick reads the land-CAP button)
        time.sleep(1)
        order = ls_lines(C, mc0, r'lockstep: orders #\d+ \(.*VLlandcap#1')
        ma, mb = log_mark(H), log_mark(C)
        ll_synced(H, C)
        ls_run_total(H, C, 2, C)
        trees['after'] = tree_tops(ctx.cp)
        hc = ls_compare(H, ma, C, mb, 'after the report\'s Ok')
        lca, lcb = parse_landcap(scmd(H, 'ls landcap')), parse_landcap(scmd(C, 'ls landcap'))
        named = div is not None and lca.get('landcap1', '').split(':', 1)[-1] == div[1]
        check(f'f) a division report opened again on the client ({how}), its land-CAP button clicked (down) and its Ok '
              f'pressed: an order batch with the request (`VLlandcap#1`); after the release both copies have side 1\'s '
              f'request on that division (`ls landcap` landcap1 equal on both); the next 2 minutes equal, no DESYNC',
              d is not None and b.get('ok') and clicked and order and lca.get('landcap1') == lcb.get('landcap1')
              and named and landcap_shared(lca) == landcap_shared(lcb) and hc['minutes'] >= 2 and not hc['differ']
              and not ls_lines(H, ma, 'DESYNC'), f'report {how}; clicked {clicked}; {order[:1]}; landcap A {lca} B {lcb}; '
                                                f'hashes {hc}')
        panel_check('f)', 'after the resync')
        close_modeless(ctx.hp)
        close_modeless(ctx.cp)
        check(f'g) the client\'s ship tree ("OB") lists only its own forces ({n1}) after the load, after a minute, after '
              f'the resyncs and after the next minutes (0.3.1: {n0}\'s after every minute)', all(
                  v and all(t.startswith(n1) for t in v) for v in trees.values()), trees)
        td = {who_of(p): teardown_lines(p, marks0[p]) for p in (H, C)}
        check('g) every load of this battle ran the game\'s battle teardown first ("battle data cleared (ok), air formations '
              'left 0": the start and the two resyncs on each copy)', all(len(v) >= 3 and all(ok and n == 0 for ok, n in v)
                                                                          for v in td.values()), td)
        gi = ls_groups(H, s['hm'], C, s['cm'], ('ident', 'date'), 'the whole battle')
        IDENT_LOG.append((_scenario[0], 'g) the whole battle', gi['minutes'], gi['differ']['ident']))
        camp = ymd_log(s['gen0'])
        check(f'g) in every minute of this battle the hash group `date=` is equal on both copies and the campaign\'s own '
              f'{camp} (engine level 10; `ident=` of every minute: the scan\'s identification check)',
              gi['minutes'] >= 10 and not gi['differ']['date'] and gi['values']['date'] == [camp], gi)
        # k) 0.3.3: a division report's speed write stays out of the live battle (the client's report, then the host's)
        divreport_speed_check(ctx, 'k) client', C, ctx.cp)
        divreport_speed_check(ctx, 'k) host', H, ctx.hp)
        # h) the end
        scmd(H, 'ls drop')
        ls_wait(lambda: ls_client_back(ctx), 120, 'the client back in slot 77 after the drop')
        hc_mark = log_mark(H)
        closed = ls_finish_host(ctx)
        hn = ls_wait(lambda: (lambda n: n if n.get('slotMode') == '0' else None)(lsn(H)), 30, 'slot mode off')
        check('h) the host drops the client (the client back in slot 77) and finishes its battle alone on auto-run; '
              'battle slot mode off', closed and hn.get('slotMode') == '0', hn)
        want, back = ymd(s['gen0']), ls_lines(H, hc_mark, r'lockstep: campaign date \S+ put back')
        check(f'h) the campaign date: every snapshot of this battle (its start and both resyncs) saved the campaign\'s '
              f'own date {want} in slot 1\'s [General], and the host\'s close put it back (`campaign date '
              f'{ymd_log(s["gen0"])} put back`; up to 3cc0628 a resync saved the battle\'s own day and month, and a '
              f'later turn could be rejected or a month skipped)', all(ymd(g) == want for _, g in snaps)
              and len(back) == 1 and back[0].startswith(f'lockstep: campaign date {ymd_log(s["gen0"])} put back'),
              f'snapshots {snaps}; {back}')

    ls_case(ctx, 'lockstep_ui: the battle screen\'s controls', battle)
    ls_quiet(ctx)
    ls_after_checks(ctx, 'i)')
    ls_log_scan('j)', marks0)


def pvp_lines(hlog, bid):
    return log_lines(hlog, rf'battle (request )?{bid}[ :]|relay {bid} ')


PVP_DIV_A = (('RT K Pvp', 'RKP', 'BX'),)  # lockstep_pvp: the client's division when it holds none (e.g. --only)
PVP_DIV_B = (('RT Bot Div', 'RBD', 'BX'),)  # and the third copy's (nation 2)


def pvp_divs_setup(ctx):
    """lockstep_pvp (a docs question, no failing check): campaign divisions on both joined players' copies before the
    war month (the client's from `divisions` in a full run, else one new; one new on the third copy) and a live hook
    that records the battle's divisions (`ls divs`) and the campaign lists (`divs`) on both copies at the load of the
    first live battle 1-2. Returns the record for pvp_divs_note."""
    pd = dict(seen=[])
    dc = parse_divs(cmd(C, 'divs'))
    if not (dc and any(d['ships'] for d in dc['divs'])):
        pd['madeA'] = fo_make(ctx.cp, 'client', PVP_DIV_A)
        fo_set_tab(ctx.cp, 0)
        dc = parse_divs(cmd(C, 'divs'))
    pd['madeB'] = fo_make(k2_pid(), 'k2', PVP_DIV_B)
    fo_set_tab(k2_pid(), 0)
    dk = parse_divs(cmd(K2, 'divs'))
    pd['camp'] = {p: [d['name'] for d in (x or {}).get('divs', []) if d['name'] and d['ships']]
                  for p, x in ((C, dc), (K2, dk))}
    log(f'  campaign divisions before the war month: client {div_summary(dc)}; third copy {div_summary(dk)}')

    def hook(what, rec, A, B, r):
        if what == 'load' and {A, B} == {C, K2} and not pd['seen']:
            pd['seen'].append(dict(A=A, B=B, side={A: r['a0'].get('side'), B: r['b0'].get('side')},
                                   bat={A: ls_divs(A), B: ls_divs(B)},
                                   camp={p: div_summary(parse_divs(scmd(p, 'divs'))) for p in (A, B)}))
    pd['hook'] = hook
    return pd


def pvp_divs_note(pd):
    """lockstep_pvp: whose campaign divisions shape the relayed battle (set up on A's PC from its campaign): a NOTE
    (CONFIRMED: A's campaign divisions on A's side, none of B's; REFUTED: B's in the battle; INCONCLUSIVE: none of
    A's, e.g. their ships not in it) and one check that the battle's division list is the same on both copies."""
    s = pd['seen'][0] if pd['seen'] else None
    if not s:
        log('  NOTE lockstep_pvp divisions: INCONCLUSIVE: no live battle 1-2 was loaded')
        return
    A, B = s['A'], s['B']

    def where(port, names):
        return {n: sorted({d['side'] for d in s['bat'][port] if n in d['name']}) for n in names
                if any(n in d['name'] for d in s['bat'][port])}
    fa, fb = {p: where(p, pd['camp'][A]) for p in (A, B)}, {p: where(p, pd['camp'][B]) for p in (A, B)}
    sa = int(s['side'][A]) if str(s['side'][A]).isdigit() else None
    a_own = {n for n, sides in fa[A].items() if sa in sides}
    verdict = 'REFUTED' if fb[A] or fb[B] else 'CONFIRMED' if a_own else 'INCONCLUSIVE'
    names = {p: [f'{d["i"]}:{d["side"]}:{d["name"]}:{d["ships"]}' for d in s['bat'][p]] for p in (A, B)}
    log(f'  NOTE lockstep_pvp divisions: {verdict}: A={who_of(A)} side {s["side"][A]}, B={who_of(B)} side '
        f'{s["side"][B]}; A\'s campaign divisions {pd["camp"][A]} in the battle (name: sides) on A {fa[A]}, on B '
        f'{fa[B]}; B\'s {pd["camp"][B]} on A {fb[A]}, on B {fb[B]}; battle divisions on A {names[A]}; campaign lists '
        f'at the load: A {s["camp"][A]} | B {s["camp"][B]}')
    la, lb = ([(d['i'], d['side'], d['name']) for d in s['bat'][p]] for p in (A, B))
    check(f'b) the battle\'s divisions (`ls divs` at the load: index, side, name) are the same on both players\' copies '
          f'({len(la)} divisions)', bool(la) and la == lb, f'A {names[A][:14]} | B {names[B][:14]}')


def scenario_lockstep_pvp(ctx):
    """Live battles between two joined players (three copies; from the research driver ls_pvp.py). a) a third copy
    joins as "Bot" and gets the reserved nation 2. b) war 1-2 (`settension 1 2 50`), `battles injectpvp 1 2 Northern
    Europe`, processed months (up to 3: the attacker's CheckAttackLocation may find no battle) until a live battle is
    fought: the battle phase sends it to the attacker's copy (A, its battle slot) and the defender's copy commands the
    other side (B, its battle slot), the host relays; runs and an order of B with equal hashes; default: 10 live
    minutes, then A drops B and fights on alone on auto-run; --stress: to the agreed end (>= 400 minutes) and an
    idea-1 battle of nation 1 against an AI nation injected into the same month (the host runs them one after the
    other). c) the result merged, the new month on all three copies, ship counts equal. f) the war score of 1-2
    (`warvp 1 2` before and after the month) rose by the VP of the month's merged live battles 1-2 plus the host's own
    `war score 1-2` credits. d) peace, the third copy leaves (nation 2 stays reserved for Bot) and is closed. Campaign
    divisions on both players' copies before the war month (pvp_divs_setup): the battle's division list equal on both
    copies, and a NOTE whose campaign divisions shape the battle (pvp_divs_note)."""
    marks0 = {H: log_mark(H), C: log_mark(C)}
    stress = OPTS['stress']
    ls_ensure_session(ctx)
    r, sent, st = k2_start(ctx)
    marks0[K2] = 0
    hs = lsn(H)
    check(f'a) a third copy joins as "{K2_NAME}" (bridge {K2}, slot {K2_SLOT}): the host gives it the reserved nation '
          f'{STANDIN} and sends the month; it plans nation {STANDIN} in slot {K2_SLOT}; the host lists Captain(1,b,ls) '
          f'and {K2_NAME}({STANDIN},b,ls)', r == 'ok' and sent and st.get('playerIdx') == str(STANDIN)
          and 'Captain(1,b,ls)' in hs.get('players', '') and f'{K2_NAME}({STANDIN},b,ls)' in hs.get('players', ''),
          f'{r} {sent[:1]} {st.get("slot")}/{st.get("playerIdx")} {hs.get("players")}')
    pvpd = pvp_divs_setup(ctx)
    t12 = rel(1, 2).get('tension', '5')
    cmd(H, 'settension 1 2 50')
    r12 = rel(1, 2)
    check('setup: nations 1 and 2 (both joined players) at war (`settension 1 2 50`)', r12.get('war') == '1', r12)
    J = area = tJ = None
    if stress:
        cands = battle_pairs(1)
        if cands:
            _, _, J, area = cands[0]
            tJ = rel(1, J).get('tension', '5')
            cmd(H, f'settension 1 {J} 50')
            log(f'  interplay: nation 1 at war with AI nation {J} too; an idea-1 battle in {area} each month')
    mode = 'agree' if stress else 'drop10'
    done, attempts = None, []
    for attempt in range(1, 4):
        hm = log_mark(H)
        if rel(1, 2).get('war') != '1':
            cmd(H, 'settension 1 2 50')
        rp = cmd(H, f'battles injectpvp 1 2 {PVP_AREA}')
        pbid = int(rp.split()[1]) if re.match(r'^ok \d+$', rp) else None
        ibid = None
        if J is not None:
            if rel(1, J).get('war') != '1':
                cmd(H, f'settension 1 {J} 50')
            ibid, _ = inject(1, J, area)
        ws0, wm = warvp(1, STANDIN), log_mark(H)  # f) the war score of 1-2 before the month
        rec = ls_month(ctx, f'lockstep_pvp M{attempt}', modes=[mode], k2=True, live_hook=pvpd['hook'])
        hlog = log_since(H, hm)
        lives = [b for b in rec['live'] if b['A'] in (C, K2)]
        applied = {int(x) for x in re.findall(r'battle (\d+) applied: ', hlog)}
        attempts.append((attempt, rp, [(b['bid'], b['mode'], b.get('error')) for b in lives], sorted(applied),
                         log_lines(hlog, r'battle \d+: resolved by the game')[:3]))
        if lives:
            ws = dict(before=ws0, after=warvp(1, STANDIN), war=rel(1, STANDIN).get('war'))
            ws['log'] = log_since(H, wm)  # the month, and a restart of the score by the read after it
            done = (rec, lives, hm, pbid, ibid, ws)
            break
    check(f'b) a live battle between nations 1 and 2 fought within 3 months (`battles injectpvp 1 2 {PVP_AREA}`; '
          f'attempts: month, inject, live battles, merged ids, resolved by the game)', done, attempts)
    if done:
        pvp_checks(ctx, stress, *done)
    pvp_divs_note(pvpd)
    cmd(H, f'settension 1 2 {t12}')
    if J is not None:
        cmd(H, f'settension 1 {J} {tJ}')
    k2_stop(ctx)
    hs, r2 = lsn(H), row(H, STANDIN)
    check(f'd) peace 1-2 again; the third copy left and is closed: the host lists only Captain, nation {STANDIN} stays '
          f'reserved for {K2_NAME}', rel(1, 2).get('war') == '0' and f'{K2_NAME}(' not in hs.get('players', '')
          and r2 and r2['player'] == K2_NAME, f'{rel(1, 2)} {hs.get("players")} {r2}')
    ls_after_checks(ctx, 'd)')
    ls_log_scan('e)', marks0)


def pvp_checks(ctx, stress, rec, lives, hm, pbid, ibid, ws):
    b = lives[0]
    A, B = b['A'], b['B']
    hlog = log_since(H, hm)
    req = log_lines(hlog, r'battle request \d+: nation \d vs \d in .* fought live by \w+ and \w+')
    sentl = log_lines(hlog, r'battle \d+ sent to \w+ \(\d+ bytes\), live against \w+')
    relay = log_lines(hlog, r'lockstep relay \d+ ended')
    applied = log_lines(hlog, APPLIED_RE)
    check('b) host log: the request "battle request N: nation a vs b in <area> (x:y ships), fought live by <p1> and <p2>", '
          '"battle N sent to <p> (B bytes), live against <q>", the relay ended with the result, "battle N applied: X '
          'ships changed (F fields), R removed, VP a/b ..."', req and sentl and relay and applied,
          f'{req[:2]} {sentl[:2]} {relay[:2]} {applied[:2]}')
    la, lb = ls_lines(A, rec['marks'][A], r'StartPlayerBattle|lockstep: battle \d+ epoch 1 sent|battle \d+: (fought|'
                                                                   r'fighting)'), \
        ls_lines(B, rec['marks'][B], r'lockstep: battle loaded from slot (8[67])|live battle: leaving the battle slot')
    check(f'b) the attacker\'s copy ({who_of(A)}) fought it in its battle slot as A (StartPlayerBattle, "battle .. epoch 1 '
          f'sent", "battle N: fighting ..."), the defender\'s copy ({who_of(B)}) loaded it from its battle slot as B and '
          f'left the battle slot afterwards', la and lb and any('epoch 1 sent' in x for x in la)
          and any('battle loaded from slot' in x for x in lb) and any('leaving the battle slot' in x for x in lb),
          f'A {la[:4]} | B {lb[:3]}')
    h = b.get('hash') or {}
    need = 400 if stress else 8
    check(f'b) live: every minute\'s state hash equal on both players\' copies (>= {need} minutes compared), no DESYNC',
          h.get('minutes', 0) >= need and not h.get('differ') and not b.get('desync') and not b.get('error'),
          f'{h} {b.get("desync")} {b.get("error")}')
    o = b.get('order') or {}
    check('b) an order of B (one of its divisions, course +90, AI off) shows the same course on both copies',
          o and o.get('A') == o.get('B') == o.get('want'), o)
    if stress:
        endl = ls_lines(A, rec['marks'][A], r'The battle is over \(ended by agreement')
        endb = ls_lines(B, rec['marks'][B], r'The battle is over \(ended by agreement')
        gl, gb = ls_lines(A, rec['marks'][A], LS_GAME_END_RE), ls_lines(B, rec['marks'][B], LS_GAME_END_RE)
        agreed, by_game = bool(endl and endb), bool(gl and gb and b.get('refusals'))
        # (as lockstep_month's 'agree': with enemies near the game refuses the agreed end, "Forced battle end not
        # allowed!", and may end the battle at its length first: dist_vp_2's --stress run, minute 793)
        check(f'b) the battle ended on both copies at minute >= 400 ({b.get("minute")}), '
              f'{"by agreement" if agreed else "by the game itself after the agreed end was refused" if by_game else "?"}'
              f' (end requests {b.get("tries")}, refused by the game {b.get("refusals")}; the game refuses before 400 '
              f'minutes and while enemies are near)', (agreed or by_game) and b.get('minute', 0) >= 400,
              f'minute {b.get("minute")} {endl[:1]} {endb[:1]} game {gl[-1:]} {gb[-1:]}')
    else:
        fought = ls_lines(A, rec['marks'][A], r'battle \d+: fought')
        check('b) A dropped B after 10 live minutes ("dropping <B>: test"), B went back to its own slot, A fought on '
              'alone on auto-run and sent the result ("battle N: fought")', b.get('drop') and b.get('back_s') is not None
              and fought, f'{b.get("drop")} back {b.get("back_s")} s {fought[:1]}')
    s1, s2, sh = sstatus(C), sstatus(K2), sstatus(H)
    nh, n1, n2 = nation_table(H), nation_table(C), nation_table(K2)
    ships = {n: (nh.get(n, {}).get('ships'), n1.get(n, {}).get('ships'), n2.get(n, {}).get('ships')) for n in (1, 2)}
    check('c) the new month on all three copies (host, Captain in slot 77 as nation 1, Bot in slot 76 as nation 2); the '
          'ship counts of nations 1 and 2 equal on the three copies',
          s1.get('date') == s2.get('date') == sh.get('date') == rec['date1'] and s1.get('slot') == str(CLIENT_SLOT)
          and s2.get('slot') == str(K2_SLOT) and s2.get('playerIdx') == str(STANDIN)
          and all(len(set(v)) == 1 and v[0] is not None for v in ships.values()),
          f'dates {sh.get("date")}/{s1.get("date")}/{s2.get("date")}; ships {ships}')
    pvp_war_score_check(ws, hlog)
    if stress and ibid is not None:
        def t_of(lines):
            return log_secs(lines[0]) if lines else None
        p_sent = t_of(sentl)
        t_relay = t_of(relay)
        isent = log_lines(hlog, rf'battle {ibid} sent to Captain')
        idone = log_lines(hlog, rf'battle {ibid}( applied|: resolved by the game)')
        t_isent, t_idone = t_of(isent), t_of(idone)
        apart = (t_relay is not None and t_isent is not None and t_isent >= t_relay) or \
            (t_idone is not None and p_sent is not None and p_sent >= t_idone)
        check(f'h) interplay: the idea-1 battle {ibid} (nation 1 vs an AI nation) of the same month and the live battle '
              f'ran one after the other for Captain (one battle per player at a time, in the host\'s order) and both were '
              f'settled (the idea-1 battle merged or resolved by the game)', idone and apart,
              f'live sent {sentl[:1]} relay {relay[:1]} | idea-1 sent {isent[:1]} done {idone[:1]}')


PVP_REQ_RE = r'battle request (\d+): nation (\d+) vs (\d+) in .* \(\d+:\d+ ships\), fought live by (\S+) and (\S+)'
WAR_VP_CREDIT_RE = (r'victory points: nation (\d+) \+(\d+) \((.*?), in its war with nation (\d+)\) -> -?\d+, war score '
                    r'(\d+)-(\d+) (\d+):(\d+)$')


def pvp_war_score_check(ws, hlog):
    """f) The war score of the war 1-2 (the host's per-pair ledger behind the peace terms, `warvp 1 2`), read before and
    after the month with the live battle(s), must have risen by the VP of every live battle between 1 and 2 merged into
    the host's save that month (`battle N applied: ... VP a/b`: a = the battle's own nation K, the first player's, b =
    its opponent J, as in the request `battle request N: nation K vs J ..., fought live by ...`; mapped onto the pair
    order 1, 2) plus the host's own credits of the month (`war score 1-2: +x/+y -> A:B` of its battle hooks: battles the
    game resolved on the host, e.g. an unfought request; since 0.6.0 also its CreditWarVP lines of that war, e.g. B5's
    blockade: `victory points: nation G +v (blockade, in its war with nation L) -> t, war score 1-2 x:y`). Before 0.3.0
    the host's game fought such battles and its hooks
    credited the ledger; since 0.3.0 they are fought on the players' PCs and merged into the save."""
    w0, w1, wlog = ws.get('before'), ws.get('after'), ws.get('log', '')
    req = {int(m[1]): (int(m[2]), int(m[3])) for m in re.finditer(PVP_REQ_RE, hlog)}
    merged = []
    for ln in log_lines(wlog, APPLIED_RE):
        m = re.search(APPLIED_RE, ln)
        kj = req.get(int(m[1]))
        if not kj or sorted(kj) != [1, STANDIN]:
            continue
        a, b = max(0, int(m[5])), max(0, int(m[6]))  # the ledger counts gains only
        merged.append(dict(bid=int(m[1]), K=kj[0], vp=(a, b), v12=(a, b) if kj[0] == 1 else (b, a), line=ln))
    lines = log_lines(wlog, rf'war score 1-{STANDIN}\b')
    hooks = [tuple(int(x) for x in re.search(WAR_SCORE_RE, ln).groups()[2:4]) for ln in lines
             if re.search(WAR_SCORE_RE + '$', ln) and "player's PC" not in ln]
    # 0.6.0: the host's other credits of a war between players' nations (CreditWarVP, e.g. B5's blockade VP:
    # "victory points: nation G +v (blockade, in its war with nation L) -> t, war score 1-2 x:y")
    for ln in lines:
        m = re.search(WAR_VP_CREDIT_RE, ln)
        if m and sorted((int(m[1]), int(m[4]))) == [1, STANDIN] and (m[5], m[6]) == ('1', str(STANDIN)):
            hooks.append((int(m[2]), 0) if int(m[1]) == 1 else (0, int(m[2])))
    restart = [ln for ln in lines if re.search(r'starts at|first battle', ln)]
    add = (sum(x['v12'][0] for x in merged) + sum(h[0] for h in hooks),
           sum(x['v12'][1] for x in merged) + sum(h[1] for h in hooks))
    want = (w0['a'] + add[0], w0['b'] + add[1]) if w0 else None
    got = (w1['a'], w1['b']) if w1 else None
    detail = (f'warvp 1 {STANDIN}: before {w0 and (w0["a"], w0["b"])}, after {got}, expected {want} = before + live '
              f'battles merged {[(x["bid"], "K=%d" % x["K"], "VP %d/%d" % x["vp"], "1:+%d 2:+%d" % x["v12"]) for x in merged]}'
              f' + host credits {hooks}; at war after the month: {ws.get("war")}; war score lines {lines}; applied '
              f'{[x["line"] for x in merged]}')
    log(f'  f) war score 1-{STANDIN}: {detail}')
    if merged and not any(sum(x['vp']) for x in merged):
        log('  SKIP-note f): the live battles gave 0 VP to both sides; the check cannot tell a missing credit from a '
            'correct one')
    return check(f'f) the war score of 1-{STANDIN} (host `warvp 1 {STANDIN}` before and after the month) rose by the VP '
                 f'of the month\'s live battles between 1 and {STANDIN} merged into the host\'s save ("battle N applied: '
                 f'... VP a/b", a = the first player\'s nation K) plus the host\'s own credits of that month ("war score '
                 f'1-{STANDIN}: +x/+y -> A:B"); still at war, the score not restarted',
                 w0 and w1 and merged and ws.get('war') == '1' and not restart and got == want, detail)


def ls_war01(ctx):
    """The host at war with nation 1 (host `diplo war 1` + applydiplo). Returns rel 0 1."""
    if rel(0, 1).get('war') != '1':
        mark = log_mark(H)
        cmd(H, 'diplo war 1')
        wait_log(H, mark, r'diplomacy request 0 war 1 accepted', 8)
        apply_diplo(ctx, lambda: rel(0, 1).get('war') == '1')
    return rel(0, 1)


def ls_peace01(ctx):
    """Peace between the host and nation 1 with an equal war score (a compromise: no treaty): the host offers, the client
    accepts with its "Accept peace" button, applydiplo. Returns rel 0 1."""
    if rel(0, 1).get('war') == '1':
        warvp(0, 1, 300, 300)
        cmd(H, 'diplo peace 1')
        bt, acc = client_accept_peace(ctx, 0)
        log(f'  peace 0-1: the client\'s button "{bt}", {acc[:1]}')
        apply_diplo(ctx, lambda: rel(0, 1).get('war') == '0')
    return rel(0, 1)


SHIP_BATTLE_FIELDS = ('RepairTime', 'BattleStars', 'NumberOfLogEntries', 'Status', 'Fate', 'CrewQuality')


def lost_ship(f0, f1):
    """A ship lost between two saves of it: its Fate is no longer 'XXX' (in service), e.g. "Sunk in battle off ..."."""
    a, z = f0.get('Fate') or 'XXX', f1.get('Fate') or 'XXX'
    return z != 'XXX' and z != a


def battle_effects(s_battle, s_post, nations=(0, 1), slot_nations=None):
    """What happened to the campaign ships of `nations` between two saves (e.g. the live battle's save at its start and
    the host's save at the battle phase start): the ships that took part (a battle star or a new "Took part"/action log
    entry), the ships lost (gone from the list, or their Fate no longer 'XXX', whether they took part or not: a loss
    outside a battle too), the [NationNLosses] counters of the nation's ship types that changed (`lost`; the others,
    e.g. MSLost and AUXLost, in `abstract`) and `counted` = the sum of the `lost` increases. `slot_nations` {n: section index in s_post}
    reads s_post in battle slot numbering (Game87: K is nation 0)."""
    out = {}
    for n in nations:
        m = (slot_nations or {}).get(n, n)
        b0, b1 = ships_by_id((s_battle or {}).get(f'Nation{n}Ships')), ships_by_id((s_post or {}).get(f'Nation{m}Ships'))
        part, gone, sunk, rep = [], [], [], {}
        for sid, f0 in b0.items():
            f1 = b1.get(sid)
            if f1 is None:
                gone.append((sid, f0.get('Name'), f0.get('ShipType')))
                continue
            if lost_ship(f0, f1):
                sunk.append((sid, f0.get('Name'), f0.get('ShipType'), f1.get('Fate')))
            logs0 = [v for k, v in f0.items() if k.startswith('LogEntry') and v]
            new = [v for k, v in f1.items() if k.startswith('LogEntry') and v and v not in logs0]
            if int(f1.get('BattleStars') or 0) > int(f0.get('BattleStars') or 0) or \
                    any(re.search(r'took part|in action|battle', x, re.I) for x in new):
                part.append(sid)
                rep[sid] = (f0.get('Name'), f0.get('RepairTime'), f1.get('RepairTime'), f0.get('Status'),
                            f1.get('Status'), f1.get('Fate'))
        l0, l1 = (s_battle or {}).get(f'Nation{n}Losses', {}), (s_post or {}).get(f'Nation{m}Losses', {})
        # Counters of types without campaign ships (no such ShipType in the nation's list) are only reported: MSLost
        # (merchant ships of the month's trade war) and AUXLost (auxiliaries, e.g. transports in a battle) never come
        # with a ship of the list.
        types = {f.get('ShipType') for f in list(b0.values()) + list(b1.values())}
        changed = {k: (l0.get(k), v) for k, v in l1.items() if l0.get(k) != v}
        lost = {k: v for k, v in changed.items() if k.endswith('Lost') and k[:-4] in types}
        out[n] = dict(part=part, gone=gone, sunk=sunk, repair=rep, lost=lost,
                      counted=sum(int(v or 0) - int(a or 0) for a, v in lost.values()),
                      abstract={k: v for k, v in changed.items() if k not in lost},
                      merchants=(l0.get('MSLost'), l1.get('MSLost')))
    return out


def losses_explained(eff):
    """Every warship loss the counters added has a lost ship (gone or Fate) in the same window."""
    return all(e['counted'] <= len(e['gone']) + len(e['sunk']) for e in eff.values())


def effects_txt(eff):
    return '; '.join(f'nation {n}: losses {e["lost"] or "-"}, lost ships {(e["gone"] + e["sunk"])[:4] or "-"}'
                     + (f', other counters {e["abstract"]}' if e['abstract'] else '')
                     for n, e in eff.items() if e['lost'] or e['gone'] or e['sunk'] or e['abstract'])


def month_stages(rec, b, s_post, nations):
    """The live battle's month step by step (saves read by StageWatcher): [(label, before, after)]: the live battle and
    the month end (its save at the start -> the host's save at the battle phase start, after DoEndOfTurn), each idea-1
    merge (the save as that battle was sent -> the merged save), what came after the last merge (the game's resolution
    of declined or unfought battles, the new month's save). Without a battle phase: one step to the month's save."""
    st = rec.get('stages') or {}
    if not b.get('s_battle'):
        return []
    pts = [('live battle start', b.get('s_battle'))]
    if st.get('s0'):
        pts.append(('battle phase start', st['s0']))
    pts += [(f'battle {n} merged', st['s1'][n]) for n in sorted(st.get('s1') or {})]
    pts.append(('after the month', s_post))
    pts = [p for p in pts if p[1]]
    return [(f'{l0} -> {l1}', a, z, battle_effects(a, z, nations)) for (l0, a), (l1, z) in zip(pts, pts[1:])]


def same_ships(sa, sb, nations=(0, 1)):
    """Differences between two saves in the ships of `nations` (ids, the battle fields) and their Losses sections."""
    diffs = []
    for n in nations:
        a, b = ships_by_id(sa.get(f'Nation{n}Ships')), ships_by_id(sb.get(f'Nation{n}Ships'))
        if set(a) != set(b):
            diffs.append((n, 'ids', sorted(set(a) ^ set(b))[:6]))
        for sid in set(a) & set(b):
            for k in SHIP_BATTLE_FIELDS:
                if a[sid].get(k) != b[sid].get(k):
                    diffs.append((n, sid, k, a[sid].get(k), b[sid].get(k)))
        if sa.get(f'Nation{n}Losses') != sb.get(f'Nation{n}Losses'):
            diffs.append((n, 'Losses', sa.get(f'Nation{n}Losses'), sb.get(f'Nation{n}Losses')))
    return diffs


LS_DEFER_RE = r'lockstep: "Exit battle" in the results: the battle screen closes after this minute'
LS_DEFER_SEQ = (LS_DEFER_RE, r'lockstep: The battle is over \(', r'live battle ended \(normal\)',
                r'lockstep: closing the battle screen \("Exit battle" in the results\)')


def deferred_close_checks(tag, rec, b, hl, cl):
    """0.3.0: a live battle the game ends INSIDE a minute (its results' "Exit battle" is pressed during the minute's
    step) closes only after that minute: on both copies `"Exit battle" in the results: the battle screen closes after
    this minute`, then the normal end at the boundary ("The battle is over (...)", "live battle ended (normal)"), then
    `closing the battle screen ("Exit battle" in the results)`, in this order; the host's month after it (FormClose ->
    DoStrategicTurn -> DoEndOfTurn) runs with the game's own dialogs, answered by the test ("Turn messages"), and no box
    goes through the battle's minute-box policy (no "minute box", skipped picture message, "Battle: ..." or WARNING
    line between the close and "DoEndOfTurn finished")."""
    def seq(t):
        lines, idx = (t or '').splitlines(), []
        for p in LS_DEFER_SEQ:
            i = next((k for k in range(idx[-1] + 1 if idx else 0, len(lines)) if re.search(p, lines[k])), None)
            if i is None:
                return None, lines
            idx.append(i)
        return idx, lines

    order = {}
    for who, t in (('host', hl), ('client', cl)):
        idx, lines = seq(t)
        order[who] = [lines[i].split('] ', 1)[-1][:70] for i in idx] if idx else None
    idx, lines = seq(hl)
    policy, eot = [], False
    for ln in lines[idx[-1] + 1:] if idx else []:
        if 'DoEndOfTurn finished' in ln:
            eot = True
            break
        if re.search(r'lockstep: (minute box|picture message .* skipped|Battle: |WARNING)', ln):
            policy.append(ln.split('] ', 1)[-1][:100])
    t_end = b.get('t_end') or rec['t0']
    month = [e for t, w, e in (_ANS[0].seen if _ANS[0] else []) if w == 'host' and t >= t_end
             and not e.startswith('TdlgResults')]
    check(f'{tag}: the game ended the battle inside a minute and the battle screen closed only after that minute: on both '
          f'copies "\\"Exit battle\\" in the results: the battle screen closes after this minute" -> "The battle is over" '
          f'-> "live battle ended (normal)" -> "closing the battle screen", in this order; the host\'s month after it ran '
          f'with normal dialogs (answered by the test, "Turn messages" among them), none answered by the battle\'s '
          f'minute-box policy (no minute box / skipped picture message / "Battle: ..." / WARNING after the close) up to '
          f'"DoEndOfTurn finished"', order['host'] and order['client'] and eot and not policy
          and any(e.startswith('TdlgCampTurnRep') for e in month),
          f'host {order["host"]} | client {order["client"]} | policy lines after the close {policy[:4]} | DoEndOfTurn '
          f'{eot} | host dialogs after the end {month[:8]}')


def host_battle_checks(ctx, tag, rec, b, plan, before):
    """The host's battle against nation 1 inside a real processed month (CheckForBattles2 -> DoBattle during the host's
    turn -> lockstep -> end -> FormClose -> DoStrategicTurn -> DoEndOfTurn -> the new month to the client)."""
    hl, cl = log_since(H, rec['hmark']), log_since(C, rec['cmark']) if not rec['relaunched'] else ''
    order = [log_lines(hl, p)[:1] for p in (r'host turn: \d+ submissions merged, running turn', re.escape(LS_HOLD),
                                            r'lockstep: battle \d+ epoch 1 sent', r'live battle \d+ started with Captain',
                                            r'lockstep: battle \d+ epoch 1 running at minute 0')]
    secs = [log_secs(x[0]) if x else None for x in order]
    prev = ls_answered(_ANS[0], 'host', rec['t0'], 'TdlgBattlePreview')
    check(f'{tag}: the host\'s month (Turn after the merge) started a battle against nation 1 (CheckForBattles2 -> '
          f'DoBattle): the host\'s preview accepted, then held, sent, started with Captain and running at minute 0 - in '
          f'this order; host `ls session` hostOpp=1 testSlotMode=0 (a real month: no battle slot mode)',
          prev and None not in secs and secs == sorted(secs) and b['sA'].get('testSlotMode') == '0'
          and b['sA'].get('slotMode') == '0' and b.get('hostOpp') == '1',
          f'{prev[:1]} {[x[0][:70] if x else None for x in order]} {b["sA"]}')
    eot = log_lines(hl, r'DoEndOfTurn finished')
    check(f'{tag}: the host\'s month ran once: one DoEndOfTurn, the date one month on ({rec["date0"]} -> {rec["date1"]})',
          len(eot) == 1 and rec['date1'] == month_after(rec['date0']), f'{len(eot)} DoEndOfTurn lines {eot[:3]}')
    probe = [p for p in _ANS[0].probe if p[0] >= rec['t0'] and p[2] == 'host']
    if probe:
        usable = [p for p in probe if p[3] and p[4]]
        log(f'  {tag}: after "Exit battle" the host\'s battle screen was up without a dialog {len(probe)} times, '
            f'{len(usable)} of them enabled with "View results" (closing: {sum(1 for p in usable if p[5])}); '
            f'first {probe[:3]}')
    loaded = log_lines(cl, rf'lockstep: battle loaded from slot {BATTLE_SLOT} ') if cl else ['(client restarted)']
    check(f'{tag}: the client (submitted, waiting for the month) loaded the battle from its battle slot {BATTLE_SLOT} and '
          f'ran it as B (side 1)', loaded and b['b0'].get('role') == 'B' and b['b0'].get('side') == '1',
          f'{loaded[:1]} {b["b0"].get("role")}/{b["b0"].get("side")}')
    h = b.get('hash') or {}
    mode = b['mode']
    need = max(6, (b.get('minute') or 0) - 5) if mode in ('agree', 'game') else 6
    check(f'{tag}: live ({mode}): every minute\'s state hash equal on both copies (>= {need} minutes compared), no DESYNC; '
          f'the client\'s order (course +90) shows the same on both', h.get('minutes', 0) >= need and not h.get('differ')
          and not b.get('desync') and not b.get('error') and (b.get('order') or {}).get('A') == (b.get('order') or {}).get('B')
          == (b.get('order') or {}).get('want'), f'{h} {b.get("desync")} {b.get("error")} {b.get("order")}')
    if mode in ('agree', 'game', 'endsoon'):
        ends_a = log_lines(hl, r'lockstep: The battle is over \(|live battle ended \(')
        ends_b = log_lines(cl, r'lockstep: The battle is over \(|live battle ended \(') if cl else []
        game_end = log_lines(hl, LS_GAME_END_RE)
        agreed = any('ended by agreement' in x for x in ends_a) and any('ended by agreement' in x for x in ends_b)
        if mode == 'agree':
            check(f'{tag}: the battle ended on both copies at minute >= 400 ({b.get("minute")}), '
                  f'{"by agreement" if agreed else "by the game itself" if game_end else "?"} (end requests '
                  f'{b.get("tries")}, refused by the game {b.get("refusals")}; after a refusal the game may end it first)',
                  (b.get('minute') or 0) >= 400 and ends_a and ends_b and (agreed or game_end),
                  f'{ends_a[-2:]} | {ends_b[-2:]}')
        elif mode == 'game':
            capped = agreed and not game_end and not b.get('proposals') and (b.get('minute') or 0) >= 900
            check(f'{tag}: the game ended the battle at minute {b.get("minute")} on both copies: by itself '
                  f'({(game_end or ["-"])[-1][-90:]}), by its proposal agreed ({b.get("proposals")}), or, when it did '
                  f'neither within 900 minutes, by the agreed end at that cap ({capped})',
                  (game_end or b.get('proposals') or capped) and ends_a and ends_b, f'{ends_a[-2:]} | {ends_b[-2:]}')
        else:
            tl = {w: log_lines(t, r'lockstep: TEST scenario length \d+ -> \d+: the game ends the battle at the end of '
                                  r'minute \d+') for w, t in (('host', hl), ('client', cl))}
            ge = {'host': game_end, 'client': log_lines(cl, LS_GAME_END_RE) if cl else []}
            mins = {int(re.search(r'minute (\d+)$', v[-1])[1]) for v in tl.values() if v}
            check(f'{tag}: `ls endsoon` at minute {b.get("endsoon_at")} ({b.get("endsoon")}): on both copies the game '
                  f'itself ended the battle inside the next minute ("TEST scenario length a -> b: the game ends the battle '
                  f'at the end of minute M", then the game\'s "Scenario absolute time limit is reached!"), over at '
                  f'minute M = {b.get("minute")}', all(tl.values()) and all(ge.values()) and len(mins) == 1
                  and b.get('minute') in mins and (b.get('endsoon') or '').startswith('ok'),
                  f'{ {w: [x.split("] ", 1)[-1][:90] for x in v[-1:]] for w, v in tl.items()} } '
                  f'{ {w: [x.split("] ", 1)[-1][:60] for x in v[-1:]] for w, v in ge.items()} }')
        # a battle the game ends inside a minute: its results' "Exit battle" closes the screen and FormClose runs the rest
        # of the host's month; that must not happen inside the battle's simulation step (minute-box policy, shared RNG)
        hlines, nested, seen_end = hl.splitlines(), [], False
        for ln in hlines:
            if re.search(LS_GAME_END_RE, ln):
                seen_end = True
                continue
            if seen_end and re.search(r'live battle ended \(', ln):
                break
            if seen_end and re.search(r"lockstep: (minute box|picture message .* skipped|WARNING)", ln):
                nested.append(ln.split('] ', 1)[-1][:110])
        warn = log_lines(hl, r'lockstep: WARNING .* inside a simulation step')
        check(f'{tag}: both copies report the end as the normal end of the battle ("The battle is over (...)"), not "the '
              f'battle screen was closed"; the host\'s month after the battle runs outside the battle\'s simulation step '
              f'(no "WARNING ... handled inside a simulation step")', ends_a and ends_b
              and not any('screen was closed' in x for x in ends_a + ends_b) and not warn,
              f'host {ends_a[-2:]} | client {ends_b[-2:]} | warnings {warn[:2]} | boxes answered by the battle\'s policy '
              f'after the game\'s end: {nested[:6]}')
        if mode == 'endsoon' or re.search(LS_DEFER_RE, hl):
            deferred_close_checks(tag, rec, b, hl, cl)
    elif mode.startswith('drop'):
        ar = ls_answered(_ANS[0], 'host', rec['t0'], 'OK [Yes]')
        check(f'{tag}: the host dropped the client after its live minutes, the client went back to slot 77 at once, the '
              f'host\'s battle went on against the AI to its end (auto-run)', b.get('drop') and b.get('back_s') is not None
              and ar, f'{b.get("drop")} back {b.get("back_s")} s; auto-run {ar[:1]}')
    tdna = chat(ctx.cp).count('turn did not advance') - rec['chat0'].count('turn did not advance')
    pkg = log_lines(hl, r'state seq \d+ -> Captain \(nation 1,')
    hst, cst = sstatus(H), sstatus(C)
    hn = lsn(H)
    check(f'{tag}: the host\'s month completed after the battle (FormClose -> DoStrategicTurn -> DoEndOfTurn) and the new '
          f'month reached the client once (one "state seq N -> Captain (nation 1, ..." line, no "turn did not advance"); '
          f'both in {rec["date1"]}; host live battle and slot mode off', hst.get('date') == cst.get('date') == rec['date1']
          and rec['date1'] != rec['date0'] and len(pkg) == 1 and tdna <= 0 and hn.get('hostOpp') == '-1'
          and hn.get('slotMode') == '0' and cst.get('slot') == str(CLIENT_SLOT) and cst.get('playerIdx') == '1',
          f'{rec["date0"]} -> host {hst.get("date")} client {cst.get("date")}; packages {len(pkg)}; "did not advance" '
          f'+{tdna}; {hn}')
    s_post, c_post = read_save(save_path(HOST_SLOT)), read_save(save_path(CLIENT_SLOT))
    stages = month_stages(rec, b, s_post, (0, 1))
    win, _, _, eff = stages[0] if stages else ('live battle start -> after the month', None, None,
                                                battle_effects(b.get('s_battle'), s_post))
    rec['stage_effects'] = stages
    log(f'  {tag}: battle effects ({win}): ' + '; '.join(
        f'nation {n}: {len(e["part"])} took part, {len(e["gone"])} gone {e["gone"][:3]}, lost {e["sunk"][:4]}, losses '
        f'{e["lost"]} (counters without campaign ships, e.g. MSLost/AUXLost: {e["abstract"]}), repair/status/fate changed '
        f'{[v for v in e["repair"].values() if v[1] != v[2] or v[3] != v[4]][:5]}'
        for n, e in eff.items()))
    if len(stages) > 1:
        log(f'  {tag}: the month step by step: ' + ' | '.join(f'{lab}: {effects_txt(e) or "no losses"}'
                                                             for lab, _, _, e in stages))
    diffs = same_ships(s_post or {}, c_post or {})
    check(f'{tag}: the battle is in the campaign ({win}): ships of both nations took part (battle star / "Took part" log '
          f'entry); every warship loss counted in [NationNLosses] (counters of types with no campaign ships, MSLost and '
          f'AUXLost, only reported) comes with a lost '
          f'ship (gone, or its Fate no longer "XXX", e.g. "Sunk in battle ..."; the month\'s idea-1 battles and the '
          f'game\'s resolutions after the battle phase are checked apart); the client\'s month (slot '
          f'77) has the same ships, battle fields (RepairTime, BattleStars, log entries, Status, Fate, CrewQuality) and '
          f'losses for nations 0 and 1 as the host\'s save', all(eff[n]['part'] or eff[n]['gone'] for n in (0, 1))
          and losses_explained(eff) and not diffs,
          f'{[(n, len(e["part"]), len(e["gone"]), len(e["sunk"]), e["lost"]) for n, e in eff.items()]}; '
          f'differences {diffs[:5]}')
    nh, nc = nation_table(H), nation_table(C)
    vh, vc = vpinfo(H), vpinfo(C)
    vpl = re.findall(VP_BATTLE_RE, hl)
    check(f'{tag}: ship counts of nations 0 and 1 equal on host and client; VP of 0 and 1 equal on host and client'
          + (f'; "victory points: nation 1 +{vpl[0][1]} in its battle against the host -> {vpl[0][2]}" and nation 1 >= '
             f'that after the month' if vpl else ' (no VP line: nation 1 scored nothing in the battle)'),
          all(nh.get(n, {}).get('ships') == nc.get(n, {}).get('ships') for n in (0, 1)) and vh and vc
          and vh['vp'].get(0) == vc['vp'].get(0) and vh['vp'].get(1) == vc['vp'].get(1)
          and (not vpl or vh['vp'].get(1, -1) >= int(vpl[-1][2])),
          f'ships {[(nh.get(n, {}).get("ships"), nc.get(n, {}).get("ships")) for n in (0, 1)]}; vp host '
          f'{vh and vh["raw"]} client {vc and vc["raw"]}; lines {vpl}; before {before.get("vp")}')
    hv, cv = nint(H, 1, 'ResearchPct'), nint(C, 1, 'ResearchPct')
    check(f'{tag}: the client\'s plans for that month were not lost (nation 1 ResearchPct {plan} set before the submit: '
          f'host {hv}, client {cv})', hv == cv == plan, f'{hv} {cv}')
    return eff


def idea1_merge_checks(tag, rec, K, J):
    """h2) the month's idea-1 merges, from the saves StageWatcher read at once: for each merged battle N the host's save
    as that battle was sent (the save before the merge), the battle slot after the battle (Game87, K = nation 0 there)
    and the merged save: [NationKLosses] and [NationJLosses] of the merged save = the battle slot's (the merge adds
    result - sent), and every warship loss the merge added comes with a lost ship (gone or Fate) in the merged save.
    The battle slot's own accounting and what the game's resolution of the month's other battles did after the last
    merge are reported."""
    st = rec.get('stages') or {}
    s1, g87, prev = st.get('s1') or {}, st.get('g87') or {}, st.get('s0')
    rows, bad = [], []
    for n in sorted(s1):
        merged, slot = s1[n], g87.get(n)
        if not (prev and merged):
            bad.append(n)
            rows.append((n, 'save not read'))
            prev = merged or prev
            continue
        eff_m = battle_effects(prev, merged, (K, J))
        ok, row = losses_explained(eff_m), dict(merge=effects_txt(eff_m) or 'no losses')
        if slot and 'General' in slot:
            eff_s = battle_effects(prev, slot, (K, J), slot_nations={K: 0})
            same = all(merged.get(f'Nation{x}Losses') == slot.get(f'Nation{y}Losses') for x, y in ((K, 0), (J, J)))
            row.update(slot=effects_txt(eff_s) or 'no losses', same_losses=same,
                       slot_explained=losses_explained(eff_s))
            ok = ok and same
        else:
            row['slot'] = 'not read (rewritten by the next battle first)'
        rows.append((n, row))
        if not ok:
            bad.append(n)
        prev = merged
    after = [(lab, effects_txt(e) or 'no losses') for lab, _, _, e in (rec.get('stage_effects') or [])
             if lab.endswith('-> after the month') and 'merged' in lab]
    resolved = [s for s in st.get('steps', []) if s.startswith('resolved')]
    log(f'  {tag}: h2) idea-1 merges: {rows}; after the last merge (the game\'s resolution {resolved}): {after}')
    check(f'{tag}: h2) each idea-1 battle merged this month (saves read at once: as sent -> battle slot Game87 -> merged): '
          f'the merged [Nation{K}Losses]/[Nation{J}Losses] = the battle slot\'s, and every warship loss the merge added '
          f'comes with a lost ship (gone or Fate) in the merged save' + ('' if s1 else ' (none merged this month)'),
          not bad, f'{rows}; bad {bad}')


def scenario_lockstep_month(ctx):
    """The host's battle against the joined player inside a REAL processed month (the path test battles skip). The host
    at war with nation 1 (`diplo war 1` + applydiplo); months are processed until the game's CheckForBattles2 starts a
    battle against nation 1 during the host's turn (random: up to 8 months). Each time: the host's preview, the lockstep
    start on both, the live battle (every division on the AI for contact; default: 12 live minutes, then the host drops
    the client and fights on against the AI on auto-run; --stress: two battles, the first ended by agreement (or by the
    game) at >= 400 minutes, the second ended by the game itself INSIDE a minute (`ls endsoon` after 6 minutes: 0.3.0's
    deferred close, the host's month after it with normal dialogs), the second's months with idea-1 battles of nation 1
    against an AI nation too, their merges checked step by step), the end,
    FormClose -> DoStrategicTurn -> DoEndOfTurn (idea 1's battle phase), the new month to the client; the campaign: the
    battle's ships and losses in the host's save and in the client's month for both nations, VP, the client's plans of
    that month (ResearchPct set before its submit); after each battle `vp_reload_check` (0.4.0: every reload keeps the
    saved VP). Then peace (compromise) and one normal month."""
    marks0 = {H: log_mark(H), C: log_mark(C)}
    stress = OPTS['stress']
    ls_ensure_session(ctx)
    ls_quiet(ctx)
    r01 = ls_war01(ctx)
    check('setup: the host at war with nation 1 (`diplo war 1` accepted + applydiplo)', r01.get('war') == '1', r01)
    modes = ['agree', 'endsoon'] if stress else ['drop12']
    J = area = tJ = None
    fought, attempts = [], []
    for attempt in range(1, 9):
        if len(fought) >= len(modes):
            break
        k = len(fought)
        if rel(0, 1).get('war') != '1':
            ls_war01(ctx)
        if stress and k == 1 and J is None:
            cands = battle_pairs(1)
            if cands:
                _, _, J, area = cands[0]
                tJ = rel(1, J).get('tension', '5')
                log(f'  interplay: nation 1 at war with AI nation {J} too; idea-1 battles in {area} injected each month')
        if J is not None and k == 1:
            if rel(1, J).get('war') != '1':
                cmd(H, f'settension 1 {J} 50')
            for _ in range(2):
                inject(1, J, area)
        pct = nint(C, 1, 'ResearchPct')
        plan = 9 if pct != 9 else 8
        cmd(C, f'nfield 1 ResearchPct {plan}')
        before = dict(vp=vpinfo(H) and vpinfo(H)['raw'])
        d_before = gen_date(HOST_SLOT)
        rec = ls_month(ctx, f'lockstep_month M{attempt}', modes=[modes[k]])
        kind = ls_host_battle(rec)
        hb = [b for b in rec['live'] if b['A'] == H]
        hl = log_since(H, rec['hmark'])
        attempts.append((attempt, rec['date0'], kind, [(b['bid'], b['mode'], b.get('error')) for b in rec['live']],
                         log_lines(hl, r'battle phase: \d+')[:1]))
        if kind != 'none' and not hb:
            check(f'M{attempt}: the host\'s battle against nation 1 ran live (the client fights battles, plays them live)',
                  False, f'{kind}: {log_lines(hl, LS_OFF)[:3]}')
        if hb:
            tag = f'battle {len(fought) + 1} ({modes[k]})'
            n0 = len(results)
            host_battle_checks(ctx, tag, rec, hb[0], plan, before)
            d_after = gen_date(HOST_SLOT)
            rl = [x.split('] ', 1)[-1] for x in log_lines(hl, r'lockstep: campaign date (recorded: |\S+ kept from)')]
            dl = log_lines(hl, r'lockstep: the month runs: (the recorded campaign date is dropped|campaign date \S+ put '
                               r'back, the record is dropped)')
            check(f'{tag}: the campaign date (0.3.2): the host recorded the month\'s own date {ymd_log(d_before)} when its '
                  f'live battle opened, the month ran from it and dropped the record ("the month runs: ... the record is '
                  f'dropped"), the new month is the next one with the same day ({ymd(d_before)} -> {ymd(d_after)})',
                  rl and ymd_log(d_before) in rl[0] and dl and ymd(d_after) == next_month_ymd(d_before),
                  f'{rl[:2]}; {dl[:1]}; before {d_before}, after {d_after}')
            # the battle's aftermath on the campaign's own date (0.3.2 919b40d) and every nation's VP in all three places;
            # since engine level 10 every live load keeps the campaign's own date, so the results screen puts nothing back
            sac = hb[0].get('sac') or (None, None, None)
            camp = ymd(d_before).split('/')
            differs = sac[1] is not None and (str(sac[1]), str(sac[2])) != (camp[1], camp[2])
            res = [x.split('] ', 1)[-1] for x in log_lines(hl, r"lockstep: the battle's results: campaign date \S+ put "
                                                             r'back')]
            loads = [x.split('] ', 1)[-1] for x in log_lines(hl, r'lockstep: the load: campaign date ')]
            vh, vc, vs, vf = vpinfo(H), vpinfo(C), saved_vp(HOST_SLOT), saved_vp(CLIENT_SLOT)
            same = bool(vh and vc) and all(vh['vp'].get(n) == vc['vp'].get(n) == vs.get(n) for n in range(9))
            check(f'{tag}: the battle\'s aftermath (0.3.2, engine level 10): every nation\'s VP is the same in the host\'s '
                  f'memory, in its saved slot 1 and in the client\'s month package; the battle ran on the campaign\'s own '
                  f'date: every live load on the host kept {ymd_log(d_before)} ("the load: campaign date '
                  f'{ymd_log(d_before)} kept (the battle save said ...)" when the battle\'s own date '
                  f'{"/".join(str(x) for x in sac)} differs), so the results screen put nothing back',
                  same and bool(loads) and all(f'campaign date {ymd_log(d_before)} ' in x for x in loads)
                  and (not differs or any(' kept (' in x for x in loads)) and not res,
                  f'host {vh and vh["vp"]}; saved {vs}; client {vc and vc["vp"]} (its slot {CLIENT_SLOT} file {vf}); '
                  f'loads {loads[:3]}; results {res[:1]}; before the month {before.get("vp")}; files written at slot 1 '
                  f'{file_time(save_path(HOST_SLOT))}, slot {CLIENT_SLOT} {file_time(save_path(CLIENT_SLOT))}')
            if not same and vh and vc:
                vp_mismatch_probe(ctx, tag)
            vp_reload_check(ctx, tag)
            if J is not None and k == 1:
                phase = log_lines(hl, r'battle phase: \d+ battle')
                live_t = log_secs((log_lines(hl, r'lockstep: battle \d+ epoch 1 sent') or [''])[0])
                ph_t = log_secs(phase[0]) if phase else None
                sent1 = log_lines(hl, r'battle \d+ sent to Captain')
                settled = log_lines(hl, r'battle \d+ applied: |battle \d+: resolved by the game')
                check(f'{tag}: h) interplay: in the same month the idea-1 battle phase (nation 1 vs AI nation {J}) ran after '
                      f'the host\'s live battle (DoTurn2 -> battle, then DoEndOfTurn -> the battle phase) and its battles '
                      f'were sent to Captain and settled', phase and live_t is not None and ph_t is not None
                      and ph_t >= live_t and sent1 and len(settled) >= len(sent1),
                      f'live {live_t} phase {phase[:1]} sent {sent1[:3]} settled {settled[:3]}')
                idea1_merge_checks(tag, rec, 1, J)
            rs = results[n0:]
            b = hb[0]
            LS_MATRIX.append((f'real month {rec["date0"]}: host battle {b.get("bid")} ({modes[k]})',
                              sum(1 for r in rs if r[2]), len(rs), round(rec['seconds']),
                              f'minutes {(b.get("hash") or {}).get("minutes")}, end at {b.get("minute") or "drop"}'))
            fought.append(rec)
    check(f'the game started {len(modes)} host battle(s) against nation 1 within 8 months (CheckForBattles2 is random; '
          f'attempts: month, date, kind, live battles, battle phase)', len(fought) >= len(modes), attempts)
    relview_check('0.4.1 at war with the host: the client\'s screen shows its own war (slot 1 = the host\'s nation at war, '
                  '"At war with <host>.") and the host\'s screen nation 1 at war', C, 1)
    relview_check('0.4.1 at war with the client: the host\'s screen (`relview` on the host)', H, 0)
    if J is not None:
        cmd(H, f'settension 1 {J} {tJ}')
    r01 = ls_peace01(ctx)
    check('peace 0-1 again (compromise: the host offers, the client\'s "Accept peace" button, applydiplo)',
          r01.get('war') == '0', r01)
    hm = log_mark(H)
    run_month(ctx, 'lockstep_month peace')
    check('the next normal month works (both in the new month; no live battle, no battle phase)',
          LS_HOLD not in log_since(H, hm) and 'battle phase:' not in log_since(H, hm), log_lines(log_since(H, hm),
                                                                                                    LS_HOLD)[:2])
    relview_check('0.4.1 after the peace: the client\'s screen shows its own relations at peace', C, 1)
    vh, vc, vs = vpinfo(H), vpinfo(C), saved_vp(HOST_SLOT)
    check('the month after the reloads (0.4.0): every nation\'s VP is the same in the host\'s memory, in its saved slot '
          f'{HOST_SLOT} and in the client\'s memory', vh and vc and all(vh['vp'].get(n) == vc['vp'].get(n) == vs.get(n)
                                                                       for n in range(9)),
          f'host {vh and vh["vp"]}; saved {vs}; client {vc and vc["vp"]}')
    ls_after_checks(ctx, 'lockstep_month')
    ls_log_scan('lockstep_month', marks0)


# ---------------------------------------------------------------- two PCs (0.4.1, live-battle engine level 15)
# Every other scenario plays both PCs on one PC: one Preferences file, one locale, one window size, localhost. `twopc`
# gives the joined player's copy (B) what another PC would have (docs/TESTING.md, "Two-PC conditions"): its own
# Preferences, read by the game's own reader at B's start (the shared file holds B's variant from B's start to the
# scenario's end: "B's own Preferences file"; A read the run's file at its start and doesn't read it again), a comma
# locale (RTW3MP_TEST_LOCALE=comma), its own window size (its MainFormWidth/Height at every load; both windows resized
# with SetWindowPos between minutes) and a network with latency, jitter and a bandwidth cap (tools/net_delay_proxy.py
# between B and the host's session port). The short variant runs by default, the full one with --stress.
TWOPC_PROXY_PORT = 47634  # the delay proxy listens on 127.0.0.1 here and forwards to the host's MP_PORT
TWOPC_NET = dict(short=dict(delay=120, jitter=60, kbps=4000, seed=6),  # one-way ms, +- ms, kbit/s per direction
                 full=dict(delay=200, jitter=100, kbps=2000, seed=7))
TWOPC_PLACE = dict(A=(20, 20, 900, 650), B=(300, 40, 1560, 980))  # the battle windows between minutes: x, y, w, h
TWOPC_MONTHS = dict(short=4, full=6)  # months tried until the game's CheckForBattles2 starts the host's battle
# B's value of each key: the first of its list that differs from A's (the battle preferences: A's `ls prefs`; the others:
# the file as A read it). The battle preferences are kPrefs of src/mod/lockstep.cpp (battle_prefs_keys: a live battle
# takes them from A); the others stay each PC's own (display, sound, messages, pauses, names, the battle window's size).
TWOPC_ALT = dict(
    AIControl=(0, 1, 2), FloatWarning=(0, 2, 1), ReadyPopup=(1, 0), BreakOnNewSighting=(0, 1), AirApproachMessage=(0, 1),
    AirSurfaceMessageLvl=(2, 0, 1), LetAIControlForce=(1, 0), LOScalc=(0, 1), SoundOption=(4, 1, 0), Autosave=(30, 60),
    FloatplaneLaunch=(0, 1), RealismSetting=(2, 1), NoFriendlyTorpHits=(1, 0), BSSMHC=(35, 40),
    DarkMode=(1, 0), Scale=(1, 0), SoundVolume=(5, 25), FOW=(0, 1), EnglishRanks=(1, 0), ConvertCharacters=(1, 0),
    BreakOnHit=(0, 1), BreakOnId=(0, 1), BreakOnSighting=(0, 1), BreakOnTorpedoHit=(0, 1), BreakOnSinking=(0, 1),
    BreakOnSunk=(0, 1), LoseContactPopup=(0, 1), OpenFireMsg=(1, 5), AirCombatMessageLvl=(2, 0), ShipFlags=(1, 0),
    DamageMeter=(1, 0), CourseIndicator=(1, 0), Compass=(1, 0), GridLines=(1, 0), MainFormWidth=(1400, 1200),
    MainFormHeight=(880, 800))
TWOPC_SECTIONS = dict(Break=('BreakOnHit', 'BreakOnId', 'BreakOnSighting', 'BreakOnTorpedoHit', 'BreakOnMissileHit',
                             'BreakOnNewSighting', 'BreakOnSubSighting', 'BreakOnSinking', 'BreakOnSunk',
                             'AirApproachMessage', 'LetAIControlForce'),
                      MainForm=('MainFormWidth', 'MainFormHeight', 'MainFormState', 'MainFormLeftPanelWidth'))
SBPREFS_AT = (108 + 14, 5 + 14)  # TfrmMain.sbPrefs, the battle screen's Preferences (a 28x28 TSpeedButton on Panel1)
PREFS_LINE_RE = r"lockstep: battle preferences: (\S+)'s for the load and the simulation \((.*)\); this PC's own come back"
PREFS_BACK_RE = r"lockstep: this PC's own battle preferences again \((.*)\)"
PREFS_DLG_RE = r"lockstep: the Preferences dialog changed battle preferences the simulation uses \((.*)\): this battle's"
ENSIGN_LINE = "lockstep: the battle screen shows side 1's ensign"
LOCALE_RE = r"TEST: RTW3MP_TEST_LOCALE=comma: decimal separator"
LOADED_RE = r'lockstep: battle loaded from slot'
QUEUED_RE = r'lockstep: battle \d+ epoch \d+ queued for loading'
TWOPC_DESYNC_RE = r'DESYNC at minute|the loaded battles differ'  # (not "DESYNC report ...": `ls desyncreport`'s own)
PROXY_STATS_RE = (r'^\S+ connection (\d+)(?: closed)?: up (\d+) chunks (\d+) bytes \(bandwidth wait max ([\d.]+) s\), '
                  r'down (\d+) chunks (\d+) bytes \(max ([\d.]+) s\)')
NET_PROXY = {}  # bridge port -> the port that copy joins instead of MP_PORT (twopc: the delay proxy's)
PROXY = [None]  # the delay proxy's Popen while twopc runs (stopped by the scenario, else by the runner)
SHOTS_DIR = os.environ.get('RTW3_SHOTS', '')  # optional: PrintWindow captures of the battle windows (evidence only)
SHOTS = []  # the captures taken (path, size)
_u32w = ctypes.WinDLL('user32')  # twopc: window sizes, layered windows, PrintWindow (own prototypes: `u` unchanged)
_gdiw = ctypes.WinDLL('gdi32')
_u32w.GetWindowRect.argtypes = [wt.HWND, ctypes.POINTER(wt.RECT)]
_u32w.IsWindowVisible.argtypes = [wt.HWND]
_u32w.IsWindow.argtypes = [wt.HWND]
_u32w.SetWindowPos.argtypes = [wt.HWND, wt.HWND, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, wt.UINT]
_u32w.GetWindowLongW.argtypes = [wt.HWND, ctypes.c_int]
_u32w.GetWindowLongW.restype = ctypes.c_long
_u32w.GetLayeredWindowAttributes.argtypes = [wt.HWND, ctypes.POINTER(wt.DWORD), ctypes.POINTER(ctypes.c_ubyte),
                                             ctypes.POINTER(wt.DWORD)]
_u32w.GetWindowDC.argtypes = [wt.HWND]
_u32w.GetWindowDC.restype = wt.HDC
_u32w.ReleaseDC.argtypes = [wt.HWND, wt.HDC]
_u32w.PrintWindow.argtypes = [wt.HWND, wt.HDC, wt.UINT]
_gdiw.CreateCompatibleDC.argtypes = [wt.HDC]
_gdiw.CreateCompatibleDC.restype = wt.HDC
_gdiw.CreateCompatibleBitmap.argtypes = [wt.HDC, ctypes.c_int, ctypes.c_int]
_gdiw.CreateCompatibleBitmap.restype = wt.HBITMAP
_gdiw.SelectObject.argtypes = [wt.HDC, wt.HGDIOBJ]
_gdiw.SelectObject.restype = wt.HGDIOBJ
